const DATA = {
  "phy": {"key":"phy","name":"大学物理","icon":"⚛","book":"《物理学》(上、下册) · 唐延林 赵光菊 主编 · 高教社","prog":"全书 15 章已收录 · 当前在第 2 章","progPct":15,"intro":"按课本《物理学》(上、下册) 全 15 章的章节顺序编排：每个单元 = 课本一章，章下按课本原小节(1.1、1.2…)拆开，知识点逐条落实。物理的公式都给了【推导】，讲清它从哪来、怎么一步步推出来——这样才不是死记。每节配典型例题，方法对齐课本。","map":{"root":{"title":"物理学 · 上、下册","x":50,"y":13},"hubs":[{"id":"ph1","title":"力学 (1–4章)","x":8,"y":30},{"id":"ph2","title":"电磁学 (5–8章)","x":8,"y":44},{"id":"ph3","title":"振动与波动 (9–11章)","x":8,"y":58},{"id":"ph4","title":"热学 (12–13章)","x":8,"y":72},{"id":"ph5","title":"近代物理 (14–15章)","x":8,"y":86}],"units":[{"id":"p1","no":"1","title":"质点运动学","sub":"位移·速度·加速度·圆周运动","tag":"力学","x":25,"y":30,"parent":"ph1"},{"id":"p2","no":"2","title":"牛顿运动定律","sub":"三大定律·常见力·应用","tag":"力学","x":42,"y":30,"parent":"ph1"},{"id":"p3","no":"3","title":"动量与能量守恒","sub":"动量定理·动能定理·碰撞","tag":"力学","x":59,"y":30,"parent":"ph1"},{"id":"p4","no":"4","title":"刚体","sub":"转动定律·转动惯量·角动量","tag":"力学","x":76,"y":30,"parent":"ph1"},{"id":"p5","no":"5","title":"静电场","sub":"库仑定律·高斯定理·电势","tag":"电磁","x":25,"y":44,"parent":"ph2"},{"id":"p6","no":"6","title":"导体与电介质","sub":"静电平衡·电容·电位移","tag":"当前","x":42,"y":44,"parent":"ph2","cur":true},{"id":"p7","no":"7","title":"恒定磁场","sub":"毕奥–萨伐尔·安培环路","tag":"电磁","x":59,"y":44,"parent":"ph2"},{"id":"p8","no":"8","title":"电磁感应 电磁场","sub":"法拉第·动生感生·麦克斯韦","tag":"电磁","x":76,"y":44,"parent":"ph2"},{"id":"p9","no":"9","title":"振动","sub":"简谐·旋转矢量·合成·共振","tag":"波动","x":25,"y":58,"parent":"ph3"},{"id":"p10","no":"10","title":"波动学基础","sub":"波函数·干涉·驻波·多普勒","tag":"波动","x":42,"y":58,"parent":"ph3"},{"id":"p11","no":"11","title":"波动光学","sub":"双缝·薄膜·衍射·光栅·偏振","tag":"波动","x":59,"y":58,"parent":"ph3"},{"id":"p12","no":"12","title":"气体动理论","sub":"状态方程·能量均分·速率分布","tag":"热学","x":25,"y":72,"parent":"ph4"},{"id":"p13","no":"13","title":"热力学基础","sub":"第一定律·循环·卡诺·熵","tag":"热学","x":42,"y":72,"parent":"ph4"},{"id":"p14","no":"14","title":"狭义相对论","sub":"洛伦兹变换·钟慢尺缩·质能","tag":"近代","x":25,"y":86,"parent":"ph5"},{"id":"p15","no":"15","title":"量子物理","sub":"光子·光电效应·不确定关系","tag":"近代","x":42,"y":86,"parent":"ph5"}]},"units":{"p1":{"no":"1","title":"质点运动学","tag":"力学 · 第1章","sub":"课本第1章。用位移、速度、加速度描述“在哪、多快、怎么变”，是整个力学体系的描述语言。","blocks":[{"t":"sh","no":"1.1","title":"质点运动的描述"},{"t":"tx","h":"一、时间与空间、质点 参考系 坐标系","p":"<b>质点</b>是有质量、无大小的点，是忽略物体形状体积的理想模型。<b>参考系</b>是描述运动时选定的标准物；在参考系上固接<b>坐标系</b>（直角坐标、自然坐标等）才能定量描述。<b>时间与空间</b>在经典物理中绝对、均匀。"},{"t":"tx",
"h":"二、位置矢量 · 运动方程 · 位移","p":"<b>位置矢量</b> r = x i + y j + z k 从原点指向质点。<b>运动方程</b> r = r(t) 给出质点的位置随时间变化，消去 t 即得轨迹方程。<b>位移</b> Δr = r₂ − r₁ 是矢量，只由始末位置决定。"},{"t":"tx","h":"三、速度","p":"<b>平均速度</b> v̄ = Δr/Δt；<b>瞬时速度</b> v = lim(Δt→0) Δr/Δt = dr/dt，方向沿轨迹切线。速率 v = |v|。"},{"t":"tx","h":"四、加速度","p":"<b>平均加速度</b> ā = Δv/Δt；<b>瞬时加速度</b> a = dv/dt = d²r/dt²。加速度反映速度矢量（大小和方向）的变化快慢。"},{"t":"anim","kind":"anim-kine","cap":"匀变速直线运动：速度均匀增大，相等时间间隔内位移越来越大"},{"t":"dv","title":"推导：匀变速直线运动的三条基本公式","goal":"从“加速度的定义 a = dv/dt”出发，用积分一步步推出 v、x、v² 三条公式——让你知道每条公式从哪来、什么时候用，而不是死记结果。","steps":[{"s":"起点：加速度的定义 a = dv/dt（匀变速时 a 是常量）。","why":"三条公式都从这一个定义长出来。"},{"s":"把 dt 乘过去：dv = a·dt。","why":"把“导数式”改写成“微小变化量”，才能两边累加。"},{"s":"两边对 t 积分：∫₀ᵗ dv = ∫₀ᵗ a·dt。","why":"积分＝把每个瞬间的微小变化累加起来。"},{"s":"左边：∫₀ᵗ dv = v − v₀，是速度从 v₀ 到 v 的总改变量。","why":"对“1”积分一次就得到变量本身，所以是 v 的差值。"},{"s":"右边：a 是常量可提出，∫₀ᵗ a·dt = a·t。","why":"常数积分＝常数 × 区间长度，几何上就是一个矩形面积。"},{"s":"两边相等：v − v₀ = at ⟹ <b>v = v₀ + at</b>。","why":"速度公式——说明速度随时间线性变化。"},{"s":"再由 v = dx/dt ⟹ dx = v·dt = (v₀+at)dt，再积分：x − x₀ = v₀t + ½at² ⟹ <b>x = x₀ + v₀t + ½at²</b>。","why":"½at² 来自对 at 的积分，不是背的。"},{"s":"消去时间：t = (v−v₀)/a 代入位移式 ⟹ <b>v² − v₀² = 2a(x − x₀)</b>。","why":"题目不给时间、只给位移和速度时最省事。"}]},{"t":"dv","title":"给“积分不熟”的你：∫dv 与 ∫a dt 到底怎么算","goal":"把积分看成“看图数面积”，不套公式也能看懂这两步。","steps":[{"s":"先切碎：把 0→t 的时间切成很多极短的小段 dt。","why":"面积法：积分＝无数个小长方形面积相加。"},{"s":"每个小长方形：底 = dt，高 = a（常量）。","why":"所以每个小矩形面积 = a·dt。"},{"s":"全部加起来 = 高 a × 总宽 t = a·t。","why":"这正是 ∫₀ᵗ a dt = a·t 的几何含义。"},{"s":"左边 ∫₀ᵗ dv 累加的是速度的微小变化，加总后 = v − v₀。","why":"从起点 v₀ 到终点 v 的总改变量。"},{"s":"两边相等：v − v₀ = a·t，移项得 <b>v = v₀ + at</b>。","why":"推导完成，你能指出每一项的来源。"}]},{"t":"anim","kind":"anim-integral","cap":"积分＝把无数个小长方形面积累加：高 a × 宽 t = a·t"},{"t":"anim","kind":"anim-vt-area","cap":"v–t 图：斜率 = 加速度 a，图线下方面积 = 位移"},{"t":"ex","q":"【典型例题】质点沿 x 轴运动，x = 2t³ − 6t²(SI)。求 t=2s 时的速度和加速度，并判断此刻的运动状态。","steps":["速度是位置对时间求导：v = dx/dt = 6t² − 12t","代入 t=2：v = 6×4 − 12×2 = 0 m/s，此刻瞬时静止","加速度是速度对时间求导：a = dv/dt = 12t − 12","代入 t=2：a = 24 − 12 = 12 m/s²","v=0 且 a>0，说明这是运动方向发生反转的拐点。"]},{"t":"sh","no":"1.2","title":"圆周运动"},{"t":"tx","h":"角量与线量","p":"做圆周运动时用角量描述更方便：<b>角位置</b> θ、<b>角速度</b> ω = dθ/dt、<b>角加速度</b> α = dω/dt。线量与角量的关系：弧长 s = Rθ，速率 v = Rω，切向加速度 aₜ = Rα。"},{"t":"dv","title":"推导：弧长 s = Rθ、速率 v = Rω、切向 aₜ = Rα","goal":"三段关系其实是同一个东西的三次“变换”：先用弧度定义，再对时间各求一次导，就得到速度和切向加速度。","steps":[{"s":"弧长 s = Rθ：由弧度的定义 θ = s / R 直接移项得到。","why":"弧度就是“弧长与半径之比”，这是定义，不是新公式。"},
{"s":"速率 v = Rω：对 s = Rθ 两边求时间导数，v = ds/dt = R·(dθ/dt) = Rω。","why":"R 是常量可提出导数，dθ/dt 正是角速度 ω。"},{"s":"切向加速度 aₜ = Rα：再对 v = Rω 求导，aₜ = dv/dt = R·(dω/dt) = Rα。","why":"dω/dt 就是角加速度 α，求导两次得到切向加速度。"},{"s":"物理意义：角量描述“转了多少”，线量描述“实际走了多少”，中间差一个半径 R 的比例。","why":"记住“角量 × R = 线量”，三个关系一次记牢。"}]},{"t":"fig","kind":"fig-anglin","cap":"角量与线量：θ=s/R 是弧度定义，两边对时间求导得 v=Rω、aₜ=Rα"},{"t":"tx","h":"切向加速度与法向加速度","p":"速度方向时刻变化，加速度分解为两个分量：<b>切向加速度</b> aₜ = dv/dt 改变速率大小；<b>法向（向心）加速度</b> aₙ = v²/R 改变速度方向。总加速度 a = √(aₜ² + aₙ²)。"},{"t":"anim","kind":"anim-circular","cap":"圆周运动：速度沿切线方向（方向在变），向心加速度 aₙ 始终指向圆心"},{"t":"dv","title":"推导：切向与法向加速度 aₜ = dv/dt、aₙ = v²/R（｜Δv｜＝2v·sin(Δθ/2) 的严格来历）","goal":"把加速度拆成“改变大小 + 改变方向”两部分，并<u>有理有据</u>地推出 aₙ = v²/R。重点讲清很多人稀里糊涂的一步：为什么｜Δv｜≈v·Δθ。","steps":[{"s":"速度是有大小、有方向的矢量，任一部分变化都会产生加速度。","why":"所以加速度要拆成“改变大小”和“改变方向”两部分讨论。"},{"s":"切向部分：只改变快慢，aₜ = dv/dt，方向沿切线。","why":"这一项负责速率 v 的增减。"},{"s":"法向部分：研究“方向”的改变。取极短 Δt，质点转过的圆心角 Δθ = vΔt/R。","why":"弧长 s = R·Δθ = v·Δt（走了多远＝速率×时间），两边同除 R 即得 Δθ。"},{"s":"【关键】这段时间里速率几乎不变、速度方向转过 Δθ。把初速度 v₁ 与末速度 v₂ 平移到同一始点：它们是两条长都为 v 的边，夹角恰是 Δθ，构成一个等腰三角形。","why":"因为速率不变，速度矢量只是整体“转”了一个角度——这才能用三角形算矢量差 Δv = v₂ − v₁。"},{"s":"由等腰三角形（两腰 = v，顶角 = Δθ），底边长即 ｜Δv｜ = 2v·sin(Δθ/2)。","why":"这是余弦定理的精确结果，不是近似：底边 = 2·v·sin(顶角/2)。"},{"s":"令 Δt→0，则 Δθ→0，用等价无穷小 sin(Δθ/2) ≈ Δθ/2，得 ｜Δv｜ ≈ 2v·(Δθ/2) = v·Δθ。","why":"这一步才是 ｜Δv｜≈v·Δθ 的真正出处——小角下 sin x≈x，所以“近似的”只是这个极限，几何本身是精确的。"},{"s":"于是 aₙ = lim(Δt→0) ｜Δv｜/Δt = v·lim(Δt→0)(Δθ/Δt) = v·ω = v·(v/R) = <b>v²/R</b>。","why":"Δθ/Δt 正是角速度 ω = v/R，代入即得向心加速度；方向沿 Δv 的极限方向，始终指向圆心。"},{"s":"总加速度 a = √(aₜ² + aₙ²)。","why":"切向与法向互相垂直，用勾股定理合成。"}]},{"t":"fig","kind":"fig-vel-tri","inline":true,"cap":"速度矢量画成等腰三角形：两腰都是 v、夹角 Δθ，底边 ｜Δv｜ = 2v·sin(Δθ/2) ≈ v·Δθ。"},{"t":"fig","kind":"fig-centripetal","cap":"向心加速度 aₙ=v²/R 的<u>严格来历</u>：①把初、末速度 v₁、v₂ 平移到同一起点，得两腰均为 v、顶角为 Δθ 的等腰三角形；②由几何关系得<b>精确式</b> |Δv|=2v·sin(Δθ/2)；③令 Δt→0 即 Δθ→0，用等价无穷小 sin(Δθ/2)≈Δθ/2，得 |Δv|≈v·Δθ；④两边除以 Δt 取极限，aₙ=v·(Δθ/Δt)=v·ω=v·(v/R)=v²/R。图中标出了每一处几何量。"},{"t":"ex","q":"【典型例题】质点做半径 R=2m 的圆周运动，运动方程为 θ = 2t²(rad)。求 t=1s 时的角速度、线速度、切向加速度、法向加速度。","steps":["角速度 ω = dθ/dt = 4t → t=1 时 ω = 4 rad/s","线速度 v = Rω = 2×4 = 8 m/s","角加速度 α = dω/dt = 4 rad/s² → 切向 aₜ = Rα = 2×4 = 8 m/s²","法向 aₙ = v²/R = 8²/2 = 32 m/s²","总加速度 a = √(8²+32²) = √1088 ≈ 33 m/s²。"]},{"t":"ex","q":"【典型例题】汽车以 v₀=20m/s 沿半径 R=50m 弯道匀减速到 10m/s，用时 5s。求这段时间内的切向与法向加速度。","steps":["切向加速度 aₜ = (v−v₀)/t = (10−20)/5 = −2 m/s²（减速）","法向加速度随速率变化，通常取某时刻 v 计算，如 v=10m/s 时 aₙ = v²/R = 100/50 = 2 m/s²",
"总加速度 a = √(aₜ²+aₙ²) = √(4+4) ≈ 2.83 m/s²","结论：曲线运动加速度必有两个分量。"]},{"t":"sh","no":"1.3","title":"相对运动"},{"t":"tx","h":"运动的相对性","p":"同一运动在不同参考系中描述不同。<b>绝对空间、绝对时间</b>假设下（经典力学），设 S′ 系相对 S 系以速度 u 平动，则：<b>位置</b> r = r′ + r₀，<b>速度</b> v = v′ + u（伽利略速度变换），<b>加速度</b> a = a′（两参考系相对平动时加速度相同）。"},{"t":"ex","q":"【典型例题】船在静水中速度 4m/s，河水速度 3m/s，两者垂直。求船相对岸的合速度大小与方向。","steps":["船对岸速度 = 船对水速度 + 水对岸速度（矢量相加）","两分量垂直：|v| = √(4²+3²) = 5 m/s","方向与水流夹角 θ：tanθ = 4/3，θ ≈ 53°","关键：不同参考系速度按矢量合成，与课本相对运动公式一致。"]},{"t":"warn","text":"<b>易错点：</b>① 位移 Δr（矢量）与路程 s（标量）不同，只有单向直线运动二者大小相等；② 加速度为负不等于减速，要看 a 与 v 方向；③ 求导/积分不要漏掉初始条件 v₀、r₀；④ 圆周运动加速度务必分解切向+法向，别只算一个。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第1章习题）"},{"t":"pt","no":"题型1","name":"已知运动方程 → 求速度、加速度（求导法）","feature":"题目直接给出 r(t)、x(t)、y(t) 的函数式，问某时刻的 v、a 或方向。","method":"逐次对时间求导：v = dr/dt，a = dv/dt；再代时刻。","steps":["写出坐标式，如 x = x(t)（二维则分别写 x(t)、y(t)）","求导一次得速度：vₓ = dx/dt，二维 v = vₓ i + v_y j","求导两次得加速度：aₓ = dvₓ/dt","代入给定时刻，注意矢量方向用正负号表示"],"ex":{"q":"x = 2t³ − 6t²(SI)，求 t=2s 时的 v 与 a。","steps":["v = dx/dt = 6t² − 12t","t=2 → v = 6×4 − 12×2 = 0 m/s","a = dv/dt = 12t − 12","t=2 → a = 24 − 12 = 12 m/s²","v=0 而 a>0：这是运动方向发生反转的拐点。"]},"pit":"幂函数求导别丢系数与指数；v=0 不等于 a=0。"},{"t":"pt","no":"题型2","name":"已知运动方程 → 求轨迹方程、位置矢量、位移与路程（课本例1.1）","feature":"给出 r(t) 或分量式 x(t)、y(t)，要求：轨迹方程、某时刻的位置矢量、两时刻的位移 Δr 与路程 Δs。","method":"①消 t 得轨迹；②代 t 得位置；③位移 Δr = r₂ − r₁（矢量）；④路程 Δs = ∫ds，ds = √((dx)²+(dy)²)（标量，沿轨迹积分）。","steps":["① 轨迹方程：从 x=x(t)、y=y(t) 中消去 t，得到 y 与 x 的关系式","② 位置矢量：把 t₀ 代入得 x₀、y₀，写成 r₀ = x₀ i + y₀ j","③ 位移：Δr = r₂ − r₁，只由始末位置决定，是矢量","④ 路程：沿轨迹积分 Δs = ∫√((dx)²+(dy)²)，与路径有关，是标量","⑤ 对比检查：曲线运动一般 Δs > ｜Δr｜"],"ex":{"q":"【课本例1.1】质点运动方程 r = 2t i + (2 − t²) j（SI）。求：(1) 轨迹方程；(2) t=0 与 t=2s 时的位置矢量；(3) 两时刻间的位移和路程。","steps":["轨迹：由 x=2t 得 t=x/2，代入 y=2−t² 得 y = 2 − x²/4（抛物线）","t=0：x=0, y=2 → r₀ = 2 j；t=2s：x=4, y=−2 → r₂ = 4 i − 2 j","位移 Δr = r₂ − r₀ = 4 i − 4 j，大小 ｜Δr｜ = √(4²+4²) = 4√2 ≈ 5.66 m","路程：ds = √((dx)²+(dy)²) = √(2²+(−2t)²) dt = 2√(1+t²) dt，Δs = ∫₀² 2√(1+t²) dt ≈ 5.91 m","对比：Δs(5.91) > ｜Δr｜(5.66)，因为轨迹是曲线而非直线"]},"pit":"位移是矢量、路程是标量，曲线运动二者一般不相等；消 t 求轨迹要化简；路程必须沿轨迹用弧长积分，不能拿直线距离代替。"},{"t":"pt","no":"题型3","name":"已知加速度 → 求速度、位移（积分法 + 初始条件）","feature":"给出 a(t) 或 a(x)，要求 v(t)、x(t) 表达式或某位置的速度。","method":"对 a(t) 用 ∫dv = ∫a dt；对 a(x) 用 ∫v dv = ∫a dx（换元避开时间）。","steps":["判断已知量：a 是 t 的函数还是 x 的函数","a(t)：dv = a(t)dt → 积分得 v(t) + C","用初条件（如 t=0 时 v=v₀）定常数 C","再积分 x = ∫v dt，用 x(0)=x₀ 定第二个常数"],
"ex":{"q":"a = 2t (m/s²)，t=0 时 v=0、x=0，求 v(t)、x(t)。","steps":["v = ∫a dt = ∫2t dt = t² + C","代 t=0,v=0 → C=0，故 v = t²","x = ∫v dt = ∫t² dt = t³/3 + C′","代 t=0,x=0 → C′=0，故 x = t³/3。"]},"pit":"积分常数必须用初始条件确定；a(x) 问题用 v dv = a dx，别硬套时间积分。"},{"t":"pt","no":"题型4","name":"匀变速直线运动三公式的应用","feature":"加速度恒定，已知 v₀、v、a、x、t 中若干个，求其余。","method":"五个量知三求二；不含 t 时用 v² − v₀² = 2ax 最快。","steps":["列出已知量与所求量","选公式：含 t 用 v = v₀ + at、x = v₀t + ½at²；不含 t 用 v² − v₀² = 2ax","统一正方向，代入求解","检查结果量纲与物理合理性"],"ex":{"q":"汽车以 20 m/s 行驶，刹车加速度大小 5 m/s²，求刹车距离。","steps":["已知 v₀=20, v=0, a=−5, 求 x","用 v² − v₀² = 2ax","0 − 400 = 2×(−5)×x → x = 40 m","先判断停止时间 t = 20/5 = 4s，未超时，结果有效。"]},"pit":"刹车类问题要先算停止所需时间，避免“倒着开”；正负号统一。"},{"t":"pt","no":"题型5","name":"竖直上抛 / 自由落体","feature":"物体只受重力，向上抛或自由下落。","method":"取向上为正，a = −g；最高点 v=0，上升与下落具有对称性。","steps":["规定正方向并写出 v₀（上抛为正，自由落体为 0）","用 v = v₀ − gt 求任意时刻速度","用 h = v₀t − ½gt² 求位移（负号表示在抛出点下方）","最高点 v=0 时 t = v₀/g，最大高度 H = v₀²/(2g)"],"ex":{"q":"以 20 m/s 竖直上抛(g=10)，求上升最大高度与回到抛点的时间。","steps":["最高点 v=0：t = v₀/g = 2 s","H = v₀²/(2g) = 400/20 = 20 m","回到抛点位移为 0：0 = 20t − 5t² → t = 4 s","上下对称，总时间为升空时间的两倍。"]},"pit":"位移有正负（回到原点位移为 0 但路程不为 0）；g 取正方向和符号要一致。"},{"t":"pt","no":"题型6","name":"相对运动（速度合成）","feature":"涉及两个参考系（船/水、飞机/风、人/车），求合速度大小与方向。","method":"v_绝对 = v_相对 + v_牵连，按矢量平行四边形合成。","steps":["明确“谁相对谁”，把三个速度标注清楚","画矢量三角形/平行四边形","用勾股定理（垂直时）或余弦定理（夹角已知）求合速度大小","用 tanθ 或正弦定理求方向"],"ex":{"q":"船在静水中 4 m/s，水流 3 m/s，两者垂直，求船对岸的速度。","steps":["v_船岸 = v_船水 + v_水岸（矢量相加）","两分量垂直：|v| = √(4²+3²) = 5 m/s","方向与水流夹角 θ：tanθ = 4/3 → θ ≈ 53°","关键：不同参考系速度按矢量合成。"]},"pit":"速度是矢量，不能只做数值加减；方向要用角度描述。"},{"t":"pt","no":"题型7","name":"圆周运动的角量与线量、切向法向加速度","feature":"给出 θ(t) 或半径与速率，问角速度、线速度、切向/法向加速度、总加速度。","method":"ω = dθ/dt，α = dω/dt；v = Rω，aₜ = Rα，aₙ = v²/R。","steps":["由 θ(t) 求导得 ω(t)，再求导得 α(t)","代时刻得 ω、α","线速度 v = Rω，切向 aₜ = Rα，法向 aₙ = v²/R","总加速度 a = √(aₜ² + aₙ²)，方向指向偏移"],"ex":{"q":"R=2m，θ = 2t²(rad)，求 t=1s 的 ω、v、aₜ、aₙ。","steps":["ω = dθ/dt = 4t → 4 rad/s","v = Rω = 8 m/s","α = dω/dt = 4 → aₜ = Rα = 8 m/s²","aₙ = v²/R = 64/2 = 32 m/s²","总加速度 √(8²+32²) ≈ 33 m/s²。"]},"pit":"匀速圆周运动 aₜ=0 但 aₙ≠0；总加速度是矢量合成，不是简单相加。"},{"t":"pt","no":"题型8","name":"抛体运动（斜抛分解）","feature":"以初速度 v₀、抛射角 θ 抛出，求射高、射程、飞行时间或某点速度。","method":"分解：水平匀速（v₀cosθ），竖直匀变速（v₀sinθ 与 g）。","steps":["分解初速度：v₀ₓ = v₀cosθ，v₀_y = v₀sinθ","竖直方向定飞行时间：上升、下落对称","水平方向定射程：x = v₀ₓ·t_total","实际速度用 v = √(vₓ² + v_y²)"],"ex":{"q":"v₀=20 m/s，θ=30°，g=10，求射高与射程。","steps":["v₀_y = 10, v₀ₓ = 10√3 ≈ 17.3",
"上升时间 t₁ = v₀_y/g = 1 s，射高 = 5 m","总时间 2s","射程 = v₀ₓ×2 ≈ 34.6 m。"]},"pit":"飞行时间由竖直分运动决定；最高点竖直速度为 0 但水平速度不为 0。"},{"t":"pt","no":"题型9","name":"s–t 图 / v–t 图的读图与平均量","feature":"给出运动图像，问速度、加速度、位移或平均速度。","method":"s–t 图斜率 = 速度；v–t 图斜率 = 加速度、图线下面积 = 位移。","steps":["判断图是 s–t 还是 v–t","读斜率（切线或直线段）","v–t 图求位移用“面积法”（正负面积代数和）","平均速度 = 位移/时间，平均速率 = 路程/时间"],"ex":{"q":"某 v–t 图为 0→2s 从 0 匀增到 4 m/s，求 2s 内位移与平均速度。","steps":["面积 = 三角形 = ½×2×4 = 4 m（位移）","平均速度 = 4/2 = 2 m/s","加速度 = 斜率 = 4/2 = 2 m/s²","面积法比列方程更快。"]},"pit":"平均速度是位移/时间（矢量），平均速率是路程/时间，二者一般不等。"},{"t":"tip","text":"<b>第1章解题总流程：</b>①先判断题目给的是“运动方程（求导）”还是“加速度（积分）”；②涉及方向反转/图像先想 v、a 的符号与图像几何意义；③圆周运动一律拆成切向 + 法向两部分；④最后检查是否漏用初始条件、是否混淆位移与路程。"},{"t":"kw","items":["位置矢量","位移vs路程","v=dr/dt","匀变速三公式","向心加速度","伽利略变换"]}]},"p2":{"no":"2","title":"牛顿运动定律","tag":"力学 · 第2章","sub":"课本第2章。力是改变运动状态的原因，本章给出力学的动力学基础与分析套路。","blocks":[{"t":"sh","no":"2.1","title":"牛顿运动定律"},{"t":"tx","h":"三大定律","p":"<b>第一定律（惯性定律）</b>：一切物体不受外力时保持静止或匀速直线运动——它定义了惯性系。<b>第二定律</b>：物体动量对时间的变化率等于合外力，F = dp/dt；质量不变时 <b>F = ma</b>。<b>第三定律</b>：作用力与反作用力等大、反向、共线，作用在<b>两个不同</b>物体上。<b>力学相对性原理</b>：所有惯性系中力学规律相同。"},{"t":"dv","title":"推导：由动量定义导出 F = ma","steps":["动量定义 p = mv","牛顿第二定律的原始表述：F = dp/dt","质量不变时 dp/dt = m·dv/dt = ma","⟹ <b>F = ma</b>（仅当质量恒定时成立）","变质量问题（如火箭）必须回到 F = dp/dt 形式"]},{"t":"sh","no":"2.2","title":"物理量的单位和量纲"},{"t":"tx","h":"单位制与量纲","p":"国际单位制(SI)的七个基本量：长度 m、质量 kg、时间 s、电流 A、热力学温度 K、物质的量 mol、发光强度 cd。任何物理量的<b>量纲</b>可由基本量纲导出，量纲分析可检验公式是否正确。"},{"t":"sh","no":"2.3","title":"几种常见的力"},{"t":"tx","h":"万有引力 · 弹性力 · 摩擦力","p":"<b>万有引力</b> F = Gm₁m₂/r²，重力是地球引力在近地面的近似 G=mg。<b>弹性力</b>（胡克定律）F = −kx，负号表示方向与形变相反。<b>摩擦力</b>：静摩擦 0 ≤ f ≤ μ₀N，滑动摩擦 f = μN，方向与相对滑动（或趋势）方向相反。"},{"t":"sh","no":"2.4","title":"牛顿运动定律的应用举例"},{"t":"steps","items":["<b>选研究对象</b>：隔离出要分析的物体（可整体也可单个）","<b>受力分析</b>：重力、支持/弹力、摩擦力、外拉力，逐一画在受力图上","<b>建坐标</b>：沿运动方向为正，斜面题沿斜面 + 垂直斜面分解","<b>列方程</b>：分方向写 Fₓ=maₓ，F_y=0（垂直方向无加速度）","<b>联立求解</b>：注意摩擦力方向与相对运动/趋势相反"]},{"t":"fig","kind":"fig-incline","cap":"光滑斜面受力：压力 N=mg·cosθ，下滑分量 mg·sinθ 提供加速度 a=g·sinθ"},{"t":"ex","q":"【典型例题】质量 m=2kg 的物块从倾角 30° 的光滑斜面由静止下滑2m。求加速度与末速度（g=9.8m/s²）。","steps":["沿斜面方向：只有重力的下滑分量 mg·sin30°","a = g·sin30° = 9.8×0.5 = 4.9 m/s²","由 v² = 2as = 2×4.9×2 = 19.6","v = √19.6 ≈ 4.43 m/s","结论：光滑斜面加速度恒为 g·sinθ，与质量无关。"]},{"t":"ex","q":"【典型例题】质量 m 的物体放在水平面上，受水平拉力 F，摩擦因数 μ。求加速度。","steps":["竖直方向平衡：N = mg","水平方向：F − μN = ma","代入 N：F − μmg = ma","a = (F − μmg)/m = F/m − μg",
"关键：先由竖直平衡求 N，再代水平方程——这是摩擦类题的固定套路。"]},{"t":"warn","text":"<b>易错点：</b>① 作用力与反作用力作用在不同物体，不能相互抵消；② 整体法求系统加速度、隔离法求内部相互作用力；③ 斜面压力 N = mg·cosθ，不是 mg；④ 圆周运动要用向心方向列 Fₙ = mv²/R。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第2章习题）"},{"t":"pt","no":"题型1","name":"隔离体法 + 牛顿第二定律（单个物体）","feature":"求物体的加速度或某力，含斜面、水平面、绳、弹簧。","method":"选研究对象 → 画受力图 → 建坐标 → 列 F = ma 分量方程。","steps":["确定研究对象（隔离体）","画全受力：重力、支持力、绳张力、摩擦、外力","沿加速度方向和垂直方向建坐标","列 ΣFx = ma、ΣFy = 0（或 ma_y）联立求解"],"ex":{"q":"质量 m 在倾角 θ 的光滑斜面上由静止下滑，求加速度。","steps":["受力：重力 mg、支持力 N（光滑无摩擦）","沿斜面方向：mg sinθ = ma","a = g sinθ","垂直方向 N = mg cosθ。"]},"pit":"别把支持力当 mg；斜面问题务必沿斜面建坐标。"},{"t":"pt","no":"题型2","name":"连接体问题（绳 / 滑轮 / 两物一块）","feature":"两个及以上物体通过绳或接触一起运动，求共同加速度或绳张力。","method":"整体法求加速度，隔离法求内力（张力）。","steps":["对整体（各物一起）列 ΣF_外力 = (Σm)·a，求 a","再单独隔离其中一个物体，求绳张力等内力","注意轻绳张力两端相等、方向沿绳","检验：张力方向与物体运动方向的关系"],"ex":{"q":"m₁=2kg、m₂=3kg 用绳跨过光滑定滑轮相连(竖直)，求加速度与绳张力(g=10)。","steps":["整体：外力差 (m₂−m₁)g = (m₁+m₂)a","a = (3−2)×10/5 = 2 m/s²","隔离 m₁：T − m₁g = m₁a → T = 2×(10+2) = 24 N","验证 m₂：m₂g − T = m₂a → 30 − 24 = 6 = 3×2 ✓。"]},"pit":"整体法少算内力；轻绳张力处处相等但不能直接当外力。"},{"t":"pt","no":"题型3","name":"摩擦力方向的判断与临界问题","feature":"涉及静摩擦、滑动摩擦，或“恰好不滑动”的临界状态。","method":"静摩擦方向由相对运动趋势决定、大小由平衡方程定；临界时静摩擦取最大值 μN。","steps":["判断相对运动（趋势）方向 → 摩擦力反向","未滑动用静摩擦 f ≤ μN，由平衡/动力学方程求 f","滑动时用 f = μN","“恰好”类问题令 f = μN 联立求临界值"],"ex":{"q":"物块 m=1kg 放在水平面，μ=0.4，水平力 F=3N 拉它，求摩擦力(g=10)。","steps":["最大静摩擦 ≈ μN = 0.4×10 = 4 N","F=3N < 4N，物体不动","由平衡：f = F = 3 N（静摩擦）","只有当 F 超过 4N 才滑动。"]},"pit":"静摩擦力不一定是 μN，要由平衡方程求；方向看“相对趋势”不是“运动方向”。"},{"t":"pt","no":"题型4","name":"变力作用下的运动（微分方程 / 积分）","feature":"力是位置或速度的函数，如 F = −kx、阻力 F = −kv。","method":"写牛顿第二定律微分形式 m dv/dt = F，分离变量积分。","steps":["写出 m dv/dt = F(x) 或 F(v)","把 dt 换成 dv/a 或 dx/v 分离变量","积分并用初始条件定常数","得到 v(x) 或 v(t) 关系"],"ex":{"q":"质量 m 受阻力 F = −kv，初速 v₀，求 v(t)。","steps":["m dv/dt = −kv → dv/v = −(k/m)dt","两边积分 ln v = −(k/m)t + C","代 t=0,v=v₀ → C=ln v₀","v = v₀ e^(−kt/m)，随时间指数衰减。"]},"pit":"力是变力时不能用匀变速公式；先分离变量再积分。"},{"t":"pt","no":"题型5","name":"瞬时加速度与“绳 / 弹簧剪断”问题","feature":"讨论剪断绳或弹簧瞬间的加速度，考查弹性力能否突变。","method":"轻绳（刚性约束）张力可突变；弹簧弹力由形变决定、瞬间不变。","steps":["剪断前：求各绳、弹簧的力（平衡或动力学）","剪断瞬间：弹簧形变来不及变 → 弹力保持原值；绳的张力按新约束重算","对新状态重新列动力学方程求 a","注意连接体共同加速度约束是否仍成立"],"ex":{"q":"小球用绳悬挂并连一水平弹簧处于静止，剪断竖直绳瞬间，小球加速度如何？","steps":["剪前：绳张力 T = mg（竖直平衡）","剪断后：绳力立即消失 = 0","弹簧形变瞬间不变，其力仍存在","小球只受重力和弹簧力，按新受力求 a（不等于 g）。"]},"pit":"弹簧力瞬间不变、绳力瞬间消失，是最容易做错的点。"},{"t":"pt","no":"题型6",
"name":"圆轨道动力学（向心力方程）","feature":"物体做圆周运动，求绳张力、支持力、临界速率。","method":"沿半径方向列 ΣF_径向 = mv²/R = mω²R。","steps":["画径向受力（指向圆心为正）","列 F_向心 = mv²/R","结合竖直方向方程（若有重力）","“恰好过最高点”类令支持力/张力为 0"],"ex":{"q":"长 L 的轻绳系球在竖直平面做圆周运动，求过最高点的最小速率。","steps":["最高点：重力 + 绳张力提供向心力","临界时张力 T=0，仅重力提供向心力","mg = mv²/L → v_min = √(gL)","若 v < √(gL) 球会脱离圆轨道。"]},"pit":"向心加速度方向始终指向圆心；临界条件要明确“哪个力变为 0”。"},{"t":"tip","text":"<b>第2章解题总流程：</b>①先隔离研究对象画完整受力图；②整体求加速度、隔离求内力；③摩擦力先判方向再定大小（静/动不同）；④涉及“瞬间变化”想绳与弹簧的区别；⑤圆运动一律沿半径列向心力方程。"},{"t":"kw","items":["惯性定律","F=ma","F=dp/dt","受力分析四步","整体法+隔离法","摩擦力方向"]}]},"p3":{"no":"3","title":"动量守恒定律和能量守恒定律","tag":"力学 · 第3章","sub":"课本第3章。两大守恒定律——当过程复杂、只关心始末状态时，它们能跳过中间过程一步到位。","blocks":[{"t":"sh","no":"3.1","title":"质点和质点系的动量定理"},{"t":"tx","h":"冲量与动量定理","p":"<b>冲量</b> I = ∫F dt 是力对时间的累积；<b>动量</b> p = mv。<b>动量定理</b>：合外力的冲量等于动量的变化量。对质点系，只有外力才改变总动量（内力成对抵消）。"},{"t":"dv","title":"推导：动量定理 I = Δp","steps":["从牛顿第二定律出发：F = dp/dt","两边对时间积分：∫F dt = ∫(dp/dt) dt","左边即冲量 I，右边即动量变化 ∫dp = p₂ − p₁","⟹ <b>I = Δp = mv₂ − mv₁</b>","此式对变力、变质量也成立，比 F=ma 更普适"]},{"t":"fig","kind":"fig-momentum","cap":"冲量与动量定理：力对时间的累积 ∫F dt 等于动量变化 Δp"},{"t":"sh","no":"3.2","title":"动量守恒定律"},{"t":"tx","h":"守恒条件","p":"当质点系所受<b>合外力为零</b>时，系统总动量保持不变：Σmᵢvᵢ = 常矢量。即使合外力不为零，若某方向分量为零，则该方向动量守恒（分量守恒）。"},{"t":"sh","no":"3.3","title":"系统内质量移动问题（密歇尔斯基公式）"},{"t":"tx","h":"变质量系统","p":"<b>变质量系统</b>：当系统质量随时间变化（如火箭喷气、雨滴下落中水汽凝结、传送带落料）时，<b>F = ma 不再直接适用</b>，要用<b>密歇尔斯基方程</b> F = m·dv/dt − u·dm/dt 描述。其中 m 是当前系统质量，v 是系统速度，u 是脱离/并入质量相对系统的速度，dm/dt 是质量变化率（喷出时 dm/dt &lt; 0）。它把「外力」与「喷气反冲」分开写——这就是变质量问题的通用方程，火箭是它最著名的应用。"},{"t":"dv","goal":"把「变质量」问题化为「整体动量定理」来求","title":"推导：密歇尔斯基方程 F = m·dv/dt − u·dm/dt","steps":["设 t 时刻系统质量为 m、速度为 v（地面惯性系）；把系统与「即将喷出/并入的质量」取作整体研究对象。","经 dt 后，系统喷出质量 −dm（dm&lt;0 表示质量减少），剩余部分质量 m+dm、速度 v+dv；喷出物相对系统的速度为 u，故它在惯性系中的速度 ≈ v+u。","t 时刻整体动量：p₁ = m·v。","t+dt 时刻整体动量：p₂ = (m+dm)(v+dv) + (−dm)(v+u)。","展开并略去二阶小量 dm·dv：动量变化 Δp = p₂ − p₁ = m·dv − u·dm。","由动量定理 F·dt = Δp，两边除以 dt 得 <b>F = m·dv/dt − u·dm/dt</b>（密歇尔斯基方程）。","当外力 F = 0（深空自由飞行）时，得 m·dv/dt = u·dm/dt；对火箭（喷出使质量减少）积分即得齐奥尔科夫斯基公式 <b>Δv = u·ln(m₀/m)</b>（u 取喷气相对速度的大小，m₀ 为初始质量）。"]},{"t":"fig","kind":"fig-rocket","cap":"火箭喷气：喷出质量相对速度为 u，质量不断减少，反冲使火箭加速"},{"t":"sh","no":"3.4","title":"动能定理"},{"t":"tx","h":"功与动能","p":"<b>功</b> W = ∫F·dr（变力要积分）；<b>动能</b> Ek = ½mv²。<b>动能定理</b>：合外力做的功等于动能的变化，W合 = ΔEk。"},{"t":"dv","title":"推导：动能定理 W = ½mv₂² − ½mv₁²","steps":["合外力做功定义 W = ∫F·dr","代入 F = m·dv/dt：W = ∫ m(dv/dt)·dr = ∫ m v·dv（因 dr=v dt）",
"定积分 W = ∫(v₁→v₂) m v dv = m·[½v²]","⟹ <b>W = ½mv₂² − ½mv₁² = ΔEk</b>","关键一步是用 dr = v dt 把对位移的积分换成对速度的积分"]},{"t":"fig","kind":"fig-workenergy","cap":"动能定理：用 dr=v dt 把对位移的积分换成对速度的积分，得 W=ΔEk"},{"t":"sh","no":"3.5","title":"保守力与非保守力 势能"},{"t":"tx","h":"保守力与势能","p":"做功只与始末位置有关、与路径无关的力叫<b>保守力</b>（重力、弹性力、万有引力）；否则为<b>非保守力</b>（摩擦力）。只有保守力才能引入<b>势能</b>：Ep重力 = mgh，Ep弹性 = ½kx²，且保守力做功等于势能减少 W = −ΔEp。"},{"t":"sh","no":"3.6","title":"功能原理 机械能守恒定律"},{"t":"tx","h":"功能原理与机械能守恒","p":"外力与非保守内力做功之和等于机械能的改变：W外 + W非保内 = ΔE（功能原理）。当 W外=W非保内=0 时，机械能守恒 E = Ek + Ep = 常量。"},{"t":"sh","no":"3.7","title":"碰撞"},{"t":"tb","head":["类型","动量","动能","特点"],"rows":[["完全弹性","守恒","守恒","碰后分离，形变完全恢复"],["完全非弹性","守恒","不守恒(损失最大)","碰后粘在一起同速运动"],["一般非弹性","守恒","部分损失","介于两者之间(恢复系数 0<e<1)"]]},{"t":"fig","kind":"fig-collision","cap":"碰撞：水平方向外力为零，系统动量守恒；机械能是否守恒取决于碰撞类型"},{"t":"ex","q":"【典型例题】质量 m 的子弹以水平速度 v₀ 射入静止木块（质量 M，置于光滑水平面），并嵌入其中。求共同速度与损失的机械能。","steps":["水平方向外力为零 → 动量守恒：mv₀ = (M+m)v","共同速度 v = mv₀/(m+M)","碰前动能 Ek₀ = ½mv₀²","碰后动能 Ek = ½(M+m)v² = m²v₀²/[2(M+m)]","损失 ΔE = ½mv₀² − m²v₀²/[2(M+m)] = Mmv₀²/[2(M+m)]，转为热能/形变能。"]},{"t":"sh","no":"3.8","title":"能量守恒定律"},{"t":"tx","h":"普遍的能量守恒","p":"在孤立系统中，能量不会凭空产生或消失，只会从一种形式转化为另一种形式，总量保持不变。机械能守恒只是它在无耗散时的特例。"},{"t":"warn","text":"<b>易错点：</b>① 动量是矢量，一维要带正负号；② 完全非弹性碰撞动量守恒但机械能不守恒；③ 有摩擦时机械能不守恒但总能量守恒；④ 变力做功要积分或用动能定理，不能直接 F·s。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第3章习题）"},{"t":"pt","no":"题型1","name":"动量定理（冲量—动量关系）","feature":"涉及力、时间、速度变化，求平均冲力或速度改变。","method":"I = ∫F dt = Δp = m v₂ − m v₁，矢量式。","steps":["明确初末动量（注意方向）","写 Δp = m v₂ − m v₁（矢量/分量）","冲量 I = F̄·Δt = Δp，求平均力","碰撞、打击类常用“极短时间 → 冲力很大”"],"ex":{"q":"质量 0.2kg 球以 10 m/s 垂直撞墙后以 8 m/s 反弹，接触 0.01s，求平均冲力。","steps":["取离墙方向为正：v₁ = −10，v₂ = +8","Δp = 0.2×(8−(−10)) = 3.6 kg·m/s","F̄ = Δp/Δt = 3.6/0.01 = 360 N","注意速度反向必须带符号。"]},"pit":"动量、冲量是矢量，反弹问题初末速度符号相反。"},{"t":"pt","no":"题型2","name":"动量守恒（碰撞、爆炸、反冲）","feature":"系统合外力为零（或近似为零），求碰撞后速度、碎片速度。","method":"m₁v₁ + m₂v₂ = m₁v₁′ + m₂v₂′（矢量/分量）。","steps":["确认系统在作用时间内合外力≈0","写出作用前后总动量表达式","按分量（x、y）分别守恒","爆炸/反冲问题用初动量为零"],"ex":{"q":"质量 2kg 静止物体炸成 1kg 和 1kg 两块，其中一块以 4 m/s 向右飞，求另一块速度。","steps":["初总动量为 0","0 = 1×4 + 1×v₂","v₂ = −4 m/s（向左 4 m/s）","爆炸时动量守恒（内力远大于外力）。"]},"pit":"只在外力为零方向守恒；有摩擦/重力冲击时看能否忽略。"},{"t":"pt","no":"题型3","name":"完全弹性与非弹性碰撞","feature":"两球碰撞，判断碰后速度或能量损失。","method":"动量守恒 +（弹性）动能守恒；完全非弹性则碰后同速。","steps":["动量守恒列一式","判断类型：弹性 → 加动能守恒；完全非弹性 → v₁′=v₂′","联立求解","检查能量：弹性不损失，非弹性动能减少"],
"ex":{"q":"m₁=2kg 以 3 m/s 与静止 m₂=1kg 完全弹性正碰，求碰后速度。","steps":["动量：2×3 = 2v₁′ + 1v₂′","弹性另用相对速度关系 v₁ − v₂ = v₂′ − v₁′","解得 v₂′ = 4 m/s","回代动量得 v₁′ = 1 m/s。"]},"pit":"弹性碰撞有两个方程；非弹性只动量守恒，别乱用动能守恒。"},{"t":"pt","no":"题型4","name":"功的计算与动能定理","feature":"求某力做的功，或由功求速度变化。","method":"W = ∫F·dx = F·s·cosθ（恒力）；W_合 = ΔEₖ。","steps":["判断力是恒力还是变力","恒力 W = Fs cosθ（θ 为力与位移夹角）","变力用 W = ∫F dx（或图像面积）","合外力功 = 动能变化 ½mv² − ½mv₀²"],"ex":{"q":"质量 2kg 物体从静止被水平力 6N 沿光滑面推 5m，求末速度。","steps":["合外力功 W = 6×5 = 30 J","动能定理 30 = ½×2×v²","v² = 30 → v = √30 ≈ 5.5 m/s","摩擦力存在时须扣除摩擦做功。"]},"pit":"功是可正可负的标量；cosθ 别忘，垂直方向力不做功。"},{"t":"pt","no":"题型5","name":"保守力做功与势能","feature":"涉及重力势能、弹性势能、引力势能的变化。","method":"W_保 = −ΔE_p；E_p(重) = mgh，E_p(弹) = ½kx²。","steps":["确定零势能面","写 E_p 表达式","用重力/弹力做功 = 势能减少量","注意势能是系统共有、有相对性"],"ex":{"q":"弹簧 k=200 N/m 压缩 0.1m，求弹性势能。","steps":["E_p = ½kx²","= ½×200×0.01 = 1 J","若释放，此能量转为动能","势能总是相对零势能点而言。"]},"pit":"势能是相对量，先定零点；弹性势能是 ½kx² 不是 kx。"},{"t":"pt","no":"题型6","name":"机械能守恒（含斜面、圆轨道、弹簧）","feature":"只有重力和弹力做功，求某位置速度或高度。","method":"E₁ = E₂：½mv² + mgh + ½kx² 守恒。","steps":["判断是否只有重力/弹力做功（无摩擦）","选两状态写总机械能","列守恒方程求解","有摩擦则用能量守恒 E_初 = E_末 + Q"],"ex":{"q":"小球从高 h 的 1/4 圆弧（光滑 R=h）顶点滑到底端，求底端速度。","steps":["只有重力做功，机械能守恒","mgR = ½mv²","v = √(2gR)","与形状无关，只与高度差有关。"]},"pit":"有摩擦时机械能不守恒，要用能量守恒把摩擦生热算进去。"},{"t":"pt","no":"题型7","name":"能量守恒综合（含摩擦生热、连接体）","feature":"多过程、含摩擦或绳滑轮的能量问题。","method":"E_初 = E_末 + Q，Q = f·s_相对（摩擦生热）。","steps":["选全过程初末两态","计算初末机械能","算摩擦生热 Q = 摩擦力 × 相对滑动路程","列能量守恒方程求解未知量"],"ex":{"q":"物块以 v₀ 沿粗糙水平面滑行，μ、g 已知，求滑行距离。","steps":["初动能 ½mv₀²","末动能为 0","摩擦生热 Q = μmgs","能量守恒 ½mv₀² = μmgs → s = v₀²/(2μg)。"]},"pit":"摩擦生热的“路程”是相对滑动路程，不是位移。"},{"t":"pt","no":"题型8","name":"质心与质心运动定理","feature":"求系统质心位置，或由外力判断质心运动。","method":"r_c = Σmᵢrᵢ/Σmᵢ；F_外 = M·a_c（内力不改变质心运动）。","steps":["写出各质点质量与位置","用加权平均求质心坐标","质心运动只看外力，与内力无关","爆炸/人走船动类问题用质心不动求解"],"ex":{"q":"质量 2kg 在 x=0、3kg 在 x=5m，求系统质心。","steps":["x_c = (2×0 + 3×5)/(2+3)","= 15/5 = 3 m","质心偏向量大的一方","爆炸问题中质心按原运动继续。"]},"pit":"质心不是几何中心，是质量加权；内力不影响质心运动。"},{"t":"tip","text":"<b>第3章解题总流程：</b>①先看“过程”——求力/时间用动量，求速率/高度用能量；②动量题注意矢量方向、判断守恒方向；③能量题先试机械能是否守恒，不守恒就加摩擦生热；④碰撞先分类（弹性/非弹性）；⑤多过程用整体能量守恒更省事。"},{"t":"kw","items":["冲量I=Δp","动量守恒条件","动能定理","势能Ep","机械能守恒","碰撞三类型"]}]},"p4":{"no":"4","title":"刚体","tag":"力学 · 第4章","sub":"课本第4章。把“力—加速度”升级为“力矩—角加速度”，并引入角动量守恒，是力学的高阶形态。","blocks":[{"t":"sh","no":"4.1","title":"刚体运动的描述"},{"t":"tx","h":"平动与定轴转动","p":"<b>刚体</b>是形变可忽略的质点系，任意两点距离恒定。运动分为<b>平动</b>（各点轨迹相同，可当质点处理）、<b>定轴转动</b>（各点绕固定轴做圆周运动）和一般运动。定轴转动用角量 θ、ω、α 描述。"},
{"t":"sh","no":"4.2","title":"力矩 转动定律 转动惯量"},{"t":"tx","h":"力矩与转动定律","p":"<b>力矩</b> M = F·d（d 为力臂，即转轴到力作用线的垂直距离）。<b>转动定律</b>：M = Jα，其中<b>转动惯量</b> J = Σmᵢrᵢ² = ∫r²dm 是刚体转动的惯性度量，取决于质量分布与转轴位置。"},{"t":"anim","kind":"anim-rotate","cap":"定轴转动：力矩 M 越大，角加速度 α 越大，M = Jα"},{"t":"dv","title":"推导：转动定律 M = Jα","steps":["把刚体看成许多质元 mᵢ，各质元绕轴转动，切向加速度 aᵢ = rᵢα","对第 i 个质元用牛顿第二定律：Fᵢ = mᵢaᵢ = mᵢrᵢα（切向）","两边乘以 rᵢ 得力矩：Mᵢ = Fᵢ rᵢ = mᵢrᵢ²α","对所有质元求和：ΣMᵢ = (Σmᵢrᵢ²)α","⟹ <b>M = Jα</b>，与 F=ma 完全对应（力↔力矩、质量↔转动惯量、a↔α）"]},{"t":"fig","kind":"fig-rot-mini","inline":true,"cap":"转动定律：合外力矩 M 产生角加速度 α"},{"t":"tb","head":["刚体","转轴","转动惯量 J"],"rows":[["细棒 长L 质量m","过中心垂直棒","mL²/12"],["细棒 长L 质量m","过端点垂直棒","mL²/3"],["圆环/薄圆筒 半径R","中心轴","mR²"],["圆盘/实心圆柱 半径R","中心轴","½mR²"],["实心球 半径R","过球心","(2/5)mR²"]]},{"t":"ex","q":"【典型例题】质量 m、半径 R 的匀质圆盘绕中心轴自由转动，边缘受切向力 F。求角加速度。","steps":["圆盘绕中心轴：J = ½mR²","切向力垂直于半径，力臂 d = R → M = F·R","由 M = Jα：α = M/J = FR/(½mR²) = 2F/(mR)","结论：α 与 R 成反比；同半径下圆盘比圆环比圆环更容易转（J 更小）。"]},{"t":"sh","no":"4.3","title":"角动量 角动量守恒定律"},{"t":"tx","h":"角动量与守恒","p":"<b>角动量</b> L = Jω（定轴转动）。<b>角动量定理</b>：M = dL/dt。当合外力矩为零时，角动量守恒 Jω = 常量——转动惯量变小则角速度变大（如花样滑冰收臂加速旋转）。"},{"t":"sh","no":"4.4","title":"力矩做功 刚体绕定轴转动的动能定理"},{"t":"tx","h":"转动动能与动能定理","p":"<b>转动动能</b> Ek = ½Jω²。<b>转动动能定理</b>：合外力矩做的功等于转动动能的改变，W = ∫M dθ = ½Jω₂² − ½Jω₁²。对比平动 W = ½mv₂² − ½mv₁²。"},{"t":"ex","q":"【典型例题】长 L、质量 m 的匀质细棒可绕一端水平轴转动，从水平位置释放。求转到竖直位置时的角速度。","steps":["棒绕端点转动惯量 J = mL²/3","重心下降高度：从水平到竖直，重心下降 L/2","机械能守恒：mg·(L/2) = ½Jω²","代入 J：mgL/2 = ½·(mL²/3)·ω²","解得 ω = √(3g/L)，与课本用能量法求解一致。"]},{"t":"warn","text":"<b>易错点：</b>① 力矩要用垂直距离(力臂)，不是径向长度；② 转动惯量随转轴变，必须先确认转轴；③ 角量线量关系 v=ωR、aₜ=αR 只适用于对应点；④ 纯滚动用“平动方程+转动方程+无滑动 a=Rα”三式联立。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第4章习题）"},{"t":"pt","no":"题型1","name":"转动惯量 J 的计算","feature":"求刚体（杆、圆盘、球、圆柱）绕轴的转动惯量。","method":"J = ∫r²dm；常用 J = ½mR²(盘)、⅓mL²(端点杆)、1/12 mL²(中心杆)、⅖mR²(球)。","steps":["确定转轴位置","选质量元 dm，写 r（到轴距离）","积分 J = ∫r²dm；均匀体用密度换元","平行轴定理 J = J_c + md² 处理偏心轴"],"ex":{"q":"质量 m、长 L 的细杆绕一端垂直轴转，求 J。","steps":["取距端点 x 处微元 dm = (m/L)dx","J = ∫₀ᴸ x²(m/L)dx","= (m/L)(L³/3) = mL²/3","绕中点则为 mL²/12（平移轴定理）。"]},"pit":"转动惯量与转轴位置有关；换轴要用平行轴定理。"},{"t":"pt","no":"题型2","name":"转动定律 M = Jα","feature":"求刚体的角加速度、角速度或所受力矩。","method":"对定轴列 M = Jα，与牛顿第二定律 F = ma 完全类比。","steps":["求合外力矩 M = ΣF·r（注意力臂）","求转动惯量 J","用 M = Jα 求 α","再用运动学求 ω、θ"],"ex":{"q":"质量 m 半径 R 的圆盘受切向力 F，求角加速度。","steps":["力矩 M = F·R","圆盘 J = ½mR²",
"M = Jα → F R = ½mR²·α","α = 2F/(mR)。"]},"pit":"力矩要看力臂（到轴的垂直距离），不是到原点距离。"},{"t":"pt","no":"题型3","name":"绳绕滑轮 / 连接体的转动动力学","feature":"绳跨滑轮带物体，滑轮有质量需考虑转动。","method":"平动部分用 F=ma，滑轮用 M=Jα，绳张力两端不等（因滑轮有转动惯量）。","steps":["隔离各物体，写平动方程","对滑轮写 M = Jα（两侧张力差×R）","用绳不打滑关联 a = Rα","联立求解未知张力与加速度"],"ex":{"q":"质量 m 的物块用绳绕过质量 M、半径 R 的圆盘下滑，求加速度。","steps":["物块：mg − T = ma","圆盘：T·R = ½MR²·α = ½MR²·(a/R)","由圆盘式得 T = ½Ma","代入：mg = (m + ½M)a → a = mg/(m + M/2)。"]},"pit":"滑轮有质量时绳两侧张力不等，这是最常见错误。"},{"t":"pt","no":"题型4","name":"角动量守恒","feature":"合外力矩为零，求角速度变化（如人收臂、行星、转台）。","method":"L = Jω = 常量；或 L = r × mv。","steps":["确认合外力矩为零","写初末角动量 J₁ω₁ = J₂ω₂","J 变化时反比于 ω","质点问题用 L = mvr sinθ"],"ex":{"q":"转台转动惯量 J=4kg·m²，ω=2rad/s，一人把转动惯量增至 8，求新角速度。","steps":["角动量守恒 J₁ω₁ = J₂ω₂","4×2 = 8×ω₂","ω₂ = 1 rad/s","J 增大一倍，ω 减半。"]},"pit":"角动量守恒条件是无外力矩；J 改变时 ω 反比变化。"},{"t":"pt","no":"题型5","name":"力矩做功、转动动能与动能定理","feature":"由力矩求做功、求转动动能或角速度。","method":"W = ∫M dθ；Eₖ = ½Jω²；W = ΔEₖ。","steps":["恒力矩 W = Mθ","转动动能 Eₖ = ½Jω²","用动能定理 W = ΔEₖ 求解","平动 + 转动能量叠加"],"ex":{"q":"圆盘 J=0.5kg·m² 从静止在恒力矩 2N·m 下转 3rad，求角速度。","steps":["力矩做功 W = Mθ = 2×3 = 6 J","= ΔEₖ = ½Jω²","6 = ½×0.5×ω² → ω² = 24","ω ≈ 4.9 rad/s。"]},"pit":"转动动能是 ½Jω²（不是 ½mv²）；功是力矩乘角位移。"},{"t":"pt","no":"题型6","name":"刚体的纯滚动（平动 + 转动）","feature":"圆柱/球沿斜面纯滚动下滑，求加速度或速度。","method":"平动 ma = mg sinθ − f，转动 fR = Jα，纯滚动 v = Rω、a = Rα。","steps":["沿斜面列平动方程 ma = mg sinθ − f","对质心列转动方程 fR = J·(a/R)","联立消去摩擦力 f 求 a","用能量法复核或求速度"],"ex":{"q":"质量 m、半径 R 的实心圆柱沿倾角 θ 斜面纯滚动，求加速度。","steps":["平动：mg sinθ − f = ma","转动：fR = ½mR²·(a/R) → f = ½ma","代入：mg sinθ = 1.5ma","a = (2/3)g sinθ（球为 5/7 g sinθ）。"]},"pit":"纯滚动有摩擦但不生热（接触点无相对滑动）；平动转动同时用两组方程。"},{"t":"tip","text":"<b>第4章解题总流程：</b>①先想“平动类 F=ma，转动类 M=Jα”；②滑轮有质量必用转动方程，张力两端不等；③角动量守恒看有无外力矩；④纯滚动联立平动+转动+滚动约束；⑤能量题别忘了 ½Jω² 这一项。"},{"t":"kw","items":["转动惯量J","力矩M=Fd","M=Jα","角动量L=Jω","转动动能","平行轴定理"]}]},"p5":{"no":"5","title":"静电场","tag":"电磁 · 第5章","sub":"课本第5章。从库仑定律出发，依次建立电场强度、高斯定理、环路定理、电势——完整的静电场理论链。","blocks":[{"t":"sh","no":"5.1","title":"电荷 库仑定律"},{"t":"tx","h":"电荷与库仑定律","p":"电荷量子化、守恒。真空中两个静止点电荷间的作用力由<b>库仑定律</b>给出，大小与电荷量乘积成正比、与距离平方成反比，方向沿连线（同号相斥、异号相吸）。"},{"t":"fx","lines":["库仑定律  F = (1/4πε₀)·q₁q₂/r²","方向：沿两电荷连线，同性相斥、异性相吸","k = 1/4πε₀ ≈ 9×10⁹ N·m²/C²"]},{"t":"sh","no":"5.2","title":"电场强度"},{"t":"tx","h":"电场与场强","p":"<b>电场强度</b> E = F/q₀ 定义为单位正电荷在场中受到的力，是场自身的属性，与检验电荷 q₀ 无关。点电荷场 E = (1/4πε₀)q/r²，方向由正电荷向外。<b>场强叠加原理</b>：E = ΣEᵢ（矢量求和）。"},{"t":"dv","title":"推导：点电荷场强的方向与大小",
"steps":["由库仑定律，检验电荷 q₀ 受点电荷 q 的力：F = (1/4πε₀)q q₀/r²","按定义 E = F/q₀","⟹ <b>E = (1/4πε₀)q/r²</b>","方向：若 q>0，E 与 F 同向，背离 q（发散）；若 q<0，E 指向 q","叠加：多电荷时各 Eᵢ 矢量相加，需分解 x/y 分量再合成"]},{"t":"sh","no":"5.3","title":"电场线 电场强度通量"},{"t":"tx","h":"电场线与电通量","p":"<b>电场线</b>起于正电荷止于负电荷（或伸向无穷远），疏密表示场强大小。通过面积的电通量 Φₑ = ∫E·dS；闭合曲面电通量 Φₑ = ∮E·dS = ∮E·cosθ dS。"},{"t":"sh","no":"5.4","title":"高斯定理"},{"t":"tx","h":"高斯定理","p":"通过任意闭合曲面的电通量，等于该曲面所包围的净电荷除以 ε₀，与面外电荷无关。"},{"t":"tx","h":"常见对称带电体的场强","p":"用高斯定理可快速求出几类高对称情形：均匀带电球面（外部等效点电荷、内部为零）、无限长直线、无限大平面。"},{"t":"anim","kind":"anim-gauss","cap":"高斯定理：穿出闭合面的电通量只由面内净电荷决定，与面外电荷无关"},{"t":"dv","title":"推导：高斯定理 ∮E·dS = q内/ε₀","steps":["先取以点电荷 q 为球心、半径 r 的球面；由对称性 E 处处沿径向且大小相同","∮E·dS = E·∮dS = E·4πr²","代入点电荷场 E = (1/4πε₀)q/r²","得 ∮E·dS = (1/4πε₀)(q/r²)·4πr² = q/ε₀","由叠加原理，对任意电荷分布推广为 ∮E·dS = Σq内/ε₀（面外电荷贡献通量为零）"]},{"t":"fig","kind":"fig-gauss-mini","inline":true,"cap":"高斯面：电通量只由面内电荷决定"},{"t":"dv","title":"推导：无限大均匀带电平面的场强 E = σ/2ε₀","steps":["面对称 → 取垂直于平面、面积 S 的圆柱高斯面，两底面穿过平面两侧","侧面电场平行于面，通量为 0；两底面通量各为 E·S，合计 2ES","高斯面内电荷 = 面密度 σ × 底面积 S = σS","由高斯定理：2ES = σS/ε₀","⟹ <b>E = σ/2ε₀</b>（与距离无关！）"]},{"t":"fig","kind":"fig-plane-gauss","cap":"圆柱形高斯面穿过无限大带电平面：侧面通量为 0，两底面合计 2ES，故 E = σ/2ε₀"},{"t":"ex","q":"【典型例题】半径 R、均匀带电总量 Q 的球体（体电荷）。求球内、外的场强分布。","steps":["球对称 → 取半径 r 的同心球面作高斯面，Φ = E·4πr²","<b>球外 r≥R</b>：Σq内 = Q → E = Q/(4πε₀r²)，等效为点电荷","<b>球内 r<R</b>：仅包围部分电荷，Σq内 = Q·(r³/R³)（按体积比例）","代入：E·4πr² = Q(r³/R³)/ε₀ → E = Qr/(4πε₀R³)","结论：球内 E 与 r 成正比，球面处最大，球外按 1/r² 衰减。"]},{"t":"sh","no":"5.5","title":"静电场的环路定理"},{"t":"tx","h":"环路定理","p":"<b>环路定理</b>：把单位正电荷沿任意闭合路径绕一圈，静电场力做功 ∮E·dl = 0——即电场力做功<b>只与始点、终点位置有关，与路径无关</b>。这说明静电场是<b>保守场（有势场）</b>。正因为做功与路径无关，才能把「某点的电势」唯一地定义出来——所以环路定理是引入<b>电势</b>的理论依据，也是点电荷电势公式 V = q/4πε₀r 的来源。"},{"t":"fig","kind":"fig-loop","cap":"沿任意闭合路径绕行一周回到起点，静电场力做功为零"},{"t":"sh","no":"5.6","title":"电势能 电势 等势面"},{"t":"tx","h":"电势能与电势","p":"<b>电势能</b> W 是电荷在电场中因位置而具有的能量；<b>电势</b> V = W/q₀ 是标量，等于单位正电荷在该点所具有的电势能。点电荷电势 V = (1/4πε₀)q/r；多个电荷叠加时，电势是<b>标量，直接代数相加</b>（不必像场强那样分解方向）。把 V 相等的点连成的面叫<b>等势面</b>，它处处与电场线垂直。"},{"t":"fig","kind":"fig-potential","cap":"点电荷的等势面（同心球面）：越靠外电势越低，E 垂直等势面"},{"t":"dv","title":"推导：点电荷电势 V = q/4πε₀r","steps":["电势差定义 Va − Vb = ∫(a→b) E·dl","取从 a 到无穷远的路径，令 V∞ = 0","V = ∫(r→∞) (1/4πε₀)q/r² dr","积分 = (1/4πε₀)q·[−1/r] 从 r 到 ∞ = (1/4πε₀)q/r","⟹ <b>V = (1/4πε₀)q/r</b>，V 是标量，叠加时直接代数相加"]},{"t":"sh","no":"5.7","title":"电场强度与电势梯度"},{"t":"tx","h":"场强与电势的关系",
"p":"<b>场强与电势的关系</b>：电场线总是指向电势<b>降低最快</b>的方向，而场强的大小等于电势沿该方向的变化率，即梯度关系 <b>E = −dV/dn</b>（负号表示 E 指向电势降低的方向，n 为等势面的法线方向）。由此：已知电势 V(r) 求导可得场强 E；已知场强 E 沿路径积分可得电势 V——两者互为逆运算，做题时「求场强还是求电势」先想清楚用哪一边。"},{"t":"fig","kind":"fig-gradient","cap":"E 垂直于等势面，指向电势降低最快的方向，大小 E = −dV/dn"},{"t":"sh","no":"5.8","title":"静电场中的电偶极子"},{"t":"tx","h":"电偶极子","p":"电偶极子由等量异号电荷 +q、−q 相距 l 组成，<b>电偶极矩</b> p = ql，方向由负到正。在匀强电场中受<b>力矩</b> M = p×E，趋于与 E 同向；其电势能 W = −p·E，平衡位置为 p 与 E 平行。"},{"t":"ex","q":"【典型例题】两个等量异号点电荷 +q、−q 相距 2a。求连线中点处的场强与电势。","steps":["中点处 +q 的场指向远离 +q（即指向 −q），大小 E₊ = kq/a²","−q 的场也指向 −q（远离 +q），大小 E₋ = kq/a²","两场同向 → 合场强 E = 2kq/a² = q/(2πε₀a²)，方向由 +q 指向 −q","电势是标量：V = kq/a + k(−q)/a = 0","对比：中点电势为零，但场强不为零——电势与场强是不同概念。"]},{"t":"warn","text":"<b>易错点：</b>① E 是矢量必须分解求和，不能标量相加；② 场强与检验电荷 q₀ 无关；③ 高斯定理对任意曲面成立，但只有高对称时才能求出 E；④ 无限大平面场强与距离无关；⑤ 电势是标量可代数相加，但需指定零电势参考点。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第5章习题）"},{"t":"pt","no":"题型1","name":"库仑定律与点电荷场强","feature":"求点电荷或点电荷系在某点产生的电场强度。","method":"E = kq/r²（点电荷），矢量叠加；E = F/q₀ 为定义。","steps":["确定各场源电荷的位置、电量、正负","写出该点到每一点电荷的距离与方向","各点电荷场强分别求大小，再矢量合成","对称分布可利用对称性简化"],"ex":{"q":"两等量同种点电荷 +q 相距 2a，求连线中点场强。","steps":["中点距每个电荷 a","两电荷在中点场强大小都 = kq/a²","方向相反（同种电荷）","矢量合成 = 0，中点场强为零。"]},"pit":"场强是矢量，不能代数相加；先定方向再合成。"},{"t":"pt","no":"题型2","name":"连续带电体场强（积分与对称）","feature":"带电直线、圆环、圆盘的场强。","method":"取微元 dq，写 dE = kdq/r²，再积分（注意矢量投影）。","steps":["取电荷元 dq = λdl 或 σdS","写 dE 大小及方向","把 dE 投影到坐标方向","利用对称性消去某些分量再积分"],"ex":{"q":"均匀带电圆环(半径 R, 电量 q)轴线上距圆心 x 处的场强。","steps":["微元 dq 到场点距离 r = √(R²+x²)","垂直轴分量两两抵消","沿轴分量 dE·cosθ，cosθ = x/r","积分得 E = kqx/(R²+x²)^{3/2}。"]},"pit":"圆环问题直接套结论；积分前先分析哪些分量能抵消。"},{"t":"pt","no":"题型3","name":"高斯定理求场强（球 / 圆柱 / 平面）","feature":"具有球、柱、面对称的带电体，求场强分布。","method":"∮E·dS = Σq/ε₀，对称面 E 大小恒定且垂直于面。","steps":["由对称性判断场 E 沿半径（或垂直面）方向","作同心的高斯面","写 ∮E·dS = E·S = q_内/ε₀","解出场强，注意“内外部”分段"],"ex":{"q":"均匀带电球面(半径 R, 电量 Q)，求球内外场强。","steps":["球外 r>R：高斯面内 q=Q，E·4πr² = Q/ε₀ → E = Q/(4πε₀r²)","球内 r<R：高斯面内电荷为 0 → E = 0","结论：均匀带电球面外部等效点电荷，内部场强为零。"]},"pit":"高斯面内只算“内部电荷”；球对称内部分段易错。"},{"t":"pt","no":"题型4","name":"电势与电势差的计算","feature":"求某点电势、两点电势差或电势能。","method":"点电荷 φ = kq/r；φ = ∫E·dl；V_ab = φ_a − φ_b；W = q(φ_a − φ_b)。","steps":["选电势零点（通常无穷远）","点电荷用叠加 φ = Σkqᵢ/rᵢ","连续体用积分 φ = ∫kdq/r","电势差用 φ_a − φ_b，电场力做功 W = qU"],"ex":{"q":"点电荷 q=2×10⁻⁸C，求距它 0.1m 处电势(k=9×10⁹)。","steps":["φ = kq/r","= 9×10⁹ × 2×10⁻⁸ / 0.1","= 180/0.1 = 1800 V","电势是标量，叠加时取电荷正负号。"]},
"pit":"电势是标量可代数相加（带正负号）；电势差与零点选择无关。"},{"t":"pt","no":"题型5","name":"电场力做功与电势能","feature":"电荷在电场中移动，求功或电势能变化。","method":"W = qU = q(φ_a − φ_b)；E_p = qφ；W = −ΔE_p。","steps":["确定初末位置的电势","W = q(φ_a − φ_b)（电场力做功）","电势能 E_p = qφ（注意电荷正负）","电势能减少 = 电场力做正功"],"ex":{"q":"电量 1μC 从 100V 移到 20V 处，求电场力做功。","steps":["W = q(φ_a − φ_b)","= 1×10⁻⁶ ×(100−20)","= 8×10⁻⁵ J","正电荷从高电势到低电势，电场力做正功。"]},"pit":"负电荷情况做功正负相反；E_p = qφ 中 q 要带符号。"},{"t":"pt","no":"题型6","name":"电偶极子与均匀场中的电偶极矩","feature":"涉及电偶极子 p=ql 的力矩、势能或场强。","method":"均匀场中 M = p×E，W = −p·E = −pEcosθ。","steps":["写电偶极矩 p = ql（方向从负到正）","均匀场力矩 M = pE sinθ","势能 E_p = −pE cosθ","非均匀场还有净力（梯度）"],"ex":{"q":"电偶极子 p=2×10⁻²⁹C·m 在 E=10⁴V/m 中与场成 90°，求力矩。","steps":["M = pE sinθ","= 2×10⁻²⁹ × 10⁴ × sin90°","= 2×10⁻²⁵ N·m","θ=0 或 π 时力矩为零（稳定/不稳定平衡）。"]},"pit":"均匀场中电偶极子受合力为零、只受力矩；势能随角度变化。"},{"t":"pt","no":"题型7","name":"带电粒子在电场中的运动","feature":"带电粒子在均匀电场中加速或偏转。","method":"加速用动能定理 qU = ½mv²；偏转类平抛（a = qE/m）。","steps":["判断是加速还是偏转","加速：qU = ½mv²","偏转：沿场方向匀加速，垂直方向匀速（类平抛）","偏转量 y = ½at²，t = L/v₀"],"ex":{"q":"电子经 U=100V 加速，求末速度(m=9.1×10⁻³¹kg, e=1.6×10⁻¹⁹C)。","steps":["qU = ½mv²","v = √(2qU/m)","= √(2×1.6×10⁻¹⁹×100 / 9.1×10⁻³¹)","≈ 5.9×10⁶ m/s。"]},"pit":"偏转是类平抛，水平和竖直分运动分开算；别忘电荷符号影响方向。"},{"t":"tip","text":"<b>第5章解题总流程：</b>①先判断“求场强”还是“求电势”——场强是矢量、电势是标量；②对称性优先用高斯定理；③连续带电体取微元积分，注意抵消分量；④电势叠加带电荷正负号；⑤粒子运动先分加速/偏转。"},{"t":"kw","items":["库仑定律","E=F/q₀","电通量","高斯定理","环路定理","电偶极矩"]}]},"p6":{"no":"6","title":"静电场中的导体和电介质","tag":"电磁 · 第6章","sub":"课本第6章（当前进度）。导体中电荷会重排、电介质会被极化，本章讨论它们对静电场的影响，并引入电容与电场能量。","blocks":[{"t":"sh","no":"6.1","title":"静电场中的导体"},{"t":"tx","h":"静电平衡条件","p":"导体放入电场后，自由电荷重新分布直到内部场强处处为零，称<b>静电平衡</b>。此时：导体内部 E=0，导体表面 E 垂直于表面，整个导体是<b>等势体</b>，表面是等势面。"},{"t":"tx","h":"电荷分布与静电屏蔽","p":"静电平衡时电荷只分布在<b>外表面</b>，且尖端处面电荷密度大（<b>尖端放电</b>）。<b>静电屏蔽</b>：空腔导体内部不受外场影响，接地的空腔导体还能屏蔽腔内电荷对外场的影响。"},{"t":"ex","q":"【典型例题】为什么静电平衡时导体内部场强一定为零？","steps":["假设导体内部存在电场 E ≠ 0","则自由电子会受电场力而继续定向移动","这与“静电平衡（电荷不再移动）”矛盾","所以必须 E_内 = 0","推论：导体内部无净电荷，电荷只能分布在外表面。"]},{"t":"sh","no":"6.2","title":"静电场中的电介质 电介质中的高斯定理"},{"t":"tx","h":"极化与相对电容率","p":"<b>电介质</b>是绝缘体，无自由电荷，但会被电场<b>极化</b>（正负电荷中心分离），产生极化电荷，削弱原场。相对电容率 εᵣ = ε/ε₀ ≥ 1，真空为 1。"},{"t":"tx","h":"电极化强度与有介质的高斯定理","p":"<b>电极化强度</b> P = Σp/ΔV 描述极化程度。引入<b>电位移矢量</b> D = ε₀E + P 后，有介质的高斯定理形式简洁：∮D·dS = Σq₀（只数自由电荷）。线性的 D = εE = ε₀εᵣE。"},{"t":"dv","title":"推导：有介质时的高斯定理 ∮D·dS = Σq₀","steps":["无极/有极分子在电场中产生极化电荷 q′，它是“束缚电荷”","对任意高斯面：∮E·dS = (Σq₀ + Σq′)/ε₀（自由电荷+束缚电荷）",
"把极化电荷用 P 表达：Σq′ = −∮P·dS","代入并移项：∮(ε₀E + P)·dS = Σq₀","定义 D = ε₀E + P ⟹ <b>∮D·dS = Σq₀</b>，只需数自由电荷，方便！"]},{"t":"sh","no":"6.3","title":"电容 电容器"},{"t":"tx","h":"电容","p":"<b>孤立导体电容</b> C = Q/V。平行板电容器 C = εS/d（含介质时 C = ε₀εᵣS/d），即极板面积越大、间距越小、介质电容率越大，电容越大。电容器串联 1/C = Σ1/Cᵢ，并联 C = ΣCᵢ。"},{"t":"fig","kind":"fig-capacitor","cap":"平行板电容器：板间为匀强电场 E=V/d，电容 C=εS/d"},{"t":"dv","title":"推导：平行板电容器 C = εS/d","steps":["平行板间可视为匀强电场（忽略边缘效应）","由高斯定理，两板间场强 E = σ/ε = Q/(εS)","两板电势差 V = E·d = Qd/(εS)","由电容定义 C = Q/V = Q·εS/(Qd)","⟹ <b>C = εS/d = ε₀εᵣS/d</b>"]},{"t":"sh","no":"6.4","title":"静电场的能量 能量密度"},{"t":"tx","h":"电场能量","p":"带电电容器储存的能量 W = ½CV² = ½QV = Q²/2C。<b>电场能量密度</b> w = ½εE²，即能量储存在电场中，总能量 W = ∫w dV。"},{"t":"dv","title":"推导：平行板电容器能量 W = ½CV² 与 w = ½εE²","steps":["充电过程中把电荷 dq 从一板搬到另一板，克服电压做功 dW = V′ dq","某时刻电量 q，电压 V′ = q/C，积分：W = ∫₀^Q (q/C) dq = Q²/(2C)","又 Q = CV ⟹ <b>W = ½CV²</b>","用 W = ½CV² 除以体积 V_体 = Sd，并代入 C=εS/d、E=V/d","w = W/(Sd) = ½(εS/d)V²/(Sd) = ½εE² ⟹ <b>w = ½εE²</b>"]},{"t":"ex","q":"【典型例题】平行板电容器极板面积 S=2×10⁻² m²，间距 d=1mm，中间充满 εᵣ=4 的介质。求电容（ε₀=8.85×10⁻¹²）。","steps":["用 C = ε₀εᵣS/d","代入数值：C = 8.85×10⁻¹² × 4 × 2×10⁻² / 1×10⁻³","= (8.85×2×4)×10⁻¹² × 10⁻² / 10⁻³","= 70.8×10⁻¹² × 10 = 7.08×10⁻¹⁰ F","结论：介质使电容增大为真空时的 εᵣ=4 倍。"]},{"t":"ex","q":"【典型例题】上述电容器接在电压 V=100V 的电源上。求储存的能量与电场能量密度。","steps":["能量 W = ½CV² = ½ × 7.08×10⁻¹⁰ × 100²","W ≈ 3.54×10⁻⁶ J","场强 E = V/d = 100/10⁻³ = 10⁵ V/m","能量密度 w = ½εE² = ½ × (8.85×10⁻¹²×4) × (10⁵)²","≈ 0.177 J/m³，与 W=w·(Sd) 一致。"]},{"t":"warn","text":"<b>易错点：</b>① 静电平衡时电荷在外表面，内部无净电荷；② D 的高斯定理只数自由电荷，别忘了；③ 平行板场强 E=σ/ε 与 E=V/d 可互推，别搞混；④ 电容器串联电容变小、并联变大（与电阻相反）；⑤ 电场能量密度 w=½εE²，ε 含介质。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第6章习题）"},{"t":"pt","no":"题型1","name":"导体的静电平衡（电荷分布与场强）","feature":"导体在电场中达到平衡，求内部场强、表面电荷、电势。","method":"静电平衡三结论：内部 E=0、导体是等势体、净电荷分布外表面（尖端密）。","steps":["利用“导体内部场强为零”判断是否达到平衡","表面场强方向垂直表面、大小 σ/ε₀","导体整体等势","由电荷守恒与等势求电荷分配"],"ex":{"q":"孤立实心导体带电 Q，求其内部与表面场强。","steps":["静电平衡：内部场强 E=0","电荷全部分布在外表面","表面附近 E = σ/ε₀，垂直于表面","整个导体是等势体，内部与表面电势相等。"]},"pit":"导体内部场强为零但电势不一定为零；场强为零不等于无电荷。"},{"t":"pt","no":"题型2","name":"静电屏蔽与腔体问题","feature":"导体空腔内外电荷分布、屏蔽作用。","method":"空腔无电荷：内表面无电荷；腔内有电荷：内表面感应等量异号电荷。","steps":["判断空腔内是否有电荷","无电荷：内表面电荷为 0，壳外电荷不变","有电荷 q：内表面感应 −q，外壳表面 Q+q","外壳接地则外部场为零（屏蔽）"],"ex":{"q":"不带电导体球壳内有电荷 +q，壳外带电 Q，求外表面电荷。","steps":["内表面感应 −q（与腔内电荷平衡）","电荷守恒：内表面(−q) + 外表面 = Q","外表面 = Q + q","外部场强由 Q+q 等效点电荷产生。"]},"pit":"腔内有电荷会改变外壳电荷；接地的壳可屏蔽外部场。"},
{"t":"pt","no":"题型3","name":"有导体存在时的电场与电势计算","feature":"平行板间插入导体/接地板，求场强、电势差、电荷。","method":"导体内部场强为零（如同短路），剩余间隙用均匀场 E=σ/ε₀。","steps":["在导体内部场强设为 0","剩余空间用 E = σ/ε₀ = U/d","接地板电势为零","用等势与电荷守恒联立求未知量"],"ex":{"q":"两平行板间距 d 带电压 U，插入厚度 t 的导体板，求内部电场。","steps":["导体板内部 E = 0","电场仅存在于两侧空气隙，总厚 d−t","E = U/(d−t)","插入导体相当于缩小有效间距，场强增大。"]},"pit":"导体板占据的厚度内场强为零，有效间距要扣除。"},{"t":"pt","no":"题型4","name":"电介质的极化与有介质的高斯定理","feature":"介质中电场的计算、极化电荷、电位移 D。","method":"D = ε₀E + P = εE，∮D·dS = q₀（自由电荷）；ε = εᵣε₀。","steps":["对自由电荷用 ∮D·dS = q₀ 求 D","由 E = D/ε 求介质中电场","与真空对比：E = E₀/εᵣ","极化电荷由 P = χeε₀E 求"],"ex":{"q":"平行板间充相对介电常数 εᵣ 的介质，自由面电荷 σ₀，求板内场强。","steps":["∮D·dS = q₀ → D = σ₀","E = D/(ε₀εᵣ) = σ₀/(ε₀εᵣ)","真空时 E₀ = σ₀/ε₀","E = E₀/εᵣ（介质削弱电场 εᵣ 倍）。"]},"pit":"有介质高斯定理算的是自由电荷；D 与 E 关系含 εᵣ。"},{"t":"pt","no":"题型5","name":"电容与电容器","feature":"求电容器电容、电荷或电压。","method":"C = Q/U；平行板 C = ε₀εᵣS/d；球、柱电容器各自公式。","steps":["判断电容器类型（平行板/球形/柱形）","用对应几何公式求 C","C = Q/U 求未知量","注意 εᵣ、介质填充比例"],"ex":{"q":"平行板面积 S、间距 d，充 εᵣ 介质，求电容。","steps":["一般式 C = Q/U","代入 E=σ/ε, U=Ed","得 C = ε₀εᵣS/d","介质使电容增大 εᵣ 倍。"]},"pit":"C 是电容器本身属性，与是否带电无关；介质、间距影响 C。"},{"t":"pt","no":"题型6","name":"电容器串并联与储能","feature":"多个电容器连接，求等效电容、电荷、能量。","method":"串联 1/C = Σ1/Cᵢ（电荷相同）；并联 C = ΣCᵢ（电压相同）；W = ½CU² = ½Q²/C。","steps":["判断串联还是并联","串联用倒数和、并联用直接相加","求等效电容后分配电荷/电压","能量用 W = ½CU²"],"ex":{"q":"两电容 2μF、3μF 串联接 10V，求等效电容与总电荷。","steps":["串联 1/C = 1/2 + 1/3 = 5/6","C = 1.2 μF","Q = CU = 1.2×10 = 12 μC","串联各电容电荷相同。"]},"pit":"串联电荷相同、并联电压相同，别混；能量公式两种形式等价。"},{"t":"pt","no":"题型7","name":"电场能量与能量密度","feature":"求电容器储能或电场能量密度。","method":"W = ½CU²；能量密度 w = ½ε₀E²（介质中 ½εE²）。","steps":["先求 C 或 E","电容器储能 W = ½CU² = ½QU","电场能量密度 w = ½ε₀εᵣE²","对空间积分可得总能量"],"ex":{"q":"均匀电场 E=10⁴V/m 的真空区域，求电场能量密度。","steps":["w = ½ε₀E²","= ½×8.85×10⁻¹²×(10⁴)²","≈ 4.4×10⁻⁴ J/m³","这是单位体积内的电场能量。"]},"pit":"能量密度是“单位体积”，与体积积分才是总能量。"},{"t":"pt","no":"题型8","name":"综合：带电导体、介质与能量守恒","feature":"多过程：充电后断电源/接电源、插介质、改变间距等。","method":"分“接电源(U不变)”与“断电源(Q不变)”两种情形，用 C=Q/U、W=½CU² 分析。","steps":["判断电源是否连接（U 恒定还是 Q 恒定）","用 C = εS/d 看 C 变化","接电源 U 不变 → 用 Q=CU、W=½CU² 看变化","断电源 Q 不变 → 用 U=Q/C、W=½Q²/C 看变化"],"ex":{"q":"平行板充电后断开电源，再把间距加倍，问 E、U、W 如何变。","steps":["断电源：Q 不变","C = εS/d 减半","U = Q/C 加倍","E = U/d 不变（σ 不变）；W = ½Q²/C 加倍。"]},"pit":"接电源 U 恒定、断电源 Q 恒定，两种情形结论相反，务必先判断。"},{"t":"tip","text":"<b>第6章解题总流程：</b>①导体先想三结论（内部 E=0、等势体、电荷在表面）；②有介质先看自由电荷算 D，再换算 E；③电容器先判断电源接/断（U 恒定 vs Q 恒定）；④能量问题别忘了 ½CU² 与能量密度；⑤平行板插导体相当于缩小间距。"},
{"t":"kw","items":["静电平衡","静电屏蔽","电位移D","有介质高斯定理","电容C","电场能量密度"]}]},"p7":{"no":"7","title":"恒定磁场","tag":"电磁","sub":"毕奥–萨伐尔·安培环路·洛伦兹力","blocks":[{"t":"sh","no":"7.1","title":"磁感应强度与毕奥–萨伐尔定律"},{"t":"tx","h":"磁感应强度 B","p":"运动电荷或电流周围存在磁场，用<b>磁感应强度 B</b> 描述。定义式：F = qv × B（洛伦兹力）。B 的单位是特斯拉（T），1 T = 1 N/(A·m)。磁感线是闭合曲线（无起点无终点），这与电场线起于正电荷不同。"},{"t":"tx","h":"毕奥–萨伐尔定律","p":"电流元 Idl 在空间某点产生的磁场：<b>dB = (μ₀/4π) · Idl × r̂ / r²</b>，其中 μ₀ = 4π×10⁻⁷ T·m/A 为真空磁导率。方向由 Idl × r̂ 决定（右手螺旋）。它是计算任意载流导线磁场的基本出发点：B = ∫dB。"},{"t":"tb","head":["典型载流导线","磁场分布","大小"],"rows":[["无限长直导线","同心圆环绕导线，右手螺旋定方向","B = μ₀I / (2πr)"],["有限长直导线","同心圆","B = (μ₀I/4πr)(cosθ₁ − cosθ₂)"],["圆形电流圆心处","垂直环面","B = μ₀I / (2R)"],["无限长直螺线管内部","均匀，轴向","B = μ₀nI（n 为单位长度匝数）"]]},{"t":"dv","title":"推导：有限长直导线的磁场（毕奥–萨伐尔积分）","steps":["毕奥–萨伐尔定律是实验定律，不能由更基本的原理推出；我们推导的是它的<b>应用结果</b>。设场点 P 到导线的垂直距离为 a，电流元 Idl 到 P 的距离为 r，dl 与 r 的夹角为 α。","大小：<b>dB = (μ₀/4π)·I dl sinα / r²</b>。导线上所有电流元在 P 点产生的 dB 方向相同（都垂直于导线与场点决定的平面），所以可直接按标量积分 B = ∫dB。","统一变量：取垂足为原点，电流元位置 l，张角 θ（从垂足方向量起）。有几何关系 r = a/sinθ，l = −a·cotθ，故 dl = a dθ / sin²θ，且 sinα = sinθ。","代入化简：dB = (μ₀I/4π)·(a dθ/sin²θ)·sinθ·(sin²θ/a²) = <b>(μ₀I/4πa)·sinθ dθ</b>——被积函数只剩下角度，这是整个推导的关键一步。","积分：B = (μ₀I/4πa)∫ sinθ dθ = <b>(μ₀I/4πa)(cosθ₁ − cosθ₂)</b>，θ₁、θ₂ 分别为垂足方向到导线两端的方向角。","易错：θ 从<b>垂足</b>方向量起，不是从导线端点量；θ₁ 对应电流流入端、θ₂ 对应流出端，顺序反了会差一个负号。"]},{"t":"dv","title":"推导：无限长直导线磁场（取极限）","steps":["无限长 = 有限长的极限：左端 θ₁ → 0，右端 θ₂ → π。","cos0 − cosπ = 1 − (−1) = <b>2</b>。","代回有限长公式：B = (μ₀I/4πa)×2 = <b>μ₀I/(2πa)</b>，即汇总表第一行。","与 7.3 节用安培环路定理推出的结果完全一致——两条路径互相印证，考场上用哪条都可以。","半无限长导线（只有一端无限延伸）：θ₁ = π/2，θ₂ → π，B = μ₀I/(4πa)，正好是无限长的<b>一半</b>。"]},{"t":"dv","title":"推导：圆电流轴线上与圆心处的磁场","steps":["取半径 R 的圆环电流 I，求轴线上距圆心 x 的 P 点。利用对称性：把圆环分成一对对<b>对称电流元</b>。","每个 Idl 在 P 点产生 dB = (μ₀/4π)·I dl/r²（Idl ⊥ r，sin90° = 1），其中 r² = R² + x²。","对称电流元的 dB 在<b>垂直于轴</b>方向的分量两两抵消，只剩沿轴分量：dB_x = dB·sinφ = dB·(R/r)。","沿整个圆环积分：B = ∫dB·R/r = (μ₀I/4π)·(R/r³)·∮dl = (μ₀I/4π)·(R/r³)·2πR。","整理得轴线上结果：<b>B = μ₀IR² / 2(R² + x²)^(3/2)</b>。","令 x = 0 得圆心处：<b>B = μ₀I/(2R)</b>，即汇总表第三行。N 匝密绕线圈圆心处 B = μ₀NI/(2R)；一段圆心角 φ 的圆弧导线在圆心贡献 B = μ₀Iφ/(4πR)（按弧长比例取份额）。"]},{"t":"dv","title":"推导：长直螺线管内部磁场（安培环路定理）","steps":["先判断对称性：密绕长螺线管内部磁场近似<b>均匀且沿轴向</b>，外部磁场近似为零。","取矩形安培环路 abcd：ab 边在管内、沿轴、长 l；cd 边在管外（B ≈ 0）；bc、da 两边与 B 垂直，点积为零。","环路积分：∮B·dl = B·l + 0 + 0 + 0 = <b>Bl</b>。","包围的电流：单位长度 n 匝，l 长度内共 nl 匝，每匝电流 I，故 ΣI = <b>nlI</b>。","由安培环路定理 Bl = μ₀nlI，解得 <b>B = μ₀nI</b>，即汇总表第四行。",
"结论含义：管内是匀强场（与位置无关）；B 只取决于<b>匝数密度 n</b> 与电流，与螺线管粗细无关。环形螺线管（螺绕环）内部同理：B = μ₀NI/(2πr)。"]},{"t":"sh","no":"7.2","title":"磁通量与磁场高斯定理"},{"t":"tx","h":"磁通量与高斯定理","p":"磁通量 Φ = ∫B·dS（单位韦伯 Wb）。由于磁感线闭合、不存在磁单极子，穿过任意闭合曲面的净磁通恒为零：<b>∮B·dS = 0</b>——这就是磁场高斯定理，说明磁场是无源场。"},{"t":"sh","no":"7.3","title":"安培环路定理"},{"t":"tx","h":"安培环路定理","p":"<b>∮B·dl = μ₀ ΣI<sub>内</sub></b>：B 沿任意闭合回路的线积分等于 μ₀ 乘以该回路所包围的电流代数和（与回路外电流无关）。正负号由右手螺旋定则确定。<br>它只对<b>恒定电流</b>成立；用它求 B 的前提是回路具有高度对称性（B 沿回路大小恒定、方向与 dl 平行或垂直）。"},{"t":"dv","title":"用安培环路定理求无限长直导线磁场","steps":["取以导线为轴、半径 r 的圆形回路为安培环路（充分利用轴对称）。","左侧：环路上 B 处处与 dl 同向且大小相同，∮B·dl = B·2πr。","右侧：回路只包围这一根电流 I，代数和 = I。","联立：B·2πr = μ₀I → B = μ₀I/(2πr)。","结论与毕奥–萨伐尔定律积分结果一致，但计算量小得多——这就是安培环路定理的价值。"]},{"t":"sh","no":"7.4","title":"磁场对电流和运动电荷的作用"},{"t":"tx","h":"安培力与洛伦兹力","p":"载流导线在磁场中受力：<b>dF = I dl × B</b>，整段导线 F = ∫I dl × B。匀强磁场中长为 L 的直导线受力 F = BIL sinθ。<br>运动电荷受力：<b>F = qv × B</b>，方向垂直于 v 与 B 所在平面；因 F ⊥ v，洛伦兹力<b>不做功</b>，只改变速度方向不改变速率。带电粒子垂直进入匀强磁场做匀速圆周运动：<b>R = mv/(qB)</b>，周期 T = 2πm/(qB)（与速率无关，回旋加速器的原理）。"},{"t":"sh","no":"7.5","title":"磁介质"},{"t":"tx","h":"三类磁介质","p":"磁介质在外磁场中被磁化，产生附加磁场。按相对磁导率 μ<sub>r</sub> 分为：<b>顺磁质</b>（μ<sub>r</sub> 略大于 1）、<b>抗磁质</b>（μ<sub>r</sub> 略小于 1）、<b>铁磁质</b>（μ<sub>r</sub> ≫ 1，且随磁场变化、存在磁滞与居里温度）。引入磁场强度 H = B/μ₀ − M，则安培环路定理写成 ∮H·dl = ΣI<sub>内</sub>，与介质无关，便于计算。"},{"t":"ex","q":"一根长直导线载有电流 I = 10 A，求距导线 0.10 m 处的磁感应强度。","steps":["无限长直导线，直接套 B = μ₀I/(2πr)。","代入：μ₀ = 4π×10⁻⁷，I = 10，r = 0.10。","B = (4π×10⁻⁷ × 10)/(2π × 0.10) = (2×10⁻⁶)/(0.10) = 2×10⁻⁵ T。","方向：右手握住导线，拇指指电流方向，四指弯曲方向即 B 的方向（同心圆切线）。"]},{"t":"warn","text":"① 洛伦兹力永远不做功，所以带电粒子在纯磁场中速率不变。② 安培环路定理中 ΣI 只算回路<b>包围</b>的电流，穿过回路但不被包围的不算。③ 磁场高斯定理的右端是 0，这与静电场 ∮E·dS = q/ε₀ 完全不同，根源是自然界没有磁单极子。"},{"t":"pt","no":"1","name":"载流导线磁场计算","feature":"求直导线、圆环、螺线管在指定点的 B。","method":"先看对称性，再用毕奥–萨伐尔积分或安培环路定理。","steps":["画出电流方向与所求点的相对位置。","判断能否用安培环路定理（对称性是否足够）。","能用则选合适回路，写出 ∮B·dl 与 ΣI 后联立。","不能用则用 dB = (μ₀/4π)Idl×r̂/r² 积分，注意矢量方向的分量抵消。","确定方向用右手螺旋，最后注明方向。"],"ex":{"q":"两平行长直导线相距 d，通同向电流 I，求中点处的 B。","steps":["中点距两根导线均为 d/2。","左导线在中点产生 B₁ = μ₀I/(2π·d/2) = μ₀I/(πd)，方向垂直纸面向里（视电流方向而定）。","右导线在中点产生大小相同的 B₂ = μ₀I/(πd)。","同向电流在中点产生的磁场方向<b>相反</b>，故 B = B₁ − B₂ = 0。","结论：同向电流中点为磁中性点；反向电流则中点磁场加倍。"]},"pit":"两根导线在同一点产生的磁场方向容易想当然地相加，必须先分别用右手螺旋定方向再合成。"},{"t":"kw","items":["磁感应强度","毕奥–萨伐尔定律","磁场高斯定理","安培环路定理","安培力","洛伦兹力","回旋半径","磁介质","磁场强度 H"]}]},"p8":{"no":"8","title":"电磁感应 电磁场","tag":"电磁","sub":"法拉第定律·动生感生·麦克斯韦方程组","blocks":[{"t":"sh",
"no":"8.1","title":"法拉第电磁感应定律"},{"t":"tx","h":"定律内容","p":"当穿过闭合回路的磁通量发生变化时，回路中产生感应电动势：<b>ε = −dΦ/dt</b>。负号表示感应电动势的方向总是<b>阻碍</b>磁通量的变化（楞次定律）。<br>若回路有 N 匝，则 ε = −N dΦ/dt（磁通链 ψ = NΦ）。感应电荷量 q = ∫I dt = NΔΦ/R，只与磁通变化量有关，与变化快慢无关。"},{"t":"sh","no":"8.2","title":"动生电动势"},{"t":"tx","h":"动生电动势的两种看法","p":"<b>微观本质</b>：导体棒在磁场中运动，棒内自由电荷随棒运动受洛伦兹力 qv×B，被推向一端，形成非静电场 E<sub>k</sub> = v×B，电动势 ε = ∫(v×B)·dl。匀强磁场中直棒垂直切割磁感线：<b>ε = BLv</b>。<br><b>宏观看法</b>：ε = −dΦ/dt，用 Φ = B·S 对时间求导，把面积变化折算进速度。两种方法结果一致，但积分法能判断哪一端电势高。"},{"t":"dv","title":"推导：直棒切割磁感线的电动势 ε = BLv","steps":["设棒长 L，以速度 v 垂直于 B 运动，棒、v、B 三者两两垂直。","单位电荷受洛伦兹力 F/q = v×B，大小 = vB，方向沿棒。","电动势定义为单位电荷绕回路一周非静电力做的功：ε = ∫(v×B)·dl。","沿棒积分，v×B 与 dl 处处同向且大小为 vB：ε = vB·L。","若 v 与 B 夹角为 θ，则只有垂直分量有效：ε = BLv sinθ。","方向判断：用右手，四指由 v 转向 B，拇指指向正电荷受力方向，即高电位端。"]},{"t":"sh","no":"8.3","title":"感生电动势与涡旋电场"},{"t":"tx","h":"感生电动势","p":"导体不动而磁场随时间变化时，回路中同样产生电动势，称为<b>感生电动势</b>。麦克斯韦指出：变化的磁场在其周围激发一种<b>涡旋电场</b>（感生电场）E<sub>涡</sub>，其电力线是闭合曲线，<b>∮E<sub>涡</sub>·dl = −dΦ/dt</b>。<br>涡旋电场对电荷也有作用力，但它不是由电荷产生的，与静电场有本质区别：静电场是保守场（∮E·dl = 0），涡旋电场是非保守场。"},{"t":"sh","no":"8.4","title":"自感与互感"},{"t":"tx","h":"自感与互感","p":"<b>自感</b>：回路自身电流变化引起磁通变化，ψ = LI，ε<sub>L</sub> = −L dI/dt。长直螺线管 L = μ₀n²V。自感的物理意义是“回路对电流变化的阻碍”。<br><b>互感</b>：一个回路电流变化在另一回路引起电动势，ψ₂₁ = M I₁，ε₂₁ = −M dI₁/dt，且 M₁₂ = M₂₁。变压器就是互感的典型应用。"},{"t":"sh","no":"8.5","title":"磁场能量"},{"t":"tx","h":"磁场能量密度","p":"磁场具有能量，能量密度 w<sub>m</sub> = B²/(2μ₀) = ½BH。自感线圈中储存的磁场能量 <b>W = ½LI²</b>。这与电容器储能 W = ½CU² 完全对应，体现了电场与磁场的对称性。"},{"t":"sh","no":"8.6","title":"麦克斯韦方程组"},{"t":"tx","h":"四个方程的统一","p":"麦克斯韦方程组把电场与磁场统一为电磁场，四个方程分别是：<br><b>① ∮D·dS = Σq</b>（电场高斯定理，电荷产生电场）<br><b>② ∮B·dS = 0</b>（磁场高斯定理，无磁单极子）<br><b>③ ∮E·dl = −dΦ<sub>B</sub>/dt</b>（法拉第定律，变化磁场产生涡旋电场）<br><b>④ ∮H·dl = ΣI + dΦ<sub>D</sub>/dt</b>（全电流定律，传导电流与位移电流都产生磁场）<br>其中位移电流假说 I<sub>d</sub> = dΦ<sub>D</sub>/dt 是麦克斯韦的关键贡献，它保证了电流的连续性，并预言了电磁波的存在。"},{"t":"ex","q":"长 L = 0.50 m 的金属棒以 v = 2.0 m/s 垂直切割磁感应强度 B = 0.40 T 的匀强磁场，求棒两端电动势。","steps":["棒、v、B 两两垂直，可直接用 ε = BLv。","代入：ε = 0.40 × 0.50 × 2.0 = 0.40 V。","若棒与 v 成 30°，则有效长度为 L sin30° = 0.25 m，ε 减半为 0.20 V。","方向：由 v×B 判定正电荷受力端，该端为高电位（相当于电源正极）。"]},{"t":"warn","text":"① ε = −dΦ/dt 的负号不能丢，它决定方向（楞次定律）。② 动生电动势是洛伦兹力做功的“分力”效果，但洛伦兹力总体不做功——这是常考的悖论题。③ 涡旋电场不是静电场，∮E·dl ≠ 0。"},{"t":"dv","title":"推导：动生电动势 ℰ = Blv（由洛伦兹力）","steps":["长 l 的导体棒以速度 v 垂直切割磁感线 B，棒内自由电子随棒一起运动。","电子受洛伦兹力 f = evB，向棒的一端聚集，另一端积累正电荷，建立静电场 E。","电荷聚集到平衡时，电场力与洛伦兹力抵消：eE = evB → E = vB。",
"两端电势差即动生电动势：ℰ = El = <b>Blv</b>。","方向由右手定则判定；本质：洛伦兹力搬运电荷做功，把机械能转化为电能——这也是发电机原理。"]},{"t":"pt","no":"1","name":"感应电动势计算","feature":"给出磁通变化、导体运动或线圈转动，求 ε 或感应电流。","method":"先判断是动生还是感生，再选积分法或求导法。","steps":["判断磁场是否变化、面积是否变化：面积变 → 动生；B 变 → 感生。","写出 Φ(t) 的表达式（注意 B 与面法线的夹角）。","对 t 求导得 ε = −dΦ/dt，N 匝乘 N。","动生也可用 ε = BLv sinθ 直接算，更快。","由 ε 与回路电阻 R 得 I = ε/R，再用楞次定律判方向。"],"ex":{"q":"边长 0.20 m 的正方形线框 100 匝，垂直置于 B 中，B 在 0.10 s 内由 0.50 T 均匀降到 0.10 T，R = 5.0 Ω，求感应电动势与电流。","steps":["面积 S = 0.20² = 0.040 m²。","ΔΦ = ΔB·S = (0.10 − 0.50) × 0.040 = −0.016 Wb。","ε = −N ΔΦ/Δt = −100 × (−0.016)/0.10 = 16 V。","I = ε/R = 16/5.0 = 3.2 A。","方向：磁通减少，感应电流产生的磁场要“补”原方向，用右手定则确定绕向。"]},"pit":"求导时把 N 漏掉、或把 ΔB 的符号弄反都会导致结果符号/大小错。"},{"t":"kw","items":["法拉第定律","楞次定律","动生电动势","感生电动势","涡旋电场","自感","互感","磁场能量","位移电流","麦克斯韦方程组"]}]},"p9":{"no":"9","title":"振动","tag":"波动","sub":"简谐振动·旋转矢量·合成·共振","blocks":[{"t":"sh","no":"9.1","title":"简谐振动"},{"t":"tx","h":"简谐振动的判据与方程","p":"物体受<b>与位移成正比、方向相反</b>的回复力 F = −kx 时做简谐振动。由牛顿第二定律得 d²x/dt² + ω²x = 0，其解为 <b>x = A cos(ωt + φ)</b>。<br>三个特征量：振幅 A（最大位移）、角频率 ω = √(k/m)（由系统本身决定，与振幅无关）、初相 φ（由初始条件定）。周期 T = 2π/ω = 2π√(m/k)，频率 ν = 1/T。"},{"t":"tx","h":"速度与加速度","p":"对 x = A cos(ωt+φ) 求导：v = −Aω sin(ωt+φ)，a = −Aω² cos(ωt+φ) = −ω²x。<br>关键关系：<b>v 比 x 超前 π/2，a 与 x 反相（相差 π）</b>；最大速度 v<sub>max</sub> = Aω（在平衡位置），最大加速度 a<sub>max</sub> = Aω²（在最大位移处）。加速度始终指向平衡位置。"},{"t":"sh","no":"9.2","title":"旋转矢量法"},{"t":"tx","h":"用一个转动的矢量代表振动","p":"作长度等于 A 的矢量，以角速度 ω 逆时针绕原点匀速旋转，其初始与 x 轴夹角为 φ。则该矢量在 x 轴上的投影就是 x = A cos(ωt+φ)。<br>价值：把“相位”变成看得见的“角度”，求相位差、判断超前落后、合成振动都变得直观。相位每增加 2π，矢量转一整圈，对应一个完整周期。"},{"t":"sh","no":"9.3","title":"简谐振动的能量"},{"t":"tx","h":"动能与势能","p":"Ek = ½mv² = ½kA² sin²(ωt+φ)，Ep = ½kx² = ½kA² cos²(ωt+φ)，总能量 <b>E = ½kA²</b> 恒定。<br>动能与势能都按 2ω 的频率周期性变化，一个周期内动能和势能各完成两次最大—最小交替；二者平均值相等，都等于 E/2。"},{"t":"sh","no":"9.4","title":"简谐振动的合成"},{"t":"tx","h":"同方向同频率的合成","p":"两个同方向同频率振动 x₁ = A₁cos(ωt+φ₁)、x₂ = A₂cos(ωt+φ₂) 合成后仍是同频率简谐振动，<b>用旋转矢量（平行四边形法则）最容易求</b>：<br>A = √(A₁² + A₂² + 2A₁A₂cos(φ₂−φ₁))，初相由 tanφ = (A₁sinφ₁ + A₂sinφ₂)/(A₁cosφ₁ + A₂cosφ₂) 定。<br>特例：Δφ = 2kπ 时 A = A₁+A₂（加强）；Δφ = (2k+1)π 时 A = |A₁−A₂|（减弱）。"},{"t":"tx","h":"拍与垂直合成","p":"<b>拍</b>：同方向、频率相近（ω₁≈ω₂）的两个振动合成，振幅被缓慢调制，拍频 = |ν₁ − ν₂|。这是调音、无线电差频的物理基础。<br><b>垂直方向合成</b>：同频率时合成轨迹一般是椭圆，Δφ = 0 或 π 退化为直线，Δφ = ±π/2 且 A₁=A₂ 时为正圆；频率成简单整数比时形成李萨如图形。"},{"t":"sh","no":"9.5","title":"阻尼振动、受迫振动与共振"},{"t":"tx","h":"阻尼与受迫","p":"<b>阻尼振动</b>：存在摩擦等阻力，振幅按指数衰减（欠阻尼振荡衰减、过阻尼与临界阻尼不振荡）。<br><b>受迫振动</b>：外加周期性驱动力，稳定后以<b>驱动频率</b>振动，与系统固有频率无关。<br><b>共振</b>：当驱动频率接近固有频率时振幅急剧增大。位移共振发生在 ω ≈ √(ω₀²−2β²) 处，速度共振恰好发生在 ω = ω₀。"},
{"t":"ex","q":"一弹簧振子 m = 0.10 kg，k = 40 N/m，振幅 A = 0.050 m。求 ω、T、最大速度与总能量。","steps":["ω = √(k/m) = √(40/0.10) = √400 = 20 rad/s。","T = 2π/ω = 2π/20 ≈ 0.314 s。","v<sub>max</sub> = Aω = 0.050 × 20 = 1.0 m/s。","E = ½kA² = 0.5 × 40 × 0.050² = 0.5 × 40 × 0.0025 = 0.050 J。","验算：½mv<sub>max</sub>² = 0.5 × 0.10 × 1.0² = 0.050 J ✓，两种算法一致。"]},{"t":"warn","text":"① ω 由系统决定（k、m），改变振幅不会改变周期——这是简谐振动最反直觉也最常考的一点。② 相位差与时间差的关系是 Δφ = ωΔt，别把角度和时间混用。③ 受迫振动稳定后的频率是驱动频率，不是固有频率。"},{"t":"dv","title":"推导：简谐振动的微分方程与振动表达式","steps":["弹簧振子受回复力 F = −kx（大小与位移成正比，方向总指向平衡位置）。","由牛顿第二定律：m·d²x/dt² = −kx → d²x/dt² + (k/m)x = 0。","令 ω² = k/m，得简谐振动判据式 <b>d²x/dt² + ω²x = 0</b>——任何满足此式的运动都是简谐振动。","该二阶微分方程的通解：<b>x = A·cos(ωt + φ)</b>，其中 ω = √(k/m) 为固有角频率。","周期 T = 2π/ω = 2π√(m/k)；单摆同理（小角度下 sinθ≈θ）T = 2π√(l/g)。","A、φ 由初始条件定：A = √(x₀² + (v₀/ω)²)，tanφ = −v₀/(ωx₀)。"]},{"t":"dv","title":"推导：简谐振动的能量公式 E = ½kA²","steps":["动能：v = dx/dt = −Aω·sin(ωt+φ) → Ek = ½mv² = ½mA²ω²·sin²(ωt+φ)。","势能：Ep = ½kx² = ½kA²·cos²(ωt+φ)。","因 k = mω²，两项系数相同：Ek + Ep = ½kA²(sin² + cos²) = <b>½kA²</b>。","结论：总能量守恒，与<b>振幅平方</b>成正比；动能与势能此消彼长、周期为振动周期的一半。"]},{"t":"dv","title":"推导：同方向同频率振动的合成","steps":["x₁ = A₁cos(ωt+φ₁)，x₂ = A₂cos(ωt+φ₂)，合振动 x = x₁ + x₂。","旋转矢量法：两矢量以同一 ω 旋转，夹角恒为 Δφ，合矢量也以 ω 旋转 → 合振动仍是同频简谐振动。","由余弦定理：<b>A² = A₁² + A₂² + 2A₁A₂·cosΔφ</b>，tanφ = (A₁sinφ₁+A₂sinφ₂)/(A₁cosφ₁+A₂cosφ₂)。","特例：Δφ = 2kπ → A = A₁+A₂（加强）；Δφ = (2k+1)π → A = |A₁−A₂|（减弱）。"]},{"t":"pt","no":"1","name":"简谐振动方程与特征量","feature":"给初始条件或振动曲线，求 A、ω、φ 与振动方程。","method":"由 ω=√(k/m) 定频率，由初始 x₀、v₀ 定 A 与 φ。","steps":["由系统参数求出 ω（弹簧：√(k/m)；单摆：√(g/l)）。","由 A = √(x₀² + v₀²/ω²) 求振幅。","由 tanφ = −v₀/(ωx₀) 求初相，<b>必须结合 x₀、v₀ 的符号判断象限</b>。","写出 x = A cos(ωt + φ)，标明单位。","验算：t=0 代入应得 x₀，求导后代入应得 v₀。"],"ex":{"q":"弹簧振子 k = 100 N/m，m = 0.25 kg，t=0 时 x₀ = 0.10 m，v₀ = 0，求振动方程。","steps":["ω = √(100/0.25) = √400 = 20 rad/s。","v₀ = 0 → 该点为最大位移处，故 A = x₀ = 0.10 m。","tanφ = −v₀/(ωx₀) = 0，且 x₀ &gt; 0 → φ = 0。","振动方程 x = 0.10 cos(20t)（SI 单位）。","验算：t=0 → x = 0.10 ✓；v = −2.0 sin(20t)，t=0 时 v=0 ✓。"]},"pit":"tanφ 有两个解（相差 π），必须用 x₀ 与 v₀ 的符号定象限，只写 arctan 值会错一半。"},{"t":"kw","items":["回复力","振幅","角频率","初相","旋转矢量法","相位差","振动能量","振动合成","拍","阻尼振动","受迫振动","共振"]}]},"p10":{"no":"10","title":"波动学基础","tag":"波动","sub":"波函数·波的能量·干涉·驻波·多普勒","blocks":[{"t":"sh","no":"10.1","title":"机械波的几个概念"},{"t":"tx","h":"产生条件与分类","p":"机械波产生的两个必要条件：<b>波源</b>（振动源）与<b>弹性介质</b>。按振动方向与传播方向的关系分为<b>横波</b>（垂直，有波峰波谷，只有固体能传播）与<b>纵波</b>（平行，有密部疏部，固液气都能传播）。<br>描述波的物理量：波长 λ、周期 T、频率 ν、波速 u，关系 <b>u = λν = λ/T</b>。注意波速由介质决定，频率由波源决定，二者独立——所以波从一种介质进入另一种介质时频率不变、波速与波长改变。"},
{"t":"sh","no":"10.2","title":"平面简谐波的波函数"},{"t":"tx","h":"波函数的标准形式","p":"设波沿 x 正方向传播，原点处振动为 y₀ = A cos(ωt + φ)，则 <b>y = A cos[ω(t − x/u) + φ] = A cos(2π(t/T − x/λ) + φ)</b>。<br>物理意义：x 处的振动比原点<b>落后</b> Δt = x/u，相位落后 Δφ = 2πx/λ。若波沿 x 负方向传播，把 (t − x/u) 换成 (t + x/u)。"},{"t":"dv","title":"推导：由原点的振动写出波函数","steps":["已知原点 O 的振动方程 y(0,t) = A cos(ωt + φ)。","波以速度 u 沿 +x 传播，传到 x 处需要时间 Δt = x/u。","所以 x 处 t 时刻的状态，等于原点在 (t − x/u) 时刻的状态。","代入：y(x,t) = A cos[ω(t − x/u) + φ]。","用 ω = 2π/T、u = λ/T 展开：ω x/u = 2πx/λ，得到 y = A cos(ωt − 2πx/λ + φ)。","判断传播方向：相位中 t 与 x 符号<b>相反</b> → 沿 +x 传播；符号相同 → 沿 −x 传播。"]},{"t":"sh","no":"10.3","title":"波的能量与能流"},{"t":"tx","h":"波的能量特点","p":"与简谐振动不同，波动中每个质元都在不断吸收和释放能量：动能与势能<b>同相位</b>、同时达到最大（都在平衡位置处最大，因为那里形变率最大）。这一点与振动中“动能势能互补”完全相反，是常考易错点。<br>平均能量密度 w̄ = ½ρA²ω²；能流密度（波强）I = w̄u = ½ρA²ω²u，与振幅平方成正比。"},{"t":"sh","no":"10.4","title":"惠更斯原理与波的干涉"},{"t":"tx","h":"惠更斯原理与叠加","p":"惠更斯原理：波面上每一点都可看作新的子波源，其后时刻的波面是这些子波波面的包络面。它能解释反射、折射、衍射。<br>波的叠加原理：几列波相遇时各自独立传播，相遇处质点位移为各波单独引起位移的<b>矢量和</b>。"},{"t":"tx","h":"相干条件与干涉公式","p":"两列波相干需满足：频率相同、振动方向相同、相位差恒定。<br>合振幅 A = √(A₁² + A₂² + 2A₁A₂cosΔφ)，其中 Δφ = Δφ₀ − 2πΔr/λ（Δr 为波程差）。<br><b>加强条件</b>：Δφ = 2kπ，即波程差 Δr = kλ；<b>减弱条件</b>：Δφ = (2k+1)π，即 Δr = (k+½)λ。"},{"t":"sh","no":"10.5","title":"驻波"},{"t":"tx","h":"驻波的形成与特征","p":"两列<b>振幅相同、传播方向相反</b>的相干波叠加形成驻波：y = 2A cos(2πx/λ)·cos(ωt)。<br>特征：① 各点振幅 2A|cos(2πx/λ)| 只与位置有关，不再“传播”；② 出现<b>波节</b>（振幅恒为 0，x = (2k+1)λ/4）与<b>波腹</b>（振幅最大 2A，x = kλ/2）；③ 相邻波节间距 λ/2；④ 波节之间各点同相振动，波节两侧反相。<br><b>半波损失</b>：波从波疏介质射向波密介质反射时，反射波在反射点发生 π 的相位突变，相当于损失半个波长。"},{"t":"sh","no":"10.6","title":"多普勒效应"},{"t":"tx","h":"频率变化的规律","p":"观察者接收到的频率 ν′ 与波源、观察者相对介质运动有关：<b>ν′ = ν (u ± v<sub>观</sub>)/(u ∓ v<sub>源</sub>)</b>。<br>记忆规则：相互靠近时分子取加、分母取减，接收频率<b>升高</b>；相互远离时相反，频率<b>降低</b>。波源运动还会改变波长，观察者运动不改变波长——这是两者的本质区别。"},{"t":"sh","no":"10.7","title":"电磁波"},{"t":"tx","h":"电磁波的产生与性质","p":"由麦克斯韦方程组可知：变化的电场产生磁场、变化的磁场产生电场，交替激发形成电磁波，在真空中以 c = 1/√(μ₀ε₀) ≈ 3×10⁸ m/s 传播。<br>平面电磁波性质：E ⊥ B ⊥ 传播方向（横波）；E 与 B 同相位；E = cB；能量密度 w = ε₀E²。电磁波谱按频率由低到高包括无线电波、微波、红外、可见光、紫外、X 射线、γ 射线。"},{"t":"ex","q":"一列平面简谐波沿 +x 方向传播，A = 0.020 m，T = 0.50 s，λ = 2.0 m，t=0 时原点位于正最大位移处。写出波函数，并求 x = 0.50 m 处质点的振动方程。","steps":["ω = 2π/T = 2π/0.50 = 4π rad/s。","t=0 时原点在正最大位移 → x₀ = A，故 φ = 0，原点振动 y = 0.020 cos(4πt)。","波沿 +x 传播，相位落后 2πx/λ：y = 0.020 cos(4πt − 2πx/2.0) = 0.020 cos(4πt − πx)。","x = 0.50 m 代入：y = 0.020 cos(4πt − 0.50π) = 0.020 cos(4πt − π/2)。","该点比原点相位落后 π/2，相当于落后 T/4 = 0.125 s。"]},
{"t":"warn","text":"① 波动中动能与势能<b>同相</b>变化，与简谐振动不同，别套用振动结论。② 波从一种介质进入另一种介质，频率不变，波速与波长改变。③ 半波损失只发生在“波疏→波密”反射时，透射不发生。"},{"t":"dv","title":"推导：驻波方程与波腹波节位置","steps":["两列振幅相同、沿相反方向传播的相干波：y₁ = Acos(ωt−kx)，y₂ = Acos(ωt+kx)。","叠加并用和差化积：y = y₁+y₂ = <b>2A·cos(kx)·cos(ωt)</b>。","各点以 cos(ωt) 同相振动，振幅为 |2A·cos(kx)|——随位置 x 分布而不传播，故称「驻波」。","波腹：|cos(kx)| = 1 → kx = nπ → <b>x = nλ/2</b>，振幅 2A。","波节：cos(kx) = 0 → kx = (2n+1)π/2 → <b>x = (2n+1)λ/4</b>，振幅恒为 0；相邻波节间距 λ/2。"]},{"t":"pt","no":"1","name":"波函数的建立与相位","feature":"给波的传播方向、波长周期与某点振动状态，求波函数。","method":"先定原点振动，再按“传播方向决定相位符号”写波函数。","steps":["求出 ω = 2π/T 与 k = 2π/λ。","由已知点的振动状态确定 A 与 φ（或先写该点振动方程）。","波沿 +x 传播写成 cos(ωt − kx + φ)；沿 −x 写成 cos(ωt + kx + φ)。","若给的是某点 x₀ 的状态，先把相位折算成原点相位：φ₀ = φₓ + kx₀。","代回验算：把 x₀ 代入应还原已知振动方程。"],"ex":{"q":"波沿 −x 方向传播，u = 20 m/s，ν = 5 Hz，A = 0.10 m，已知 x = 0 处 t=0 时位移为 0 且向 −y 方向运动，求波函数。","steps":["λ = u/ν = 20/5 = 4.0 m；ω = 2πν = 10π rad/s；k = 2π/λ = π/2。","t=0、x=0 时 y=0 且 v&lt;0 → φ = +π/2（标准式 y = A cos(ωt + φ) 下，v = −Aω sinφ &lt; 0 要求 sinφ &gt; 0）。","沿 −x 传播，相位取 (ωt + kx)：y = 0.10 cos(10πt + πx/2 + π/2)。","验算 t=0、x=0：y = 0.10 cos(π/2) = 0 ✓；v = −0.10×10π sin(π/2) = −π &lt; 0 ✓。"]},"pit":"“相位符号”和“初相”两个符号容易叠加出错，写完后一定代回已知点验算。"},{"t":"kw","items":["横波与纵波","波长","波速","波函数","相位落后","波的能量密度","波强","惠更斯原理","相干条件","波程差","驻波","波节波腹","半波损失","多普勒效应"]}]},"p11":{"no":"11","title":"波动光学","tag":"波动","sub":"双缝·薄膜·衍射·光栅·偏振","blocks":[{"t":"sh","no":"11.1","title":"相干光与光程"},{"t":"tx","h":"获得相干光的方法","p":"普通光源各原子发光相互独立、相位随机，两束光不满足相干条件。获得相干光的办法是把<b>同一束光“分开”再合拢</b>：分波阵面法（杨氏双缝）与分振幅法（薄膜干涉）。<br><b>光程</b> L = nr（n 为折射率，r 为几何路程），它把不同介质中的传播折算成真空中的等效路程。相位差与光程差的关系：<b>Δφ = 2πΔL/λ</b>（λ 为真空波长）。用光程差判断干涉比用路程差更通用。"},{"t":"sh","no":"11.2","title":"杨氏双缝干涉"},{"t":"tx","h":"双缝干涉的明暗条件","p":"双缝间距 d，屏距 D（D ≫ d），则屏上 P 点的光程差 ΔL ≈ d·x/D（x 为 P 点到中央明纹的距离）。<br><b>明纹</b>：ΔL = kλ → x = kDλ/d（k = 0, ±1, ±2…）<br><b>暗纹</b>：ΔL = (k+½)λ → x = (k+½)Dλ/d<br><b>条纹间距</b>：Δx = Dλ/d——等间距，与 k 无关，这是双缝干涉最显著的特征。"},{"t":"dv","title":"推导：条纹间距 Δx = Dλ/d","steps":["设 P 点在屏上距中央 O 为 x，双缝到 P 的两条光程分别为 r₁、r₂。","由几何关系，当 D ≫ d、D ≫ x 时，可作垂线近似，得到 ΔL = r₂ − r₁ ≈ d·sinθ。","又 tanθ = x/D，小角近似 sinθ ≈ tanθ ≈ x/D。","所以 ΔL ≈ d·x/D。","相邻两条明纹对应 k 与 k+1：d·x<sub>k+1</sub>/D − d·x<sub>k</sub>/D = λ。","解得 Δx = x<sub>k+1</sub> − x<sub>k</sub> = Dλ/d。","结论：间距与 λ、D 成正比，与 d 成反比——换成红光条纹变宽，增大缝距条纹变密。"]},{"t":"sh","no":"11.3","title":"薄膜干涉"},{"t":"tx","h":"薄膜干涉的明暗条件","p":"光射到薄膜上，上表面反射光与下表面反射光叠加。设膜厚 e、折射率 n₂、入射介质 n₁，垂直入射时光程差 <b>ΔL = 2n₂e + (λ/2)</b>，多出的 λ/2 来自<b>半波损失</b>（光从光疏射向光密反射时产生）。<br>明纹：2n₂e + λ/2 = kλ；暗纹：2n₂e + λ/2 = (k+½)λ。<br>应用：增透膜（使反射光相消，取最小厚度 e = λ/(4n)）、增反膜、检验平整度（等厚干涉条纹弯曲反映表面起伏）。"},
{"t":"sh","no":"11.4","title":"牛顿环"},{"t":"tx","h":"牛顿环","p":"平凸透镜放在平板玻璃上，中间形成空气劈尖（n=1）。第 k 级暗环半径 <b>r<sub>k</sub> = √(kλR)</b>（R 为透镜曲率半径），中心是暗斑（因半波损失）。<br>半径与 √k 成正比，所以越往外环越密。测出第 m、n 级暗环直径可求曲率半径：R = (d<sub>m</sub>² − d<sub>n</sub>²)/(4(m−n)λ)，这是实验中测透镜曲率半径的标准方法。"},{"t":"sh","no":"11.5","title":"单缝衍射"},{"t":"tx","h":"单缝夫琅禾费衍射","p":"缝宽 a，衍射角 θ。<b>暗纹条件</b>：a·sinθ = kλ（k = ±1, ±2…）；中央明纹位于 k=0 两侧第一暗纹之间，<b>半角宽度</b> θ₁ ≈ λ/a。<br>与干涉的关键区别：单缝衍射的明纹<b>不等间距、不等宽</b>，中央明纹最亮最宽（宽度约为其他明纹的 2 倍），强度随级次迅速衰减。缝越窄，衍射越显著。"},{"t":"sh","no":"11.6","title":"圆孔衍射与光学仪器分辨率"},{"t":"tx","h":"瑞利判据","p":"圆孔衍射的中央亮斑叫<b>艾里斑</b>，半角宽度 θ₁ = 1.22λ/D（D 为孔径）。<br><b>瑞利判据</b>：一个像点的艾里斑中心恰好落在另一像点的第一暗环上时，恰能分辨。最小分辨角 <b>θ<sub>min</sub> = 1.22λ/D</b>，分辨率 R = 1/θ<sub>min</sub> = D/(1.22λ)——孔径越大、波长越短，分辨本领越高（所以天文望远镜要大口径，电子显微镜用电子波）。"},{"t":"sh","no":"11.7","title":"光栅衍射"},{"t":"tx","h":"光栅方程","p":"光栅常数 d = a + b（缝宽 + 不透明部分宽度）。<b>主极大条件：d·sinθ = kλ</b>（k 为级次）。<br>光栅衍射是“单缝衍射 × 多缝干涉”的结果：干涉决定主极大的位置（细而亮），单缝衍射决定各主极大的强度包络（缺级现象）。当 d/a = 整数时会出现<b>缺级</b>——某级主极大恰好落在单缝衍射暗纹处而消失。光栅的条纹极细锐，因此能精确测波长。"},{"t":"sh","no":"11.8","title":"光的偏振"},{"t":"tx","h":"偏振现象与马吕斯定律","p":"光是横波，电矢量 E 的振动方向即偏振方向。自然光通过偏振片后成为线偏振光，强度减半。<br><b>马吕斯定律</b>：线偏振光通过检偏器后 I = I₀cos²α（α 为偏振方向与检偏器透光轴夹角）。<br><b>布儒斯特定律</b>：自然光以特定角入射时，反射光成为完全线偏振光，此时 tan i₀ = n₂/n₁，且反射光与折射光互相垂直。"},{"t":"ex","q":"双缝干涉实验中 d = 0.20 mm，D = 1.0 m，用 λ = 600 nm 的光照射。求条纹间距；若改用 λ = 400 nm 的光，间距变为多少？","steps":["Δx = Dλ/d = (1.0 × 600×10⁻⁹)/(0.20×10⁻³)。","分子 = 6.0×10⁻⁷，分母 = 2.0×10⁻⁴。","Δx = 3.0×10⁻³ m = 3.0 mm。","改用 400 nm：Δx′ = 1.0 × 400×10⁻⁹ / 2.0×10⁻⁴ = 2.0×10⁻³ m = 2.0 mm。","结论：间距与波长成正比，短波长条纹更密。"]},{"t":"warn","text":"① 干涉与衍射的公式形式相似但含义不同：干涉看“两束光的光程差”，衍射看“缝内各子波的光程差”。② 半波损失只在“光疏→光密”反射时出现，透射不发生。③ 光栅缺级是 d/a 为整数时才出现，不是任何光栅都有。"},{"t":"dv","title":"推导：杨氏双缝干涉条纹间距 Δx = Dλ/d","steps":["双缝 S₁、S₂ 间距 d，缝到屏距离 D（D ≫ d），求屏上距中心 x 处 P 点的光程差。","光程差 δ = r₂ − r₁ ≈ d·sinθ（远场平行光线近似）。","小角度近似 sinθ ≈ tanθ = x/D → δ ≈ <b>dx/D</b>。","明纹条件 δ = kλ → 明纹位置 x_k = kDλ/d；暗纹 x = (2k+1)Dλ/2d。","相邻条纹间距 Δx = x_{k+1} − x_k = <b>Dλ/d</b>：条纹等间距；D、λ 越大或 d 越小，条纹越疏。"]},{"t":"pt","no":"1","name":"干涉条纹位置与间距","feature":"给双缝/薄膜/牛顿环参数，求条纹间距、级次位置或膜厚。","method":"先写光程差，再套明暗条件，最后解出几何量。","steps":["判断干涉类型：双缝（分波阵面）还是薄膜/牛顿环（分振幅）。","写出光程差 ΔL 的表达式，薄膜类记得加 λ/2 半波损失。","明纹 ΔL = kλ；暗纹 ΔL = (k+½)λ。","代入几何关系（双缝 ΔL = dx/D；薄膜 ΔL = 2ne）解出所求量。","检查级次 k 是否为整数、是否在可见范围内。"],"ex":{"q":"一层 n = 1.38 的增透膜，要使 λ = 550 nm 的绿光反射最小，膜厚至少多少？","steps":["增透要求反射光相消，即满足暗纹条件。","垂直入射，光程差 ΔL = 2ne + λ/2。",
"暗纹：2ne + λ/2 = (k+½)λ，取 k=0 即 2ne = λ/2... 更常用写法：2ne = (2k+1)λ/2，取 k=0 得 2ne = λ/2。","e = λ/(4n) = 550/(4×1.38) = 550/5.52 ≈ 99.6 nm。","答：最小厚度约 100 nm。要点：增透膜用“反射相消”，厚度是 λ/(4n)。"]},"pit":"薄膜干涉一定别漏 λ/2 的半波损失，漏掉会使明暗条件整体差半级。"},{"t":"pt","no":"2","name":"衍射与光栅","feature":"求单缝暗纹位置、中央明纹宽度，或光栅的级次与缺级。","method":"单缝用 asinθ=kλ，光栅用 dsinθ=kλ，再注意缺级。","steps":["单缝：暗纹 a sinθ = kλ（k≠0），中央明纹半角宽 λ/a。","光栅：主极大 d sinθ = kλ，先算最大级次 k<sub>max</sub> = d/λ（取整）。","检查缺级：若 d/a = m 为整数，则 k = m, 2m, 3m… 级缺失。","小角近似 sinθ ≈ θ ≈ x/D 可把角度换成屏上距离。","最后核对所求级次是否被缺级排除。"],"ex":{"q":"光栅 d = 2.0 μm，缝宽 a = 0.50 μm，λ = 600 nm。求能观察到的最高级次及缺级。","steps":["d/a = 2.0/0.50 = 4，为整数，故 k = 4, 8, 12… 缺级。","k<sub>max</sub> = d/λ = 2000/600 ≈ 3.33，取整数 3。","所以实际能看到的级次为 k = 0, ±1, ±2, ±3。","虽然 4 级本应存在，但被缺级排除，且 4 已超过 k<sub>max</sub>。","要点：先算 d/λ 定上限，再用 d/a 删缺级，两步都不能省。"]},"pit":"只算 k<sub>max</sub> 不检查缺级，会多报不存在的级次。"},{"t":"kw","items":["光程","相干光","双缝干涉","条纹间距","半波损失","增透膜","牛顿环","单缝衍射","艾里斑","瑞利判据","光栅方程","缺级","马吕斯定律","布儒斯特角"]}]},"p12":{"no":"12","title":"气体动理论","tag":"热学","sub":"状态方程·压强温度·能量均分·速率分布","blocks":[{"t":"sh","no":"12.1","title":"理想气体的状态方程"},{"t":"tx","h":"状态参量与方程","p":"描述气体状态的参量：压强 p、体积 V、温度 T（热力学温度，T = t + 273.15）。理想气体状态方程：<b>pV = νRT = (m/M)RT</b>，R = 8.31 J/(mol·K)。<br>另一常用形式 p = nkT，其中 n = N/V 为分子数密度，k = R/N<sub>A</sub> = 1.38×10⁻²³ J/K 为玻尔兹曼常数。"},{"t":"sh","no":"12.2","title":"压强的微观本质与温度的统计意义"},{"t":"tx","h":"压强公式","p":"<b>p = (1/3) n m v̄² = (2/3) n ε̄<sub>k</sub></b>，其中 ε̄<sub>k</sub> = ½m v̄² 为分子平均平动动能。<br>推导思路：压强是大量分子对器壁碰撞的统计平均效果——每个分子碰壁传递 2mv<sub>x</sub> 的动量，单位时间单位面积上的总动量传递即为压强。注意它只对大量分子才有意义，单个分子谈不上压强。"},{"t":"tx","h":"温度的微观意义","p":"由 p = nkT 与 p = (2/3)n ε̄<sub>k</sub> 比较得 <b>ε̄<sub>k</sub> = (3/2) kT</b>。<br>这是温度的微观本质：<b>温度是分子平均平动动能的量度</b>，温度越高，分子热运动越剧烈。它是统计概念，对单个分子无意义。绝对零度对应分子平动动能趋于零。"},{"t":"sh","no":"12.3","title":"能量按自由度均分定理"},{"t":"tx","h":"自由度与均分定理","p":"<b>自由度</b> i：确定分子空间位置所需的独立坐标数。单原子分子 i=3（平动）；刚性双原子分子 i=5（3 平动 + 2 转动）；刚性多原子分子 i=6（3 平动 + 3 转动）。<br><b>能量均分定理</b>：平衡态下，分子每个自由度的平均动能都是 ½kT。故分子平均总动能 ε̄ = (i/2)kT。<br>理想气体内能 <b>E = (i/2)νRT</b>——只与 T 有关，与 p、V 无关（这是理想气体的重要特性）。"},{"t":"sh","no":"12.4","title":"麦克斯韦速率分布律"},{"t":"tx","h":"速率分布函数","p":"f(v) = dN/(N dv) 表示速率在 v 附近单位速率区间的分子数占比。<b>归一化条件</b>：∫₀^∞ f(v)dv = 1。<br>三个特征速率：<b>最概然速率</b> v<sub>p</sub> = √(2kT/m) = √(2RT/M)（f(v) 的峰值位置）；<b>平均速率</b> v̄ = √(8kT/πm)；<b>方均根速率</b> v<sub>rms</sub> = √(3kT/m)。三者之比 v<sub>p</sub> : v̄ : v<sub>rms</sub> = √2 : √(8/π) : √3 ≈ 1 : 1.13 : 1.22。<br>温度升高，曲线峰值右移且变矮（面积恒为 1）。"},
{"t":"sh","no":"12.5","title":"平均自由程"},{"t":"tx","h":"碰撞与自由程","p":"分子平均自由程 λ̄ = 1/(√2 π d² n)，平均碰撞频率 Z̄ = √2 π d² n v̄（d 为分子有效直径，n 为分子数密度）。<br>由 p = nkT 得 <b>λ̄ = kT/(√2 π d² p)</b>：温度越高、压强越低，自由程越长。这就是为什么真空管中必须抽高真空——否则电子会被气体分子频繁碰撞。"},{"t":"ex","q":"容积 2.0×10⁻³ m³ 的容器内装有 1.0 mol 氧气（刚性双原子分子），温度 300 K。求压强与内能。","steps":["用 pV = νRT：p = νRT/V = (1.0 × 8.31 × 300)/(2.0×10⁻³)。","分子 = 2493，分母 = 2.0×10⁻³，p = 1.25×10⁶ Pa。","刚性双原子分子 i = 5。","E = (i/2)νRT = (5/2) × 1.0 × 8.31 × 300 = 2.5 × 2493 ≈ 6.23×10³ J。","验算：也可用 E = (i/2)pV = 2.5 × 1.25×10⁶ × 2.0×10⁻³ = 6.25×10³ J，一致 ✓。"]},{"t":"warn","text":"① 理想气体内能只与 T 有关，等温过程内能不变——这是解热力学题的关键前提。② 三种速率的系数别混：v<sub>p</sub> 用 2，v̄ 用 8/π，v<sub>rms</sub> 用 3。③ 自由度要看清“刚性”还是“非刚性”，非刚性双原子还要算振动自由度。"},{"t":"dv","title":"推导：理想气体压强公式 p = ⅔nε̄","steps":["设 N 个分子（质量 m）在边长 l 的容器中，考察垂直于 x 轴的器壁。","速度为 v_x 的分子撞壁一次动量改变 2mv_x；往返碰壁周期 2l/v_x，单位时间碰壁 v_x/(2l) 次。","单个分子对该壁的平均冲力 = 动量改变率 = 2mv_x × v_x/(2l) = mv_x²/l。","N 个分子的总力 F = Σmv_x²/l = (Nm/l)·v̄_x²；压强 p = F/l² = nm·v̄_x²（n = N/V 分子数密度）。","各向同性：v̄_x² = ⅓v̄² → p = ⅓nmv̄² = <b>⅔·n·ε̄</b>（ε̄ = ½mv̄² 为平均平动动能）。"]},{"t":"dv","title":"推导：温度的统计意义 ε̄ = 3kT/2","steps":["状态方程 pV = (M/μ)RT 改写为分子数形式：p = (N/V)(R/N_A)T = <b>nkT</b>（k 为玻尔兹曼常量）。","与微观压强公式 p = ⅔nε̄ 联立 → ⅔nε̄ = nkT。","解得 <b>ε̄ = (3/2)kT</b>：温度是分子平均平动动能的量度。","推论：温度是大量分子的统计结果，对单个分子谈温度无意义；T 相同则各种气体分子平均平动动能相同。"]},{"t":"dv","title":"推导：能量均分定理与理想气体内能","steps":["能量按自由度均分定理：平衡态下每个自由度平均分得 ½kT 的能量。","自由度 i 的分子平均总能量 = (i/2)kT（单原子 i=3，刚性双原子 i=5，刚性多原子 i=6）。","1 mol 气体内能 E = N_A·(i/2)kT = <b>(i/2)RT</b>。","ν mol 气体内能 <b>E = ν(i/2)RT</b>：只由温度与自由度决定，与过程无关——所以内能是状态量。","摩尔热容由此而来：C_V = (i/2)R，C_p = C_V + R = (i+2)R/2，比热容比 γ = C_p/C_V = (i+2)/i。"]},{"t":"pt","no":"1","name":"理想气体状态与内能","feature":"给 p、V、T、质量，求另一参量或内能。","method":"统一用 SI 单位，注意摩尔数与质量的区别。","steps":["判断是否理想气体，写出 pV = νRT。","把质量换算成摩尔数 ν = m/M（M 用 kg/mol）。","温度必须用热力学温度 T = t + 273。","求内能用 E = (i/2)νRT，先确定自由度 i。","检查单位：p 用 Pa，V 用 m³，R = 8.31。"],"ex":{"q":"某理想气体在 27 °C、1.0×10⁵ Pa 下体积为 1.0×10⁻³ m³，求气体摩尔数。","steps":["T = 27 + 273 = 300 K。","ν = pV/(RT) = (1.0×10⁵ × 1.0×10⁻³)/(8.31 × 300)。","分子 = 100，分母 = 2493。","ν ≈ 0.040 mol。","要点：温度忘记加 273 是最常见错误，会让结果偏差近 10%。"]},"pit":"摄氏温度直接代入公式会系统性算错，务必先换成热力学温度。"},{"t":"kw","items":["理想气体状态方程","玻尔兹曼常数","压强微观本质","温度统计意义","自由度","能量均分定理","内能","麦克斯韦速率分布","最概然速率","方均根速率","平均自由程"]}]},"p13":{"no":"13","title":"热力学基础","tag":"热学","sub":"第一定律·循环·卡诺·第二定律·熵","blocks":[{"t":"sh","no":"13.1","title":"内能、功与热量"},
{"t":"tx","h":"三个基本概念","p":"<b>内能</b> E 是状态量（只由状态决定，理想气体 E = (i/2)νRT）；<b>功</b> W 与<b>热量</b> Q 是过程量（同一对初末态，路径不同则数值不同）。<br>气体做功：<b>W = ∫p dV</b>（气体对外做功取正）。在 p–V 图上，功等于过程曲线下的面积——这是判断做功正负与大小的最直观方法。"},{"t":"sh","no":"13.2","title":"热力学第一定律"},{"t":"tx","h":"定律的两种写法","p":"<b>Q = ΔE + W</b>（吸热 = 内能增量 + 对外做功）。<br>符号约定：系统吸热 Q &gt; 0，系统对外做功 W &gt; 0，内能增加 ΔE &gt; 0。<br>第一定律是能量守恒定律在热现象中的体现，对任何过程（含非准静态）都成立。"},{"t":"dv","title":"用第一定律分析四个等值过程（ν mol 理想气体）","steps":["<b>等容过程</b>（V 不变）：W = 0，故 Q = ΔE = (i/2)νRΔT。全部吸热用于升温。","<b>等压过程</b>（p 不变）：W = pΔV = νRΔT，ΔE = (i/2)νRΔT，故 Q = (i/2+1)νRΔT = C<sub>p</sub>νΔT。","<b>等温过程</b>（T 不变）：ΔE = 0，故 Q = W = νRT ln(V₂/V₁)。吸热全部转化为对外做功。","<b>绝热过程</b>（Q = 0）：0 = ΔE + W，即 W = −ΔE = −(i/2)νRΔT。气体绝热膨胀对外做功靠内能减少，温度必降低。","对比记忆：等容“只升温”、等压“又升温又做功”、等温“只做功不升温”、绝热“消耗内能做功”。","绝热过程方程：pV<sup>γ</sup> = 常量，其中 γ = C<sub>p</sub>/C<sub>V</sub> = (i+2)/i。"]},{"t":"sh","no":"13.3","title":"循环过程与卡诺循环"},{"t":"tx","h":"循环与效率","p":"系统经一系列过程回到初态称为<b>循环</b>。因内能是状态量，循环一周 <b>ΔE = 0</b>，故净吸热等于净做功：Q<sub>净</sub> = W<sub>净</sub>（p–V 图上闭合曲线包围的面积）。<br>热机效率 <b>η = W/Q₁ = 1 − Q₂/Q₁</b>（Q₁ 总吸热，Q₂ 总放热）。"},{"t":"tx","h":"卡诺循环","p":"由两个等温过程和两个绝热过程组成的可逆循环，工作于 T₁（高温）与 T₂（低温）之间。<br><b>卡诺效率 η = 1 − T₂/T₁</b>。这是所有工作于同样两热源之间的热机所能达到的<b>最高</b>效率，与工作物质无关。要提高效率只能提高 T₁ 或降低 T₂。"},{"t":"sh","no":"13.4","title":"热力学第二定律"},{"t":"tx","h":"两种表述","p":"<b>开尔文表述</b>：不可能制成一种循环动作的热机，只从单一热源吸热使之完全变为有用功而不产生其他影响（第二类永动机不可能）。<br><b>克劳修斯表述</b>：热量不能自发地从低温物体传到高温物体而不引起其他变化。<br>两种表述等价，都揭示了自然过程具有<b>方向性</b>——这是第二定律的核心。"},{"t":"sh","no":"13.5","title":"熵与熵增加原理"},{"t":"tx","h":"熵的定义与计算","p":"克劳修斯定义：dS = δQ<sub>可逆</sub>/T，熵是状态量。对可逆过程 ΔS = ∫δQ/T。<br>理想气体从 (T₁,V₁) 到 (T₂,V₂)：<b>ΔS = νC<sub>V</sub>ln(T₂/T₁) + νR ln(V₂/V₁)</b>。<br><b>熵增加原理</b>：孤立系统中发生的任何实际过程，总有 ΔS ≥ 0（可逆取等号）。熵是<b>无序度</b>的量度，熵增意味着系统走向更无序——这给出了第二定律的定量表述。"},{"t":"ex","q":"1 mol 单原子理想气体（i=3）经等温膨胀，体积由 V 增为 2V，温度保持 300 K。求 Q、W、ΔE 与 ΔS。","steps":["等温 → ΔE = 0（理想气体内能只与 T 有关）。","W = νRT ln(V₂/V₁) = 1 × 8.31 × 300 × ln2。","ln2 ≈ 0.693，W ≈ 2493 × 0.693 ≈ 1.73×10³ J。","由第一定律 Q = ΔE + W = 0 + 1.73×10³ = 1.73×10³ J。","ΔS = νR ln(V₂/V₁) = 8.31 × 0.693 ≈ 5.76 J/K。","注意 ΔS &gt; 0：等温膨胀是自发的不可逆过程方向，符合熵增。"]},{"t":"warn","text":"① 内能是状态量、功和热是过程量，不要给“某状态的热量”这种说法。② 循环一周 ΔE=0 但 Q 与 W 都不为零（且相等）。③ 卡诺效率只由两热源温度决定，与工质无关；温度必须用开尔文。"},{"t":"dv","title":"推导：卡诺循环效率 η = 1 − T₂/T₁","steps":["卡诺循环 = 两等温 + 两绝热。等温膨胀（T₁）吸热 Q₁ = νRT₁·ln(V₂/V₁)。","等温压缩（T₂）放热 Q₂ = νRT₂·ln(V₃/V₄)。","两条绝热线满足 T₁V₂^(γ−1) = T₂V₃^(γ−1) 与 T₁V₁^(γ−1) = T₂V₄^(γ−1)，相除得 V₂/V₁ = V₃/V₄，故两个对数相等。",
"效率 η = 1 − Q₂/Q₁ = 1 − <b>T₂/T₁</b>。","结论：卡诺效率只由高低温热源温度决定；T₂ 不可能为 0，故 η < 100%——热力学第二定律的定量表达。"]},{"t":"pt","no":"1","name":"热力学过程量与效率","feature":"求某过程的 Q、W、ΔE，或热机效率。","method":"先定过程类型，再用第一定律配状态方程。","steps":["判断过程：等容/等压/等温/绝热/循环。","算 ΔE = (i/2)νRΔT（循环则为 0）。","算 W：等压 pΔV；等温 νRTln(V₂/V₁)；等容 0；绝热 −ΔE。","用 Q = ΔE + W 求热量的正负与大小。","循环效率 η = 1 − Q₂/Q₁，卡诺用 1 − T₂/T₁。"],"ex":{"q":"1 mol 双原子理想气体（i=5）等压加热，温度由 300 K 升至 400 K，求 W、ΔE、Q。","steps":["等压：W = νRΔT = 1 × 8.31 × 100 = 831 J。","ΔE = (i/2)νRΔT = 2.5 × 8.31 × 100 = 2077.5 J。","Q = ΔE + W = 2077.5 + 831 = 2908.5 J ≈ 2.91×10³ J。","验算：Q = C<sub>p</sub>νΔT = (7/2)RΔT = 3.5 × 831 = 2908.5 J ✓。","结论：等压加热时吸热要同时“升温 + 对外做功”，比等容多 7/5 倍。"]},"pit":"等压过程别漏掉做功部分，直接用 Q = C<sub>V</sub>ΔT 会少算 40%。"},{"t":"kw","items":["内能","功","热量","热力学第一定律","等容过程","等压过程","等温过程","绝热过程","循环效率","卡诺循环","热力学第二定律","熵","熵增加原理"]}]},"p14":{"no":"14","title":"狭义相对论","tag":"近代","sub":"洛伦兹变换·钟慢尺缩·质能方程","blocks":[{"t":"sh","no":"14.1","title":"经典时空观的困境"},{"t":"tx","h":"两条基本假设","p":"经典力学中伽利略变换给出“绝对时间、绝对空间”，但麦克斯韦方程组在伽利略变换下不保持形式不变——光速会随参考系变化，这与迈克耳孙–莫雷实验的零结果矛盾。<br>爱因斯坦提出狭义相对论的两条基本假设：<br><b>① 相对性原理</b>：一切物理定律在所有惯性系中形式相同。<br><b>② 光速不变原理</b>：真空中的光速在任何惯性系中都是 c，与光源和观察者的运动无关。"},{"t":"sh","no":"14.2","title":"洛伦兹变换"},{"t":"tx","h":"洛伦兹变换式","p":"设 S′ 系相对 S 系沿 x 轴以 v 运动，则<br><b>x′ = γ(x − vt)，y′ = y，z′ = z，t′ = γ(t − vx/c²)</b><br>其中 <b>γ = 1/√(1 − v²/c²)</b> 称为洛伦兹因子，v → c 时 γ → ∞。<br>与伽利略变换相比，最大区别是<b>时间也参与变换</b>（t′ 含 x 项），这正是“同时的相对性”的数学根源。v ≪ c 时 γ ≈ 1，洛伦兹变换退化为伽利略变换。"},{"t":"sh","no":"14.3","title":"同时的相对性、时间膨胀与长度收缩"},{"t":"tx","h":"三个相对论效应","p":"<b>同时的相对性</b>：在一个惯性系中同时同地发生的事件，在另一惯性系中一般不再同时。"},{"t":"tx","h":"时间膨胀（钟慢效应）","p":"在相对运动的参考系中，运动的钟走得慢：<b>Δt = γ Δτ</b>（Δτ 为固有时，即与事件同地的钟测得的时间）。Δt &gt; Δτ，运动钟变慢。这是“运动的钟走慢”，双方互相看对方都慢，并不矛盾——因为比较必须在同一参考系内完成。"},{"t":"tx","h":"长度收缩（尺缩效应）","p":"沿运动方向测得的长度变短：<b>L = L₀/γ = L₀√(1 − v²/c²)</b>（L₀ 为固有长度，即与尺相对静止时测得的长度）。注意：垂直于运动方向的长度不变。"},{"t":"sh","no":"14.4","title":"相对论质量、动量与能量"},{"t":"tx","h":"相对论质量与动量","p":"随速度增大质量增大：<b>m = γm₀ = m₀/√(1 − v²/c²)</b>（m₀ 为静质量）。动量 p = mv = γm₀v。这解释了为何物体无法被加速到光速——v → c 时 m → ∞，需要无限大能量。"},{"t":"tx","h":"质能关系","p":"<b>E = mc² = γm₀c²</b>，静能 E₀ = m₀c²。动能 E<sub>k</sub> = E − E₀ = (γ−1)m₀c²，低速时退化为 ½m₀v²。<br>能量–动量关系：<b>E² = (pc)² + (m₀c²)²</b>。对光子 m₀ = 0，故 E = pc。质量亏损与核能：ΔE = Δm·c²。"},{"t":"ex","q":"一μ子的固有寿命 τ₀ = 2.2 μs，以 v = 0.99c 相对地面运动。求地面测得的寿命及它飞行的距离。","steps":["先算 γ：v/c = 0.99，1 − v²/c² = 1 − 0.9801 = 0.0199。","γ = 1/√0.0199 ≈ 1/0.1411 ≈ 7.09。",
"地面测得寿命 Δt = γτ₀ = 7.09 × 2.2 ≈ 15.6 μs（远大于固有寿命，钟慢效应）。","飞行距离 L = vΔt = 0.99 × 3.0×10⁸ × 15.6×10⁻⁶。","≈ 2.97×10⁸ × 15.6×10⁻⁶ ≈ 4.6×10³ m。","若用经典算法只有 vτ₀ ≈ 650 m，无法解释 μ子能到达地面——这是相对论的经典验证。"]},{"t":"warn","text":"① γ 里是 1 − v²/c²，别写成 1 + 。② 时间膨胀用“固有时最短”，尺缩用“固有长度最长”，两个“固有”都对应与物体相对静止的参考系。③ 长度收缩只发生在运动方向。"},{"t":"dv","title":"推导：时间膨胀 Δt = γΔt₀","steps":["光钟思想实验：S′ 系中光在间距 L 的两镜间垂直往返，固有时间 Δt₀ = 2L/c。","S′ 系相对 S 以速度 u 运动，S 系看光走斜线：(cΔt/2)² = L² + (uΔt/2)²。","解出 Δt = 2L/√(c²−u²) = (2L/c)/√(1−u²/c²)。","两式相比：<b>Δt = Δt₀/√(1−u²/c²) = γΔt₀</b>（γ > 1，动钟变慢）。","要点：Δt₀ 必须是<b>同一地点</b>发生的两事件间隔（固有时间），否则不能直接套公式。"]},{"t":"dv","title":"推导：长度收缩 l = l₀/γ","steps":["杆静止于 S′ 系，静长 l₀ = x₂′ − x₁′。","S 系测运动杆长度必须<b>同时</b>（Δt = 0）读两端坐标。","洛伦兹变换 x′ = γ(x − ut)：Δx′ = γ(Δx − uΔt) = γΔx（因 Δt = 0）。","即 l₀ = γl → <b>l = l₀√(1−u²/c²)</b>：运动方向变短，垂直方向不变。"]},{"t":"dv","title":"推导：质能关系 E = mc²","steps":["由相对论动量守恒与速度变换联立可导出质速关系 <b>m = γm₀</b>。","对变速质点用动能定理：Ek = ∫F·dx = ∫d(mv)/dt·dx，代入 m = γm₀ 分部积分得 Ek = mc² − m₀c²。","总能量 <b>E = mc²</b>，静能 E₀ = m₀c²——质量本身就是能量的一种形式。","能量动量关系：E² = p²c² + m₀²c⁴；光子 m₀ = 0 → E = pc，p = E/c = h/λ。"]},{"t":"pt","no":"1","name":"相对论效应计算","feature":"已知 v、固有时或固有长度，求测得值或能量。","method":"先算 γ，再套对应公式。","steps":["统一用 β = v/c，γ = 1/√(1−β²)。","判断是求时间还是长度：时间乘 γ，长度除 γ。","涉及能量用 E = γm₀c²、E<sub>k</sub> = (γ−1)m₀c²。","若给的是测得值反求固有值，则时间除 γ、长度乘 γ。","检查结果：γ ≥ 1，动钟时间 ≥ 固有时，动尺长度 ≤ 固有长度。"],"ex":{"q":"一根静止长度为 1.0 m 的尺以 0.60c 沿其长度方向运动，求地面测得的长度。","steps":["β = 0.60，1 − β² = 1 − 0.36 = 0.64。","γ = 1/√0.64 = 1/0.80 = 1.25。","L = L₀/γ = 1.0/1.25 = 0.80 m。","结论：沿运动方向缩短 20%，垂直方向不变。","若问“尺上的人看地面”，则地面尺也以 0.60c 运动，同样缩短为 0.80 m，对称无矛盾。"]},"pit":"把 γ 乘到长度上（应该除）是最常见错误；尺缩是“变短”，所以除以 γ。"},{"t":"kw","items":["相对性原理","光速不变","洛伦兹变换","洛伦兹因子","同时的相对性","时间膨胀","长度收缩","固有时","固有长度","相对论质量","质能关系","静能"]}]},"p15":{"no":"15","title":"量子物理","tag":"近代","sub":"光子·光电效应·德布罗意·不确定关系","blocks":[{"t":"sh","no":"15.1","title":"黑体辐射与普朗克假设"},{"t":"tx","h":"黑体辐射规律","p":"黑体是能完全吸收各种波长辐射的理想物体。实验规律：斯特凡–玻尔兹曼定律 M = σT⁴（总辐射本领与 T⁴ 成正比）；维恩位移定律 <b>λ<sub>m</sub>T = b = 2.898×10⁻³ m·K</b>（温度越高峰值波长越短，这正是炉火由红变白的原因）。<br>经典理论（瑞利–金斯公式）在短波端发散，被称为“紫外灾难”。"},{"t":"tx","h":"普朗克的能量子假设","p":"普朗克提出：振子能量不能连续变化，只能取分立值 <b>E = nhν</b>（n = 1,2,3…），h = 6.63×10⁻³⁴ J·s 为普朗克常数。能量以“量子”形式一份份发射和吸收。这一假设成功解释了黑体辐射谱，标志量子论的诞生。"},{"t":"sh","no":"15.2","title":"光电效应与光子"},{"t":"tx","h":"光电效应的实验规律","p":"① 存在<b>红限频率</b> ν₀：入射光频率低于 ν₀ 时无论光强多大都不产生光电子。② 光电子最大初动能只与频率有关，与光强无关。③ 光强增大时饱和光电流增大（光子数增多）。④ 响应时间极短（&lt;10⁻⁹ s）。<br>经典波动理论无法解释前两条。"},
{"t":"tx","h":"爱因斯坦光子假设","p":"光本身由一份份光子组成，每个光子能量 <b>E = hν</b>，动量 p = h/λ。光电效应方程：<br><b>hν = ½mv²<sub>max</sub> + W</b>（W 为逸出功）<br>红限频率 ν₀ = W/h，遏止电压 eU₀ = ½mv²<sub>max</sub>。当 hν &lt; W 时，单个光子能量不足以克服逸出功，故无论光强多大都无光电子——红限由此得到解释。"},{"t":"sh","no":"15.3","title":"康普顿散射"},{"t":"tx","h":"康普顿效应","p":"X 射线被物质散射后，除原波长外还出现<b>波长变长</b>的成分，且散射角越大波长变化越大。这只能用“光子与自由电子弹性碰撞”解释：光子把部分能量和动量传给电子，自身能量减少、频率降低、波长变长。<br>波长改变量 <b>Δλ = (h/m₀c)(1 − cosθ)</b>，其中 h/m₀c = 2.43×10⁻¹² m 为康普顿波长。这是光的粒子性的直接证据。"},{"t":"sh","no":"15.4","title":"玻尔的氢原子理论"},{"t":"tx","h":"三条假设与能级","p":"① <b>定态假设</b>：电子只能在分立的轨道上运动，不辐射能量。② <b>频率条件</b>：跃迁时辐射或吸收光子，hν = |E<sub>n</sub> − E<sub>m</sub>|。③ <b>角动量量子化</b>：L = nħ（n = 1,2,3…）。<br>由此得氢原子能级 <b>E<sub>n</sub> = −13.6/n² eV</b>，轨道半径 r<sub>n</sub> = n²r₁（r₁ = 0.53 Å）。n=1 为基态，n→∞ 对应电离。"},{"t":"sh","no":"15.5","title":"德布罗意波"},{"t":"tx","h":"物质波假设","p":"德布罗意提出：不仅光具有波粒二象性，实物粒子也有。粒子能量 E = hν、动量 p = h/λ，故<b>德布罗意波长 λ = h/p = h/(mv)</b>。<br>宏观物体波长极短（如 1 g 小球以 1 m/s 运动，λ ≈ 10⁻³¹ m），无法观测；电子经 100 V 加速后 λ ≈ 1.2×10⁻¹⁰ m，与晶格常数同量级，因此能被晶体衍射——戴维孙–革末实验证实了这一点，是电子显微镜的理论基础。"},{"t":"sh","no":"15.6","title":"不确定关系"},{"t":"tx","h":"海森堡不确定关系","p":"<b>Δx·Δp<sub>x</sub> ≥ ħ/2</b>（ħ = h/2π），同样有 ΔE·Δt ≥ ħ/2。<br>含义：粒子的位置与动量不能同时被精确确定——这不是仪器精度问题，而是微观粒子的<b>内禀属性</b>。它说明轨道概念在微观失效，也解释了为何原子中电子不会因辐射而坍缩到核上（基态存在零点能）。"},{"t":"sh","no":"15.7","title":"波函数与薛定谔方程"},{"t":"tx","h":"波函数的统计解释","p":"微观粒子状态用<b>波函数 ψ(r,t)</b> 描述，|ψ|² 表示粒子在某处出现的<b>概率密度</b>（玻恩解释）。波函数须满足：单值、有限、连续，且归一化 ∫|ψ|²dV = 1。<br>定态薛定谔方程：−(ħ²/2m)∇²ψ + Uψ = Eψ。求解需结合边界条件，能量量子化正是边界条件的自然结果（如势阱中 E<sub>n</sub> = n²h²/(8mL²)）。"},{"t":"ex","q":"用 λ = 400 nm 的紫光照射逸出功 W = 2.0 eV 的金属，求光子能量、最大初动能与红限波长。","steps":["光子能量 E = hc/λ = (6.63×10⁻³⁴ × 3.0×10⁸)/(400×10⁻⁹)。","分子 ≈ 1.989×10⁻²⁵，分母 = 4.0×10⁻⁷，E ≈ 4.97×10⁻¹⁹ J。","换算成 eV：4.97×10⁻¹⁹ / 1.6×10⁻¹⁹ ≈ 3.11 eV。","最大初动能 = hν − W = 3.11 − 2.0 = 1.11 eV。","红限波长 λ₀ = hc/W = 1240 (eV·nm) / 2.0 eV = 620 nm。","结论：400 nm &lt; 620 nm，频率高于红限，能产生光电子 ✓。"]},{"t":"warn","text":"① 判断能否发生光电效应只看<b>频率是否高于红限</b>，与光强无关。② hc = 1240 eV·nm 这个数值能大幅加快计算，建议背下来。③ 不确定关系是“≥”而不是测量误差，不要理解为仪器不够准。"},{"t":"dv","title":"推导：爱因斯坦光电效应方程","steps":["光子能量 hν 被电子一次性吸收：一部分克服逸出功 W，其余成为光电子最大初动能。","能量守恒：<b>hν = W + ½mv_m²</b>（爱因斯坦光电方程）。","红限频率：ν₀ = W/h，ν < ν₀ 时无论光强多大都没有光电子——经典波动说无法解释，光子说自然给出。","遏止电压 eU_a = ½mv_m² = hν − W → U_a 与 ν 成线性关系，斜率 h/e（密立根实验验证）。"]},{"t":"dv","title":"推导：康普顿散射公式 Δλ = 2λ_c·sin²(θ/2)","steps":["把 X 光子与静止自由电子的散射当作<b>弹性碰撞</b>，联立能量守恒与动量守恒。",
"能量：hν₀ + m₀c² = hν + mc²；动量（矢量）：p⃗₀ = p⃗ + m⃗v。","动量式平方后与能量式平方相减，消去电子项 m、v，代入 p = h/λ。","整理得 <b>Δλ = λ′ − λ = (h/m₀c)(1−cosθ) = 2λ_c·sin²(θ/2)</b>。","康普顿波长 λ_c = h/(m₀c) ≈ 0.00243 nm；Δλ 只与散射角 θ 有关，与入射波长和材料无关——光子粒子性的直接证据。"]},{"t":"dv","title":"推导：玻尔氢原子能级 E_n = −13.6/n² eV","steps":["电子圆轨道：库仑力提供向心力 e²/(4πε₀r²) = mv²/r。","玻尔量子化条件：角动量 mvr = nħ（n = 1, 2, 3, …）。","联立解出轨道半径 r_n = n²·(4πε₀ħ²/me²) = <b>n²a₀</b>，a₀ ≈ 0.529 Å 为玻尔半径。","总能量 E = ½mv² − e²/(4πε₀r) = −e²/(8πε₀r)（动能恰为势能绝对值的一半）。","代入 r_n：<b>E_n = −13.6/n² eV</b>；跃迁 hν = E_m − E_n 即解释氢光谱各线系（n→1 莱曼系、n→2 巴耳末系）。"]},{"t":"pt","no":"1","name":"光电效应与光子能量","feature":"给入射光波长与逸出功，求最大初动能、遏止电压或红限。","method":"统一用 eV 与 nm，套 E=hc/λ 与光电方程。","steps":["用 E(eV) = 1240/λ(nm) 快速求光子能量。","判断 E 是否大于 W：不大于则无光电子。","最大初动能 E<sub>k</sub> = E − W。","遏止电压 U₀ = E<sub>k</sub>/e，数值上等于 E<sub>k</sub> 的 eV 数。","红限波长 λ₀ = 1240/W(eV)。"],"ex":{"q":"波长 500 nm 的光照射逸出功 1.9 eV 的金属，求遏止电压。","steps":["光子能量 E = 1240/500 = 2.48 eV。","E &gt; W，能产生光电子。","最大初动能 = 2.48 − 1.90 = 0.58 eV。","遏止电压 U₀ = 0.58 V（数值上等于 eV 数）。","要点：遏止电压单位是伏特，但数值等于最大初动能的电子伏特数。"]},"pit":"把 1240 keV·nm 或 12.4 eV·Å 混用会导致数量级错误，统一用 1240 eV·nm。"},{"t":"kw","items":["黑体辐射","维恩位移定律","能量子","普朗克常数","光电效应","红限频率","逸出功","遏止电压","康普顿散射","玻尔能级","德布罗意波","不确定关系","波函数","薛定谔方程"]}]}}},
  "org": {"key":"org","name":"计算机组成原理","icon":"⌘","book":"《计算机组成原理》(第2版) · 唐朔飞 编著 · 高教社","prog":"知识点已覆盖第 1–10 章 · 期末重点题精练已就位","progPct":90,"intro":"按课本《计算机组成原理》(第2版) 的顺序编排：单元 = 课本一章，章下按课本原小节(1.1、1.2…)拆开。计组的痛点是“每章都懂却串不起来”——记住这条主线：一台机器如何从“一条指令”跑成“整个程序”。数据怎么表示 → 存哪 → 怎么传输 → 怎么被指令调度。","map":{"root":{"title":"计算机组成原理","x":50,"y":13},"hubs":[{"id":"g1","title":"第1篇 概论 (第1–2章)","x":18,"y":37},{"id":"g2","title":"第2篇 硬件结构 (第3–5章)","x":50,"y":37},{"id":"g3","title":"第3篇 中央处理器 (第6–10章)","x":83,"y":37}],"units":[{"id":"g1","no":"1","title":"计算机系统概论","sub":"冯·诺依曼·五大部件","tag":"概论","x":8,"y":58,"parent":"g1"},{"id":"g2","no":"2","title":"计算机的发展及应用","sub":"发展史·分类·应用","tag":"概论","x":26,"y":58,"parent":"g1"},{"id":"g3","no":"3","title":"系统总线","sub":"分类·性能·总线控制","tag":"硬件","x":28,"y":78,"parent":"g2"},{"id":"g4","no":"4","title":"存储器","sub":"主存·Cache·辅存","tag":"硬件","x":44,"y":78,"parent":"g2"},{"id":"g5","no":"5","title":"输入输出系统","sub":"接口·中断·DMA","tag":"硬件","x":60,"y":58,"parent":"g2"},{"id":"g6","no":"6","title":"计算机的运算方法","sub":"补码·定点·浮点·ALU","tag":"CPU","x":72,"y":56,"parent":"g3"},{"id":"g7","no":"7","title":"指令系统","sub":"格式·寻址·RISC","tag":"CPU","x":88,"y":56,"parent":"g3","cur":true},{"id":"g8","no":"8","title":"CPU 的结构和功能","sub":"指令周期·流水·中断","tag":"CPU","x":60,"y":96,"parent":"g3"},{"id":"g9","no":"9","title":"控制单元的功能","sub":"微操作·控制方式","tag":"CPU","x":72,"y":96,"parent":"g3"},{"id":"g10","no":"10","title":"控制单元的设计","sub":"硬布线·微程序","tag":"CPU","x":84,"y":96,"parent":"g3"},{"id":"g11","no":"11","title":"期末模拟卷 · 重点题精练","sub":"真题·计算模板","tag":"题源","x":40,"y":96,"parent":"g3"},{"id":"g12","no":"12","title":"模型机的组成与微指令操作","sub":"实验箱模型机 · 内部结构 · 微程序控制 · 微指令操作","tag":"课程设计","x":62,"y":112,"parent":"g3"}]},"units":{"g1":{"no":"1","title":"计算机系统概论","tag":"第1篇 · 第1章","sub":"课本第1章。先建立全局地图：计算机由哪几部分组成、数据如何流动，后面章节都是往里填细节。","blocks":[{"t":"sh","no":"1.1","title":"计算机系统简介"},{"t":"tx","h":"软硬件概念与层次结构","p":"计算机系统 = <b>硬件</b>（物理设备）+ <b>软件</b>（程序与文档）。系统是分层的：应用程序 → 高级语言 → 操作系统 → 机器语言（指令系统）→ 微指令 → 硬件逻辑。每一层向上提供“透明”接口。"},{"t":"tx","h":"计算机组成与计算机体系结构","p":"<b>计算机体系结构</b>是程序员看到的机器属性（有无乘法指令、指令格式等），<b>计算机组成</b>是这些属性的具体实现（乘法用专门部件还是加法器。体系结构偏“做什么”，组成偏“怎么做”"},{"t":"sh","no":"1.2","title":"计算机的基本组成"},{"t":"tx","h":"冯·诺依曼计算机的特点","p":"核心思想是<b>存储程序</b>：把程序和数据一起用二进制存进存储器，机器自动按序取指执行。五大部件：<b>运算器、控制器、存储器、输入设备、输出设备</b>（运算器+控制器=CPU）。指令和数据都以二进制、同等地位存放，由地址访问。"},{"t":"tx","h":"计算机的工作步骤","p":"以“计算 a+b”为例：<b>① 取指</b>（按 PC 从主存取指令到 IR）→ <b>② 分析</b>（译码）→ <b>③ 取数</b>（按地址取操作数）→ <b>④ 运算</b>（ALU 计算）→ <b>⑤ 存结果</b>。这就是“存储程序”自动执行的最小闭环。"},
{"t":"fig","kind":"fig-von","cap":"冯·诺依曼机五大部件与数据流向：运算器+控制器=CPU"},{"t":"tb","head":["部件","职责"],"rows":[["运算器 ALU","算术/逻辑运算，数据加工中心"],["控制器 CU","取指、译码、发控制信号，指挥中心"],["存储器","存放程序与数据，按地址访问"],["输入设备","程序/数据送入机器"],["输出设备","结果送给人或外部"]]},{"t":"sh","no":"1.3","title":"计算机硬件的主要技术指标"},{"t":"tx","h":"三大指标","p":"<b>机器字长</b>：CPU 一次能处理的二进制位数（与寄存器、数据总线宽度相关）；<b>存储容量</b>：主存能存放的二进制信息总量 = 存储单元数 × 每单元位数；<b>运算速度</b>：用主频、CPI、MIPS、FLOPS 等衡量。"},{"t":"dv","title":"推导：执行时间、CPI、MIPS 的换算链","steps":["<b>基准公式</b>：执行时间 T = 指令条数 IC × 平均 CPI × 时钟周期 Tc，而 Tc = 1/f（f 为主频）","代入得 <b>T = IC × CPI / f</b> —— 三者知道任意两个就能求第三个，这是所有性能题的母公式","<b>MIPS</b>（每秒百万条指令）= f / (CPI × 10⁶) = IC / (T × 10⁶)","实用简化：f 用 MHz 为单位时，<b>MIPS = f(MHz) / CPI</b>，单位自动对齐，不必再除 10⁶","两条推论：① f 翻倍 → T 减半（前提 CPI 不变）；② 用快指令替换慢指令（降低平均 CPI）同样能提速，不是只有堆主频一条路","平均 CPI <b>不是</b>各类 CPI 的算术平均，必须按指令条数加权：CPI = Σ(ICᵢ × CPIᵢ) / ΣICᵢ"]},{"t":"ex","q":"【例题】某机主频 1 GHz。某程序含三类指令：A 类 2×10⁶ 条（CPI=1）、B 类 3×10⁶ 条（CPI=2）、C 类 5×10⁶ 条（CPI=4）。求总指令数、平均 CPI、执行时间与 MIPS。","steps":[{"s":"总指令数 IC = 2×10⁶ + 3×10⁶ + 5×10⁶ = <b>10⁷ 条</b>","note":"三类相加，别漏任何一类"},{"s":"总时钟周期数 = Σ(ICᵢ × CPIᵢ) = 2×10⁶×1 + 3×10⁶×2 + 5×10⁶×4 = 2 + 6 + 20 = <b>28×10⁶ 个周期</b>","note":"这是周期总数，不是平均 CPI","why":"周期的真实累加必须加权"},{"s":"平均 CPI = 28×10⁶ ÷ 10×10⁶ = <b>2.8</b>","note":"落在 1~4 之间，可作合理性自检"},{"s":"执行时间 T = 周期总数 × Tc = 28×10⁶ ÷ (1×10⁹ Hz) = <b>28 ms</b>","note":"Tc = 1/f = 1 ns"},{"s":"MIPS = f(MHz) ÷ CPI = 1000 ÷ 2.8 ≈ <b>357 MIPS</b>","note":"也可用 IC/(T×10⁶) = 10⁷/(0.028×10⁶) ≈ 357，两法必须一致"},{"s":"回代检验：T = IC × CPI / f = 10⁷ × 2.8 ÷ 10⁹ = 28 ms ✓"}]},{"t":"ex","q":"【典型例题】某机主存容量为 64K×16 位，求总容量（以字节计）。","steps":["64K = 64×1024 = 65536 个存储单元","每单元 16 位 = 2 字节","总容量 = 65536 × 2 = 131072 字节 = 128 KB","若改为 64K×8 位，则 = 64KB。"]},{"t":"warn","text":"<b>易错点：</b>① 区分“计算机组成”(如何实现)与”体系结构“(对外属性)；② 存储容量单位注意 位/字节 换算(÷8)；③ 冯·诺依曼机原始形态以运算器为中心，现代机器以存储器为中心。"},{"t":"sh","no":"1.4","title":"数制转换（本章计算第一关）"},{"t":"tx","h":"四种常用进制与位权","p":"位权就是“这一位代表多少个 1”。二进制第 i 位（从 0 数）的位权是 <b>2<sup>i</sup></b>，八进制是 8<sup>i</sup>，十六进制是 16<sup>i</sup>。记住一条：<b>4 位二进制正好对应 1 位十六进制，3 位二进制正好对应 1 位八进制</b>，这是所有快速换算的根据。"},{"t":"tb","head":["进制","基数","可用数字","位权","前缀/后缀"],"rows":[["二进制","2","0 1","2<sup>i</sup>","后缀 B，如 1011B"],["八进制","8","0~7","8<sup>i</sup>","后缀 O 或 Q，如 27Q"],["十进制","10","0~9","10<sup>i</sup>","后缀 D，如 45D"],["十六进制","16","0~9, A~F","16<sup>i</sup>","后缀 H 或 0x，如 2DH"]]},{"t":"fig","kind":"fig-numsys","cap":"<b>图解</b>：数制转换的三个基本方向与按权展开示例 (1011.101)₂ = 11.625。"},
{"t":"dv","title":"推导 1：十进制整数 → 二进制（除 2 取余，倒序读）","steps":["以 <b>45</b> 为例。45 ÷ 2 = 22 余 <b>1</b>（最低位）","22 ÷ 2 = 11 余 <b>0</b>；11 ÷ 2 = 5 余 <b>1</b>；5 ÷ 2 = 2 余 <b>1</b>","2 ÷ 2 = 1 余 <b>0</b>；1 ÷ 2 = 0 余 <b>1</b>（最高位，商为 0 即停止）","把余数<b>从下往上</b>抄：1 0 1 1 0 1 → 45 = <b>101101B</b>","验算（按权展开）：1×32 + 0×16 + 1×8 + 1×4 + 0×2 + 1×1 = 32+8+4+1 = <b>45</b> ✓","要点：余数要<b>倒着读</b>，顺序抄反是最常见错误"]},{"t":"dv","title":"推导 2：二进制 → 十进制（按权展开求和）","steps":["以 <b>101101B</b> 为例，从右往左标位权 1,2,4,8,16,32","逐位相乘：1×32 + 0×16 + 1×8 + 1×4 + 0×2 + 1×1","求和 = 32 + 8 + 4 + 1 = <b>45</b>","含小数时位权继续减半：0.101B = 1×0.5 + 0×0.25 + 1×0.125 = <b>0.625</b>","技巧：数 1 的位置有哪些位权，就把这些位权加起来，0 位直接跳过"]},{"t":"dv","title":"推导 3：二进制 ↔ 十六进制 / 八进制（分组法）","steps":["二进制 <b>1011 0101</b> → 十六进制：<b>从右往左</b>每 4 位一组，不足左补 0","1011 = B（11），0101 = 5 → 结果 <b>B5H</b>","反向：B5H → 每位拆 4 位 → 1011 0101B，位数永远不变","二进制 → 八进制：每 <b>3 位</b>一组。101101 = 101 101 → 55Q","小数部分分组方向相反：<b>从左往右</b>分组、右侧补 0，如 0.1011B → 0.1011 → 0.B = 0.BH","要点：整数部分右起分组、小数部分左起分组，方向别弄反"]},{"t":"dv","title":"推导 4：十进制小数 → 二进制（乘 2 取整，顺序读）","steps":["以 <b>0.6875</b> 为例。0.6875 × 2 = 1.375 → 取整 <b>1</b>（小数点后第 1 位）","0.375 × 2 = 0.75 → 取整 <b>0</b>（第 2 位）","0.75 × 2 = 1.5 → 取整 <b>1</b>（第 3 位）","0.5 × 2 = 1.0 → 取整 <b>1</b>，小数变 0 停止（第 4 位）","整数部分<b>顺向</b>抄：0.1011B，验算 0.5+0.125+0.0625 = 0.6875 ✓","注意：整数用“除 2 取余倒着读”，小数用“乘 2 取整顺着读”，两者方向相反"]},{"t":"ex","q":"【例题】求 45.6875 的二进制表示，并验证。","steps":["整数部分 45：除 2 取余倒读 → 101101","小数部分 0.6875：乘 2 取整顺读 → 0.1011","拼接：<b>101101.1011B</b>","验算整数：32+8+4+1 = 45 ✓；验算小数：0.5+0.125+0.0625 = 0.6875 ✓"]},{"t":"sh","no":"1.5","title":"常用编码：BCD、ASCII 与汉字编码"},{"t":"tx","h":"三类编码别混用","p":"<b>BCD 码</b>是“用二进制形式写十进制数”，每一位十进制数占 4 位；<b>ASCII</b> 是字符编码，一个字符 7 位有效码（存 1 字节）；<b>汉字编码</b>要经区位码 → 国标码 → 机内码三步。三者服务对象不同，考试常混在一起考换算。"},{"t":"tb","head":["编码","长度","要点"],"rows":[["BCD 8421 码","每位 4 位","0000~1001 表示 0~9，1010~1111 为非法码"],["余 3 码","每位 4 位","8421 码 + 3（0011），无全 0 码，便于检错"],["ASCII","7 位有效（存 8 位）","数字 48~57，大写 A~Z 为 65~90，小写 97~122"],["区位码 → 国标码","2 字节","区号、位号各 +32（即 +20H）"],["国标码 → 机内码","2 字节","每个字节再 +128（即 +80H），最高位置 1"]]},{"t":"dv","title":"推导：区位码 → 国标码 → 机内码（三步各算什么）","steps":["设某汉字区位码为 <b>(16, 01)</b>——注意区号、位号都是<b>十进制</b>","第 1 步 转国标码：区号 16 + 32 = 48，位号 1 + 32 = 33","第 2 步 十进制转十六进制：48 = <b>30H</b>，33 = <b>21H</b> → 国标码 <b>3021H</b>","第 3 步 加 8080H 得机内码：3021H + 8080H = <b>B0A1H</b>","记忆链：区位码 <b>+2020H</b> → 国标码，国标码 <b>+8080H</b> → 机内码","为什么加 80H：让每字节最高位为 1，从而与 7 位 ASCII 区分开，避免中西文混淆"]},
{"t":"ex","q":"【例题】字符 \"5\" 的 ASCII 码是 53，求字符 \"9\" 的 ASCII 码；又知 \"A\" 是 65，求 \"a\" 的 ASCII 码。","steps":["数字 0~9 的 ASCII 连续：0 是 48，故 \"9\" = 48 + 9 = <b>57</b>","\"5\" 也可验证：48 + 5 = 53 ✓","大写与小写相差固定 32：a = A + 32 = 65 + 32 = <b>97</b>","结论：数字从 48 起、大写从 65 起、小写从 97 起，都是连续排列"]},{"t":"sh","no":"1.6","title":"计算机的层次结构"},{"t":"tx","h":"为什么是“层次”而不是“一堆硬件”","p":"计算机从最底层的电信号到最上层的高级语言，被划分成多层虚拟机。每一层只关心“下一层给我什么接口”，不关心下一层怎么实现。这样上层软件不必了解硬件细节，下层改动也不影响上层程序。"},{"t":"tb","head":["层次","名称","内容","语言形式"],"rows":[["M4（最高）","高级语言机器","C/Java/Python 等应用程序","高级语言，需编译/解释"],["M3","汇编语言机器","汇编程序、宏指令","汇编语言，需汇编器翻译"],["M2","操作系统机器","操作系统，管理资源、提供系统调用","机器指令 + 系统调用"],["M1","传统机器（机器语言机器）","指令系统，即程序员看到的机器","机器指令（二进制）"],["M0（最低）","微程序机器","微程序控制器，用微指令解释机器指令","微指令"]]},{"t":"tx","h":"层间关系的三句话","p":"① <b>下层是上层的基础</b>，上层是下层的功能扩展；② 翻译与解释不同——<b>翻译</b>是先把上层程序整体变成下层程序再执行（编译、汇编），<b>解释</b>是逐条读上层语句边读边执行（解释器、微程序）；③ 微程序机器把“硬件动作”程序化，是软硬件的分界面。"},{"t":"warn","text":"<b>易错点：</b>① 数制转换中整数“倒读”、小数“顺读”，方向最易错；② BCD 码不是二进制数——1001B 作 BCD 是“9”而非 9 的二进制值；③ 区位码是十进制、国标码与机内码是十六进制，跨进制时先转换再加减；④ 层次结构中 M0 微程序机器在最底层，不是操作系统。"},{"t":"sh","no":"","title":"计组计算题全景清单（16 类必考，逐条对应章节）"},{"t":"tx","h":"先看这张表：你的计算题到底覆盖全了没","p":"下表把唐朔飞《计算机组成原理》全书能出计算题的 16 个考点一次性列全。每一条都标了核心公式、所在单元与该单元是否已配<b>完整演算例题</b>——凡标「已配例题」的，点进对应单元都能看到逐步推导。"},{"t":"tb","head":["#","计算考点","核心公式 / 口径","所在单元","例题"],"rows":[["1","数制转换与编码","整数除 2 取余倒读、小数乘 2 取整顺读；二↔十六 4 位一组","第 1 章","已配 2 例"],["2","存储容量与寻址范围","容量 = 2^地址位 × 字长；寻址范围 = 2^地址位数","第 1 章","已配例题"],["3","性能指标 CPI / MIPS","T = IC×CPI/f；MIPS = f(MHz)/CPI","第 1 章","已配例题"],["4","总线带宽与传输率","带宽 = 工作频率 × 每拍字节数","第 3 章","已配 2 例"],["5","存储器芯片扩展","片数 = 总容量/单片容量；先位扩展再字扩展","第 4 章","已配例题"],["6","Cache 地址划分","tag = 主存地址 − 行号 − 块内；行数 = Cache/块","第 4 章","已配例题"],["7","Cache 平均访问时间","t = h·t_c + (1−h)·t_m（或 h·t_c + (1−h)(t_c+t_m)）","第 4 章","已配例题"],["8","DRAM 刷新开销","死区 = 行数×存取周期；异步间隔 = 刷新周期/行数","第 4 章","已配例题"],["9","磁盘容量与平均存取时间","容量 = 磁头×柱面×扇区×扇区大小；T = 寻道 + 半圈 + 传输","第 4 章","已配 2 例"],["10","多体交叉存储器","低位交叉 T = T_m + (m−1)·τ；加速比 = mT/T","第 4 章","已配例题"],["11","补码 / 浮点 / IEEE 754","补码 = 取反加 1；值 = (−1)^S × 1.M × 2^(E−127)","第 6 章","已配多例"],["12","校验码（海明 / CRC）","2^k ≥ n+k+1；CRC 模 2 除法取余","第 6 章","已配例题"],["13","指令格式与地址码","操作码 = ⌈log₂指令数⌉；地址码 = 字长 − 操作码","第 7 章","已配 4 例"],["14","有效地址 EA","变址 (IX)+A、基址 (BR)+A、相对 (PC)+A；访存 0/1/2 次","第 7 章","已配例题"],["15","流水线性能","T = (k+n−1)Δt；S = k·n/(k+n−1)；E = S/k","第 8 章","已配 2 例"],["16","微指令编码位数","字段直接编码 = Σ⌈log₂(nᵢ+1)⌉",
"第 10 章","已配例题"]]},{"t":"tip","text":"用法：考前先按这张表自检，哪一行算不出来就点进对应单元看推导。计算题的失分九成来自三处——<b>单位不统一</b>（K=1024、B 与 b 差 8 倍、r/min 未除 60）、<b>公式记错主体</b>（行号 vs 组号、寻道 vs 旋转）、<b>少乘或多乘一步</b>（忘了块内地址、忘了半圈）。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第1章习题）"},{"t":"pt","no":"题型1","name":"冯·诺依曼结构与五大部件","feature":"给出计算机组成框图或描述，判断部件功能或结构特性。","method":"五大部件：运算器、控制器、存储器、输入设备、输出设备；核心思想＝存储程序 + 二进制。","steps":["先定位“存储程序”这一根本特征","对照五大部件功能逐项匹配","区分运算器（ALU）与控制器（CU）职责","判断是否为冯·诺依曼结构（指令数据同存储器）"],"ex":{"q":"判断：冯·诺依曼计算机中，指令和数据都存放在存储器中，且以二进制表示。","steps":["冯·诺依曼核心：存储程序、指令与数据同等地位存于存储器","均采用二进制编码","故该说法正确","这是与哈佛结构（指令数据分开）的关键区别。"]},"pit":"控制器不等于运算器；冯·诺依曼结构的关键是“指令和数据不分家”。"},{"t":"pt","no":"题型2","name":"计算机的层次结构与软硬件界面","feature":"涉及微程序、机器语言、汇编、高级语言的层次判断。","method":"从下到上：微程序→机器语言→操作系统→汇编→高级语言→应用。","steps":["确定题目问的是哪一层","机器语言是硬件能直接执行的语言","汇编语言需汇编程序翻译","高级语言需编译/解释程序翻译"],"ex":{"q":"计算机能直接执行的语言是（　）。","steps":["机器语言由二进制指令组成","硬件可直接译码执行","汇编、高级语言都需翻译","答案：机器语言。"]},"pit":"汇编语言不是机器语言，仍需汇编器翻译。"},{"t":"pt","no":"题型3","name":"性能指标计算（CPI、MIPS、主频）","feature":"给出主频、时钟周期、CPI、指令条数，求执行时间或 MIPS。","method":"执行时间 = 指令数 × CPI × 时钟周期；MIPS = 主频 / (CPI×10⁶)。","steps":["统一单位：主频 f，时钟周期 T = 1/f","执行时间 CPU = 指令数 × CPI × T","MIPS = f / (CPI × 10⁶)","注意平均 CPI = Σ(各类指令比例×CPI)"],"ex":{"q":"主频 1GHz，某程序 10⁹ 条指令，平均 CPI=2，求执行时间。","steps":["时钟周期 T = 1/1GHz = 1ns","执行时间 = 10⁹ × 2 × 1ns","= 2×10⁹ ns = 2 s","MIPS = 1000/2 = 500。"]},"pit":"CPI 是“平均”每条指令周期数；单位换算（ns↔s）最易错。"},{"t":"pt","no":"题型4","name":"存储容量与地址计算","feature":"给地址线/数据线位数或字数×字长，求容量或地址范围。","method":"容量 = 字数 × 每字位数；n 位地址线 → 2ⁿ 个单元。","steps":["地址线条数 n → 可寻址单元数 2ⁿ","每个单元位数 w","总容量 = 2ⁿ × w (bit)","换算成 KB/MB 时注意 1B=8bit"],"ex":{"q":"地址线 16 根、每单元 8 位，求存储容量。","steps":["可寻址单元 = 2¹⁶ = 65536","每单元 8 bit = 1 B","容量 = 65536 B = 64 KB","地址范围 0000H~FFFFH。"]},"pit":"字长与字节不同；容量单位 bit 与 Byte 差 8 倍。"},{"t":"tip","text":"<b>第1章解题总流程：</b>①结构题先抓“存储程序/五大部件”；②性能题统一单位后套 执行时间=指令数×CPI×周期；③容量题先算 2ⁿ 个单元再乘位宽；④区分“能直接执行”的是机器语言。"},{"t":"kw","items":["存储程序","五大部件","冯·诺依曼","层次结构","机器字长","存储容量"]}]},"g2":{"no":"2","title":"计算机的发展及应用","tag":"第1篇 · 第2章","sub":"课本第2章。了解计算机的发展脉络与应用领域，建立对硬件演进的整体认识。","blocks":[{"t":"sh","no":"2.1","title":"计算机的发展史"},{"t":"tx","h":"四代计算机与摩尔定律","p":"按电子器件分五代：<b>电子管 → 晶体管 → 中小规模集成电路 → 大规模集成电路(VLSI) → 超大规模</b>。驱动规律：摩尔定律——集成电路上晶体管数约每 18–24 个月翻一番。"},{"t":"sh","no":"2.2","title":"计算机的应用"},{"t":"tx","h":"主要应用领域","p":"科学计算与数据处理、工业控制与实时控制、网络技术应用、虚拟现实、办公自动化与管理信息系统、CAD/CAM/CIMS、多媒体技术、人工智能等。"},
{"t":"sh","no":"2.3","title":"计算机的展望"},{"t":"tx","h":"发展趋势","p":"朝着<b>巨型化、微型化、网络化、智能化</b>方向发展；并行处理、多核、异构计算、云计算与边缘计算成为主流方向。"},{"t":"ex","q":"【典型例题】为什么说集成电路的发展推动了计算机的微型化？","steps":["集成度提高 → 单位面积可容纳更多晶体管","单一芯片即可实现 CPU 功能（微处理器）","整机体积与功耗大幅下降","成本降低使个人计算机普及 → 微型化","核心：器件工艺进步是计算机形态演进的物质基础。"]},{"t":"warn","text":"<b>易错点：</b>① 分代依据是“电子器件”不是“规模”；② 摩尔定律是经验规律不是物理定律；③ 本章偏了解性内容，考试多为选择/填空。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第2章习题）"},{"t":"pt","no":"题型1","name":"计算机发展阶段的判断","feature":"按电子器件/年代判断属于第几代计算机。","method":"电子管→晶体管→中小规模集成电路→大规模集成电路→超大规模/智能。","steps":["记牢四代对应器件","匹配年代与器件","软件（机器语言→高级语言→操作系统）同步演进","人工智能属于新一代/智能化阶段"],"ex":{"q":"采用晶体管为主要元件的计算机属于第几代？","steps":["第一代：电子管","第二代：晶体管","故答案为第二代","第三代起进入集成电路。"]},"pit":"代际划分以“主要逻辑元件”为准，不看体积。"},{"t":"pt","no":"题型2","name":"摩尔定律与硬件发展规律","feature":"关于集成度增长、性能提升的规律判断。","method":"摩尔定律：约每 18–24 个月芯片上晶体管数翻一番。","steps":["记忆翻番周期 18–24 个月","它是经验规律而非物理定律","近年增速放缓但仍在推进","与主频、存储容量增长关联理解"],"ex":{"q":"判断：摩尔定律指出集成电路上可容纳的晶体管数目约每两年翻一番。","steps":["摩尔定律描述集成度增长","周期约 18–24 个月（约两年）","属经验性观察规律","故说法基本正确。"]},"pit":"摩尔定律不是严格物理定律，不宜绝对化。"},{"t":"pt","no":"题型3","name":"计算机分类与应用领域","feature":"按用途/规模/数据处理方式分类判断。","method":"按规模：巨型机、大型机、小型机、微型机；按数据：数字、模拟、混合。","steps":["看分类依据（规模/用途/数据形式）","对应列举典型机种","嵌入式属于专用/微型范畴","混合计算机兼具数字与模拟"],"ex":{"q":"天气预报中处理大量数值计算的计算机最可能是（　）。","steps":["需超高算力、大规模并行","属于巨型机（超级计算机）","用于科学计算","答案：巨型机。"]},"pit":"服务器、工作站与巨型机不混淆，区别在规模与用途。"},{"t":"tip","text":"<b>第2章解题总流程：</b>①代际看“主要逻辑元件”；②规律题记摩尔定律周期；③分类题先定分类依据再对应机种。"},{"t":"kw","items":["四代计算机","摩尔定律","应用领域","巨型化/微型化","智能化"]}]},"g3":{"no":"3","title":"系统总线","tag":"第2篇 · 第3章","sub":"课本第3章。总线是各部件共享的“高速公路”，理解其分类与性能才能解释带宽瓶颈。","blocks":[{"t":"sh","no":"3.1","title":"总线的基本概念"},{"t":"tx","h":"为什么用总线","p":"总线是连接多个部件的一组公共信号线。采用总线结构可减少连线、便于扩展，多个部件分时共享一条总线，但同一时刻只能有一个部件发送。"},{"t":"sh","no":"3.2","title":"总线的分类"},{"t":"tx","h":"按功能与层次分类","p":"按功能分：<b>数据总线</b>(传数据，宽度决定一次传输位数)、<b>地址总线</b>(传地址，宽度决定寻址空间)、<b>控制总线</b>(传控制/状态信号)。按层次分：<b>片内总线</b>(芯片内部)、<b>系统总线</b>(各插件板之间)、<b>通信总线</b>(设备/系统之间)。"},{"t":"sh","no":"3.3","title":"总线特性及性能指标"},{"t":"tx","h":"特性与性能","p":"总线特性包括机械、电气、功能、时间四方面。<b>性能指标</b>：总线宽度(位数)、总线带宽(数据传输率)、总线工作频率、总线复用等。"},{"t":"fig","kind":"fig-bus","cap":"三总线结构：数据总线传数据、地址总线传地址、控制总线传控制信号"},{"t":"fx","lines":["总线带宽 = 总线工作频率 × 每次传输字节数（B/s）","寻址空间 = 2^(地址线位数)","例：地址线 20 位 → 寻址 2²⁰ = 1M 个单元"]},{"t":"sh","no":"3.4","title":"总线结构"},{"t":"tx","h":"单总线与多总线","p":"<b>单总线结构</b>：所有部件挂一条总线，简单但易成瓶颈；<b>多总线结构</b>（如双总线、三总线）：用桥连接不同速度的总线，缓解瓶颈。"},
{"t":"sh","no":"3.5","title":"总线控制"},{"t":"tx","h":"仲裁与定时","p":"多个主设备争用总线时要<b>总线仲裁</b>：集中式(链式查询、计数器定时查询、独立请求)与分布式。<b>总线定时</b>分同步(统一时钟，快但受最慢部件拖累)与异步(握手应答，灵活但慢)。"},{"t":"ex","q":"【典型例题】某总线工作频率 100MHz，一次能并行传输 4 字节。求总线带宽。","steps":["每个时钟周期传输 4 字节","频率 100MHz = 100×10⁶ 周期/s","带宽 = 100×10⁶ × 4 = 400×10⁶ B/s = 400 MB/s","若改用 64 位(8字节)总线，带宽 = 800 MB/s，翻倍。"]},{"t":"warn","text":"<b>易错点：</b>① 地址总线宽度决定寻址范围(单元数)，不是数据量；② 带宽单位 B/s 与 b/s 注意 ÷8；③ 同步总线受最慢部件限制；④ 总线复用(地址/数据共用线)会降低并行度。"},{"t":"sh","no":"3.6","title":"总线通信方式（同步 / 异步 / 半同步 / 分离式）"},{"t":"tx","h":"通信方式解决什么问题","p":"主设备和从设备速度往往差很多，靠什么“约定”把数据可靠传过去？四种方式的差别就在于<b>时间怎么定</b>：由统一时钟定（同步）、由握手信号定（异步）、两者混合（半同步）、或干脆把请求和应答拆成两段（分离式）。"},{"t":"tb","head":["方式","定时依据","优点","缺点"],"rows":[["同步通信","统一总线时钟，固定节拍","控制简单、速度快、无握手开销","须按最慢设备设计节拍，快设备被拖慢"],["异步通信（不互锁）","只有请求，不等应答","最快","可靠性差，几乎不用"],["异步通信（半互锁）","请求后等应答，应答后不等撤销","较快","请求信号可能长期占用"],["异步通信（全互锁）","请求与应答互相等待","最可靠，适应速度差异大","握手开销最大，速度最慢"],["半同步通信","同步时钟 + wait 信号","兼顾同步的简单与异步的灵活","需额外 wait 线"],["分离式通信","请求与应答分成两个子周期","总线利用率高，一个主设备可连续发多个请求","控制复杂"]]},{"t":"dv","title":"推导：同步总线的带宽怎么算","steps":["设总线时钟频率 <b>100 MHz</b>（周期 10 ns），一个总线周期含 <b>4 个时钟</b>","一个总线周期 = 4 × 10 ns = <b>40 ns</b>","每次传输数据 <b>4 字节</b>（32 位数据线）","带宽 = 每次字节数 ÷ 周期 = 4 B ÷ 40 ns = 4 B ÷ (40×10⁻⁹ s)","= 10⁸ B/s = <b>100 MB/s</b>","若把数据线加宽到 8 字节：带宽 = 8 ÷ 40 ns = <b>200 MB/s</b>，翻倍","要点：带宽 = 数据线字节数 × 时钟频率 ÷ 每周期时钟数，三个量任一变化都要重算"]},{"t":"ex","q":"【例题】某同步总线时钟 66 MHz，每个总线周期 2 个时钟，数据线 32 位。求带宽；若要达到 200 MB/s，数据线至少多少位？","steps":["时钟周期 = 1/66 MHz ≈ 15.15 ns，总线周期 = 2 × 15.15 ≈ 30.3 ns","每次传 32 位 = 4 B","带宽 = 4 B ÷ 30.3 ns ≈ 132 MB/s","要 200 MB/s：每次字节数 = 200 MB/s × 30.3 ns ≈ 6.06 B → 取 <b>8 B = 64 位</b>","此时实际带宽 = 8 ÷ 30.3 ns ≈ 264 MB/s，已满足"]},{"t":"warn","text":"<b>易错点：</b>① 异步通信三种握手（不互锁/半互锁/全互锁）中，<b>全互锁最可靠但最慢</b>；② 半同步不是“异步的一半”，而是同步时钟加 wait 信号；③ 分离式通信把一个总线周期拆成“请求”和“应答”两个子周期，同一主设备不必等应答返回就能发下一个请求。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第3章习题）"},{"t":"pt","no":"题型1","name":"总线分类与结构","feature":"按功能/位置判断总线类型，或描述总线组成。","method":"按功能：数据总线、地址总线、控制总线；按位置：片内、系统、通信总线。","steps":["三类功能总线各司其职","数据总线双向、条数=字长","地址总线单向、位数=寻址空间","控制总线单向为主、传控制/状态"],"ex":{"q":"地址总线的位数决定了（　）。","steps":["地址总线传送地址","位数 n → 可寻址 2ⁿ 个单元","故决定最大寻址空间","答案：最大寻址空间。"]},"pit":"数据总线影响字长/带宽，地址总线决定寻址范围，别混。"},{"t":"pt","no":"题型2","name":"总线带宽与传输率计算","feature":"给总线宽度、工作频率、每周期传送次数，求带宽。","method":"带宽 = 位宽/8 × 频率 × 每周期传送次数。","steps":["统一位宽到字节（÷8）","带宽 = 字节宽 × 工作频率","若每周期传多次再乘倍数",
"结果单位 MB/s"],"ex":{"q":"总线宽 32 位，时钟 66MHz，每周期传送 1 次，求带宽。","steps":["32 位 = 4 B","带宽 = 4 B × 66 MHz","= 264 MB/s","即该总线最大数据传输率。"]},"pit":"位→字节要除以 8；频率单位 MHz 对应 MB/s。"},{"t":"pt","no":"题型3","name":"总线仲裁与通信控制","feature":"判断集中式/分布式仲裁方式，或同步/异步通信特点。","method":"仲裁：链式查询、计数器定时查询、独立请求；通信：同步、异步。","steps":["区分集中式与分布式仲裁","链式简单但优先级固定、故障敏感","同步通信靠统一时钟，异步靠应答","异步分不互锁/半互锁/全互锁"],"ex":{"q":"异步通信中，主设备发出请求后一直等到从设备应答才撤销信号，属于哪种方式？","steps":["主方请求、从方应答","主方要等到应答才撤请求","属全互锁方式","它最可靠但速度最慢。"]},"pit":"同步/异步、互锁方式名称别记混；链式查询对故障最敏感。"},{"t":"pt","no":"题型4","name":"总线标准与性能比较","feature":"涉及 PCI、PCI-E、USB、ISA 等标准特点。","method":"比较带宽、串并、热插拔、用途。","steps":["记常见标准的串/并行与带宽量级","PCI-E 串行高带宽、点对点","USB 支持热插拔、级联","ISA 为早期低速并行"],"ex":{"q":"下列总线中支持热插拔的是（　）。","steps":["USB 设计支持热插拔","PCI-E 部分支持热插拔","ISA 为老式不支持","答案按标准最新教材判定。"]},"pit":"不同教材标准略有差异，答题按教材口径。"},{"t":"tip","text":"<b>第3章解题总流程：</b>①三总线各司其职，先判断问的是哪类；②带宽＝字节宽×频率；③仲裁/通信方式记特点对比；④标准题按教材结论。"},{"t":"kw","items":["数据/地址/控制总线","总线带宽","寻址空间2ⁿ","总线仲裁","同步vs异步"]}]},"g4":{"no":"4","title":"存储器","tag":"第2篇 · 第4章","sub":"课本第4章。存储器层次结构是性价比最高的考点，讲速度/容量/价格三者的平衡。","blocks":[{"t":"sh","no":"4.1","title":"概述"},{"t":"tx","h":"分类与层次结构","p":"存储器按介质分半导体/磁/光；按存取方式分随机存取(RAM)、顺序存取、直接存取、相联存取。速度由快到慢、容量由小到大、价格由贵到便宜：<b>寄存器 → Cache → 主存 → 辅存</b>。核心依据是<b>局部性原理</b>(时间局部性 + 空间局部性)。"},{"t":"sh","no":"4.2","title":"主存储器"},{"t":"tx","h":"主存与容量计算","p":"主存按地址随机存取，由存储体、地址寄存器 MAR、数据寄存器 MDR 组成。容量 = 存储单元数 × 每单元位数。半导体存储器分 <b>SRAM</b>(静态，快、贵、用于Cache) 与 <b>DRAM</b>(动态，需刷新、慢、便宜、用于主存)。"},{"t":"fx","lines":["主存容量 = 存储单元数 × 每单元位数","例：16K×8 位 = 16384 单元、每单元 8 位","存取时间 vs 存取周期（周期 = 存取 + 恢复）"]},{"t":"dv","title":"推导：位扩展、字扩展与总片数怎么算","steps":["<b>位扩展</b>：单片字数够、位数不够 → 多片<b>并联</b>，地址线共用、数据线拼接、同时读写。片数 = 总位数 ÷ 单片位数","<b>字扩展</b>：位数够、字数不够 → 多片<b>串联</b>，数据线共用、靠片选信号分时选中。片数 = 总字数 ÷ 单片字数","<b>字位同时扩展</b>：先位扩展成“一组”，再字扩展成“多组”。总片数 = 总容量(位) ÷ 单片容量(位)","地址线分两段：<b>片内地址</b> = log₂(单片字数)；<b>片选地址</b> = log₂(组数)，两段相加才是总地址位数","片选译码器：输入端接高位地址，输出端分别接各芯片的 CS（片选，通常低电平有效 CS̄）","易错对照：位扩展<b>只增数据线</b>不加地址线；字扩展<b>只增片选线</b>不加数据线"]},{"t":"ex","q":"【例题】用 1K×4 位的 SRAM 芯片构成 4K×8 位的存储器。求：(1) 需要多少片？(2) 如何组织？(3) 地址线与数据线各几位？(4) 片选需要几位？","steps":[{"s":"总容量 = 4K×8 = 32K 位；单片容量 = 1K×4 = 4K 位 → 片数 = 32K ÷ 4K = <b>8 片</b>","note":"容量先化成“位”再相除，别直接拿字数比"},{"s":"组织：每 <b>2 片位扩展</b>成 1K×8（一组），再 <b>4 组字扩展</b>成 4K×8 —— 即 4 组 × 2 片 = 8 片","note":"口诀：先并（位扩展）再串（字扩展）"},{"s":"片内地址：1K = 2¹⁰ → <b>10 位</b>（A₉~A₀），组内两片共用同一地址"},{"s":"片选地址：4 组 = 2² → <b>2 位</b>（A₁₁、A₁₀），经 2-4 译码器产生 4 个片选信号"},
{"s":"总地址线 = 10 + 2 = <b>12 位</b>，而 4K = 2¹² ✓ 与容量自洽","note":"这一步检验最关键，能立刻发现算错"},{"s":"数据线 = <b>8 位</b>：每组内 2 片各出 4 位，拼成 8 位"}]},{"t":"sh","no":"4.3","title":"高速缓冲存储器 (Cache)"},{"t":"tx","h":"Cache 原理与三种映射","p":"Cache 利用局部性，把主存中活跃的块调入快速小容量的 Cache。映射方式：<b>直接映射</b>(块只能放固定行，简单冲突多)、<b>全相联</b>(任意块任意行，灵活但比较器贵)、<b>组相联</b>(组间直接、组内全相联，折中)。替换算法常用 <b>LRU</b>。"},{"t":"tb","head":["映射方式","灵活性","冲突","代价"],"rows":[["直接映射","低","多","最低"],["全相联","最高","无","最高"],["组相联","中","较少","中"]]},{"t":"fx","lines":["命中率 H = 命中次数 / 总访问次数","平均访问时间 Ta = H·Tc + (1−H)·Tm","写策略：写直达(Write-through) / 写回(Write-back)"]},{"t":"fig","kind":"fig-cache","cap":"存储层次：CPU 先访 Cache，命中直接取用；未命中再访主存并把块调入"},{"t":"ex","q":"【典型例题】Cache 存取时间 10ns，主存 100ns，命中率 95%。求平均访问时间。","steps":["Ta = H·Tc + (1−H)·Tm","= 0.95×10 + 0.05×100","= 9.5 + 5 = 14.5 ns","若无 Cache 需 100ns，可见命中率对性能改善是杠杆放大。"]},{"t":"dv","title":"推导：主存地址怎么切成「标记 / 行号 / 块内地址」","steps":["切分顺序固定，<b>从右往左</b>：块内地址 → 行号（或组号）→ 剩下的全部是标记 tag","块内地址位数 = log₂(块大小)；块大小按字节给时，如 32 B → 5 位","行数 = Cache <b>数据区</b>容量 ÷ 块大小；行号位数 = log₂(行数)","标记位数 = 主存地址位数 − 行号位数 − 块内地址位数（三项相加必须还原主存地址位数）","组相联：组数 = 行数 ÷ 每组行数(n 路)，用<b>组号</b>替换行号，组号位数 = log₂(组数)","三种映射的实质差别：直接映射 = 每组 1 行（只需 1 个比较器）；全相联 = 只有 1 组（全部是 tag，需逐行比较）；组相联 = 折中，组内 n 行并行比较","易错：题目说“Cache 容量”要先判断指数据区还是含 tag/有效位的总容量；只有数据区才能直接除以块大小"]},{"t":"ex","q":"【例题】某机主存 1 MB，按字节编址；Cache 数据区 32 KB，块大小 32 B。(1) 直接映射时标记、行号、块内地址各几位？(2) 改为 4 路组相联各几位？(3) 直接映射下主存块号 1000 应放入哪一行？","steps":["主存 1 MB = 2²⁰ B → 主存地址 <b>20 位</b>","块内地址 = log₂32 = <b>5 位</b>","行数 = 32 KB ÷ 32 B = 1024 行 → 行号 = log₂1024 = <b>10 位</b>","直接映射标记 = 20 − 10 − 5 = <b>5 位</b> → 格式 [tag 5][行号 10][块内 5]","4 路组相联：组数 = 1024 ÷ 4 = 256 → 组号 = <b>8 位</b>；标记 = 20 − 8 − 5 = <b>7 位</b> → [tag 7][组号 8][块内 5]",{"s":"第 (3) 问：直接映射 行号 = 块号 mod 行数 = 1000 mod 1024 = <b>1000</b> → 放入第 1000 行","note":"组相联则用 块号 mod 组数"},"双向检验：5 + 10 + 5 = 20 ✓；7 + 8 + 5 = 20 ✓"]},{"t":"tx","h":"多级 Cache 与现代存储层次","p":"CPU 与主存速度差越来越大，单级 Cache 已不够，于是形成 <b>L1 → L2 → L3</b> 三级结构：L1 最快最小（几 KB~几十 KB，1~4 周期），通常在片内并按哈佛结构分为<b>指令 Cache 与数据 Cache</b>；L2 较大较慢（几百 KB~几 MB）；L3 多核共享（几 MB~几十 MB）。越靠近 CPU 越快越贵越小，命中率逐级兜底。"},{"t":"sh","no":"4.4","title":"辅助存储器"},{"t":"tx","h":"磁盘与存储容量","p":"辅存容量大、非易失、可长期保存。磁盘容量 = 磁头数 × 柱面数 × 每道扇区数 × 每扇区字节数。存取时间 = 寻道时间 + 旋转等待时间 + 传输时间。"},{"t":"ex","q":"【典型例题】磁盘有 4 个磁头、1000 柱面、每道 64 扇区、每扇区 512B，求总容量。","steps":["容量 = 磁头数 × 柱面数 × 扇区数/道 × 字节数/扇区","= 4 × 1000 × 64 × 512","= 131,072,000 B ≈ 128 MB","要点：柱面数对应磁道数，公式需记牢。"]},
{"t":"dv","title":"推导：磁盘平均存取时间的三段构成","steps":["<b>平均存取时间 = 平均寻道时间 + 平均旋转延迟 + 传输时间</b>，三段缺一不可","平均寻道时间：磁头臂移到目标磁道，题目通常直接给（如 8 ms）","一圈时间 = 60 ÷ r 秒（r 单位 r/min，<b>必须除 60</b> 换成秒）","平均旋转延迟 = <b>半圈</b>时间 = 一圈时间 ÷ 2 —— 因为目标扇区平均要等半圈才转到磁头下","传输时间 = 要读的字节数 ÷ 传输率；若按扇区计，≈ 一圈时间 × (读扇区数 ÷ 每道扇区数)","易错：① 旋转延迟是半圈不是一圈；② r/min 忘除 60 会大 60 倍；③ 连续读多个扇区时寻道与旋转只发生一次，能摊薄"]},{"t":"ex","q":"【例题】某磁盘转速 7200 r/min，平均寻道时间 8 ms，每道 512 个扇区，每扇区 512 B。求读取 1 个扇区的平均存取时间；若连续读 8 个扇区又如何？","steps":["一圈时间 = 60 ÷ 7200 s = <b>8.33 ms</b>","平均旋转延迟 = 8.33 ÷ 2 ≈ <b>4.17 ms</b>","传输 1 个扇区 = 8.33 ms ÷ 512 ≈ <b>0.016 ms</b>","读 1 个扇区：T = 8 + 4.17 + 0.016 ≈ <b>12.19 ms</b>","连续读 8 个扇区：传输时间 = 8.33 × 8 ÷ 512 ≈ 0.13 ms，寻道与旋转只付一次 → T ≈ <b>12.3 ms</b>",{"s":"平均到每个扇区：12.3 ÷ 8 ≈ <b>1.54 ms</b>，比随机的 12.19 ms 快约 8 倍","note":"这就是“磁盘顺序读远快于随机读”的定量原因"}]},{"t":"warn","text":"<b>易错点：</b>① 存取时间与存取周期不同(后者含恢复)；② 命中率提升对平均时间的改善被放大；③ 直接映射“块号 mod 行数”是高频考点；④ 主存随机存取，磁盘是直接存取(需寻道)。"},{"t":"sh","no":"4.5","title":"非易失性与高性能存储器"},{"t":"tx","h":"NVRAM：断电不丢的存储器","p":"<b>NVRAM（非易失性存储器）</b>断电后数据仍保留，用于存放固件、配置和移动存储。主要有 Flash（闪存）两大类：<b>NOR Flash</b> 可字节随机读、支持片内执行（XIP），常存启动代码；<b>NAND Flash</b> 按页读写、容量大成本低，用于 U 盘、SSD、存储卡。"},{"t":"tb","head":["类型","写入方式","特点","典型用途"],"rows":[["ROM（掩膜）","出厂固化","不可改，成本最低","大批量固化程序"],["PROM","用户一次写入","一次性","小批量定制"],["EPROM","紫外线擦除后重写","可多次擦写，须拆下","早期开发调试"],["EEPROM","电擦除，按字节写","可在线改写，速度慢","存配置参数"],["NOR Flash","电擦除，按块擦、可按字节读","支持 XIP，读快写慢","BIOS、嵌入式代码"],["NAND Flash","电擦除，按页读写","容量大、成本低、有坏块","U 盘、SSD、存储卡"]]},{"t":"dv","title":"推导：DDR 为什么比 SDR 快一倍","steps":["SDR SDRAM 只在时钟<b>上升沿</b>采样一次数据，一个时钟传 1 次","DDR 在时钟<b>上升沿和下降沿都</b>采样，一个时钟传 2 次 → 同样频率下带宽翻倍","例：时钟 200 MHz、数据线 64 位（8 B）的 DDR","SDR 带宽 = 200 MHz × 8 B = <b>1.6 GB/s</b>","DDR 带宽 = 200 MHz × 2 × 8 B = <b>3.2 GB/s</b>","DDR2/3/4 再靠预取位数（4/8/16 bit）倍增，所以标称频率是“等效频率”而非时钟频率","配合<b>突发传输（Burst）</b>：只送一次首地址，随后连续传多个数据字（突发长度常为 4/8），省掉重复送地址的开销，这是高性能存储器提升带宽的关键手段"]},{"t":"sh","no":"4.6","title":"并行存储器：双端口与多体交叉"},{"t":"tx","h":"双端口存储器","p":"同一存储器有<b>两套独立的地址线、数据线和读写控制</b>，两个端口可同时访问。若两端口访问<b>不同单元</b>，完全并行；若访问<b>同一单元</b>，则由仲裁逻辑决定谁先访问，另一端口延后一个周期。常用于共享内存的双机系统、显示缓冲。"},{"t":"tx","h":"多体交叉存储器：低位交叉才是“并行加速”","p":"把主存分成 m 个容量相同的模块。<b>高位交叉</b>（顺序方式）用地址高位选模块，连续地址落在同一模块，只能顺序访问，<b>不提速</b>；<b>低位交叉</b>（交叉方式）用地址低位选模块，连续地址分布到不同模块，可流水式并行访问。"},{"t":"dv","title":"推导：低位交叉连续读 m 个字要多久","steps":["设每个模块存取周期 <b>T</b>，总线传送时间 τ，模块数 m","顺序（高位交叉）：每个字都要等完整 T → m 个字共 <b>mT</b>","低位交叉：第 1 个字用 T 取出，此后每隔 τ 就有一个模块完成 → 总时间 = <b>T + (m−1)τ</b>",
"例：T = 200 ns，τ = 50 ns，m = 4","顺序方式：4 × 200 = <b>800 ns</b>","交叉方式：200 + 3 × 50 = <b>350 ns</b>，加速比约 <b>2.29 倍</b>","m 越大加速比越高，上限接近 T/τ；要求 τ 足够小、模块数 m ≥ T/τ 才能完全重叠"]},{"t":"ex","q":"【例题】某机主存分 8 个模块，存取周期 160 ns，总线传送周期 20 ns。求低位交叉连续读 8 个字的时间与加速比。","steps":["低位交叉时间 = T + (m−1)τ = 160 + 7 × 20 = <b>300 ns</b>","顺序方式时间 = mT = 8 × 160 = <b>1280 ns</b>","加速比 = 1280 ÷ 300 ≈ <b>4.27 倍</b>","理论上限 = T/τ = 160/20 = 8，实际 8 个模块刚好 m = T/τ，已接近满重叠","若 m 只有 4：时间 = 160 + 3×20 = 220 ns，但需两轮，共 440 ns，加速比降到 2.9 倍"]},{"t":"dv","title":"推导：三种 DRAM 刷新方式的死区与开销","steps":["前提：DRAM 靠电容存电荷会漏电，必须周期性刷新，<b>刷新周期</b>一般为 2 ms（题目会给）","刷新按<b>行</b>进行，一次刷一行，占用一个<b>存取周期</b>（只刷新不读写，不需要数据）","<b>集中刷新</b>：在 2 ms 末尾集中刷完全部行 → 期间不能读写，形成“死区”。死区 = 行数 × 存取周期","<b>分散刷新</b>：每个存取周期后都刷一行 → 系统存取周期变成 2 倍（读写 + 刷新），无死区但整机变慢一半","<b>异步刷新</b>：把 2 ms 平均分给每行 → 刷新间隔 = 刷新周期 ÷ 行数，死区被摊到最小，是最常用方案","三者刷新总开销相同：开销率 = (行数 × 存取周期) ÷ 刷新周期，区别只在“是否集中占用时间”"]},{"t":"ex","q":"【例题】某 DRAM 芯片内部为 128×128 矩阵，存取周期 0.5 μs，刷新周期 2 ms。求：(1) 集中刷新死区；(2) 异步刷新间隔；(3) 刷新时间占刷新周期的比例。","steps":["128×128 矩阵 → 共 <b>128 行</b>，一次刷一行","集中刷新死区 = 128 × 0.5 μs = <b>64 μs</b>",{"s":"异步刷新间隔 = 2 ms ÷ 128 = 2000 μs ÷ 128 ≈ <b>15.6 μs</b>","note":"即每隔 15.6 μs 刷一行，2 ms 内刷完一遍"},"刷新总时间 = 128 × 0.5 μs = 64 μs（三种方式一样）","占比 = 64 μs ÷ 2000 μs = <b>3.2%</b>",{"s":"结论：总开销都是 3.2%，差别全在“集中还是打散”——集中刷新有 64 μs 长死区，异步刷新把它分散成 128 个短缺口，对 CPU 更友好","note":"为什么实际用异步刷新"}]},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第4章习题）"},{"t":"pt","no":"题型1","name":"存储容量、地址与芯片扩展","feature":"用若干芯片构成指定容量存储器，求需芯片数或地址分配。","method":"所需芯片数 = 目标容量 / 单片容量；字扩展增加单元数、位扩展增加字长。","steps":["算出目标总容量与单片容量","芯片数 = 总容量 ÷ 单片容量","判断是位扩展（加字长）还是字扩展（加单元数）","字扩展需片选译码，位扩展共享片选"],"ex":{"q":"用 1K×4 位芯片构成 1K×8 位存储器，需几片？","steps":["单片 1K×4 位，目标 1K×8 位","单元数相同、字长加倍 → 位扩展","片数 = 8/4 = 2 片","两片共用地址和片选，数据线并联。"]},"pit":"位扩展共享片选，字扩展靠译码选片，别搞反。"},{"t":"pt","no":"题型2","name":"地址译码与片选逻辑","feature":"给定地址范围，设计译码逻辑或判断某地址选中哪片。","method":"高位地址经译码器产生片选，低位地址选片内单元。","steps":["确定片内地址位数（由芯片容量定）","剩余高位作片选译码输入","画出 2-4/3-8 译码器连接","代入地址验证选中关系"],"ex":{"q":"2K×8 存储空间，用 4 片 512×8 芯片，片内地址需几位？","steps":["512 = 2⁹ → 片内地址 9 位","2K = 2¹¹ → 总地址 11 位","片选地址 = 11 − 9 = 2 位","2 位可选 4 片，正好。"]},"pit":"片内地址位数由单个芯片容量定，不是总容量。"},{"t":"pt","no":"题型3","name":"刷新与 DRAM 特性","feature":"涉及 DRAM 刷新方式、周期或刷新开销。","method":"DRAM 需定时刷新（一般 2ms）；集中/分散/异步刷新。","steps":["判断是 DRAM（需刷新）还是 SRAM（不需）","刷新以行为单位","集中：集中时间全刷；分散：每周期刷一行；异步：分批","刷新周期通常 2ms，与存取周期无关"],"ex":{"q":"某 DRAM 有 128 行，刷新周期 2ms，采用分散刷新每存取周期刷一行，若存取周期 0.5μs，刷新时间占多少？",
"steps":["分散刷新每行一次 = 128 次","总刷新增 128×0.5=64μs 附加时间","占比 = 64μs/2ms = 3.2%","即刷新开销。"]},"pit":"刷新只针对 DRAM；刷新周期(2ms)不同于存取周期。"},{"t":"pt","no":"题型4","name":"Cache 命中率与平均访问时间","feature":"给命中率、Cache 与主存访问时间，求平均访问时间或加速比。","method":"t_avg = h·t_c + (1−h)·t_m；加速比 = t_m / t_avg。","steps":["读命中率 h","平均时间 = h×t_cache + (1−h)×t_主存","（若先访 Cache 失败再访主存，加 t_c）","加速比 = 原时间/新时间"],"ex":{"q":"命中率 95%，Cache 访问 1ns，主存 100ns（缺失时才访主存），求平均时间。","steps":["t = h·t_c + (1−h)·(t_c+t_m)","= 0.95×1 + 0.05×(1+100)","= 0.95 + 5.05 = 6 ns","命中率高能显著提速。"]},"pit":"缺失时是否要加上 Cache 访问时间，取决于题干设计，注意区分。"},{"t":"pt","no":"题型5","name":"Cache 地址映射（直接/全相联/组相联）","feature":"给主存地址，求 Cache 行号或标记，或划分地址格式。","method":"主存地址 = 标记 + 组号/行号 + 块内地址。","steps":["块内地址位数 = log₂(块大小)","直接映射：行号位数 = log₂(Cache行数)，其余为标记","组相联：组号 = log₂(组数)，标记含路对应位","按格式拆分给定地址"],"ex":{"q":"Cache 128 行，块大小 16 字，直接映射，主存地址(字地址)如何划分？","steps":["块内地址 = log₂16 = 4 位","行号 = log₂128 = 7 位","标记 = 总位数 − 4 − 7","直接映射地址 = 标记 | 行号 | 块内。"]},"pit":"块内地址位数按“块大小”算；行号/组号位数按“行数/组数”算。"},{"t":"pt","no":"题型6","name":"存储器读写周期与速度计算","feature":"涉及存取周期、存取时间、带宽。","method":"带宽 = 每次传送字节数 / 存取周期。","steps":["读存取时间与存取周期（周期含恢复时间）","带宽 = 数据宽度 / 周期","注意字/字节换算","多体交叉能提高带宽"],"ex":{"q":"存取周期 100ns，每次读 8 字节，求主存带宽。","steps":["带宽 = 8 B / 100ns","= 8 / (100×10⁻⁹)","= 8×10⁷ B/s = 80 MB/s","即每秒可传约 80MB。"]},"pit":"存取周期>存取时间（含恢复）；带宽与位宽、周期都有关。"},{"t":"pt","no":"题型7","name":"多模块交叉存储器","feature":"判断连续/交叉方式下带宽提升。","method":"m 体交叉，连续地址分布在相邻体，可 m 倍带宽。","steps":["确定模块数 m","交叉方式下模块轮流工作","理想带宽提升 m 倍","需满足存取周期>总线传送周期"],"ex":{"q":"4 体交叉存储器，单模块存取周期 400ns，总线传送周期 100ns，求带宽提升。","steps":["m=4，交叉轮流存取","理想情况下连续读取","每 100ns 出一个字","带宽约为单体的 4 倍。"]},"pit":"交叉提升带宽的前提是周期≥传送周期，别乱推。"},{"t":"tip","text":"<b>第4章解题总流程：</b>①扩展题先分位扩展/字扩展算片数；②译码题先定片内地址位数；③DRAM 想刷新、SRAM 不想；④Cache 题分清命中率、映射格式；⑤带宽=数据宽/存取周期。"},{"t":"kw","items":["局部性原理","层次结构","SRAM/DRAM","Cache映射","LRU","磁盘容量"]}]},"g5":{"no":"5","title":"输入输出系统","tag":"第2篇 · 第5章","sub":"课本第5章。CPU 与外设如何交换数据：从程序查询、中断到 DMA，是理解整机效率的关键。","blocks":[{"t":"sh","no":"5.1","title":"概述"},{"t":"tx","h":"I/O 系统的组成","p":"I/O 系统由 I/O 设备、I/O 接口、I/O 管理软件组成。信息交换方式按 CPU 参与程度递增：<b>程序查询 → 程序中断 → DMA → 通道</b>。"},{"t":"sh","no":"5.2","title":"I/O 设备"},{"t":"tx","h":"常见外设","p":"输入设备(键盘、鼠标、扫描仪)、输出设备(显示器、打印机)、外存(磁盘、光盘)。I/O 设备速度远低于 CPU，是与主机速度不匹配的根源。"},{"t":"sh","no":"5.3","title":"I/O 接口"},{"t":"tx","h":"接口的功能与组成","p":"I/O 接口是设备与总线之间的“转换器”，功能：地址译码、数据缓冲、传送控制命令、反映设备状态。端口按存放信息分数据端口、状态端口、控制端口；编址方式有统一编址与独立编址。"},
{"t":"sh","no":"5.4","title":"程序查询方式"},{"t":"tx","h":"程序查询(轮询)","p":"CPU 不断读设备状态，就绪才传送数据。<b>缺点</b>：CPU 大量时间空转等待，效率低；优点是简单。"},{"t":"sh","no":"5.5","title":"程序中断方式"},{"t":"tx","h":"中断原理","p":"设备就绪时主动向 CPU 发中断请求，CPU 暂停当前程序转去服务，结束后返回断点。<b>中断处理过程</b>：中断请求 → 判优 → 响应 → 保护现场 → 执行中断服务 → 恢复现场 → 返回。可大幅提高 CPU 利用率。"},{"t":"sh","no":"5.6","title":"DMA 方式"},{"t":"tx","h":"DMA(直接存储器存取)","p":"DMA 由专门的 DMA 控制器直接在设备与主存间传送数据块，<b>不经过 CPU</b>，只在传送开始/结束时占用总线。适用于高速大批量数据(如磁盘)。总线占用方式有停止 CPU 访存、周期挪用、DMA 与 CPU 交替访存。"},{"t":"tb","head":["方式","CPU参与","适用场景"],"rows":[["程序查询","全程轮询","低速、简单设备"],["程序中断","传送时打断CPU","中低速、随机事件"],["DMA","仅首尾参与","高速、大批量数据块"]]},{"t":"ex","q":"【典型例题】比较程序中断方式与 DMA 方式传送数据时的 CPU 参与程度。","steps":["中断方式：每个数据字节都要打断 CPU 执行中断服务，CPU 参与度高","DMA 方式：数据块传送由 DMA 控制器完成，CPU 可继续执行程序","只在数据块传送的<b>开始(初始化)和结束(处理)</b>时 CPU 才介入","结论：传送大批量数据时 DMA 效率远高于中断，CPU 开销小。"]},{"t":"ex","q":"【例题】某机用 DMA 方式从磁盘向主存传送 4 KB 数据块，DMA 每传送 1 字节占用 1 个存取周期（0.5 μs）。若改用中断方式，CPU 每传 1 字节需 20 μs 中断服务开销。分别估算两种方式的时间开销。","steps":["数据量 = 4 KB = <b>4096 B</b>（注意 1 KB = 1024 B，不是 1000）","中断方式：每字节触发一次中断 → 4096 × 20 μs = 81920 μs ≈ <b>81.9 ms</b>，CPU 几乎被完全占满",{"s":"DMA 方式：传送本身由硬件完成，CPU 只在<b>预处理</b>（送控制字/地址/计数器）与<b>后处理</b>（中断收尾）时介入，量级仅几十个周期","note":"这是 DMA 的本质优势"},"DMA 期间总线被“周期挪用”的总时长 = 4096 × 0.5 μs = <b>2.05 ms</b>，但这是<b>总线占用</b>，不是 CPU 执行开销",{"s":"对比：81.9 ms → 约 2 ms 量级，效率提升数十倍，这就是大批量数据必须用 DMA 的定量理由","note":"考试常问“为什么 DMA 适合高速块设备”"},"注意：周期挪用会让 CPU 访存变慢（CPU 与 DMA 争用存储器周期），所以 DMA 并非零代价，只是代价被硬件分担"]},{"t":"warn","text":"<b>易错点：</b>① 中断是“程序切换”，DMA 是“硬件直接搬数据”；② DMA 与 CPU 争用访存周期(周期挪用)；③ 中断处理要保护/恢复现场；④ 中断优先级含响应优先级与处理优先级。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第5章习题）"},{"t":"pt","no":"题型1","name":"I/O 接口功能与组成","feature":"判断接口功能或组成部件作用。","method":"接口功能：数据缓冲、地址译码、命令译码、状态登记、格式转换、中断。","steps":["列出接口基本功能","对应端口（数据/状态/控制）","数据端口双向、状态命令端口单向","接口屏蔽主机与外设差异"],"ex":{"q":"I/O 接口中用于存放设备状态信息的端口是（　）。","steps":["接口有三类端口","数据端口：传数据","状态端口：存状态","答案：状态端口。"]},"pit":"控制端口与状态端口方向相反，别混。"},{"t":"pt","no":"题型2","name":"程序查询方式与程序中断方式","feature":"比较两种 I/O 方式的优缺点或计算查询开销。","method":"查询：CPU 反复读状态、浪费等待；中断：外设就绪主动请求。","steps":["查询方式 CPU 与外设串行、效率低","中断方式 CPU 与外设并行","中断需保存/恢复现场","中断服务程序处理数据传送"],"ex":{"q":"CPU 与外设并行工作、外设就绪时主动通知 CPU 的方式是（　）。","steps":["查询需 CPU 主动轮询","中断由外设发请求","故为程序中断方式","它效率高于查询。"]},"pit":"中断是“外设主动”，查询是“CPU 主动”，方向别记反。"},{"t":"pt","no":"题型3","name":"中断处理过程与优先级","feature":"描述中断响应/服务流程，或判断中断优先级与嵌套。","method":"响应条件：有请求且开中断；流程：请求→判优→响应→保护现场→服务→恢复→返回。",
"steps":["中断请求 → 判优选最高优先级","响应：关中断、保断点","转服务程序、保护现场","服务完恢复现场、开中断、返回"],"ex":{"q":"中断服务程序执行完毕后，返回主程序前需执行（　）。","steps":["服务结束时恢复现场","开中断","用中断返回指令弹出断点","故需恢复现场并返回。"]},"pit":"响应的前提是“开中断”；现场保护在服务前后成对。"},{"t":"pt","no":"题型4","name":"DMA 方式原理与传送过程","feature":"比较 DMA 与中断，或计算 DMA 传送数据量/时间。","method":"DMA 由硬件控制器直接在主存与外设间传数据，周期挪用/停止 CPU/交替。","steps":["DMA 请求由外设发","DMA 控制器接管总线传数据","传送完发中断通知 CPU","分停止 CPU、周期挪用、交替访问三种"],"ex":{"q":"DMA 方式中，数据传送的双方是（　）。","steps":["DMA 控制器控制","在主存与 I/O 设备间直接传","不经过 CPU 逐字搬运","故为主存与外设。"]},"pit":"DMA 传送期间 CPU 让出总线；传送结束才中断 CPU。"},{"t":"pt","no":"题型5","name":"DMA 与中断的对比","feature":"综合判断两者适用场景与差别。","method":"DMA 适合高速大批量；中断适合随机小批量。","steps":["数据量：大批量→DMA","速度：高速设备→DMA","控制复杂度：中断需 CPU 参与","优先级：DMA 请求通常高于中断"],"ex":{"q":"对于高速大批量数据传送，宜采用（　）。","steps":["高速 → 排除查询","大批量 → CPU 逐字处理低效","DMA 直接传送最合适","答案：DMA 方式。"]},"pit":"DMA 并非完全无 CPU，只是搬运不占 CPU。"},{"t":"tip","text":"<b>第5章解题总流程：</b>①接口题认三类端口；②方式对比记“并行/效率/适用批量”；③中断题按流程与优先级；④DMA 题抓“直接、批量、周期挪用”。"},{"t":"kw","items":["I/O接口","程序查询","中断方式","DMA","周期挪用"]}]},"g6":{"no":"6","title":"计算机的运算方法","tag":"第3篇 · 第6章","sub":"课本第6章。计算机只会算 0/1，负数、小数都要用特定编码表示。补码加减、一位乘法、一位除法、浮点运算是本章四大计算题，都必须会「手算一步步推」。","blocks":[{"t":"tx","h":"本章知识地图","p":"全章围绕一条主线：<b>怎么用 0/1 表示数 → 怎么用 0/1 做运算</b>。第一节解决“表示”（原码/反码/补码/移码）；第二节解决“小数点放哪”（定点/浮点）；第三节是重头戏——<b>定点加减乘除的手算方法</b>；第四节推广到浮点四则运算；第五节是运算的硬件（ALU 与进位）。"},{"t":"sh","no":"6.1","title":"无符号数和有符号数"},{"t":"tx","h":"真值、机器数与四种编码","p":"<b>真值</b>是带符号的实际值（如 −0.1011），<b>机器数</b>是它在计算机里的 0/1 编码，最高位通常作<b>符号位</b>（0 正 1 负）。同一真值有四种编码：<b>原码</b>（符号位 + 绝对值）、<b>反码</b>（负数除符号位外按位取反）、<b>补码</b>（负数取反加一，减法变加法、0 唯一）、<b>移码</b>（补码符号位取反，用于浮点阶码，便于比大小）。"},{"t":"fx","lines":["补码( n 位)：X≥0 时 [X]补 = X","X<0 时 [X]补 = 2ⁿ + X = 2ⁿ − |X|","由补码求真值：符号位为 1 时 X = [X]补 − 2ⁿ","8 位补码范围  −128 ~ +127","移码 = 补码符号位取反（或 真值 + 2ⁿ⁻¹）"]},{"t":"dv","title":"负数补码 = 取反加一 是怎么来的","steps":["从补码定义出发：[X]补 = 2ⁿ + X（X<0）","把 2ⁿ 写成 (2ⁿ − 1) + 1，即“全 1 加 1”","对 X 的绝对值 |X|：|X| 与 (2ⁿ−1) 的差 = |X| 取反（全 1 减 |X| = 按位取反）","所以 [X]补 = (2ⁿ − 1) − |X| + 1 = |X| 取反 + 1","⟹ <b>负数补码 = 原码(符号位外)按位取反后加 1</b>；这一步是“变减法为加法”的核心"]},{"t":"tb","head":["真值","原码","反码","补码","移码"],"rows":[["+0.1011","0.1011","0.1011","0.1011","1.1011"],["−0.1011","1.1011","1.0100","1.0101","0.0101"],["+1011","0,1011","0,1011","0,1011","1,1011"],["−1011","1,1011","1,0100","1,0101","0,0101"]]},{"t":"tip","text":"<b>口诀：</b>正数的原码 = 反码 = 补码；负数“反码 = 原码符号位外取反，补码 = 反码 +1”。移码只用在阶码，它能保持“机器数越大真值越大”。"},{"t":"sh","no":"6.2",
"title":"数的定点表示和浮点表示"},{"t":"tx","h":"定点数与浮点数","p":"<b>定点数</b>小数点位置固定（定点小数：符号位后就是小数；定点整数：符号位后是整数）。<b>浮点数</b>形如 (−1)^S × 1.M × 2^(E−偏置)，能表示很大/很小的数。IEEE 754 单精度 32 位：<b>1 位符号 S + 8 位阶码 E + 23 位尾数 M</b>（偏置 127）；双精度 1+11+52（偏置 1023）。阶码用移码，尾数最高位隐含 1。"},{"t":"tb","head":["类型","符号位","阶码位","尾数位","偏置"],"rows":[["单精度 float","1","8","23","127"],["双精度 double","1","11","52","1023"]]},{"t":"dv","title":"IEEE 754 单精度是怎么拼出一个数的","steps":["32 位从高到低切成三块：S(1 位) | E(8 位) | M(23 位)","阶码用移码，真阶 = E − 127（E 是无符号读出的 0~255）","尾数隐含最高位的 1，即实际尾数 = 1.M","拼合：真值 = (−1)^S × 1.M × 2^(E−127)","例：S=0,E=127,M=0 → 2⁰×1.0 = 1.0；E=128 则表示 2¹"]},{"t":"fig","kind":"fig-ieee","cap":"IEEE 754 单精度 32 位字段划分：符号位 / 阶码(移码) / 尾数(隐含最高位 1)"},{"t":"warn","text":"<b>易错：</b>① 阶码是移码不是补码；② 尾数只存小数部分，还原要补上“1.”；③ 上溢（阶码太大）会报错，下溢（太小）按 0 处理。"},{"t":"sh","no":"6.3","title":"定点运算（本章计算题核心）"},{"t":"tx","h":"6.3.1 移位运算","p":"移位分<b>算术移位</b>（带符号，用于乘除 2ⁿ）和<b>逻辑移位</b>（无符号，空位补 0）。算术移位的空位怎么补，<b>取决于机器数类型</b>：左移补 0（原/反/补码都补 0），右移时原码补 0、<b>补码补符号位</b>（负数补 1）、反码补 1。"},{"t":"tb","head":["码制","左移补入","右移补入"],"rows":[["原码","0","0"],["补码(正)","0","0"],["补码(负)","0","1（补符号位）"],["反码(负)","0","1"]]},{"t":"dv","title":"为什么补码负数右移要补 1","steps":["补码负数的最高位（符号位）是 1，它表示“这个数是负的”","算术右移 = 除以 2，负数除以 2 仍是负数","若右移补 0，符号位变 0，负号会被抹掉，结果就错了","所以右移时把符号位复制到空位，负号才得以保留","结论：补码算术右移 = 符号位扩展（负数补 1）"]},{"t":"fig","kind":"fig-shift","cap":"算术移位：补码负数右移补 1（保持负号），左移补 0"},{"t":"tx","h":"6.3.2 补码加减法","p":"补码加减法把<b>符号位当普通位一起参与运算</b>，减法变成加“相反数的补码”，最高位的进位<b>直接舍去</b>。这样加法器只需一套加法电路，大大简化硬件。"},{"t":"fx","lines":["[X+Y]补 = [X]补 + [Y]补  （符号位参与，进位舍去）","[X−Y]补 = [X]补 + [−Y]补","溢出判断：双符号位 01 = 正溢，10 = 负溢","或：同号相加，结果符号与操作数不同 → 溢出"]},{"t":"dv","title":"双符号位为什么能判溢出","steps":["把一个符号位扩展成两个：正数 00，负数 11（变形补码）","两个正数相加，最高两位理论上应是 00；若变成 01，说明数值位进位“顶”到了符号位","两个负数相加，理论上应是 11；若变成 10，说明负数方向也“溢出”了","所以：结果双符号位 = 00 或 11 → 正常；= 01 → 正溢；= 10 → 负溢","单符号位只看一位无法区分正溢/负溢，故考试统一用双符号位"]},{"t":"fig","kind":"fig-adder","cap":"补码加减：符号位参与运算，末位进位舍去；溢出用双符号位判断"},{"t":"ex","q":"【例题】[X]补=00 1101，[Y]补=00 1001，判断相加是否溢出。","steps":["双符号位相加：00 1101 + 00 1001 = 01 0110","结果双符号位为 01 → 正溢出","两个正数之和超出正数表示范围","结论：单符号位无法区分正溢/负溢，考试用双符号位。"]},{"t":"tx","h":"6.3.3 原码一位乘法","p":"<b>思路：</b>原码乘法<b>符号位单独处理</b>（两数符号异或），数值部分用“<b>加法 + 右移</b>”重复 n 次：每次看乘数<b>最低位</b>，是 1 就加被乘数、是 0 就加 0，然后把「部分积 + 乘数」<b>联合右移</b>一位。"},{"t":"fx","lines":["符号位 = xs ⊕ ys  （异或：同号为正，异号为负）","数值部分：重复 n 次 { 看乘数末位 → 加 0 或加被乘数 → 联合右移 }","n 为数值位数；乘完后部分积+乘数即为积的数值位"]},{"t":"figure-tbl",
"title":"演算：X = 0.1101，Y = 0.1011（求 X×Y）","head":["步骤","乘数末位 → 操作","部分积 A","乘数 Q（右移）"],"rows":[["初始","—","0.0000","1011"],["第1次","末位1 → +X，右移","0.0110","1101"],["第2次","末位1 → +X，右移","0.1001","1110"],["第3次","末位0 → +0，右移","0.0100","1111"],["第4次","末位1 → +X，右移","0.1000","1111"]],"foot":"符号位：0⊕0 = 0（正）。积的数值位 = A 低4位 + Q = 1000 1111 → 结果 <b>X·Y = 0.10001111</b>"},{"t":"dv","title":"原码一位乘为什么要“联合右移”","steps":["把乘法展开：X·Y = X·(y₁2⁻¹ + y₂2⁻² + … + yₙ2⁻ⁿ)","每算一位，部分积要除以 2（右移一位），相当于把当前累加结果降一个数量级","“乘数一起右移”是为了让<u>每次露出的末位</u>正好是还没用过的下一位 y","n 次之后，部分积的高位和移出的乘数位拼在一起，恰好是完整的积","本质：用“移位”代替“逐位配权”，把乘法拆成加法+移位循环"]},{"t":"fig","kind":"fig-mul","cap":"原码一位乘数据通路：部分积 A 与乘数 Q 联合右移，末位决定加 0 还是加 X"},{"t":"warn","text":"<b>易错：</b>① 符号位不参与数值运算，最后单独补；② 每次“先加后移”，顺序别反；③ 部分积位数要比数值位多 1 位，防止进位丢失。"},{"t":"tx","h":"6.3.4 补码一位乘法（Booth 算法）","p":"补码乘法不能再“符号位单独处理”，要<b>符号位一起算</b>。Booth 算法的思路：看乘数<b>最低位 yₙ 和附加位 yₙ₊₁（初始 0）</b>这两位组合——<b>01 就加 [X]补，10 就加 [−X]补，00/11 不加</b>，然后算术右移一位；最后多一步“只加不移”。"},{"t":"tb","head":["(yₙ , yₙ₊₁)","操作","含义"],"rows":[["0 1","+ [X]补","遇到“由0变1”的边界，加被乘数"],["1 0","+ [−X]补","遇到“由1变0”的边界，加被乘数相反数"],["0 0","+ 0","无变化，不加"],["1 1","+ 0","无变化，不加"]]},{"t":"figure-tbl","title":"演算：X = 0.1101，Y = 0.1011（[X·Y]补）","head":["步骤","(yₙ,yₙ₊₁) → 操作","部分积 A","乘数 Q","附加位"],"rows":[["初始","—","00000","1011","0"],["第1次","(1,1) → +0，右移","00000","1101","1"],["第2次","(1,0) → +[X]补，右移","00110","1110","1"],["第3次","(1,1) → +0，右移","00011","1111","1"],["第4次","(1,1) → +0，右移（末步只加不移）","00011","1111","1"]],"foot":"此表为“思路演示”，标准 Booth 需严格按 (yₙ,yₙ₊₁) 判定并逐次右移。<b>核心结论：X·Y = 0.10001111</b>（正数补码 = 原码）。乘法器内部用一个附加位 + 判断电路实现。"},{"t":"dv","title":"Booth 算法背后的原理","steps":["核心公式：2 的幂的差可以重写成相邻项之差，从而减少加法次数","连续的一串 1（如 011110）可写成 100000 − 000010，即两个边界","于是只需在“由0变1”和“由1变0”两个边界处各做一次加减","yₙ,yₙ₊₁ = 0,1 表示进入 1 串 → 减 X；= 1,0 表示离开 1 串 → 加 X","中间连续的 1（11）不再操作，所以 Booth 比逐位乘法平均更快"]},{"t":"ex","q":"【例题】X = 0.1101，Y = −0.1011，用 Booth 求 [X·Y]补。","steps":["[X]补 = 0.1101，[−X]补 = 1.0011，[Y]补 = 1.0101","依次按 (yₙ,yₙ₊₁) 判定：+0 / +[X]补 / +[−X]补，逐次算术右移","末步只看两位、不再移位","最终 [X·Y]补 = 1.01110001，真值 = −0.01110001","验证：0.1101×0.1011 = 0.10001111，符号为负 ✓"]},{"t":"fig","kind":"fig-booth","cap":"Booth 判定电路：比较乘数最低位与附加位，选择 +X / −X / 0，再算术右移"},{"t":"warn","text":"<b>易错：</b>① 附加位初始必须是 0；② +[−X]补 = 对 [X]补“连同符号位”取反加一；③ 右移是<b>算术移位</b>（补符号位），不是逻辑移位；④ n 次循环后还要多做一次“只加右不移”的收尾。"},{"t":"tx","h":"6.3.5 原码一位除法","p":"除法是“减出商”。两种手算方法：<b>恢复余数法</b>——先减除数，若结果为负就<b>把除数加回来</b>（恢复），商上 0；若为正，商上 1。<b>加减交替法</b>——上一步余数为负时，下一步<b>改用“加除数”</b>，省掉恢复这一步，速度更快。"},
{"t":"tb","head":["余数 R 符号","商位","下一步操作"],"rows":[["R ≥ 0","上商 1","2R − Y"],["R < 0","上商 0","2R + Y（自动“恢复+再减”，一步顶两步）"]]},{"t":"figure-tbl","title":"演算（加减交替法）：X = 0.1011 ÷ Y = 0.1101","head":["步骤","操作","余数 R","商位"],"rows":[["初始","R = X − Y","−2 (<0)","—"],["第1次","R<0，商0，2R + Y","9 (>0)","0"],["第2次","R≥0，商1，2R − Y","5 (>0)","01"],["第3次","R≥0，商1，2R − Y","−3 (<0)","011"],["第4次","R<0，商0，2R + Y","7 (>0)","0110"]],"foot":"商 = <b>0.0110</b>；末位还需按规则“商1”修正得到最终商，余数为正。"},{"t":"dv","title":"加减交替法为什么能省掉“恢复余数”","steps":["恢复余数法：减完若为负，要把除数加回去（多做一次加法）","观察：下一位本来要算 (R+Y)·2 − Y = 2R + Y（把两次并一次）","所以余数为负时，直接用“2R + Y”就已包含“恢复再加”的效果","正负交替地“该减则减、该加则加”，故称加减交替法","少了一次恢复操作，除法速度更快，硬件也更简单"]},{"t":"fig","kind":"fig-div","cap":"原码除法数据通路：余数左移 → 加减除数 → 上商 → 循环 n 次"},{"t":"tx","h":"6.3.6 补码一位除法（加减交替）","p":"补码除法仍用加减交替，但判商规则看<b>余数与除数是否同号</b>：同号商 1，异号商 0；末位按“恒置 1”修正。原理与原码一致，只是全程在补码下做。"},{"t":"sh","no":"6.4","title":"浮点四则运算"},{"t":"tx","h":"浮点加减法五步","p":"浮点加减法必须<b>先对齐阶码</b>再运算，标准五步：<b>对阶</b>（小阶向大阶看齐，阶小的尾数右移）→ <b>尾数加减</b> → <b>规格化</b>（让尾数最高位为 1）→ <b>舍入</b> → <b>溢出判断</b>。"},{"t":"fx","lines":["① 对阶：小阶向大阶看齐，尾数右移 (阶差) 位","② 尾数求和：补码相加","③ 规格化：尾数最高位为 1（左规 / 右规）","④ 舍入：0舍1入 / 恒置1","⑤ 溢出判断：阶码溢出为上溢（报错），尾数下溢按 0"]},{"t":"figure-tbl","title":"演算：X = 0.1101×2⁰¹，Y = −0.1010×2⁰⁰","head":["步骤","说明","结果"],"rows":[["对阶","小阶 00 → 大阶 01，Y 尾数右移 1 位","Y = −0.0101×2⁰¹"],["尾数求和","0.1101 + (−0.0101)","0.1000"],["规格化","0.1000 最高位已是 1，无需再动","0.1000×2⁰¹"],["判溢出","阶码 01 在范围内","X+Y = 0.1000×2⁰¹"]],"foot":"对阶时<b>只能小阶向大阶看齐</b>（否则会丢掉大数的有效位），且右移会损失精度，这就是“大数吃小数”的来源。"},{"t":"dv","title":"为什么对阶要“小阶向大阶看齐”","steps":["浮点数相加必须保证两个数的阶码相同，尾数才能直接相加","若让大阶向小阶看齐，大数的尾数要<u>左移</u>，会超出尾数位宽，高位被挤出丢失","若让小阶向大阶看齐，只把小数尾数<u>右移</u>，损失的是低位的最低有效位","丢失低位比丢失高位对结果影响小得多（大数吃小数）","所以对齐方向规定为：小阶向大阶看齐"]},{"t":"fig","kind":"fig-float","cap":"浮点加减五步流程：对阶 → 尾数求和 → 规格化 → 舍入 → 判溢出"},{"t":"ex","q":"【例题】浮点乘除法的步骤是什么？","steps":["浮点乘法：阶码相加（移码相加要减去一个偏置）→ 尾数相乘 → 规格化 → 舍入","浮点除法：阶码相减（移码相减要加上一个偏置）→ 尾数相除 → 规格化 → 舍入","阶码运算用移码，注意“多加/少减”一个偏置","尾数部分就是定点乘/除","最后统一做规格化、舍入与溢出判断"]},{"t":"sh","no":"6.5","title":"算术逻辑单元 (ALU)"},{"t":"tx","h":"ALU 与并行进位","p":"ALU 是运算器的核心，完成算术与逻辑运算。多位加法若<b>进位逐级传递</b>会很慢，因此用<b>先行进位（超前进位）</b>：直接由各位输入算出各级进位，用“空间换时间”。运算还会产生标志位：Z(零)、C(进位)、S(符号)、O(溢出)，供条件转移指令使用。"},{"t":"dv","title":"先行进位是怎么“跳过”逐级等待的","steps":["定义第 i 位的生成 Gᵢ = AᵢBᵢ（本位一定产生进位）","定义第 i 位的传递 Pᵢ = Aᵢ⊕Bᵢ（本位能把低位进位传上去）","则 Cᵢ₊₁ = Gᵢ + PᵢCᵢ（本位产生进位，或本位传递低位进位）","把 Cᵢ 反复代入即可展开成只含 P、G、C₀ 的表达式，与前面的进位无关","于是各级进位可并行算出，不必逐级等待，加法速度大幅提升"]},
{"t":"fig","kind":"fig-cla","cap":"先行进位加法器：由 P、G 展开直接得到各级进位，消除逐级传递延迟"},{"t":"warn","text":"<b>本章总易错：</b>① 补码“取反加一”得到的是<b>相反数</b>的补码；② 溢出判断用双符号位，且“溢出 ≠ 进位”；③ 补码右移是算术移位（负数补 1）；④ 原码乘法符号位单独算、Booth 符号位一起算；⑤ 对阶必须小阶向大阶看齐；⑥ 浮点阶码是移码不是补码。"},{"t":"sh","no":"6.6","title":"数的扩展与截断"},{"t":"tx","h":"为什么会有扩展与截断","p":"不同指令、不同寄存器位宽不同，数据在它们之间流动时就要变长或变短。变长叫<b>扩展</b>，变短叫<b>截断</b>。规则的核心只有一句：<b>必须保持数值不变</b>，否则运算就错了。"},{"t":"tb","head":["操作","适用对象","规则","例（8 位 → 16 位）"],"rows":[["零扩展","无符号数","高位全补 0","1001 1101 → 0000 0000 1001 1101"],["符号扩展","有符号数（补码）","高位全补符号位","1001 1101 → 1111 1111 1001 1101"],["截断（低）","取低位","直接丢弃高位，可能溢出","1111 1001 1101 → 1001 1101"]]},{"t":"dv","title":"推导：−13 的符号扩展（8 位 → 16 位）","steps":["−13 的 8 位补码：13 = 0000 1101，取反 1111 0010，加 1 → <b>1111 0011</b>","符号位是 1（负数），故扩展时高位全补 <b>1</b>","结果：1111 1111 1111 0011","验算：取反 0000 0000 0000 1100，加 1 → 0000 0000 0000 1101 = 13，符号为负 → <b>−13</b> ✓","若错用零扩展得 0000 0000 1111 0011 = +243，数值完全变了——这就是零扩展不能用于负数的原因"]},{"t":"dv","title":"推导：截断会不会溢出（怎么判断）","steps":["把 16 位数截成 8 位，只有<b>被丢掉的高 8 位全等于符号位</b>时才不溢出","可表示的 8 位范围：−128 ~ +127","正数例：0000 0000 0100 0001（+65）高 8 位全 0 = 符号位 → 截断为 0100 0001（+65）✓","负数例：1111 1111 1011 1111（−65）高 8 位全 1 = 符号位 → 截断为 1011 1111（−65）✓","溢出例：0000 0001 0100 0001（+321 > 127）高 8 位不全 0 → 截断为 0100 0001（+65），<b>溢出</b> ✗","要点：判断标准是“丢掉的高位是否全等于符号位”，不是看数值大小"]},{"t":"sh","no":"6.7","title":"数据的校验：码距、奇偶、海明与 CRC"},{"t":"tx","h":"码距是所有校验理论的基石","p":"<b>码距 d</b> 是任意两个合法码字之间不同的最少位数。d 越大，抗干扰能力越强：<b>检 e 位错要求 d ≥ e+1</b>；<b>纠 t 位错要求 d ≥ 2t+1</b>；<b>纠 t 位并检 e 位错要求 d ≥ e+t+1（e ≥ t）</b>。这三种能力的关系是本章所有计算题的出发点。"},{"t":"tb","head":["码距 d","检错能力","纠错能力","说明"],"rows":[["1","0","0","无冗余，错一位就变成另一个合法码"],["2","1","0","奇偶校验：能发现 1 位错，不能定位"],["3","2 或 1","1","海明码（n 较大时）：可纠正 1 位错"],["4","3 或 2","1","可纠 1 位并检 2 位"],["≥2t+1","≥t+1","t","一般关系"]]},{"t":"fig","kind":"fig-hamming","cap":"<b>图解</b>：海明码校验位放在 2 的幂次位置，每个数据位被若干校验位交叉覆盖，出错时由各校验组指误字定位出错位。"},{"t":"dv","title":"推导：奇偶校验位怎么定（以偶校验为例）","steps":["设待传数据 <b>1011 001</b>（7 位）","偶校验要求“1 的个数为偶数”：数一下现有 1 有 <b>4</b> 个","4 已是偶数 → 校验位补 <b>0</b>，发送 1011 001<b>0</b>","若数据是 <b>1011 000</b>（3 个 1）→ 校验位补 <b>1</b>，凑成 4 个 1","接收端重新数 1：奇数个即判定出错","局限：只能发现 <b>奇数个</b>位错；偶数个位错（如 2 位同时翻转）无法发现，且不能定位错在哪一位"]},{"t":"dv","title":"推导：海明码校验位数与分组（n=4 求 k）","steps":["设数据位 n = 4，校验位 k 位，总长 n+k。校验位要能指出“哪一位错”或“没错”，共 n+k+1 种状态","因此需满足 <b>2<sup>k</sup> ≥ n + k + 1</b>","试 k=2：2² = 4，n+k+1 = 4+2+1 = 7，4 ≥ 7 不成立","试 k=3：2³ = 8，n+k+1 = 4+3+1 = 8，8 ≥ 8 <b>成立</b> → k = <b>3</b>",
"总长 7 位，校验位放在 2 的幂位：P1→第 1 位、P2→第 2 位、P4→第 4 位；数据位填其余 3、5、6、7 位","分组规则（按位号二进制中哪一位为 1）：P1 校验 1,3,5,7 位；P2 校验 2,3,6,7 位；P4 校验 4,5,6,7 位","纠错：收到后三组各算一次偶校验，得 3 位指误字，其十进制值就是出错位号（0 表示无错）","计算量提示：n 增大时按 2<sup>k</sup> ≥ n+k+1 逐个试 k，如 n=8 → k=4（16 ≥ 13）、n=16 → k=5（32 ≥ 22）"]},{"t":"ex","q":"【例题】数据位 n = 4，采用偶校验海明码。(1) 求校验位数 k；(2) 写出数据 0101 的海明码；(3) 若接收码字第 5 位出错，指误字是多少、如何纠正？","steps":["校验位条件：2^k ≥ n + k + 1 → k=3 时 8 ≥ 4+3+1 = 8 ✓ → <b>k = 3</b>，总码长 7 位","位置安排：校验位放在 2 的幂次位置（1、2、4），数据位填其余位置（3、5、6、7）","数据 0101 → D₁=0 在位 3，D₂=1 在位 5，D₃=0 在位 6，D₄=1 在位 7",{"s":"P₁ 校验含位 1 的组 {1,3,5,7}：P₁ ⊕ 0 ⊕ 1 ⊕ 1 = 0 → <b>P₁ = 0</b>","note":"偶校验：整组 1 的个数为偶数"},"P₂ 校验 {2,3,6,7}：P₂ ⊕ 0 ⊕ 0 ⊕ 1 = 0 → <b>P₂ = 1</b>","P₃ 校验 {4,5,6,7}：P₃ ⊕ 1 ⊕ 0 ⊕ 1 = 0 → <b>P₃ = 0</b>","海明码（位 1→7 依次）：<b>0 1 0 0 1 0 1</b>",{"s":"第 5 位出错：5 = 101B，它属于 P₁ 组与 P₃ 组、不属于 P₂ 组 → 指误字 G₃G₂G₁ = <b>101 = 5</b>","note":"指误字的值恰好就是出错位号"},"纠正：把第 5 位取反即可。若指误字为 000 则判定无错","能力边界：该配置可<b>检 2 位错、纠 1 位错</b>；要纠 2 位错需再加一个总校验位（扩展海明码）"]},{"t":"dv","title":"推导：CRC 校验位（模 2 除法，信息 1101，G(x)=1011）","steps":["生成多项式 G(x) = x³+x+1 → 系数串 <b>1011</b>，最高次 r = 3，故校验位 <b>3 位</b>","信息码 1101 左移 3 位补 0 → <b>1101 000</b>（7 位）","做模 2 除法（异或，不借位）：","① 1101000 ⊕ 1011000 = 0110000（首位 1，商 1）","② 0110000 ⊕ 0101100 = 0011100（对齐到第 2 位）","③ 0011100 ⊕ 0010110 = 0001010（对齐到第 3 位）","④ 0001010 ⊕ 0001011 = 0000001（对齐到第 4 位）","余数取后 3 位 = <b>001</b>，即 CRC 校验位","发送码字 = 1101 + 001 = <b>1101 001</b>；接收端用同一 G(x) 再除一次，余数为 0 即无错","要点：模 2 除法只做异或；校验位数 = 生成多项式最高次幂；余数位数不足要在左侧补 0"]},{"t":"ex","q":"【例题】信息码 1101，生成多项式 G(x) = x³ + x + 1，求 CRC 校验位与发送码字。","steps":["G(x) 最高次为 3 → 校验位 <b>3 位</b>；G(x) = x³+x+1 的二进制串为 <b>1011</b>（含最高次项系数）","信息码 1101 后补 3 个 0 → 被除数 <b>1101 000</b>","第 1 轮：1101 ⊕ 1011 = 0110，商 1，余 110","第 2 轮：补 0 得 1100，⊕ 1011 = 0111 → 余 111","第 3 轮：补 0 得 1110，⊕ 1011 = 0101 → 余 101","第 4 轮：补 0 得 1010，⊕ 1011 = 0001 → 余 1，补足 3 位为 <b>001</b>","校验位 = <b>001</b>，发送码字 = <b>1101 001</b>",{"s":"验算：1101 001 ÷ 1011 余数为 0000 ✓（接收端余 0 即判无错）","note":"这一步必须做，能立刻验出算错"},"模 2 除法全程<b>只异或、不借位</b>——这是与普通除法唯一但最致命的区别"]},{"t":"sh","no":"6.8","title":"定点运算补充：十进制加减、阵列乘法器、乘法溢出"},{"t":"dv","title":"推导：BCD 十进制加法（和 >9 要加 6 修正）","steps":["十进制加法器直接对 BCD 码做二进制加法，但二进制逢 16 进 1，而十进制应逢 10 进 1 → 需要修正","例：<b>47 + 38</b>。BCD 表示 0100 0111 + 0011 1000","低 4 位：0111 + 1000 = <b>1111</b>（十进制 15），大于 9 → 需 <b>+6</b> 修正","1111 + 0110 = 1 0101 → 低 4 位得 0101，同时向高位产生进位 1","高 4 位：0100 + 0011 + 1（进位）= 1000（无超过 9，不需修正）","结果 1000 0101 = <b>85</b>，与 47+38 = 85 ✓",
"规则：某 4 位结果 > 9 或产生进位 → 该 4 位 +6；减法时借位则 −6"]},{"t":"dv","title":"推导：阵列乘法器要多少个器件（n×n）","steps":["n 位 × n 位，需要产生 <b>n×n 个部分积位</b>，每个部分积位由一个与门产生 → <b>n² 个与门</b>","把 n 个部分积逐列相加，共需 (n−1) 行加法，每行 n 个全加器","全加器总数 = <b>n(n−1) 个</b>","例 n = 8：与门 8² = <b>64 个</b>，全加器 8×7 = <b>56 个</b>","例 n = 16：与门 256 个，全加器 240 个","时间：信号逐级传递，延迟约 <b>2n 个门延迟</b>，与“移位相加”法的 n 个周期相比快得多，代价是器件量随 n² 增长","要点：阵列乘法器是“用空间换时间”，适合大规模集成电路"]},{"t":"dv","title":"推导：乘法溢出怎么判断","steps":["两个 n 位数相乘，积最多 <b>2n 位</b>；若只保留 n 位，高位被丢即可能溢出","例（4 位）：7 × 6 = 42。7 = 0111，6 = 0110，实际积 0010 1010（8 位）","取低 4 位 = 1010，这是负数（−6），显然错误 → <b>溢出</b>","判断方法 1（双符号位）：积的两位符号位相同则未溢出，不同（01 或 10）则溢出","判断方法 2（范围）：|积| > 2<sup>n−1</sup> − 1（n 位补码最大正值）即溢出","方法 2 验算上例：42 > 2³−1 = 7 → 溢出 ✓","注意：原码乘法判断“高位是否有有效数字”，补码乘法用双符号位，两者规则不同"]},{"t":"ex","q":"【例题】用 4 位补码计算 (−6) × 3，判断是否溢出。","steps":["−6 的 4 位补码：6 = 0110 → 取反 1001 → 加 1 = <b>1010</b>","3 的 4 位补码：<b>0011</b>","实际乘积 = −18，8 位补码为 1110 1110","取低 4 位 = 1110，即 −2；而正确结果是 −18 → <b>溢出</b>","双符号位判断：完整积符号位为 11，低 4 位符号位为 1，看起来一致，但真实值 −18 < −8（4 位补码最小值），已越界","结论：需用 8 位存放结果；判断溢出的可靠办法是用 2n 位保存完整积后再检查范围"]},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第6章习题）"},{"t":"pt","no":"题型1","name":"原码、反码、补码、移码的转换","feature":"给一个定点数，求其原/反/补/移码表示。","method":"正数三码相同；负数：反码=符号位不变其余取反，补码=反码末位+1。","steps":["确定字长与符号位","正数：原=反=补，符号位 0","负数：原码符号 1；反码除符号位取反；补码反码+1","移码 = 补码符号位取反（同一数）"],"ex":{"q":"字长 8 位，求 −13 的补码。","steps":["13 = 0001101，原码 10001101","反码 11110010","补码 = 反码+1 = 11110011","即 0xF3。"]},"pit":"补码 = 反码+1 只在负数；0 的补码唯一。"},{"t":"pt","no":"题型2","name":"补码加减运算与溢出判断","feature":"两个补码数相加/相减，判断是否溢出。","method":"补码加法：符号位一起参与；溢出判断：同号相加结果异号则溢出，或双符号位（变形补码）判 01/10。","steps":["把两数写成同字长补码","符号位与数值一起相加","判溢出：正+正得负 或 负+负得正 → 溢出","减法转成加负数补码"],"ex":{"q":"8 位补码计算 100 + 100，判断结果。","steps":["100 补码 = 01100100","相加 = 11001000","两正数相加得负数","发生溢出，结果无效。"]},"pit":"溢出≠进位；两个异号数相加绝不溢出。"},{"t":"pt","no":"题型3","name":"原码一位乘法（移位相加型）","feature":"用原码一位乘求两数乘积。","method":"符号位单独异或，数值部分逐位乘加：乘数末位为 1 则加被乘数，随后右移。","steps":["符号位 = 两操作数符号异或","取绝对值做无符号乘法","从乘数最低位开始：为 1 加被乘数，部分积右移一位","重复 n 次得数值部分，拼上符号位"],"ex":{"q":"x=0.1101, y=0.1011，用原码一位乘法求 x·y。","steps":["符号位 = 0⊕0 = 0（正）","数值 1101 × 1011 逐位：末位1加1101，右移；","依次按位乘加右移共 4 次","得数值 10001111，结果 +0.10001111。"]},"pit":"每步“判断→加→移位”；右移是对部分积（含进位）进行。"},{"t":"pt","no":"题型4","name":"补码一位乘法（Booth 算法）","feature":"用 Booth 法求带符号数乘积。","method":"在乘数末位补附加位 y_{n+1}=0，比较 y_n y_{n+1}：01 加[x]补、10 加[−x]补、00/11 不加，再算术右移。","steps":["乘数末位补 0 作附加位",
"看相邻两位（y_n, y_{n+1}）：01→+[x]补，10→+[−x]补","算术右移一位（含符号位）","重复 n 次，最后一步不移位（共 n 次加、n 次移）"],"ex":{"q":"x=−0.1101, y=+0.1011，用 Booth 补码一位乘法求 x·y。","steps":["[x]补 = 1.0011，[−x]补 = 0.1101","按 y 相邻位对决定加 [x]补 或 [−x]补","每步后算术右移","结果补码 = 1.01101111（即 −0.10010001）。"]},"pit":"Booth 判断看“当前位与附加位”组合；算术右移须保持符号位。"},{"t":"pt","no":"题型5","name":"浮点数表示与规格化","feature":"按自定义/标准格式表示浮点数，或判断规格化。","method":"浮点数 = 阶码 + 尾数（符号）；规格化尾数最高位有效位为 1。","steps":["确定阶码位数、尾数位数、阶符尾符","把数值写成 ±2^e × M","规格化：调整尾数使最高位为 1，同步改阶码","编码时阶码常用移码/补码、尾数用补码/原码"],"ex":{"q":"设阶码 4 位（含 1 位阶符，用移码）、尾数 6 位（含 1 位尾符），表示 −0.1101×2⁻²。","steps":["阶码 = −2，移码表示","尾数 = −0.1101 的补码或原码","按格式拼接符号、阶、尾","注意规格化后尾数最高位为 1。"]},"pit":"规格化时数值不变、阶码改变；移码与补码符号位相反。"},{"t":"pt","no":"题型6","name":"浮点加减法运算","feature":"两个浮点数相加减，求结果。","method":"对阶→尾数加减→规格化→（舍入）→溢出判断。","steps":["对阶：小阶向大阶看齐，尾数右移","尾数按定点加减","结果规格化（左规/右规）","判断阶码是否上溢/下溢"],"ex":{"q":"说明浮点加法中“对阶”为什么把小阶的尾数向大阶对齐。","steps":["两数阶不同不能直接加尾数","移动大阶尾数会丢失高位有效数字","移动小阶尾数损失最小","故小阶向大阶对齐，保精度。"]},"pit":"对阶只移动小阶；规格化后要检查阶码溢出。"},{"t":"pt","no":"题型7","name":"浮点数范围与精度计算","feature":"由阶码/尾数位数求可表示范围与精度。","method":"阶码位数决定范围，尾数位数决定精度（2^−m）。","steps":["阶码 k 位 → 最大指数范围","范围 ≈ ±2^(最大阶) ","尾数 m 位 → 精度 2^−m","符号与 0 单独讨论"],"ex":{"q":"尾数 10 位（含符号）的浮点数，精度约为多少？","steps":["有效数值位 m = 9","精度 ≈ 2⁻⁹","≈ 0.00195","即能分辨的最小数量级。"]},"pit":"范围看阶码、精度看尾数，二者独立。"},{"t":"pt","no":"题型8","name":"奇偶校验与简单检错","feature":"给定数据求奇偶校验位，或判断能否检错。","method":"奇校验使 1 的个数为奇数，偶校验为偶数；只能检出奇数位错。","steps":["数数据中 1 的个数","奇校验补使总数成奇数，偶校验成偶数","接收端校验 1 的个数是否符合","只能检出奇数位错误，不能纠错"],"ex":{"q":"数据 1011001，求偶校验位。","steps":["数据中 1 的个数 = 4（偶）","偶校验要求总数仍为偶","校验位 = 0","若 1 的个数为奇则补 1。"]},"pit":"奇偶校验不能纠正错误，也只能查出奇数位错。"},{"t":"tip","text":"<b>第6章解题总流程：</b>①码制转换先定字长与符号；②加减注意溢出（变形补码看双符号）；③一位乘法按“判断→加→移”；④Booth 看相邻位组合；⑤浮点先对阶、算完必规格化并查溢出。"},{"t":"kw","items":["原码反码补码","移码","取反加一","IEEE754","算术移位","双符号位溢出","原码一位乘","补码一位乘Booth","加减交替除法","浮点对阶","先行进位"]}]},"g7":{"no":"7","title":"指令系统","tag":"第3篇 · 第7章","sub":"课本第7章(当前进度)。指令是人机接口，规定机器“能听懂哪些话”。格式、寻址方式、RISC 是核心。","blocks":[{"t":"sh","no":"7.1","title":"机器指令"},{"t":"tx","h":"指令格式","p":"一条指令 = <b>操作码 OP + 地址码 A</b>。操作码指明“做什么”，地址码指明“操作数在哪”。按地址码个数分三地址、二地址、一地址、零地址指令；按长度分定长/变长指令。"},{"t":"fx","lines":["指令 = 操作码 + 地址码","定长操作码：n 位可表示 2ⁿ 种操作","扩展操作码：短码给常用指令，长码给少用指令"]},{"t":"dv","title":"推导：扩展操作码为何能扩大指令条数","steps":["若操作码固定 n 位，最多 2ⁿ 条指令，浪费且不够灵活","让高频指令用短操作码，低频指令用长操作码","例如 4 位基本操作码：留出全 1(1111)作扩展标志，可得 15 条基础指令","再用接下来的 4 位扩展：每条扩展前缀可派生 2⁴ = 16 条","关键约束：<b>短码不能是长码的前缀</b>，否则译码产生歧义"]},
{"t":"sh","no":"7.2","title":"地址码与指令地址数（0/1/2/3/4 地址）"},{"t":"tx","h":"地址码的作用","p":"<b>地址码 A</b> 指出指令要用的操作数在哪里——可以是主存单元地址，也可以是寄存器编号；它有时还兼带“结果放哪”“下条指令在哪”的信息。指令字长固定时有一个铁律：<b>地址码个数 ↑ → 每个地址的位数 ↓ → 寻址范围 ↓</b>。这是本章所有格式计算题的出发点。"},{"t":"tx","h":"五种地址数格式（同一 32 位指令字）","p":"设指令字长 <b>32 位</b>、操作码 <b>8 位</b>，其余 <b>24 位</b>全部分给地址码。把 24 位按地址个数平均分配，就得到四地址、三地址、二地址、一地址四种格式；零地址指令不设地址码，把 24 位也并入操作码。"},{"t":"fig","kind":"fig-addr-format","cap":"同一 32 位指令字的位段分配：4 地址各 6 位 / 3 地址各 8 位 / 2 地址各 12 位 / 1 地址 24 位 / 0 地址无地址码"},{"t":"tb","head":["格式","位段分配（共 32 位）","每个地址位数","完成的操作"],"rows":[["四地址","OP 8 + A1 6 + A2 6 + A3 6 + A4 6","6","(A1) OP (A2) → A3；A4 直接指明下条指令地址"],["三地址","OP 8 + A1 8 + A2 8 + A3 8","8","(A1) OP (A2) → A3；下条指令由 PC 自动给出"],["二地址","OP 8 + A1 12 + A2 12","12","(A1) OP (A2) → A1（结果覆盖 A1）"],["一地址","OP 8 + A 24","24","(A) OP (ACC) → ACC（另一操作数隐含在累加器）"],["零地址","OP 32（无地址码）","—","无操作数（NOP、HLT）或操作数隐含（栈顶）"]]},{"t":"tx","h":"核心计算：24 位地址字段怎么分","p":"<b>通用公式</b>：每个地址位数 = (指令字长 − 操作码位数) ÷ 地址个数；<b>寻址范围 = 2^(每个地址位数)</b>。下面把四种格式逐个算一遍，每一步都写清来源。"},{"t":"dv","title":"推导 1：四地址指令 —— 6 位地址，寻址 64","steps":["地址字段总位数 = 指令字长 − 操作码位数 = 32 − 8 = <b>24 位</b>","四地址平均分配：24 ÷ 4 = <b>6 位/地址</b>","寻址范围 = 2⁶ = <b>64</b> 个单元（地址 0 ~ 63）","四地址由 A4 直接给出下条指令地址，可以省掉 PC；但 6 位地址只能指 64 个单元，容量太小","结论：四地址是“理论上最全”的格式，实际几乎不用，只作为理解地址码作用的起点"]},{"t":"dv","title":"推导 2：三地址指令 —— 8 位地址，寻址 256","steps":["地址字段总位数 = 32 − 8 = <b>24 位</b>","三地址平均分配：24 ÷ 3 = <b>8 位/地址</b>","寻址范围 = 2⁸ = <b>256</b> 个单元（地址 0 ~ 255）","省掉 A4 后，下条指令地址改由 PC 自动 +1，省下的那部分位数让每个地址从 6 位涨到 8 位","对比四地址：每个地址多 2 位，寻址范围由 64 增至 256，扩大 <b>4 倍</b>","典型形式：(A1) OP (A2) → A3，其中 A3 可复用 A1 或 A2 以节省编码"]},{"t":"dv","title":"推导 3：二地址指令 —— 12 位地址，寻址 4K","steps":["地址字段总位数 = 32 − 8 = <b>24 位</b>","二地址平均分配：24 ÷ 2 = <b>12 位/地址</b>","寻址范围 = 2¹² = <b>4096 = 4K</b> 个单元","形式：(A1) OP (A2) → A1，让结果覆盖源操作数 1，又省掉一个地址字段","对比三地址：每个地址多 4 位，寻址范围由 256 增至 4K，扩大 <b>16 倍</b>","这是除 RISC 之外最常见的格式（x86 的双操作数指令就是这种思路）"]},{"t":"dv","title":"推导 4：一地址指令 —— 24 位地址，寻址 16M","steps":["地址字段总位数 = 32 − 8 = <b>24 位</b>","一地址全部给它：<b>24 位/地址</b>","寻址范围 = 2²⁴ = 16 777 216 ≈ <b>16M</b> 个单元","另一个操作数和结果都隐含在 <b>ACC 累加器</b>：(A) OP (ACC) → ACC","对比二地址：地址位数翻倍，寻址范围由 4K 增至 16M，扩大 <b>4096 倍</b>","早期小型机常用（PDP-8），指令短、取指少，但要频繁访问 ACC"]},{"t":"dv","title":"推导 5：零地址指令 —— 操作码可扩到 32 位","steps":["不设地址码，32 位全部可作操作码 → 理论上可编 <b>2³²</b> 种操作","若仍按 8 位操作码计：2⁸ = <b>256</b> 种，余 24 位可用于扩展操作码，指令条数大幅增加","操作数隐含：堆栈机从栈顶弹出两个数，或 NOP / HLT 这类本身无操作数的指令",
"零地址机通常配堆栈结构，用“压栈 / 出栈”代替显式地址"]},{"t":"tx","h":"别忘了算“操作数范围”","p":"寻址范围只说明“能指到多少个单元”，<b>操作数范围</b>还要乘上每个单元的位数（编址单位）。例：主存按字节编址、每单元 8 位，则 12 位地址可覆盖 4K 个字节 = <b>4KB</b>；若按字（32 位）编址，则覆盖 4096 × 4B = <b>16KB</b>。答题时先看清“按什么编址”。"},{"t":"ex","q":"【例题 1】某机指令字长 32 位，操作码 8 位。分别求三地址、二地址格式下每个地址码的位数与寻址范围。","steps":["可用地址总位数 = 32 − 8 = 24 位（两种格式相同）","三地址：24 ÷ 3 = 8 位/地址 → 寻址范围 2⁸ = 256 个单元","二地址：24 ÷ 2 = 12 位/地址 → 寻址范围 2¹² = 4096 = 4K 个单元","结论：地址个数 3 → 2，每个地址 8 → 12 位，寻址范围 256 → 4K，扩大 16 倍"]},{"t":"ex","q":"【例题 2】某机指令字长 16 位，要求支持 64 条三地址指令，问每个地址码最多几位？若改成二地址，寻址范围多大？","steps":["64 条指令 → 操作码位数 = log₂64 = 6 位","三地址可用地址位 = 16 − 6 = 10 位 → 10 ÷ 3 = 3 余 1，取 <b>3 位/地址</b>","此时每个地址寻址 2³ = 8 个单元，余下 1 位可留作扩展操作码或空白位","改二地址：10 ÷ 2 = 5 位/地址 → 寻址范围 2⁵ = 32 个单元","要点：除不尽时向下取整，余位不能丢，要说明去向"]},{"t":"ex","q":"【例题 3】某机指令字长 24 位，采用一地址格式，地址码 16 位，问操作码几位？可表示多少条指令？寻址范围多大？","steps":["操作码位数 = 24 − 16 = <b>8 位</b>","指令条数 = 2⁸ = <b>256</b> 条","寻址范围 = 2¹⁶ = <b>65536 = 64K</b> 个单元","若主存按字节编址 → 可寻址 64KB；按字（24 位）编址 → 64K × 3B = 192KB"]},{"t":"warn","text":"<b>易错点：</b>① 地址码位数必须是整数，除不尽向下取整，余位别丢；② “寻址范围”按 2^位数 算，“操作数范围”还要乘编址单位；③ 一地址、零地址指令的另一操作数隐含在 ACC 或栈顶，不是“没有操作数”；④ 四地址的 A4 是下条指令地址，别当成第三个操作数。"},{"t":"sh","no":"7.3","title":"大端、小端存储与边界对齐"},{"t":"tx","h":"一个字放进内存，字节怎么排","p":"一个 32 位字占 4 个字节，这 4 个字节在内存里的先后顺序就是<b>字节序</b>。<b>大端（Big-Endian）</b>：高字节放在低地址，符合人的阅读习惯，网络字节序采用它；<b>小端（Little-Endian）</b>：低字节放在低地址，x86 与 ARM（默认）采用它。"},{"t":"dv","title":"推导：0x12345678 在两种字节序下的内存布局","steps":["把字拆成 4 个字节：最高字节 <b>12</b>、次高 <b>34</b>、次低 <b>56</b>、最低 <b>78</b>","<b>大端</b>：低地址放高字节 → 1000H:12、1001H:34、1002H:56、1003H:78","<b>小端</b>：低地址放低字节 → 1000H:78、1001H:56、1002H:34、1003H:12","两种方式下这个字的值都是 0x12345678，只是排列方向相反","若题目问“1000H 单元的内容”：大端答 12H，小端答 78H——这是最常见的考法","判断技巧：小端 = “低低”——低字节放低地址；大端 = “高低”——高字节放低地址"]},{"t":"dv","title":"推导：边界对齐后结构体占多少字节","steps":["设 32 位机，int 占 4 B（须 4 字节对齐）、short 占 2 B（须 2 字节对齐）、char 占 1 B","结构体 <b>struct { char a; int b; short c; }</b>：","a 放偏移 0（1 B）；b 须 4 对齐 → 偏移 1~3 补空 3 B，b 占偏移 4~7","c 须 2 对齐 → 偏移 8 已对齐，c 占偏移 8~9","结构体总大小须为最大成员（4 B）的整数倍 → 10 补到 <b>12 B</b>","若不补齐（紧凑排列）：1 + 4 + 2 = 7 B，省 5 B 但访问 int 要跨两次总线周期，速度下降","要点：三个规则——成员按自身大小对齐、结构体总长按最大成员对齐、数组元素间也按元素大小对齐"]},{"t":"ex","q":"【例题】32 位机，int 4 B、short 2 B、char 1 B，求 struct { char a; short b; char c; int d; } 的大小。","steps":["a 偏移 0（1 B）","b 须 2 对齐 → 偏移 1 补 1 B，b 占偏移 2~3","c 偏移 4（1 B）","d 须 4 对齐 → 偏移 5~7 补 3 B，d 占偏移 8~11","当前共 12 B，是最大成员 4 的整数倍 → 总大小 <b>12 B</b>","对比紧凑排列 1+2+1+4 = 8 B，补齐后多 4 B 的填充"]},
{"t":"sh","no":"7.4","title":"操作数类型和操作类型"},{"t":"tx","h":"操作数与操作","p":"操作数类型：地址、数字、字符、逻辑数。操作类型：数据传送、算术逻辑运算、移位、转移(跳转)、输入输出等。"},{"t":"sh","no":"7.5","title":"寻址方式"},{"t":"tx","h":"指令寻址：顺序与跳跃","p":"<b>指令寻址</b>解决“下一条指令在哪”，只有两种：<b>顺序寻址</b>靠 PC 自动 +1（按字编址加 1，按字节编址加指令字节数）；<b>跳跃寻址</b>由转移指令把新地址送 PC，实现分支、循环、调用。与之相对的<b>操作数寻址</b>解决“操作数在哪”，方式多达十余种。两者是两套不同机制，考试常放在一起设陷阱。"},{"t":"tx","h":"按字节编址时 PC 加几","p":"若指令字长 32 位、主存按<b>字节</b>编址，则一条指令占 4 个字节，顺序执行时 <b>PC ← PC + 4</b>；若按<b>字</b>编址，则 PC ← PC + 1。题目若给“按字节编址”却按 +1 算，后面所有地址全错。"},{"t":"tx","h":"常见寻址方式","p":"<b>立即寻址</b>(操作数在指令中，最快)、<b>直接寻址</b>(地址码即主存地址)、<b>间接寻址</b>(地址码指向的单元存真正地址，需两次访存)、<b>寄存器寻址</b>(操作数在寄存器)、<b>寄存器间接</b>(寄存器存主存地址)、<b>基址/变址/相对寻址</b>(地址=基址+偏移，便于程序浮动与数组访问)。"},{"t":"fig","kind":"fig-addressing","cap":"立即/直接/间接寻址：操作数位置不同，访存次数依次为 0 / 1 / 2"},{"t":"tb","head":["寻址方式","操作数位置","访存次数"],"rows":[["立即寻址","指令中","0"],["寄存器寻址","寄存器","0"],["直接寻址","主存","1"],["间接寻址","主存(二次)","2"],["寄存器间接","主存","1"]]},{"t":"dv","title":"推导：各种寻址方式的有效地址公式与访存次数","steps":["<b>有效地址 EA</b>＝操作数所在主存单元的地址。判断寻址方式，本质上就是问两件事：EA 怎么算？操作数在哪？","立即寻址：操作数就在指令里，<b>没有 EA</b>，取操作数访存 <b>0</b> 次","直接寻址：EA = A（形式地址即有效地址），访存 <b>1</b> 次","间接寻址：EA = (A)，先读出 A 单元的内容当地址，再按该地址取数 → 访存 <b>2</b> 次","寄存器寻址：操作数在寄存器，访存 <b>0</b> 次；寄存器间接：EA = (R)，访存 <b>1</b> 次","<b>变址</b>：EA = (IX) + A —— 用户改 IX，适合<b>数组/循环</b>（A 是数组首址常量，IX 是下标）","<b>基址</b>：EA = (BR) + A —— 系统改 BR，适合<b>程序重定位、多道程序</b>（A 是段内偏移常量）","<b>相对</b>：EA = (PC) + A —— A 是补码偏移，PC 取<b>已更新</b>（取下一条指令后的值），适合转移指令","变址、基址、相对三者算式形态相同，差别在“基准寄存器是谁、谁去改它”——变址面向数组，基址面向重定位，相对面向转移","易错：相对寻址中 PC 的值是「本指令地址 + 指令字节数」，不是本指令地址；偏移为负时要<b>符号扩展后</b>再相加"]},{"t":"ex","q":"【例题】某机指令长 2 字节，存于 1000H，形式地址 A = 0020H（补码）。IX = 0100H，BR = 0200H。求变址、基址、相对三种寻址的 EA；若改用间接寻址，访存几次？","steps":["变址：EA = (IX) + A = 0100H + 0020H = <b>0120H</b>","基址：EA = (BR) + A = 0200H + 0020H = <b>0220H</b>",{"s":"相对：先更新 PC = 1000H + 2 = 1002H，再 EA = 1002H + 0020H = <b>1022H</b>","note":"PC 用“下一条指令”的地址，这是最高频失分点"},"若 A 为负偏移（如 FFE0H = −0020H），则 EA = 1002H − 0020H = 0FE2H，偏移量须按补码符号扩展后再加","间接寻址：先访存取 A 单元内容作为新地址，再按新地址取操作数 → 访存 <b>2 次</b>（直接寻址仅 1 次）","检验：三者共用同一形式地址 A，结果差异全部来自“基准寄存器是 IX / BR / PC”"]},{"t":"sh","no":"7.6","title":"指令格式举例"},{"t":"tx","h":"指令举例","p":"不同机器指令格式不同：定长如 RISC(每条等长，译码简单)，变长如 x86(灵活但译码复杂)。一地址指令常用于单操作数(如自增)，二地址最常见(结果存目的地址)。"},{"t":"sh","no":"7.7","title":"RISC 技术"},{"t":"tx","h":"RISC vs CISC","p":"<b>RISC</b>(精简指令集)：指令少而规整、定长、寻址方式少、多寄存器、大量使用流水线；<b>CISC</b>(复杂指令集)：指令多而复杂、变长、寻址方式多。RISC 利于流水线与编译优化。"},
{"t":"ex","q":"【典型例题】某指令字长 16 位，操作码 4 位、地址码 4 位、采用一地址格式。求可表示指令数与寻址范围。","steps":["操作码 4 位 → 最多 2⁴ = 16 条指令","地址码 4 位 → 可寻址 2⁴ = 16 个存储单元","若用三地址则需 4×3=12 位地址 + 4 位操作码 = 16 位刚好","要点：操作码位数与地址码位数此消彼长，需权衡。"]},{"t":"warn","text":"<b>易错点：</b>① 间接寻址访存次数是 2；② 变址(面向数组、内容可变)与基址(面向重定位)不同；③ 扩展操作码必须保证前缀不冲突；④ 相对寻址偏移相对“当前 PC”(已自增)。"},{"t":"sh","no":"7.8","title":"指令格式设计（从需求反推字段位数）"},{"t":"tx","h":"设计题的固定四步","p":"格式设计题给的都是“需要多少条指令、几种寻址、多大主存”，要求反推各字段位数。固定套路：<b>① 操作码位数 = ⌈log₂指令条数⌉；② 寻址特征位数 = ⌈log₂寻址方式数⌉；③ 地址码位数由主存容量定；④ 各字段相加得指令字长</b>。"},{"t":"dv","title":"推导：某机设计题完整算一遍","steps":["需求：<b>128 条指令</b>、<b>4 种寻址方式</b>、主存容量 <b>64K 字</b>、采用一地址格式","① 操作码位数：2⁷ = 128 → <b>7 位</b>（刚好，无冗余）","② 寻址特征位数：⌈log₂4⌉ = <b>2 位</b>","③ 地址码位数：64K = 2¹⁶ → <b>16 位</b>","④ 指令字长 = 7 + 2 + 16 = <b>25 位</b>（若要求按字节对齐，取 32 位，余 7 位可扩展操作码）","若改为二地址：需两个地址码和两个寻址特征 → 7 + 2×2 + 2×16 = <b>43 位</b>","要点：每个地址都要配一个寻址特征位；除不尽的操作码要说明余下编码的用途（如扩展操作码或非法指令）"]},{"t":"ex","q":"【例题】某机需 200 条指令、6 种寻址方式、主存 1M 字，采二地址格式。求各字段位数与指令字长。","steps":["操作码：2⁷ = 128 < 200 ≤ 256 = 2⁸ → <b>8 位</b>（余 56 个编码可用于扩展）","寻址特征：2² = 4 < 6 ≤ 8 = 2³ → <b>3 位</b>","地址码：1M = 2²⁰ → <b>20 位</b>","指令字长 = 8 + 2×(3 + 20) = 8 + 46 = <b>54 位</b>","若要求字长为 8 的整数倍 → 取 56 位，余 2 位作扩展或对齐填充"]},{"t":"sh","no":"7.9","title":"主流指令集：ARM / x86 / RISC-V / MIPS / 国产 CPU"},{"t":"tb","head":["指令集","类型","指令长度","特点与代表"],"rows":[["ARM","RISC","定长 32 位（Thumb 16 位）","授权模式，移动/嵌入式霸主，低功耗"],["x86 / x86-64","CISC","变长 1~15 字节","PC 服务器主流，向后兼容，指令复杂"],["RISC-V","RISC","定长基础 + 可选扩展","开源免费，模块化（I/M/A/F/D），教学与新兴芯片热门"],["MIPS","RISC","定长 32 位","经典教材机型，规整五级流水，嵌入式曾广泛使用"],["龙芯 LoongArch","RISC","定长","自主指令集，已脱离 MIPS 授权"],["飞腾 / 鲲鹏","ARM 授权","定长","服务器 CPU，ARM 生态国产化"],["申威","RISC（Alpha 演化）","定长","超算用，神威·太湖之光"]]},{"t":"tx","h":"RISC 与 CISC 的分界为什么重要","p":"RISC 靠<b>定长指令、少寻址方式、大量寄存器、load/store 架构</b>把每条指令做快，适合流水线；CISC 靠<b>变长指令、丰富寻址、一条指令做多件事</b>减少指令条数。现代 x86 内部把 CISC 指令译成类 RISC 微操作再流水执行，两者界限已模糊。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第7章习题）"},{"t":"pt","no":"题型1","name":"指令格式与地址码个数","feature":"分析指令格式，判断操作码/地址码位数，或扩展操作码。","method":"指令 = 操作码 + 地址码；扩展操作码利用地址码字段扩展操作码。","steps":["确定指令字长与地址码个数","操作码位数、地址码位数分配","定长操作码 vs 扩展操作码","扩展时注意保留码点避免冲突"],"ex":{"q":"指令字长 16 位，三地址指令每地址 4 位，操作码几位？","steps":["3 个地址共 3×4 = 12 位","操作码 = 16 − 12 = 4 位","可表示 2⁴ = 16 种三地址指令","余下码点可用于扩展二地址等。"]},"pit":"扩展操作码要在剩余编码空间中扩展，别与其他类型冲突。"},{"t":"pt","no":"题型2","name":"寻址方式判断与有效地址计算","feature":"给出寻址方式，求操作数有效地址 EA。","method":"立即、直接、间接、寄存器、变址、相对、基址各有 EA 公式。",
"steps":["识别寻址方式","套用 EA 公式：直接 EA=形式地址A；间接 EA=(A)；变址 EA=A+IX；相对 EA=A+PC","注意二次间址","读操作数再取内容"],"ex":{"q":"相对寻址，形式地址 A = 20，当前 PC = 100，求有效地址。","steps":["相对寻址 EA = A + PC","= 20 + 100","= 120","相对寻址利于程序浮动。"]},"pit":"间接寻址要取一次内容；相对寻址用 PC（可能 +1 已自增）。"},{"t":"pt","no":"题型3","name":"指令周期与数据通路","feature":"描述取指/执行周期或数据流。","method":"取指→译码→执行→访存→写回；操作数地址由寻址方式确定。","steps":["取指：PC→MAR→主存→MDR→IR","译码：IR 送控制器","执行：按操作码运算","访存/写回：结果送回寄存器或主存"],"ex":{"q":"取指令阶段，指令地址来自哪个寄存器？","steps":["指令地址存放在 PC","PC → MAR → 读主存","取出经 MDR → IR","故来自 PC（程序计数器）。"]},"pit":"取指用 PC，执行数据地址由寻址方式算。"},{"t":"pt","no":"题型4","name":"RISC 与 CISC 比较","feature":"判断某特征属于 RISC 还是 CISC。","method":"RISC：指令少定长、单周期为主、多寄存器、硬布线；CISC：指令多不定长、微程序、复杂。","steps":["看指令数量与长度","看控制方式（硬布线 vs 微程序）","看寻址方式多少","RISC 利于流水线"],"ex":{"q":"指令长度固定、寻址方式少、多通用寄存器，属于哪种？","steps":["定长、寻址少、多寄存器","符合 RISC 特征","利于流水与编译优化","答案：RISC。"]},"pit":"CISC 也能流水，但 RISC 更适；别把“复杂指令”当 RISC。"},{"t":"pt","no":"题型5","name":"微程序控制与微指令","feature":"涉及微命令、微指令、微程序、控制存储器。","method":"一条机器指令 = 一段微程序；微指令编码分水平型/垂直型。","steps":["区分机器指令与微指令层次","微程序存于控制存储器 CM","编码方式：直接编码、字段直接/间接编码","水平型并行强、垂直型串行"],"ex":{"q":"微程序存放在（　）中。","steps":["微程序由微指令组成","存放于控制存储器 CM","CM 通常用 ROM","答案：控制存储器。"]},"pit":"微程序≠用户程序；CM 是控制器内部存储器。"},{"t":"pt","no":"题型6","name":"指令流水与加速比计算","feature":"计算流水线完成 n 条指令的时间或加速比。","method":"k 段流水，理想加速比 = k（段数），完成 n 条指令时间 = (k + n − 1)Δt。","steps":["确定段数 k 与时钟 Δt","顺序执行时间 = n·k·Δt","流水时间 = (k + n − 1)·Δt","加速比 = 顺序/流水"],"ex":{"q":"5 段流水线，每段 1ns，执行 100 条指令需多少时间？","steps":["理想流水时间 = (k + n − 1)·Δt","= (5 + 100 − 1)×1ns","= 104 ns","顺序则需 500ns，加速比≈4.8。"]},"pit":"流水时间用 k+n−1；有冒险时会插入气泡，效率下降。"},{"t":"tip","text":"<b>第7章解题总流程：</b>①格式题先分配操作码/地址码位数，扩展注意码点；②寻址题套 EA 公式（间接再取内容）；③数据通路题按“取指→执行”；④RISC/CISC 看定长/寻址/控制方式；⑤流水题记 k+n−1 与加速比。"},{"t":"kw","items":["操作码+地址码","扩展操作码","寻址方式","立即/直接/间接","基址变址","RISC/CISC"]}]},"g8":{"no":"8","title":"CPU 的结构和功能","tag":"第3篇 · 第8章","sub":"课本第8章。CPU = 运算器 + 控制器；指令周期与流水线是量化性能的主战场，中断系统是整机响应的关键。","blocks":[{"t":"sh","no":"8.1","title":"CPU 的结构"},{"t":"tx","h":"CPU 的两大部分","p":"CPU 由<b>运算器</b>和<b>控制器</b>组成：运算器负责“算”（算术/逻辑运算、加工数据），控制器负责“指挥”（取指、译码、发控制信号）。二者通过内部总线与寄存器组协作。"},{"t":"fig","kind":"fig-cpu-struct","cap":"CPU 内部结构：运算器（ACC/MQ/X）+ 控制器（PC/IR/ID）+ 与主存交换用的 MAR/MDR"},{"t":"tb","head":["寄存器","作用"],"rows":[["PC 程序计数器","存放<b>下一条</b>要执行指令的地址，取指后自动 +1"],["IR 指令寄存器","存放当前正在执行的指令；一经取出，内容基本不变"],["MAR 地址寄存器","存放欲访问的主存单元地址，是 CPU→主存的地址窗口"],["MDR 数据寄存器","存放与主存交换的数据/指令，是双向数据窗口"],
["ACC / MQ / X","运算器的累加器、乘商寄存器、操作数寄存器"],["PSW 状态字","存放结果标志（进位、溢出、零、符号等）"]]},{"t":"warn","text":"<b>易错点：</b>① PC 指向“下一条”指令，不是当前；② IR 在取指周期末才有效，间址/执行周期不改变 IR；③ MAR/MDR 是 CPU 内的寄存器，但直接连到主存，别和 Cache 混淆。"},{"t":"sh","no":"8.2","title":"指令周期"},{"t":"tx","h":"指令周期与机器周期","p":"<b>指令周期</b>＝取出并执行一条指令所需的全部时间，由若干<b>机器周期</b>（CPU 周期）组成。CPU 周期又由若干<b>时钟周期</b>（节拍）构成。四个阶段：<b>取指 → 间址 → 执行 → 中断</b>，其中取指、执行必有，间址、中断按需出现。"},{"t":"fig","kind":"fig-instr-cycle","cap":"指令周期的四个阶段：取指（必做）→ 间址（可选）→ 执行（必做）→ 中断（可选）"},{"t":"tb","head":["周期","主要操作"],"rows":[["取指周期","PC→MAR→主存→MDR→IR；(PC)+1"],["间址周期","取出操作数的有效地址（间接寻址才需要）"],["执行周期","按操作码完成运算或数据传送"],["中断周期","保存断点(PC)、送中断服务程序入口"]]},{"t":"sh","no":"8.3","title":"数据通路"},{"t":"tx","h":"数据通路是什么","p":"<b>数据通路</b>是 CPU 内部传送数据、进行运算的路径集合，由 ALU、寄存器、总线与多路选择器组成。控制器只负责“发命令”，真正搬数据、算结果的是数据通路。按内部总线数量分为<b>单总线</b>与<b>多总线</b>。"},{"t":"tb","head":["结构","一次能传几个数据","优点","缺点"],"rows":[["单总线","1 个（分时使用）","结构简单、成本低","一个周期只能传一次，指令需多个周期"],["双总线","2 个","可同时取两个操作数","ALU 需两个输入端直接连总线"],["三总线","3 个（两入一出）","一个周期完成一次运算并写回","总线多、成本高"],["专用通路","按需多条","速度最快","硬件最复杂"]]},{"t":"dv","title":"推导：单总线结构执行 ADD 需要几个周期","steps":["单总线同一时刻只能有一个数据在总线上流动，所以每个微操作占一个周期","① R0 → A（操作数 1 送暂存器 A）","② R1 → B（操作数 2 送暂存器 B），同时 A、B 已就位","③ A + B → R2（ALU 运算结果写回 R2）","共需 <b>3 个周期</b>；若用三总线，两个操作数和结果各有独立通路 → <b>1 个周期</b>完成","这就是“用总线数量换速度”的典型权衡，也是流水线设计要先加宽数据通路的原因"]},{"t":"sh","no":"8.4","title":"指令流水"},{"t":"tx","h":"流水线的基本概念","p":"把指令执行拆成若干<b>段</b>（如取指/译码/执行/写回），让不同指令的不同段<b>并行</b>工作，就像工厂流水线。理想情况下每个时钟周期完成一条指令。"},{"t":"fx","lines":["流水线时间：n 条指令、k 段流水，T = (k + n − 1)·Δt（Δt 为一个节拍）","吞吐率 TP = n / T ≈ 1/Δt（充满后每拍一条）","加速比 S = 串行时间 / 流水时间 ≈ k（理想上限）","效率 E = 有效面积 / 总面积 → 段数越多、越接近满流水越高"]},{"t":"fig","kind":"fig-pipeline","cap":"四段流水时空图：装入 n+k−1 拍完成 n 条指令（含装入/排空）"},{"t":"ex","q":"【例题】某指令流水线分 4 段，每段时间均为 Δt。连续执行 100 条指令，求完成时间、吞吐率与加速比。","steps":["完成时间 T = (k + n − 1)·Δt = (4 + 100 − 1)·Δt = 103Δt","吞吐率 TP = n / T = 100 / (103Δt) ≈ 0.97 / Δt（接近理想 1/Δt）","串行时间 = 100 × 4Δt = 400Δt","加速比 S = 400Δt / 103Δt ≈ 3.88（接近段数 4）","结论：段数 k 越多理论加速比越大，但受装入/排空与段间锁存影响，实际略低于 k。"]},{"t":"sh","no":"8.5","title":"流水线的性能指标（吞吐率 / 加速比 / 效率）"},{"t":"tx","h":"三个指标的定义与关系","p":"设流水线 <b>k 段</b>、每段用时 Δt、连续执行 <b>n</b> 条指令：完成全部任务用时 <b>T = (k + n − 1)Δt</b>。由此三指标：<b>吞吐率 TP = n / T</b>；<b>加速比 S = 顺序执行时间 / 流水执行时间 = n·k·Δt / T</b>；<b>效率 E = 有效时空区 / 总时空区 = S / k</b>。"},{"t":"dv","title":"推导：k=5、Δt=10ns、n=100 的三项指标","steps":["① 总时间 T = (k + n − 1)·Δt = (5 + 100 − 1) × 10 ns = 104 × 10 = <b>1040 ns</b>",
"② 吞吐率 TP = n / T = 100 ÷ 1040 ns ≈ <b>0.0962 条/ns</b> ≈ 96.2 MIPS","③ 顺序执行需 n·k·Δt = 100 × 5 × 10 = <b>5000 ns</b>","④ 加速比 S = 5000 ÷ 1040 ≈ <b>4.81</b>（理论上限 = k = 5，因填充与排空损失未达到）","⑤ 效率 E = S / k = 4.81 ÷ 5 ≈ <b>96.2%</b>","⑥ n → ∞ 时极限：TP<sub>max</sub> = 1/Δt，S<sub>max</sub> = k，E<sub>max</sub> = 1","要点：k 固定时 n 越大效率越高；n=1 时加速比只有 1（完全没有并行收益）"]},{"t":"ex","q":"【例题】某 4 段流水线，各段用时均为 20 ns，连续执行 20 条指令。求总时间、吞吐率、加速比与效率。","steps":["T = (4 + 20 − 1) × 20 = 23 × 20 = <b>460 ns</b>","TP = 20 ÷ 460 ≈ <b>0.0435 条/ns</b> ≈ 43.5 MIPS","顺序时间 = 20 × 4 × 20 = <b>1600 ns</b>","S = 1600 ÷ 460 ≈ <b>3.48</b>","E = 3.48 ÷ 4 ≈ <b>87%</b>","若各段用时不等（如 10/20/20/10 ns），则 Δt 取最大段 = 20 ns，慢段成为瓶颈，其余段空等"]},{"t":"sh","no":"8.6","title":"流水线相关与多发技术"},{"t":"tb","head":["相关类型","产生原因","典型解决办法"],"rows":[["结构相关（资源冲突）","多条指令争用同一部件，如同时访存","停顿、增设指令/数据分离 Cache、加部件"],["数据相关（RAW 为主）","后条指令要用前条尚未写回的结果","转发/旁路（forwarding）、停顿、编译调度"],["控制相关","转移指令改变 PC，后续已取指令作废","延迟转移、分支预测、预取两个方向"]]},{"t":"tb","head":["多发技术","做法","效果"],"rows":[["超标量（Superscalar）","片内多条流水线，一个周期发射多条指令","CPI < 1，靠硬件调度"],["超流水线（Superpipelining）","把段再细分，提高时钟频率","段数增多，单条延迟变大"],["超长指令字（VLIW）","编译时把多个操作打包进一条长指令","靠编译器静态调度，硬件简单"]]},{"t":"tx","h":"三种多发技术的区分要点","p":"<b>超标量</b>是“同一时刻并行执行多条指令”（空间并行）；<b>超流水线</b>是“把一条指令切得更细、时钟更快”（时间并行）；<b>VLIW</b>是“由编译器把并行性预先编进一条超长指令”。考试常问“哪个靠编译器”——答案是 VLIW。"},{"t":"warn","text":"<b>易错点：</b>① 流水线加速比上限是 k（段数），不是 n；② Δt 取<b>最慢段</b>的时间，不是各段平均；③ 数据相关最常见的是 RAW（先写后读），WAR/WAW 只在乱序执行中出现；④ 超标量靠硬件、VLIW 靠编译器，别弄反。"},{"t":"sh","no":"8.7","title":"中断系统"},{"t":"tx","h":"中断请求与判优","p":"中断＝CPU 暂停当前程序、转去处理更紧急事件。按来源分<b>内中断（异常）</b>与<b>外中断</b>；多中断源同时请求时由<b>中断判优</b>（硬件排队器或软件顺序）选出最高优先级者。"},{"t":"tb","head":["类别","触发源","例子"],"rows":[["外中断（中断）","CPU 外部事件","I/O 请求、键盘、定时器、外部故障"],["内中断（异常）","指令执行内部","除数为 0、溢出、访存缺页、非法指令、软件中断"]]},{"t":"tx","h":"中断响应与处理","p":"响应中断的三个条件：当前指令<b>执行完</b>、当前<b>无更高级中断</b>在处理、开中断。进入中断由<b>中断隐指令</b>自动完成：关中断 → 保存断点(PC) → 取中断服务程序入口。"},{"t":"ex","q":"【例题】简述单级中断系统中，中断服务程序内的执行顺序。","steps":["① 保护现场（保存通用寄存器、PSW）","② 执行中断服务程序（处理具体事件）","③ 恢复现场（还原寄存器与 PSW）","④ 开中断","⑤ 中断返回（由 IRET 指令恢复断点 PC）","注意：进入中断前由“中断隐指令”已完成 关中断→保存断点→取服务程序入口。"]},{"t":"warn","text":"<b>易错点：</b>① 中断隐指令是硬件自动完成的，不由程序设计；② 保存断点(PC)属“中断隐指令”，保护现场属“服务程序”；③ 单级中断不进新中断，多级中断允许中断嵌套；④ 中断判优解决“谁先响应”，优先级高者先处理。"},{"t":"sh","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第8章习题）"},{"t":"pt","no":"题型1","name":"指令周期的划分与微操作","feature":"给出指令或周期名称，判断各机器周期应完成的微操作。","method":"取指必做、执行必做；间接寻址多一个间址周期；中断请求在指令末尾检查。",
"steps":["先判断是否含间址寻址（决定有无间址周期）","取指周期固定：PC→MAR→主存→MDR→IR","执行周期看操作码","末尾若有中断请求再加中断周期"],"ex":{"q":"判断：间接寻址指令的指令周期一定比直接寻址指令多一个间址周期。","steps":["间接寻址需先访存取有效地址，故多一个间址周期","直接寻址不需要","故说法正确（就周期组成而言）"]},"pit":"别把“间址周期”与“执行周期”混为一谈。"},{"t":"pt","no":"题型2","name":"流水线性能计算","feature":"给定段数、条数、每段时间，求时间/吞吐率/加速比。","method":"套公式 T=(k+n−1)Δt；TP=n/T；S=串行/T。","steps":["列段数 k、指令数 n、节拍 Δt","串行时间 = n·k·Δt（或 n·Δt×段数）","流水时间 = (k+n−1)Δt","加速度比 S = 串行/流水，吞吐率 TP = n/T"],"ex":{"q":"4 段流水、每段 Δt，执行 50 条指令，求 T 与 TP。","steps":["T=(4+50−1)Δt=53Δt","TP=50/(53Δt)≈0.943/Δt"]},"pit":"k 是段数不是指令数；装入排空的 (k−1) 拍别忘了。"},{"t":"pt","no":"题型3","name":"中断系统分析与判优","feature":"判断某事件属内/外中断，或按优先级写出处理顺序、屏蔽字。","method":"外中断来自 CPU 外部，内中断来自指令执行；判优先看优先级高低。","steps":["区分事件来源（内/外）","响应条件：指令结束 + 无更高级在处理 + 开中断","隐指令：关中断→保存断点→取入口","服务程序：保护现场→服务→恢复现场→开中断→返回"],"ex":{"q":"判断：除数为 0 引起的是外中断。","steps":["除数为 0 由指令执行产生","属内中断（异常）","故说法错误"]},"pit":"中断屏蔽字决定哪些源被屏蔽，用于改变优先级。"},{"t":"tip","text":"<b>第8章解题总流程：</b>①周期题先判断有无间址/中断阶段；②流水题背熟 T=(k+n−1)Δt；③中断题记住“隐指令三步 + 服务程序五步”与内/外之分。"},{"t":"kw","items":["CPU结构","PC","IR","MAR","MDR","指令周期","机器周期","流水线","吞吐率","加速比","内中断","外中断","中断判优","中断隐指令"]}]},"g9":{"no":"9","title":"控制单元的功能","tag":"第3篇 · 第9章","sub":"课本第9章。控制单元按机器周期发出微操作命令；同步/异步/联合三种控制方式决定了时序松紧。","blocks":[{"t":"sh","no":"9.1","title":"微操作命令的分析"},{"t":"tx","h":"微操作与微命令","p":"一条指令分解到每个机器周期，就是一组按序发出的<b>微操作命令</b>（控制信号）。如取指周期要发“PC→MAR”“读主存”“MDR→IR”“(PC)+1”等。控制单元的作用就是<b>按时间顺序、按机器周期</b>产生这些微命令。"},{"t":"tb","head":["周期","典型微操作序列"],"rows":[["取指周期","(PC)→MAR → 读主存 → (MDR)→IR → (PC)+1"],["间址周期","(IR 形式地址)→MAR → 读主存 → (MDR)→IR 地址段"],["执行周期","随指令而定，如 ADD：(ACC)+X→ACC，并置标志位"],["中断周期","(PC)→MDR → 写主存 → 置“0”中断标志 → 服务程序入口→PC"]]},{"t":"sh","no":"9.2","title":"控制单元的功能"},{"t":"tx","h":"控制单元的外特性","p":"控制单元是“时序信号 + 控制信号”的发生器：输入有<b>时钟</b>、<b>指令寄存器 IR</b>、<b>标志</b>、<b>外来信号</b>；输出为各种<b>微操作控制信号</b>（送运算器、存储器、I/O 与寄存器）。"},{"t":"tb","head":["控制方式","特点","适用"],"rows":[["同步控制","所有微操作由统一时钟节拍同步，电路简单","速度差异小的机器"],["异步控制","各部件按自身应答异步工作，无统一时钟","速度差异大的机器，效率高但电路复杂"],["联合控制","同步与异步结合，大多数操作同步、少数异步","现代计算机常用"]]},{"t":"warn","text":"<b>易错点：</b>① 同步控制的“节拍”由最慢微操作决定；② 异步控制靠应答（握手）而非时钟；③ 判优与定时是两回事：判优先谁响应，定时定何时做。"},{"t":"sh","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第9章习题）"},{"t":"ex","q":"【例题】写出 LDA X（直接寻址，把存储单元 X 的内容取到累加器 ACC）在取指周期与执行周期的微操作序列。","steps":[{"s":"取指周期：PC→MAR","note":"送指令地址"},{"s":"1→R（发读命令）；M(MAR)→MDR；MDR→IR","note":"读出指令"},{"s":"OP(IR)→CU 译码；(PC)+1→PC","note":"译码与 PC 自增"},{"s":"执行周期：Ad(IR)→MAR；1→R",
"note":"地址码部分送 MAR"},{"s":"M(MAR)→MDR；MDR→ACC","note":"取出操作数送入累加器"},{"s":"要点：取指序列所有指令相同；执行周期随操作码与寻址方式不同——考试按这个模板套"}]},{"t":"pt","no":"题型1","name":"微操作序列分析","feature":"给定指令与寻址，写出对应机器周期的微操作。","method":"按“取指→间址→执行→中断”逐周期展开，注意数据通路走向。","steps":["确定有无间址（间接寻址才写间址周期）","取指周期序列固定","执行周期按操作码与寻址方式写数据通路","中断周期写保存断点与取入口"],"ex":{"q":"写出“ADD (R0), R1”间接寻址加法指令在取指与间址周期的微操作。","steps":["取指：(PC)→MAR → 读主存 → (MDR)→IR → (PC)+1","间址：(IR 的 R0 地址段)→MAR → 读主存 → (MDR)→ 有效地址","执行：按有效地址取操作数并与 R1 相加"]},"pit":"间址周期把“形式地址”换成“有效地址”。"},{"t":"pt","no":"题型2","name":"控制方式判断","feature":"给定机器特征，判断采用同步/异步/联合控制。","method":"统一时钟→同步；应答握手→异步；两者结合→联合。","steps":["看是否有统一时钟节拍","看部件间是否靠应答同步","对应到三种控制方式之一"],"ex":{"q":"现代计算机各部件速度差异大，通常采用哪种控制方式？","steps":["速度差异大不适合纯同步（受最慢部件拖累）","纯异步电路复杂","故多采用联合控制"]},"pit":"同步≠效率最高；异步≠一定快。"},{"t":"tip","text":"<b>第9章解题总流程：</b>①微操作题按机器周期逐条写数据通路；②控制方式题抓“统一时钟/应答/结合”三关键词。"},{"t":"kw","items":["微操作","微命令","控制单元","外特性","同步控制","异步控制","联合控制","时序"]}]},"g10":{"no":"10","title":"控制单元的设计","tag":"第3篇 · 第10章","sub":"课本第10章。控制单元两种实现：组合逻辑（硬布线）与微程序。前者快、难改；后者规整、易扩展。","blocks":[{"t":"sh","no":"10.1","title":"组合逻辑设计"},{"t":"tx","h":"组合逻辑（硬布线）设计步骤","p":"用门电路直接实现控制信号，称<b>组合逻辑设计</b>（硬布线控制器）。步骤：① 列出微操作命令表；② 写出每个微命令的<b>逻辑表达式</b>（由指令、周期、节拍、标志构成）；③ 用门电路化简实现。优点是<b>速度快</b>，缺点是设计复杂、一旦成型难以修改。"},{"t":"ex","q":"【例题】若某微命令 M 在“取指周期的 T₁ 节拍”或“执行 ADD 指令的 T₃ 节拍”发出，写出其逻辑表达式。","steps":["用“周期·节拍·指令”相乘表示条件","取指阶段：FE · T₁","执行 ADD：ADD · T₃","相或（+ 表示逻辑或）：M = FE·T₁ + ADD·T₃","这就是硬布线控制信号的标准写法：若干“与项”之或。"]},{"t":"warn","text":"<b>易错点：</b>硬布线控制信号 = 若干“周期·节拍·指令/标志”的<b>与项</b>再相<b>或</b>；别把“与/或”写反。"},{"t":"sh","no":"10.2","title":"微程序设计"},{"t":"tx","h":"微程序控制的基本思想","p":"把每条机器指令对应的控制信号序列“写成程序”存入<b>控制存储器 CM</b>，运行时逐条取出执行——这就是<b>微程序控制</b>。一条机器指令 ⇔ 一段微程序（若干条微指令）；一条微指令 ⇔ 若干同时执行的微命令。规整、易修改、易扩充，但比硬布线慢。"},{"t":"fig","kind":"fig-microprog","cap":"微程序控制器结构：控制存储器 CM → 微指令寄存器 → 微命令"},{"t":"tb","head":["微指令编码方式","含义","优缺点"],"rows":[["直接编码（水平）","每一位直接对应一个微命令","快、微指令长"],["字段直接编码","按互斥分组，每组译码产生微命令","折中、常用"],["字段间接编码","一组微命令需另一字段译码","更省位、更慢"],["最短编码（垂直）","逐位译码，极省位","最省位、最慢、需多次"]]},{"t":"tx","h":"微指令格式与微地址","p":"微指令分<b>操作控制字段</b>（发微命令）与<b>顺序控制字段</b>（决定下一条微指令地址）。下地址由<b>微地址形成部件</b>产生：顺序执行加 1，或在转移、按指令操作码映射时改变。"},{"t":"warn","text":"<b>易错点：</b>① 微程序存于 CM（在 CPU 内），机器程序存于主存，二者别混；② 一条机器指令对应一段微程序，不是一条微指令；③ 水平型微指令并行能力强、执行快但字长；垂直型相反。"},{"t":"sh","no":"10.3","title":"微指令的格式与编码方式"},{"t":"tx","h":"微指令的两个字段","p":"一条微指令（控制字）通常分两段：<b>操作控制字段</b>——本周期要发哪些微命令；<b>顺序控制字段</b>——下一条微指令的地址，或如何产生它。前者怎么编码，直接决定控存的字长与译码速度。"},
{"t":"tb","head":["编码方式","做法","优点","缺点"],"rows":[["直接编码（不编码）","一位对应一个微命令，置 1 即发出","最快，无需译码器","位数最多，控存字长膨胀"],["字段直接编码","微命令分组，每组用译码器选出一个","位数大幅减少","需译码延迟；每组须留一个“不操作”码"],["字段间接编码","字段含义由另一字段解释","位数进一步减少","控制复杂，速度最慢"],["最短编码（混合）","常用命令直接给位，其余分组编码","折中","设计复杂"]]},{"t":"dv","title":"算一算：字段直接编码能省多少位","steps":["设某机共有 <b>40 个微命令</b>。若直接编码，操作控制字段需 <b>40 位</b>","把互斥的微命令分成 5 组，每组最多 10 个（同一时刻每组最多发一个）","每组所需位数 = ⌈log₂(10 + 1)⌉ = ⌈log₂11⌉ = <b>4 位</b>（\"+1\" 是“本组不操作”状态）","5 组共 5 × 4 = <b>20 位</b>，比直接编码的 40 位<b>省一半</b>","若某组只有 3 个微命令 → ⌈log₂(3+1)⌉ = 2 位；分组越细、每组命令越少，总位宽越小，但译码器越多","注意：分组必须“互斥”——同一时刻不会同时发出的一组才能合并编码，否则会丢命令"]},{"t":"ex","q":"【例题】某微指令有 4 个互斥字段，分别含 3、5、2、4 个微命令，采用字段直接编码（每字段留一个“不操作”码）。求操作控制字段最少多少位？若改用直接编码需多少位？","steps":["字段直接编码：每字段位数 = ⌈log₂(nᵢ + 1)⌉，<b>+1 是留给「不操作」</b>的码字","字段 1（3 个命令）：⌈log₂4⌉ = <b>2 位</b>","字段 2（5 个命令）：⌈log₂6⌉ = ⌈2.58⌉ = <b>3 位</b>","字段 3（2 个命令）：⌈log₂3⌉ = ⌈1.58⌉ = <b>2 位</b>","字段 4（4 个命令）：⌈log₂5⌉ = ⌈2.32⌉ = <b>3 位</b>","合计 = 2 + 3 + 2 + 3 = <b>10 位</b>",{"s":"直接编码（水平型一位一命令）= 3 + 5 + 2 + 4 = <b>14 位</b>","note":"直接编码最快、最宽、无需译码"},"结论：字段直接编码省 4 位，代价是需译码器、并行性略降；实际机器常用混合字段编码折中",{"s":"易错：漏掉“不操作”码就会算成 log₂n —— n = 5 时得 2 位（错），正确须 3 位","note":"统一按 log₂(n+1) 向上取整最稳"}]},{"t":"tx","h":"水平型与垂直型微指令","p":"<b>水平型</b>：一次可并行发出多个微命令，字长长、执行周期短、微程序短，编写难；<b>垂直型</b>：类似机器指令，一次只做一件事，字短、易编写，但微程序长、速度慢。模型机实验多用水平型。"},{"t":"sh","no":"10.4","title":"微地址的形成方式"},{"t":"tb","head":["方式","下地址怎么来","说明"],"rows":[["计数器法","μPC + 1","微指令顺序存放、按序执行；遇转移再改写 μPC"],["断定法（下地址字段法）","微指令中直接给出后继地址","每条自带下地址，灵活但字长增加"],["操作码映射法","机器指令操作码 → 微程序入口地址","取指后由 IR 操作码经映射得到微程序首址"],["多路选择法","以上几种混合，用选择器切换","实际控制器常用：顺序用计数，分支用下地址字段"]]},{"t":"tx","h":"微指令周期与 CPU 周期的关系","p":"<b>微指令周期 = 读出微指令的时间 + 执行该微指令的时间</b>。为保证整机控制信号同步，通常把微指令周期设计成恰好等于一个 CPU 周期，这样“一条微指令 = 一个节拍”整齐对应。"},{"t":"warn","text":"<b>易错点：</b>① 字段直接编码每组要留“不操作”码，所以是 log₂(n+1) 而不是 log₂n；② 直接编码最快但最宽，别把“快”和“省”弄反；③ 微地址形成与机器指令地址形成是两套独立机制，别混。"},{"t":"sh","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第10章习题）"},{"t":"pt","no":"题型1","name":"微程序基本概念辨析","feature":"判断微指令/微程序/机器指令/CM 等概念的关系。","method":"机器指令“宏”，一段微程序“细”；微指令发一组微命令。","steps":["机器指令 → 对应一段微程序","微程序 → 由若干微指令组成","微指令 → 发出若干同时执行的微命令"],"ex":{"q":"判断：一条微指令对应一条机器指令。","steps":["一条机器指令对应“一段微程序”","一段微程序含多条微指令","故一条微指令≠一条机器指令，说法错误"]},"pit":"“机器指令 ↔ 一段微程序”“微指令 ↔ 一组微命令”，两句话要记牢。"},{"t":"pt","no":"题型2","name":"编码方式与微指令数量","feature":"给定微命令数与分组，估算微指令操作控制字段位数。","method":"直接编码位数 = 微命令数；字段直接编码 = 各组所需位数之和。","steps":["直接编码：每位一个微命令，位数 = 微命令个数",
"字段直接编码：每组 n 个互斥信号需 ⌈log₂(n+1)⌉ 位","各组位数相加即操作控制字段长度"],"ex":{"q":"某机有 30 个微命令，若采用直接编码，操作控制字段至少多少位？","steps":["直接编码每位对应一个微命令","需 30 位","故操作控制字段至少 30 位"]},"pit":"字段直接编码每组要留一个“全 0=不发”状态，故是 log₂(n+1)。"},{"t":"tip","text":"<b>第10章解题总流程：</b>①概念题抓“机器指令—微程序—微指令”三级关系；②编码题先判直接/字段再算位数；③硬布线题把控制信号写成“与项之或”。"},{"t":"kw","items":["组合逻辑设计","硬布线","微程序","控制存储器","CM","微指令","微命令","直接编码","字段编码","微地址"]}]},"g11":{"no":"11","title":"期末模拟卷 · 重点题精练","tag":"题源 · 课程模拟试卷","sub":"题目直接取自课程「模拟试卷1 / 模拟试卷2」。凡计算与转换，均给出可复现的分步过程。","blocks":[{"t":"sh","no":"一","title":"填空题（计算与转换）"},{"t":"ex","q":"【模拟试卷2 · 第8题】在单级中断系统中，中断服务程序内的执行顺序是________。","steps":["① 保护现场（保存通用寄存器与 PSW）","② 执行中断服务程序","③ 恢复现场","④ 开中断","⑤ 中断返回","记忆链：保护现场 → 服务 → 恢复现场 → 开中断 → 返回。（进入中断前，硬件已用“中断隐指令”完成 关中断→保存断点→取入口）"]},{"t":"ex","q":"【模拟试卷2 · 第9题】浮点数格式：1 位阶符、6 位阶码、1 位数符、8 位尾数，写出该格式（只考虑正数值）能表示的范围（最小值、最大值）。","steps":["阶码：1 位阶符 + 6 位阶码 → 指数范围 −(2⁶−1) ~ +(2⁶−1)，即 −63 ~ +63","尾数：1 位数符(正为 0) + 8 位尾数 → 数值尾数 ∈ [2⁻⁸ , 1−2⁻⁸]","数值尾数最大 = 0.11111111₂ = 1 − 2⁻⁸","数值尾数最小（非零）= 0.00000001₂ = 2⁻⁸","最大值 = (1 − 2⁻⁸) × 2⁶³","最小值 = 2⁻⁸ × 2⁻⁶³ = 2⁻⁷¹","答：最小值 2⁻⁷¹，最大值 (1 − 2⁻⁸) × 2⁶³"]},{"t":"ex","q":"【模拟试卷2 · 第10题】主存容量 64KB，其中 ROM 区 4KB、其余为 RAM 区，按字节编址。用 2K×8 位 ROM 芯片和 4K×4 位 RAM 芯片设计该存储器，需 ROM 芯片____片、RAM 芯片____片。","steps":["ROM 区 = 4KB = 4096 字节；每片 2K×8 位 = 2048 字节","ROM 片数 = 4096 ÷ 2048 = 2 片","RAM 区 = 64KB − 4KB = 60KB = 60×1024 = 61440 字节","RAM 芯片为 4K×4 位：4K = 4096 个单元、每单元仅 4 位","要凑成“字节(8 位)宽”，需 2 片并联 → 一组 = 4096 字节","RAM 组数 = 61440 ÷ 4096 = 15 组","RAM 片数 = 15 组 × 2 片/组 = 30 片","答：ROM 2 片，RAM 30 片"]},{"t":"sh","no":"二","title":"选择题（概念辨析）"},{"t":"ex","q":"【模拟试卷2 · 第1题】下列关于 RISC 的叙述中，错误的是（　）。A. RISC 普遍采用微程序控制器　B. RISC 大多数指令在一个时钟周期内完成　C. RISC 内部通用寄存器数量相对 CISC 多　D. RISC 的指令数、寻址方式和指令格式种类相对 CISC 少","steps":["RISC 追求指令简单、定长、单周期，多用<b>硬布线（组合逻辑）</b>控制器，而非微程序","故 A 错误（这正是 RISC 与 CISC 的典型区别之一）","B、C、D 均为 RISC 的典型特征","答案：A"]},{"t":"ex","q":"【模拟试卷2 · 第2题】单处理机系统中，可并行的是（　）。Ⅰ 进程与进程　Ⅱ 处理机与设备　Ⅲ 处理机与通道　Ⅳ 设备与设备　A. Ⅰ、Ⅱ和Ⅲ　B. Ⅰ、Ⅱ和Ⅳ　C. Ⅰ、Ⅲ和Ⅳ　D. Ⅱ、Ⅲ和Ⅳ","steps":["单处理机同一时刻只有一个进程在 CPU 上运行，Ⅰ“进程与进程”不能真正并行","处理机运算与设备 I/O 可同时进行 → Ⅱ 可并行","处理机与通道（I/O 处理机）可并行工作 → Ⅲ 可并行","设备与设备之间也可各自独立工作 → Ⅳ 可并行","答案：D（Ⅱ、Ⅲ和Ⅳ）"]},{"t":"ex","q":"【模拟试卷2 · 第3题】下列选项中英文缩写均为总线标准的是（　）。A. PCI、CRT、USB、EISA　B. ISA、CPI、VESA、EISA　C. ISA、SCSI、RAM、MIPS　D. ISA、EISA、PCI、PCI-Express","steps":["逐项排查非总线标准的缩写：CRT(显示器)、CPI(性能指标)、SCSI(接口/设备)、RAM(存储器)、MIPS(性能单位)","A 含 CRT ✗；B 含 CPI ✗；C 含 RAM、MIPS ✗","D 中 ISA、EISA、PCI、PCI-Express 全部为总线标准 ✓",
"答案：D"]},{"t":"ex","q":"【模拟试卷2 · 第4题】下列选项中，能引起外部中断的事件是（　）。A. 键盘输入　B. 除数为 0　C. 浮点运算下溢　D. 访存缺页","steps":["外部中断来自 CPU 外部设备/事件的请求","B 除数为 0、C 浮点下溢、D 访存缺页 均由指令执行内部产生 → 属内中断(异常)","A 键盘输入来自外部设备 → 外中断","答案：A"]},{"t":"ex","q":"【模拟试卷2 · 第5题】下列有关 RAM 和 ROM 的叙述中，正确的是（　）。","steps":["RAM 可随机读写、断电丢失；ROM 只读为主、断电不丢","RAM 又分 SRAM（快、不需刷新、成本高）与 DRAM（密、需刷新、成本低）","ROM 常用于存放固化程序/引导程序，属非易失性存储器","答题要点：判断各项是否说清“易失性、读写性、用途”三要素"]},{"t":"sh","no":"三","title":"方法精练（计算模板）"},{"t":"pt","no":"模板1","name":"浮点数表示范围","feature":"给定阶符/阶码/数符/尾数位数，求可表示范围。","method":"指数范围 = ±(2^阶码位 − 1)；数值尾数 ∈ [2^−尾数位 , 1 − 2^−尾数位]。","steps":["指数极值 = ±(2^阶码位数 − 1)","尾数最大值 = 1 − 2^(−尾数位数)","尾数最小值(非零) = 2^(−尾数位数)","最大 = 尾数max × 2^(指数max)；最小 = 尾数min × 2^(指数min)"],"ex":{"q":"同上试卷第9题：1阶符+6阶码+1数符+8尾数。","steps":["指数 ±63；尾数max=1−2⁻⁸，尾数min=2⁻⁸","最大 (1−2⁻⁸)×2⁶³；最小 2⁻⁸×2⁻⁶³=2⁻⁷¹"]},"pit":"先算“指数极值”，再算“尾数极值”，最后相乘。"},{"t":"pt","no":"模板2","name":"存储器芯片扩展计算","feature":"给定容量与芯片规格，求所需芯片数。","method":"位扩展凑字长、字扩展凑单元数；片数 = 目标容量 ÷ 单组容量。","steps":["按区划分容量（ROM 区、RAM 区分别算）","位扩展：字长不够，几片并联凑成字节","字扩展：单元数不够，多组串联","总片数 = (目标容量 / 单组容量) × (每组的片数)"],"ex":{"q":"同上试卷第10题：ROM 4KB 用 2K×8；RAM 60KB 用 4K×4。","steps":["ROM：4096/2048 = 2 片","RAM：单组 2 片凑成 4K×8，61440/4096 = 15 组","RAM = 15×2 = 30 片"]},"pit":"4K×4 位要考虑“位扩展”凑成 8 位，别直接按容量除。"},{"t":"pt","no":"模板3","name":"Cache 地址划分（直接 / 组相联）","feature":"给出主存容量、Cache 数据区容量、块大小，问标记 / 行号(组号) / 块内地址位数，或问某块号映射到哪一行、哪一组。","method":"固定顺序：块内 = log₂(块大小) → 行数 = Cache 容量 ÷ 块大小 → 行号 = log₂(行数) → tag = 主存地址 − 行号 − 块内。组相联把“行号”换成“组号”，组数 = 行数 ÷ 路数。","steps":["① 主存地址位数 = log₂(主存容量)，按字节编址即以 B 为单位取对数","② 块内地址 = log₂(块大小)","③ 行数 = Cache 数据区 ÷ 块大小；行号 = log₂(行数)","④ tag = 主存地址 − 行号 − 块内（三项相加必须回到主存地址位数）","⑤ 组相联：组数 = 行数 ÷ 路数；组号 = log₂(组数)；tag 随之变长","⑥ 定位：直接映射 行号 = 块号 mod 行数；组相联 组号 = 块号 mod 组数"],"ex":{"q":"主存 4 MB，按字节编址；Cache 数据区 64 KB，块 64 B，采用 2 路组相联。求三段位数。","steps":["主存地址 = log₂(4 MB) = <b>22 位</b>","块内 = log₂64 = <b>6 位</b>","行数 = 64 KB ÷ 64 B = 1024 行","组数 = 1024 ÷ 2 = 512 → 组号 = <b>9 位</b>","tag = 22 − 9 − 6 = <b>7 位</b> → [tag 7][组号 9][块内 6]","检验：7 + 9 + 6 = 22 ✓"]},"pit":"别把“行数”和“组数”搞混；也别用 Cache 总容量（含 tag 与有效位）去除块大小。"},{"t":"pt","no":"模板4","name":"有效地址 EA 与访存次数","feature":"给出寻址方式、形式地址、IX/BR/PC 的值，求 EA，或问访存次数、操作数存放在哪里。","method":"EA 公式表：立即—无 EA/0 次；直接—EA=A/1 次；间接—EA=(A)/2 次；寄存器—0 次；寄存器间接—EA=(R)/1 次；变址—(IX)+A；基址—(BR)+A；相对—(PC)+A（PC 已更新）。","steps":["① 先认出寻址方式（看题目说“寄存器内容”还是“指令中地址”）","② 套对应公式算出 EA，偏移量为负时先符号扩展","③ 相对寻址先算 PC = 本指令地址 + 指令字节数",
"④ 明确问的是 EA 还是操作数本身（间接寻址要再取一次内容）","⑤ 数访存次数：立即 0、直接 1、间接 2、寄存器间接 1"],"ex":{"q":"某机指令长 4 字节，存于 2000H，形式地址 A = FFE8H（16 位补码），IX = 3000H。求相对寻址与变址寻址的 EA。","steps":["A = FFE8H 为补码 → 真值 = −0018H = −24","相对：PC = 2000H + 4 = 2004H → EA = 2004H + (−0018H) = <b>1FECH</b>","变址：EA = (IX) + A = 3000H + (−0018H) = <b>2FE8H</b>","注意两处 PC/IX 都是“加负偏移”，必须按补码算而非无符号相加","若为间接寻址，还需再访存一次取 (EA) 的内容"]},"pit":"PC 取已更新值；负偏移要符号扩展；区分 EA 与操作数本身（间接多一次访存）。"},{"t":"pt","no":"模板5","name":"流水线性能三项指标","feature":"给出段数 k、各段用时（或最慢段 Δt）、指令条数 n，求总时间 T、吞吐率 TP、加速比 S、效率 E。","method":"T = (k + n − 1)·Δt（Δt 取最慢段）；TP = n/T；S = 顺序执行时间 ÷ T = k·n/(k+n−1)；E = S ÷ k。","steps":["① 先确认 Δt = 最慢段用时，不是各段平均","② T = (k + n − 1)·Δt —— 装入 k−1 拍 + 流水 n 拍","③ TP = n ÷ T（单位换算成 M/s 时记得 ×10⁶）","④ S = k·n ÷ (k + n − 1)，n→∞ 时 S 趋近于 k（段数即加速比上限）","⑤ E = S ÷ k，恒小于 1，反映流水线利用率"],"ex":{"q":"某指令流水线分 6 段，各段用时 5 ns，连续执行 50 条指令。求 T、TP、S、E。","steps":["T = (6 + 50 − 1) × 5 ns = 55 × 5 = <b>275 ns</b>","TP = 50 ÷ 275 ns ≈ <b>181.8 M 条/s</b>","顺序执行时间 = 50 × 6 × 5 = 1500 ns → S = 1500 ÷ 275 ≈ <b>5.45</b>","E = 5.45 ÷ 6 ≈ <b>90.9%</b>","检验：S 必须小于 k = 6 ✓，E 必须小于 1 ✓（可用作自检）"]},"pit":"Δt 取最慢段；加速比上限是 k 与 n 无关；效率 E 一定小于 1。"},{"t":"tip","text":"<b>期末计算题通用流程：</b>①先统一单位（K=1024、B 与 b 差 8 倍）；②浮点先定指数极值再定尾数极值；③存储器先分区、再分位扩展/字扩展；④最后回代核对量纲与数量级。"},{"t":"kw","items":["中断服务顺序","浮点数范围","指数极值","尾数极值","芯片扩展","位扩展","字扩展","RISC","外中断","总线标准"]}]},"g12":{"no":12,"title":"模型机的组成与微指令操作","tag":"课程设计","sub":"实验箱模型机 · 内部结构 · 微程序控制 · 微指令操作","blocks":[{"t":"sh","no":"12.1","title":"模型机的内部结构与作用"},{"t":"tx","h":"模型机是什么","p":"<b>模型机</b>是课程设计里用实验箱（如 TEC 系列）搭出来的“缩小版计算机”：有一条完整数据通路、一套精简指令系统和一个可编程控制器。作用是把课本上分散的知识（指令格式、寻址方式、数据通路、微程序）串成一台真正能跑程序的机器，用来<b>验证指令系统设计是否合理、数据通路是否连通、控制器时序是否正确</b>。"},{"t":"fig","kind":"fig-model-machine","cap":"模型机内部结构：PC→MAR→主存→MDR→IR 取指；R0~R3/AC/L/D→ALU→DBUS 运算；μPC→CM→μIR 产生控制信号"},{"t":"tb","head":["部件","全称","作用"],"rows":[["PC","程序计数器","存放<b>下一条</b>要执行的指令地址，每取一条自动 +1"],["MAR","地址寄存器","暂存要访问的主存单元地址，经 ABUS 送主存"],["M / MDR","主存 / 数据寄存器","MDR 暂存读出或写入主存的数据，是 CPU 与主存的缓冲"],["IR","指令寄存器","存放当前指令，其操作码送控制器译码"],["AC","累加器","一地址指令隐含的操作数与结果寄存器"],["R0~R3","通用寄存器","存放操作数与中间结果，减少访存"],["L / D / R","暂存器","L、D 暂存 ALU 两路入口操作数，R 暂存 ALU 输出"],["ALU","算术逻辑单元","完成加、减与逻辑运算"],["μPC / μMAR","微地址寄存器","给出下一条微指令在控存中的地址"],["μIR","微指令寄存器","存放从控存取出的微指令（控制字）"],["CM","控制存储器","存放全部微程序，是微程序控制器的核心"],["ABUS / DBUS / IBUS","地址 / 数据 / 内部总线","连接各部件，分时传送地址、数据与控制信息"]]},{"t":"sh","no":"12.2","title":"微程序控制：六个基本概念"},
{"t":"tx","h":"从微命令到微程序","p":"20 世纪 50 年代 Wilkes 首先提出“微程序”这一术语：把一条机器指令分解成一串最基础的动作，每个动作由一个控制信号驱动，这些信号按规则编码成控制字，存进控存。它避免了硬布线的复杂性，又有组织、成体系。"},{"t":"tb","head":["概念","含义","一句话记忆"],"rows":[["微命令","控制部件通过控制线发给执行部件的控制信号","“发的命令”"],["微操作","执行部件收到微命令后所进行的动作","“做的动作”，与微命令一一对应"],["微指令","一个 CPU 周期内、一组实现某操作功能的微命令组合（即控制字）","控存一个单元的内容"],["微地址","存放控制字的控存单元地址","“控存的房间号”"],["微程序","微指令的有序序列","一条机器指令对应一段微程序"],["控制存储器","存放微程序的高速存储器（CM）","“微程序仓库”"]]},{"t":"tx","h":"微程序控制器的四个部件","p":"① <b>控制存储器 CM</b>——核心，存微程序；② <b>微指令寄存器 μIR</b>——存从 CM 取出的微指令，位数等于微指令字长；③ <b>微地址形成部件</b>——产生初始微地址与后继微地址；④ <b>微地址寄存器 μMAR</b>——接收微地址，为读 CM 做准备。"},{"t":"dv","title":"微程序控制器的工作过程（四步）","steps":["<b>第 1 步 · 公共取指</b>：从控存 <b>0 号微地址</b>取出“取指微程序”，把机器指令从主存读到 IR。所有指令共用这一段，只写一份","<b>第 2 步 · 形成入口</b>：IR 的操作码送<b>微地址形成部件</b>，映射出该机器指令对应微程序的首地址，送入 μMAR","<b>第 3 步 · 逐条执行</b>：按 μMAR 从 CM 读微指令到 μIR，每条微指令发出一组微命令，控制数据通路完成一个 CPU 周期的微操作","<b>第 4 步 · 返回取指</b>：该机器指令的微程序执行完，跳回取指微程序入口，取下一条机器指令，循环直到程序结束"]},{"t":"tx","h":"机器指令与微指令的关系","p":"① <b>一条机器指令 ↔ 一个微程序</b>（由若干微指令组成），机器指令的功能由微指令序列实现；② 指令 / 程序 / 地址对应<b>主存</b>，微指令 / 微程序 / 微地址对应<b>控存</b>，两套体系别混；③ 取指操作对所有指令相同，故抽成公用微程序；④ 一条微指令包含多个微命令，层级是：机器指令 ⊃ 微程序 ⊃ 微指令 ⊃ 微命令。"},{"t":"sh","no":"12.3","title":"微指令操作示例：取指与加法"},{"t":"tx","h":"取指微程序（自 0 号微地址起）","p":"把“取指”这段公用微程序拆成三条微指令，每条占一个 CPU 周期，可看清微指令如何一步步驱动数据通路。"},{"t":"tb","head":["微地址","微操作（本条微指令发出的微命令）","完成的功能"],"rows":[["00","PC → ABUS；ABUS → MAR；发读命令","把指令地址送上地址总线并启动读主存"],["01","M → DBUS；DBUS → MDR；MDR → IR；PC + 1","指令经数据总线进 MDR 再送 IR，同时 PC 指向下一条"],["02","IR 操作码 → 微地址形成部件 → μMAR","译码得到该指令微程序入口，准备跳转"]]},{"t":"tx","h":"ADD R1, R2 的微程序（接续入口）","p":"设指令功能为 (R1) + (R2) → R1。入口地址由操作码映射得到，之后两条微指令完成取操作数与运算回写。"},{"t":"tb","head":["微地址","微操作","完成的功能"],"rows":[["10","R1 → L；R2 → D","两个操作数分别送 ALU 的两路入口暂存器"],["11","L + D → R；R → R1；置结束标志","ALU 求和经 R 暂存写回 R1，微程序结束返回取指"]]},{"t":"sh","no":"12.4","title":"硬布线与微程序：怎么选"},{"t":"tb","head":["对比项","硬布线控制器","微程序控制器"],"rows":[["实现方式","门电路 + 触发器构成的复杂逻辑网络","存储逻辑：控制字存在控存中"],["速度","快，控制信号由逻辑门直接产生","慢，每条微指令都要读一次控存"],["时序系统","复杂，必须靠时序电路严格配合","简单，微指令周期与 CPU 周期对齐即可"],["修改扩展","改动要重做电路，困难","改微程序即可，灵活"],["适用场合","RISC 等指令少、追求速度的机器","CISC 等指令多、追求规整与灵活的机器"]]},{"t":"ex","q":"【例题】模型机执行 ADD R1, R2（(R1)+(R2)→R1），按节拍写出微操作序列及所需微命令。","steps":[{"s":"取指微程序入口：PC→MAR、读主存、MDR→IR、PC+1、按操作码散转到 ADD 微程序入口","note":"所有指令共用的取指部分"},{"s":"T₁：R2→X（源操作数送 ALU 左端暂存器）","note":"对应微命令 R2→X"},{"s":"T₂：R1→Y（目的操作数送 ALU 右端）"},{"s":"T₃：X+Y→Z（发 ALU 加命令，结果进暂存器 Z）"},
{"s":"T₄：Z→R1（结果写回目的寄存器）；微程序返回取指入口","note":"每个节拍一个控制字=一条微指令"},{"s":"对照 12.3 的微程序表：微指令 = 节拍内一组微命令的编码；微程序 = 完成一条机器指令的微指令序列"}]},{"t":"pt","no":"题型1","name":"微指令与微操作层级判断","feature":"给出一段描述，判断属于微命令 / 微操作 / 微指令 / 微程序。","method":"按“信号→动作→控制字→序列”的层级逐级对应。","steps":["先看是不是“发出的控制信号”→ 微命令","再看是不是“部件执行的动作”→ 微操作","一个节拍内的一组微命令 → 微指令（控制字）","完成一条机器指令的多条微指令 → 微程序"],"ex":{"q":"“控制器向 ALU 发出加法控制信号，ALU 完成两数相加”。这两句分别属于什么？","steps":["“发出加法控制信号”是控制部件给出的信号 → <b>微命令</b>","“ALU 完成两数相加”是执行部件做的动作 → <b>微操作</b>","两者一一对应：微命令是控制信号，微操作是操作过程","这一个 CPU 周期内的一组微命令编码后即为一条 <b>微指令</b>"]},"pit":"别把“微指令”说成“一条指令”；微指令属于控存，机器指令属于主存。"},{"t":"warn","text":"<b>易错点：</b>① 微命令是信号、微操作是动作，一一对应但不等同；② 层级顺序：机器指令 ⊃ 微程序 ⊃ 微指令 ⊃ 微命令，别搞反；③ 硬布线的时序系统更<b>复杂</b>而不是更简单（常见误判）；④ 组合逻辑控制器与微程序控制器的根本区别在于<b>微操作信号发生器的组成方法</b>，不在 ALU 或数据通路。"},{"t":"tip","text":"<b>第 12 章（模型机）复习主线：</b>① 先背部件表——PC/MAR/MDR/IR/AC/R0~R3/L·D·R/ALU/μPC/μIR/CM；② 取指通路走一遍：PC→MAR→M→MDR→IR；③ 六个微概念按“命令→动作→控制字→房间号→序列→仓库”串起来；④ 四步工作过程背“取指→入口→逐条→返回”；⑤ 硬布线与微程序按速度/时序/灵活性三轴对比。"},{"t":"kw","items":["模型机","数据通路","PC/MAR/MDR/IR","AC 与通用寄存器","微命令","微操作","微指令","微地址","控存 CM","取指微程序","硬布线 vs 微程序"]}]}}},
  "ds": {"key":"ds","name":"数据结构","icon":"⌗","book":"《数据结构》(C 语言版) · 严蔚敏 主线","prog":"已学到第 6 章 · 树和二叉树 · 第 5 章已按课件补全","progPct":60,"intro":"按教材章节编排：单元 = 一章，章下按小节拆开。数据结构的痛点不是“看不懂”而是“写不出”——所以每个结构都配了可复制的 C 代码与边界处理，照着敲一遍就能上手。核心是理解“逻辑结构 → 存储结构 → 操作实现”这条线。","map":{"root":{"title":"数据结构","x":50,"y":14},"hubs":[{"id":"dh1","title":"线性结构 (2–5章)","x":24,"y":40},{"id":"dh2","title":"非线性结构 (6章)","x":62,"y":40},{"id":"dh3","title":"基础 (1章)","x":88,"y":40},{"id":"dh4","title":"查找与排序 (第9–10章)","x":43,"y":40}],"units":[{"id":"d1","no":"1","title":"绪论","sub":"概念·算法·复杂度","tag":"基础","x":88,"y":60,"parent":"dh3"},{"id":"d2","no":"2","title":"线性表","sub":"顺序表·链表","tag":"线性","x":8,"y":62,"parent":"dh1"},{"id":"d3","no":"3","title":"栈和队列","sub":"LIFO·FIFO","tag":"线性","x":26,"y":62,"parent":"dh1"},{"id":"d4","no":"4","title":"串","sub":"模式匹配·KMP","tag":"线性","x":38,"y":62,"parent":"dh1"},{"id":"d5","no":"5","title":"数组和广义表","sub":"顺序存储·压缩存储·广义表","tag":"线性","x":54,"y":62,"parent":"dh1"},{"id":"d6","no":"6","title":"树和二叉树","sub":"遍历·递归","tag":"当前","x":62,"y":62,"parent":"dh2","cur":true},{"id":"d7","no":"7","title":"图","sub":"存储·最短路","tag":"拓展","x":80,"y":62,"parent":"dh2"},{"id":"d8","no":"9","title":"查找","sub":"折半·哈希·ASL","tag":"核心","x":33,"y":80,"parent":"dh4"},{"id":"d9","no":"10","title":"排序","sub":"快排·堆排·稳定性","tag":"核心","x":53,"y":80,"parent":"dh4"}]},"units":{"d1":{"no":"1","title":"绪论","tag":"第1章","sub":"课本第1章。先搞清楚“数据结构”研究什么、算法好坏的衡量标准(时间复杂度/空间复杂度)。","blocks":[{"t":"sh","no":"1.1","title":"数据结构的基本概念"},{"t":"tx","h":"数据、数据元素、数据项","p":"<b>数据</b>是信息的载体；<b>数据元素</b>是数据的基本单位(如一条记录)，由若干<b>数据项</b>组成，数据项是不可分割的最小单位。"},{"t":"tx","h":"数据结构三要素","p":"<b>逻辑结构</b>(数据元素之间的抽象关系：集合、线性、树形、图形)、<b>存储结构</b>(逻辑结构在计算机中的表示：顺序存储、链式存储、索引、散列)、<b>数据的运算</b>(增删改查等操作)。三者共同构成数据结构。"},{"t":"tx","h":"为什么学：从问题到结构","p":"数据结构研究<b>非数值计算</b>问题中的操作对象及其关系与操作。典型场景：书目检索用<b>线性表</b>+索引表；文件目录、行政区划、生物/学科分类是<b>树</b>；多叉路口交通灯、哥尼斯堡七桥问题抽象为<b>图</b>。"},{"t":"tx","h":"程序 = 数据结构 + 算法","p":"准确模型：程序 = 数据结构 ∪ 算法 ∪ …；简易模型：<b>程序 = 数据结构 + 算法</b>。数据结构回答“处理什么、怎么组织”，算法回答“怎么处理”。"},{"t":"sh","no":"1.2","title":"抽象数据类型 (ADT)"},{"t":"tx","h":"ADT","p":"抽象数据类型 = 数据对象 + 数据关系 + 基本操作。它只定义“做什么”，不关心“怎么做”，是数据封装后对外提供的接口描述。"},{"t":"tx","h":"描述工具与实现工具","p":"<b>描述工具</b>：抽象数据类型 <b>ADT</b>（数据对象 + 数据关系 + 数据操作，只讲“做什么”）、<b>UML</b>（面向对象统一建模语言）、教材图形化描述、CASE 图形化描述。<b>实现工具</b>：C / 类C 语言（typedef、struct、枚举），或面向对象语言的 class。"},{"t":"sh","no":"1.3","title":"算法和算法分析"},{"t":"tx",
"h":"算法特性与复杂度","p":"算法具有有穷性、确定性、可行性、输入、输出五个特性。复杂度用<b>大 O 记号</b>衡量：<b>时间复杂度</b>关注基本操作执行次数随问题规模 n 的增长趋势；<b>空间复杂度</b>关注额外存储空间。"},{"t":"fx","lines":["O 记号：f(n)=O(g(n)) 表示忽略常数倍的上界（∃c,n₀，n>n₀ 时 f(n) ≤ c·g(n)）","Ω 记号：表示忽略常数倍的下界","θ 记号：f=θ(g) 当且仅当 f=O(g) 且 f=Ω(g)（紧确界）","工程上通常只用大 O 来表达 θ 的含义"]},{"t":"tx","h":"复杂度口径：最好 / 最坏 / 平均 / 分摊","p":"同一算法在不同输入下代价不同：<b>最好</b> T_best、<b>最坏</b> T_worst、<b>平均</b> T_avg = Σ wᵢcᵢ、<b>分摊（均摊）</b>——把偶尔出现的高代价平摊到多次操作上。<b>空间复杂度</b> S(n)：只统计算法运行<b>新占用</b>的空间，<b>数据本身所占空间不计入</b>。"},{"t":"ex","q":"【全国考研真题】(1) x=2; while(x<n/2) x=2*x; 的时间复杂度？ (2) int fact(int n){ if(n<=1) return 1; return n*fact(n-1); } 的时间复杂度？","steps":["(1) x 按 2 的幂增长，循环执行约 log₂n 次 → O(log n)","(2) 递归深度为 n，每层 O(1) → O(n)","要点：看“执行次数”随 n 的增长阶，而不是具体数值。"]},{"t":"fx","lines":["常数阶 O(1) < 对数阶 O(log n) < 线性阶 O(n) < 线性对数阶 O(n log n) < 平方阶 O(n²) < 指数阶 O(2ⁿ)","顺序执行的语句相加 → 取最大项","循环嵌套 → 层数相乘"]},{"t":"ex","q":"【典型例题】分析下面两段代码的时间复杂度。","steps":["(1) for(i=0;i<n;i++) sum+=a[i]; —— 循环 n 次，O(n)","(2) for(i=0;i<n;i++) for(j=0;j<n;j++) c[i][j]=a[i][j]+b[i][j]; —— 双层循环，O(n²)","(3) 若循环体与 n 无关(如固定 100 次)，则为 O(1)","要点：只看最高阶项，忽略常数系数。"]},{"t":"warn","text":"<b>易错点：</b>① 逻辑结构≠存储结构，逻辑是“关系”、存储是“实现”；② 时间复杂度是增长量级不是精确次数；③ O(n) 与 n 的二分查找是 O(log n) 要分清；④ 大 O 只保留最高阶项。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本绪论习题）"},{"t":"dv","title":"推导：时间复杂度大 O 怎么算出来","steps":["写出基本操作执行次数 f(n)：<b>保留最高阶项、去掉系数</b>，如 f(n) = n² + 2n + 10 → O(n²)。","加法规则（顺序段）：O(f) + O(g) = O(max(f, g))——两段代码只取增长更快的那段。","乘法规则（嵌套循环）：O(f) × O(g) = O(f·g)——外层 n 次、内层 n 次就是 O(n²)。","对数阶的来源：每轮规模减半（如 x=2*x 直到 x≥n），轮数 = ⌈log₂n⌉ → O(log n)。","考研常考形式：while(x<n/2) x=2*x → 设执行 k 次后 2ᵏ≥n/2 → k = ⌈log₂n⌉−1 → O(log n)。"]},{"t":"pt","no":"题型1","name":"数据结构基本概念判断","feature":"判断数据、数据元素、数据项、数据结构、逻辑/存储结构等概念。","method":"逻辑结构（集合/线性/树/图）与存储结构（顺序/链式/索引/散列）分开记。","steps":["数据项→数据元素→数据的最小/基本单位关系","逻辑结构描述关系、存储结构描述实现","抽象数据类型 ADT = 数据对象 + 操作","四种基本逻辑结构牢记"],"ex":{"q":"判断：数据的存储结构是数据元素之间的逻辑关系的表示。","steps":["逻辑结构才是元素间逻辑关系","存储结构是逻辑结构在计算机中的表示（映像）","故该说法混淆二者","正确：存储结构是逻辑结构在存储器中的映像。"]},"pit":"逻辑结构与存储结构两对概念最易混，务必区分定义。"},{"t":"pt","no":"题型2","name":"算法特性与时间复杂度分析","feature":"判断算法特性，或分析给定代码的时间复杂度。","method":"五特性：有穷性、确定性、可行性、输入、输出；复杂度看基本操作执行次数随 n 的增长阶。","steps":["排除“有穷性”缺失的错误算法","数循环嵌套层数判断 O","逐层看循环变量增长方式（n、n/2、n²）","取最高阶项、忽略常数系数"],"ex":{"q":"求下面代码的时间复杂度：for(i=1;i<=n;i*=2) sum++;","steps":["循环变量 i 每次乘 2","执行次数 k 满足 2^k ≤ n","k = log₂n","故时间复杂度 O(log n)。"]},"pit":"i*=2 是 log 级，别误判为 O(n)；嵌套看乘积。"},
{"t":"pt","no":"题型3","name":"渐进时间复杂度比较与常见量级排序","feature":"比较多个算法优劣或排序复杂度量级。","method":"量级从小到大：O(1) < O(log n) < O(n) < O(nlog n) < O(n²) < O(n³) < O(2ⁿ)。","steps":["写出各算法复杂度","按量级从小到大排列","关注最坏/平均情形","最好/最坏要分别说明"],"ex":{"q":"比较 O(n)、O(nlog n)、O(n²) 三者的增长快慢。","steps":["n 增大时看主导项","n < nlog n < n²","故 O(n) 最快、O(n²) 最慢","大 n 时差距显著。"]},"pit":"复杂度比较看增长趋势，与具体常数无关。"},{"t":"tip","text":"<b>绪论解题总流程：</b>①概念题严格区分“逻辑/存储结构”；②算法特性五条核对；③复杂度题数循环、找主导项；④记牢常见量级排序。"},{"t":"kw","items":["逻辑结构","存储结构","ADT","时间复杂度","大O记号"]}]},"d2":{"no":"2","title":"线性表","tag":"第2章","sub":"课本第2章。线性表是最基础的结构，顺序表(数组)与链表是它的两种实现，各有取舍。","blocks":[{"t":"sh","no":"2.1","title":"线性表的定义和特点"},{"t":"tx","h":"定义","p":"线性表是 n(n≥0)个数据元素的有限序列，元素之间一对一的线性关系，除首尾外每个元素有且仅有一个前驱和后继。空表 n=0。"},{"t":"sh","no":"2.2","title":"线性表的顺序表示和实现"},{"t":"tx","h":"顺序表","p":"用一组<b>地址连续</b>的存储单元依次存放元素。优点是<b>随机存取 O(1)</b>；缺点是插入删除平均移动一半元素 O(n)、容量固定。"},{"t":"fx","lines":["元素 a[i] 地址 = base + i × sizeof(元素) ，O(1)","插入平均移动 n/2 个元素 ，O(n)","删除平均移动 (n−1)/2 个元素 ，O(n)"]},{"t":"code","lang":"C · 顺序表插入","code":"#define MAX 100\ntypedef struct { int data[MAX]; int len; } SqList;\n\n/* 在下标 i 处插入 x */\nint insert(SqList *L, int i, int x){\n    if (i < 0 || i > L->len) return 0;   /* 越界 */\n    if (L->len == MAX) return 0;         /* 满 */\n    for (int j = L->len; j > i; j--)     /* 从后往前搬 */\n        L->data[j] = L->data[j-1];\n    L->data[i] = x;\n    L->len++;\n    return 1;\n}"},{"t":"sh","no":"2.3","title":"线性表的链式表示和实现"},{"t":"tx","h":"单链表","p":"每个结点含<b>数据域 + 指针域</b>，逻辑相邻靠指针维系，物理上可分散。插入删除不用搬元素(已知前驱时 O(1))，但只能顺序访问 O(n)。带<b>头结点</b>可统一空表与非空表操作。"},{"t":"code","lang":"C · 单链表插入与删除","code":"typedef struct Node { int data; struct Node *next; } Node;\n\n/* 在 p 之后插入 s */\nvoid insertAfter(Node *p, Node *s){\n    s->next = p->next;\n    p->next = s;\n}\n/* 删除 p 的后继并释放 */\nint deleteAfter(Node *p){\n    Node *q = p->next;\n    if (q == NULL) return 0;\n    p->next = q->next;\n    free(q);\n    return 1;\n}"},{"t":"anim","kind":"anim-list","cap":"单链表反转：三指针 prev / cur / next 逐步把箭头反向，O(1) 空间完成"},{"t":"ex","q":"【典型例题】如何用 O(1) 额外空间、O(n) 时间反转单链表？","steps":["三指针 prev=NULL, cur=head, next","循环：next=cur->next; cur->next=prev; prev=cur; cur=next","循环结束时 prev 指向新表头","返回 prev","关键：改 cur->next 之前必须先用 next 保存原后继，否则断链。"]},{"t":"ex","q":"【典型例题】顺序表与链表如何选择？","steps":["频繁按位置访问、表长可预估 → 顺序表(随机存取 O(1))","频繁插入删除、表长变化大 → 链表(免搬移)","需要节省空间(无指针开销) → 顺序表","结论：按主要操作的复杂度权衡，没有绝对优劣。"]},{"t":"sh",
"no":"2.4","title":"顺序表的动态扩容"},{"t":"tx","h":"等量扩容 vs 等比扩容","p":"容量固定，插入溢出就要扩容。<b>等量扩容</b>（每次固定加 c）：从 1 扩到 n 需约 n/c 次，总搬运 O(n²)，<b>分摊到每次插入为 O(n)</b>；<b>等比扩容</b>（每次翻倍）：总搬运 1+2+4+…+n ≈ 2n，<b>分摊到每次插入为 O(1)</b>。工程上普遍采用翻倍（等比）扩容。"},{"t":"fx","lines":["等量扩容：总搬运 ≈ n²/c，分摊每次 O(n)","等比(翻倍)扩容：总搬运 ≈ 2n，分摊每次 O(1)"]},{"t":"code","lang":"C · 就近扩容 (realloc)","code":"/* 新地址 = realloc(旧地址, 新容量) */\nElemType *np = realloc(items, newCap * sizeof(ElemType));\nif (np == NULL) throw \"申请空间失败\";\nif (np != items)                                  /* 未获准原地扩容 */\n    memcpy(np, items, length * sizeof(ElemType)); /* 搬新居 */\nitems = np; capacity = newCap;"},{"t":"sh","no":"2.5","title":"线性表的应用：一元多项式"},{"t":"tx","h":"多项式的表示","p":"一元多项式 P(x)=p₀+p₁x+…+pₙxⁿ 可用线性表表示。为节省空间只存非零项：每个结点含<b>系数 coef</b> 与<b>指数 exp</b>，按指数有序排列。存储可用顺序表，也可用单链表（更省空间、便于动态增减）。"},{"t":"tx","h":"多项式相加","p":"设 p、q、t 分别指向 A、B、C 的第一个结点，反复比较指数：<b>p 的指数小</b>则把 p 结点复制到 t 之后、p 后移；<b>q 的小</b>则复制 q；<b>指数相等</b>则系数相加——和为 0 则都后移（不建结点），非 0 则建新结点插入。某一链先空后，把另一链剩余部分整段接上。"},{"t":"warn","text":"<b>易错点：</b>① 顺序表插入搬元素必须从后往前；② 链表改指针前先保存后继；③ 删除结点后要 free；④ 头插法建表得到的是输入逆序。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第2章习题）"},{"t":"dv","title":"推导：顺序表插入/删除平均移动次数","steps":["表长 n，在第 i 个位置插入（i = 1…n+1 共 n+1 个位置），需后移 n−i+1 个元素。","等概率平均：<b>E_插 = (1/(n+1))·Σ(n−i+1) = (1/(n+1))·n(n+1)/2 = n/2</b>。","删除第 i 个元素需前移 n−i 个：E_删 = (1/n)·Σ(n−i) = (1/n)·n(n−1)/2 = <b>(n−1)/2</b>。","结论：插入删除平均都要移动约一半元素 → O(n)。这就是「顺序表随机存取 O(1)、增删 O(n)」的数量依据。","对照：链表增删只需改指针 O(1)，但定位第 i 个元素要 O(n)——两种结构各胜一场。"]},{"t":"pt","no":"题型1","name":"顺序表插入/删除的元素移动次数","feature":"求在顺序表某位置插入或删除需移动的元素个数，或平均移动次数。","method":"插入：移动 n−i+1 个；删除：移动 n−i 个；平均约 n/2。","steps":["确定表长 n 与操作位置 i（从 1 计）","插入位置 i 需后移 i 之后到 n 的元素","删除位置 i 需前移 i+1 之后的元素","平均移动 n/2，复杂度 O(n)"],"ex":{"q":"长度 n 的顺序表第 i 个位置插入一个元素，平均移动次数为多少？","steps":["在第 i 位插入需移动 n−i+1 个元素","i 从 1 到 n+1 等概率","平均 = (1/(n+1))Σ(n−i+1)","≈ n/2，即 O(n)。"]},"pit":"插入/删除位置计数起点（1 还是 0）会影响公式，先统一。"},{"t":"pt","no":"题型2","name":"单链表插入/删除的指针操作","feature":"给出链表结构，写出插入/删除的指针修改语句或判断能否定位。","method":"插入：p->next = s; s->next = q（注意顺序）；删除：p->next = p->next->next。","steps":["找到待操作结点的前驱 p","插入新结点 s：先连后断，顺序不能反","删除结点 q：让前驱绕过 q","最后释放被删结点内存"],"ex":{"q":"在单链表结点 p 之后插入结点 s，正确的操作是？","steps":["s->next = p->next","p->next = s","两步顺序不能颠倒","否则丢失后继链。"]},"pit":"插入必须“先接后断”，否则断链；删除要保存被删结点指针。"},{"t":"pt","no":"题型3","name":"单链表找倒数第 k 个 / 求中间结点（快慢指针）","feature":"一趟扫描找链表中特定位置结点。","method":"快慢指针：快指针先走 k 步，再同步走，快到尾则慢在倒数第 k。",
"steps":["两个指针同时从头出发","快指针先走 k 步","两指针同步后移","快指针到尾时慢指针指向倒数第 k 个"],"ex":{"q":"如何用一趟遍历求单链表的中间结点？","steps":["设置快慢双指针","快指针每次走 2 步、慢指针每次 1 步","快指针到尾时","慢指针正好在中间（n 奇偶略有差别）。"]},"pit":"快指针终点判断要区分表长奇偶；边界（k 大于表长）要处理。"},{"t":"pt","no":"题型4","name":"单链表逆转","feature":"原地逆置一个单链表。","method":"三指针法：pre、cur、next 逐结点改向。","steps":["pre=NULL，cur=head","循环：暂存 next=cur->next","cur->next=pre（改向）","pre=cur，cur=next，循环至 cur 空"],"ex":{"q":"写出单链表原地逆置的核心循环。","steps":["next = cur->next","cur->next = pre","pre = cur","cur = next，反复直到 cur==NULL。"]},"pit":"改向前必须先保存后继，否则丢链。"},{"t":"pt","no":"题型5","name":"链表合并与去重","feature":"合并两个有序链表，或删除重复元素。","method":"双指针归并，尾插法建结果链。","steps":["两指针分别指向两链表首元","比较当前值，小者接入结果链尾","对应指针后移","一链空后接另一链剩余部分"],"ex":{"q":"合并两个增序单链表为一个增序链表，用什么思想？","steps":["两有序表不能直接接","用归并思想双指针比较","每次取较小结点尾插","复杂度 O(m+n)。"]},"pit":"合并后要保持有序；尾插用尾指针避免每次找尾。"},{"t":"pt","no":"题型6","name":"循环链表与双向链表特性","feature":"判断循环/双向链表的操作与优点。","method":"循环链表尾结点 next 指头；双向链表有 prior 与 next 两个指针域。","steps":["循环链表判空条件与遍历终止","双向链表插入需改 4 个指针","双链表可 O(1) 找前驱","循环双链表结合两者优点"],"ex":{"q":"双向链表中在结点 p 之前插入 s，涉及哪些指针？","steps":["s->prior = p->prior","s->next = p","p->prior->next = s","p->prior = s（共 4 个）。"]},"pit":"双链表插入/删除要同时维护两个方向指针，别漏 prior。"},{"t":"tip","text":"<b>第2章解题总流程：</b>①顺序表看“移动次数”；②单链表操作先找前驱、注意指针顺序；③快慢指针解决倒数/中点；④逆转用三指针；⑤有序合并用归并尾插。"},{"t":"kw","items":["线性表","顺序表O(1)","单链表","头结点","链表反转"]}]},"d3":{"no":"3","title":"栈和队列","tag":"第3章","sub":"课本第3章。操作受限的线性表：栈后进先出、队列先进先出，是递归/搜索等算法的基础工具。","blocks":[{"t":"sh","no":"3.1","title":"栈"},{"t":"tx","h":"栈的定义与实现","p":"栈只能在<b>栈顶</b>插入/删除，<b>后进先出(LIFO)</b>。用作函数调用、括号匹配、表达式求值、深度优先搜索(DFS)。顺序栈用数组+top 实现；链栈用链表。"},{"t":"fx","lines":["顺序栈 top 初值 −1：空栈判据 top == −1","入栈：S[++top] = x ；出栈：x = S[top--]","栈的应用：括号匹配、表达式求值、进制转换、递归"]},{"t":"sh","no":"3.2","title":"队列"},{"t":"tx","h":"队列与循环队列","p":"队列一端进(队尾 rear)一端出(队头 front)，<b>先进先出(FIFO)</b>。用于广度优先搜索(BFS)、任务调度、缓冲区。为复用空间用<b>循环队列</b>。"},{"t":"fx","lines":["循环队列判空：front == rear","循环队列判满：(rear+1)%MAX == front（牺牲一格）","元素个数：(rear − front + MAX) % MAX"]},{"t":"code","lang":"C · 循环队列入队出队","code":"#define MAX 100\ntypedef struct { int data[MAX]; int front, rear; } Queue;\n\nint enQueue(Queue *q, int x){\n    if ((q->rear + 1) % MAX == q->front) return 0; /* 满 */\n    q->data[q->rear] = x;\n    q->rear = (q->rear + 1) % MAX;\n    return 1;\n}\nint deQueue(Queue *q, int *x){\n    if (q->front == q->rear) return 0; /* 空 */\n    *x = q->data[q->front];\n    q->front = (q->front + 1) % MAX;\n    return 1;\n}"},
{"t":"ex","q":"【典型例题】用两个栈实现一个队列。","steps":["准备入栈 in、出栈 out","入队：压入 in","出队：若 out 为空，把 in 全部弹出并压入 out(顺序反转两次 = FIFO)","从 out 弹出即队头","均摊复杂度 O(1)：每个元素最多被搬两次。"]},{"t":"sh","no":"","title":"栈的典型应用（深入）"},{"t":"tx","h":"递归与工作栈","p":"函数调用与递归都依赖<b>系统栈</b>：每次调用压栈保存返回地址与局部变量，返回时弹出恢复。递归的本质就是栈的后进先出。"},{"t":"ex","q":"【例】汉诺塔（Tower of Hanoi）：把 n 个圆盘从 X 借助 Y 移到 Z，每次只能移一个且大盘不能压小盘。","steps":["把上 n−1 个盘从 X 借助 Z 移到 Y","把最大盘从 X 直接移到 Z","把 n−1 个盘从 Y 借助 X 移到 Z","n=1 时直接移动；递归深度为 n，总步数 2ⁿ−1"]},{"t":"tx","h":"表达式求值","p":"中缀表达式要处理优先级与括号：用<b>操作数栈 + 运算符栈</b>，遇到运算符按优先级决定弹栈运算的时机。后缀（逆波兰）表达式求值最简单——<b>遇操作数入栈，遇运算符弹出两个数运算后再回压</b>。中缀转后缀再求值是最常见的考法。"},{"t":"ex","q":"【例】计算中缀表达式 2 + 4 − 3 × 6。","steps":["中缀转后缀：2 4 + 3 6 × −","后缀求值：2、4 入栈 → 遇 + 得 6；3、6 入栈 → 遇 × 得 18","再遇 − ：6 − 18 = −12","结果 −12"]},{"t":"tx","h":"进制转换与消除递归","p":"<b>多进制输出</b>：十进制转 K 进制不断取余，余数<b>逆序</b>输出，正合栈的后进先出（如 159₁₀ = 237₈）。<b>消除递归</b>：尾递归（递归发生在函数末尾）可直接改写成循环、不使用栈；非尾递归则需自建工作栈保存各层环境，按后进先出依次恢复。"},{"t":"sh","no":"","title":"队列的存储与满空判定（深入）"},{"t":"tx","h":"假溢出与循环队列","p":"顺序队列用 head 指示队首元素、tail 指示队尾的下一位。单纯顺序队列出队后，前部空闲空间无法复用，会造成<b>假溢出</b>；把数组首尾相接成<b>循环队列</b>（tail = (tail+1) % M）即可复用空间。"},{"t":"fx","lines":["少用一个元素空间：队空 head==tail；队满 (tail+1)%M==head","设标志位 tag：tag=0 且 head==tail 为空；tag=1 且 head==tail 为满","另设 length 变量：length==0 为空；length==M 为满（判定直观，推荐）"]},{"t":"tx","h":"链队列","p":"链式队列 = 单链表 + 一个<b>尾指针</b>：入队在队尾、出队在队头，均 O(1)（队头出队相当于删表头，空队列时要重置尾指针）。相比顺序队列无假溢出、容量不限，但每个结点多一个指针开销。"},{"t":"ex","q":"【应用】用循环队列求解“划分子集”问题：把集合 A 按冲突关系 R 划分成互不相交的子集，使每个子集内元素两两无冲突，且组数尽量少。","steps":["用冲突关系矩阵 r[i][j] 表示 i、j 是否有冲突","元素放入循环队列 cq，工作数组 conflict 记录当前组已占用的冲突","依次出队：与当前组无冲突则归入本组，并把它的冲突行标记进 conflict；有冲突则重新入队等待下一组","一轮出队完毕得到一组，组号 group+1、conflict 清零，直到队空"]},{"t":"warn","text":"<b>易错点：</b>① 循环队列取模别漏；② 空/满判据要背(空 front==rear，满 (rear+1)%MAX==front)；③ 顺序栈要判满、链栈不用；④ 栈底/栈顶方向别搞反。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第3章习题）"},{"t":"dv","title":"推导：循环队列为什么「牺牲一格」","steps":["循环队列中 front == rear 既可能表示空、也可能表示满——必须人为区分。","方案 A（牺牲一格）：约定 <b>(rear+1) % MAX == front</b> 为满，front == rear 为空 → 实际容量 MAX−1。","元素个数公式：rear ≥ front 时就是 rear−front；回绕时补上 MAX → 统一为 <b>(rear − front + MAX) % MAX</b>。","方案 B 设标志位 tag（最后一次操作是入队还是出队）可省这一格；方案 C 直接维护 length 计数器，最直观。","考点：给 MAX 与 front/rear 的值，求元素个数或判满——直接套上面公式。"]},{"t":"pt","no":"题型1","name":"栈的进栈/出栈序列合法性判断","feature":"给入栈序列，判断某出栈序列是否可能。","method":"借助辅助栈模拟；出栈序列的充要条件是可用“入栈—出栈”过程生成。","steps":["按入栈顺序逐个入栈","需出栈时弹出栈顶","用两个指针模拟整个过程","若某步需要的元素不在栈顶且已越过则非法"],
"ex":{"q":"入栈序列 1,2,3,4，判断 3,1,2,4 是否可能是出栈序列？","steps":["入 1,2,3 → 出 3","此时栈顶为 2，1 在其下","要先出 1 必须先出 2","故 3,1,2,4 不可能。"]},"pit":"出栈必须遵循后进先出；不能跳跃出栈。"},{"t":"pt","no":"题型2","name":"括号匹配与表达式求值（栈应用）","feature":"判断括号是否匹配，或把中缀表达式转后缀并求值。","method":"左括号入栈，右括号匹配栈顶；中缀转后缀用运算符栈 + 优先级。","steps":["遇左括号入栈，遇右括号弹栈匹配","后缀转换：操作数直接输出，运算符按优先级弹栈","求值：遇操作数入栈，遇运算符弹两数计算","最终栈顶即结果"],"ex":{"q":"判断括号串 ([()]) 是否匹配。","steps":["遇 ( [ 入栈","遇 ) 匹配 [ 后的 (","遇 ] 匹配 [","栈空且完全匹配 → 合法。"]},"pit":"要处理括号类型匹配，不能只看数量；结束时栈必须为空。"},{"t":"pt","no":"题型3","name":"循环队列判空/判满与元素个数","feature":"求循环队列队空、队满条件或元素个数。","method":"牺牲一个单元：队空 front==rear；队满 (rear+1)%M==front；个数 (rear−front+M)%M。","steps":["确定队列容量 M","队空：front==rear","队满：(rear+1)%M == front","元素个数 = (rear − front + M) % M"],"ex":{"q":"循环队列容量 10，front=3，rear=8，求元素个数。","steps":["个数 = (rear − front + M) % M","= (8 − 3 + 10) % 10","= 15 % 10 = 5","即队列中有 5 个元素。"]},"pit":"取模别忘了加 M 防负；判空判满条件不能相同。"},{"t":"pt","no":"题型4","name":"栈与队列的应用场景判断","feature":"判断某问题是栈还是队列适用。","method":"后进先出→栈；先进先出→队列。","steps":["分析数据处理的顺序特征","递归、括号、表达式、回溯→栈","调度、缓冲、层次遍历→队列","判断即可选定结构"],"ex":{"q":"操作系统中的作业调度缓冲区，最适合用（ ）。","steps":["调度按到达先后处理","先进先出","对应队列","答案：队列。"]},"pit":"递归本质用栈；层次遍历用队列，别混。"},{"t":"tip","text":"<b>第3章解题总流程：</b>①出栈序列用栈模拟；②括号/表达式用栈；③循环队列记三个公式；④应用场景看 FIFO/LIFO。"},{"t":"kw","items":["LIFO","FIFO","循环队列","括号匹配","两栈实现队列"]}]},"d4":{"no":"4","title":"串","tag":"第4章","sub":"课本第4章。串是字符的线性表，重点是模式匹配（BF 与 KMP）。","blocks":[{"t":"sh","no":"4.1","title":"串的定义"},{"t":"tx","h":"串的定义与模式匹配","p":"<b>串</b>是由零个或多个字符组成的有限序列。<b>模式匹配</b>：在主串中查找子串首次出现的位置，暴力算法 O(nm)。"},{"t":"tx","h":"KMP 算法","p":"KMP 利用已匹配信息(前缀函数 next 数组)，失配时主串指针不回溯，时间降到 O(n+m)。核心是求出模式串的 next 数组：next[j] = 最长相等前后缀长度。"},{"t":"dv","title":"推导：KMP 的 next 数组含义","steps":["暴力匹配失配时，主串指针 i 要回退，效率低","观察：已匹配的部分里，若存在相等的前缀和后缀，则可从该位置继续","next[j] 表示模式串前 j 个字符中，最长真前后缀的长度","失配时模式串指针跳到 next[j]，主串指针不动","从而避免重复比较，总时间为 O(n+m)"]},{"t":"fig","kind":"fig-kmp-mini","inline":true,"cap":"next 数组来自模式串自身的最长公共前后缀"},{"t":"sh","no":"4.2","title":"串的存储"},{"t":"tx","h":"顺序串","p":"用顺序表存放字符。<b>定长串</b>：char ch[MAXSIZE]（面试常问 varchar 与 char 的区别）；<b>不定长串</b>有两种记法——串尾加一个<b>结束标记</b>（如 '\\0'，不计入串长），或用<b>长度变量</b>记录串长。顺序串定位快、便于随机访问。"},{"t":"tx","h":"块链串","p":"用链表存字符，每个结点存放<b>多个字符</b>（称为块），即<b>块链串</b>。结点越大空间利用率越高但操作粒度越粗；结点为 1 时最灵活、指针开销也最大。字符串场景少用链式，多见于更复杂的数据结构。"},{"t":"sh","no":"4.3","title":"串的基本操作"},{"t":"tx","h":"常用操作","p":"<b>insert(A,pos)</b> 在 pos 处插入 A；<b>remove(pos,len)</b> 删除从 pos 起的 len 个字符；<b>subString(pos,len)</b> 求子串；<b>concat(T)</b> 连接两串；<b>replace(T,V)</b> 用 V 替换所有不重叠的 T；<b>compare(S,T)</b> 从左到右比字符定大小；<b>equals(S,T)</b> 判相等（注意未重载 == 时不能直接比较内容）。"},
{"t":"ex","q":"【例】S = \"character\"：subString(2,3) 取到什么？insert / remove 的效果？","steps":["subString(2,3)：取位置 2 起 3 个字符 → \"ara\"","S.insert(\"rac\",3)：把 rac 插到第 3 位 → \"cha\"+\"rac\"+\"ter\" = \"character\"","S.remove(3,3)：删除从第 3 位的 3 个字符 → \"cha\"+\"ter\" = \"chater\""]},{"t":"sh","no":"4.4","title":"模式匹配算法"},{"t":"tx","h":"BF 朴素匹配","p":"把模式串 T 与主串 S 左对齐逐位比较，失配则 T 右移一位、主串指针 i 回退到本趟起点的下一位。最坏情况（如 S=\"000…001\"、T=\"000…1\"）每趟都在末尾失配，复杂度 <b>O(n×m)</b>。实现简单，是理解 KMP 的起点。"},{"t":"code","lang":"C · BF 暴力匹配","code":"int Index(char S[], char T[]){\n    int n = strlen(S), m = strlen(T);\n    int i = 0, j = 0;\n    while (i < n && j < m){\n        if (S[i] == T[j]) { i++; j++; }   /* 当前字符匹配，同步后移 */\n        else { i = i - j + 1; j = 0; }    /* 失配：i 回到本趟起点下一位 */\n    }\n    return (j == m) ? i - m : -1;         /* 匹配成功返回起始下标 */\n}"},{"t":"code","lang":"C · 求 KMP 的 next 数组","code":"void GenNext(char T[], int next[]){\n    int m = strlen(T);\n    next[0] = -1;\n    int i = 0, j = -1;\n    while (i < m - 1){\n        if (j < 0 || T[i] == T[j])\n            next[++i] = ++j;   /* 前后缀仍相等：长度 +1 */\n        else\n            j = next[j];       /* 不等：回退到更短的前后缀 */\n    }\n}"},{"t":"tx","h":"Sunday 算法","p":"基于<b>单字符跳跃表</b>：匹配失败时看主串中参与对齐的下一字符 ch，若 ch 在模式串中出现，则跳到最后一次出现处对齐；否则整串跳过。构造 skipTable 只需一趟扫描，<b>最好情况 O(n/m)</b>，在“在长文本/图像中找目标”这类场景更接近人的直觉。"},{"t":"warn","text":"<b>易错点：</b>① 串的下标/子串概念与数组不同；② KMP 的 next 数组下标从 1 还是 0 起要看清题目约定。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第4章习题）"},{"t":"pt","no":"题型1","name":"串的模式匹配（BF 与 KMP）","feature":"求朴素匹配的比较次数，或求 next 数组、nextval。","method":"BF 逐个回退 O(mn)；KMP 利用 next 数组不回退主串 O(m+n)。","steps":["BF：失配时主串回溯到 i−j+2、模式串从头","KMP：失配时模式串按 next 滑动","next[j] = 最长相等前后缀长度 + 1","优化用 nextval 避免多次回退相同字符"],"ex":{"q":"求模式串 abab 的 next 数组（下标从 1 开始）。","steps":["next[1] = 0","next[2] = 1（'a'）","next[3] = 1（'ab' 无相等前后缀）","next[4] = 2（'aba' 前缀 a 后缀 a）。"]},"pit":"next 数组下标起点（0/1）因教材而异；nextval 是 next 的优化。"},{"t":"tip","text":"<b>第4章解题总流程：</b>①模式匹配分 BF/KMP，KMP 写 next/nextval；②注意 next 数组下标起点（0/1）按教材约定；③串是字符的线性表，下标/子串概念与一般线性表要区分。"},{"t":"kw","items":["串","模式匹配","BF","KMP","next数组","nextval"]}]},"d5":{"no":"5","title":"数组和广义表","tag":"线性","sub":"顺序存储·压缩存储·稀疏矩阵·广义表","blocks":[{"t":"sh","no":"5.1","title":"数组的定义和特点"},{"t":"tx","h":"数组是线性表的推广","p":"数组可以看成一种<b>特殊的线性表</b>：线性表中的数据元素本身又是一个线性表。一维数组是普通线性表；二维数组可视为“每个元素是一维数组”的线性表；三维数组再套一层。<br>以 m 行 n 列的二维数组 A<sub>m×n</sub> 为例，它可以看作由 m 个行向量组成的线性表，每个行向量又是一个含 n 个元素的线性表。"},
{"t":"tb","head":["维度","结构形式","元素个数"],"rows":[["一维数组","a<sub>0</sub>, a<sub>1</sub>, …, a<sub>n-1</sub>","n"],["二维数组","m 个行向量，每个行向量 n 个元素","m×n"],["三维数组","m 个二维数组（面），每面 p 行 q 列","m×p×q"]]},{"t":"tx","h":"两个必须记住的特点","p":"<b>① 数组结构固定</b>：数组一旦定义，维数和各维长度就确定了，元素个数不能增减——这一点与线性表可以插入删除不同。<br><b>② 数据元素同构</b>：同一数组中所有元素的数据类型相同，每个元素占用的存储单元数一致。<br>正因为“结构固定 + 元素同构”，数组才能用<b>公式直接算出</b>任一元素的存储地址，实现 O(1) 随机存取。"},{"t":"tb","head":["对比项","线性表","数组"],"rows":[["长度","可变（可插入、删除）","固定（定义后不变）"],["元素类型","同一线性表内相同","必须完全相同（同构）"],["存取方式","顺序表随机 / 链表顺序","一律随机存取，靠地址公式"],["逻辑关系","一对一前驱后继","每个元素可有多个直接前驱/后继"]]},{"t":"ex","q":"设二维数组 A[1..6][1..8]，每个元素占 4 个字节，首元素 A[1][1] 的地址为 1000。分别求按行序、按列序存储时 A[4][5] 的地址。","steps":["按行序为主序：A[4][5] 之前已有 3 整行，每行 8 个元素，本行内前面还有 4 个元素。","元素偏移个数 = (4−1)×8 + (5−1) = 24 + 4 = 28。","地址 = 1000 + 28×4 = 1000 + 112 = <b>1112</b>。","按列序为主序：之前已有 4 整列，每列 6 个元素，本列内前面还有 3 个元素。","元素偏移个数 = (5−1)×6 + (4−1) = 24 + 3 = 27。","地址 = 1000 + 27×4 = 1000 + 108 = <b>1108</b>。","结论：同一个 A[4][5]，两种次序算出的地址不同——<b>先判断题干按行还是按列</b>，这是唯一的分岔点。"]},{"t":"sh","no":"5.2","title":"数组的运算"},{"t":"tx","h":"五类常见运算","p":"课件把数组运算归为五组，考试里最常考的是“按维度变换后元素位置怎么变”。"},{"t":"tb","head":["运算类别","典型操作","说明"],"rows":[["索引元素","A[i][j] / A[i,j]","按行列下标直接定位，靠地址公式 O(1) 完成"],["转置 / 重排","transpose、permute","交换维度次序，如把 [行,列] 变成 [列,行]"],["形状重排","reshape","元素总个数不变，只改维度划分方式"],["连接 / 堆叠 / 切割","concatenate、stack、split","沿某维拼接或拆分，维度要匹配"],["统计运算","min、max、sum、mean、argmax、var","沿指定维度聚合，结果维度降一"]]},{"t":"ex","q":"神经网络训练中，一批图像按 [样本数, 行, 列, 通道] 存放（RGB 三通道连续排列）。若要把通道维提到前面变成 [样本数, 通道, 行, 列]，应如何重排维度？","steps":["原维度编号：0=样本数，1=行，2=列，3=通道。","目标顺序：样本数 → 通道 → 行 → 列，即取原维度 0、3、1、2。","所以调用 transpose 时维度参数写成 <b>[0,3,1,2]</b>。","元素总个数不变（只是下标映射变了），因此这是一次“重排”而非“复制增删”。","要点：重排只改维度次序，reshape 只改维度划分，二者都不改变元素个数。"]},{"t":"sh","no":"5.3","title":"数组的顺序存储结构"},{"t":"tx","h":"为什么能随机存取","p":"数组结构固定、元素同构，所以只要知道首地址和每个元素占多少单元，就能用一条公式算出任意元素的地址——不需要从头遍历。这就是数组能 O(1) 随机存取的根本原因。<br>两种次序约定：<b>以行序为主序</b>（先存完第 1 行再存第 2 行，C/Pascal 采用）与<b>以列序为主序</b>（先存完第 1 列再存第 2 列，FORTRAN 采用）。"},{"t":"dv","title":"推导 1：行序为主序的地址公式（a<sub>ij</sub>，i=1..m，j=1..n，每元素 L 字节）","steps":["<b>第 1 步 数“整行”</b>：a<sub>ij</sub> 前面已经完整存过 i−1 行，每行 n 个元素，共 (i−1)·n 个元素。","<b>第 2 步 数“行内偏移”</b>：第 i 行内部，a<sub>ij</sub> 前面还有 j−1 个元素。","<b>第 3 步 合并偏移个数</b>：总偏移 = (i−1)·n + (j−1)。","<b>第 4 步 乘单元长度</b>：字节偏移 = [(i−1)·n + (j−1)]·L。","<b>第 5 步 加首地址</b>：Loc(a<sub>ij</sub>) = Loc(a<sub>11</sub>) + [(i−1)·n + (j−1)]·L。","<b>注意符号</b>：这里的 n 是<b>列数</b>（每行几个元素），不是行数——这是最常见的错项。若写成 (i−1)·m 就错了。"]},
{"t":"dv","title":"推导 2：列序为主序的地址公式（同一 a<sub>ij</sub>）","steps":["<b>第 1 步 数“整列”</b>：a<sub>ij</sub> 前面已经完整存过 j−1 列，每列 m 个元素，共 (j−1)·m 个。","<b>第 2 步 数“列内偏移”</b>：第 j 列内部，a<sub>ij</sub> 前面还有 i−1 个元素。","<b>第 3 步 合并</b>：总偏移 = (j−1)·m + (i−1)。","<b>第 4 步 加首地址</b>：Loc(a<sub>ij</sub>) = Loc(a<sub>11</sub>) + [(j−1)·m + (i−1)]·L。","<b>记忆法</b>：行序公式里“行号乘列数”，列序公式里“列号乘行数”——乘的永远是<b>另一维</b>的长度。"]},{"t":"tb","head":["约定","存储顺序","地址公式","典型语言"],"rows":[["行序为主序","a<sub>11</sub>,a<sub>12</sub>,…,a<sub>1n</sub>,a<sub>21</sub>,…","Loc(a<sub>11</sub>) + [(i−1)·n + (j−1)]·L","C / Pascal / Java"],["列序为主序","a<sub>11</sub>,a<sub>21</sub>,…,a<sub>m1</sub>,a<sub>12</sub>,…","Loc(a<sub>11</sub>) + [(j−1)·m + (i−1)]·L","FORTRAN"]]},{"t":"warn","text":"① 公式里的 m、n 别搞反：行序乘列数 n，列序乘行数 m。② 若数组下标从 0 开始（C 语言），公式中的 (i−1) 要换成 i、(j−1) 换成 j，否则整体错一位。③ 题目给的“每个元素占 k 个单元”要乘进去，漏乘是最常见的扣分点。"},{"t":"sh","no":"5.4","title":"矩阵的压缩存储"},{"t":"tx","h":"为什么要压缩","p":"矩阵里常有大量<b>值相同或恒为零</b>的元素（对称矩阵一半重复、三角矩阵一半是常数、稀疏矩阵几乎全是 0）。压缩存储就是只存“有用的那部分”，再用下标映射公式换算出原矩阵中的位置。<br>代价是：不再能直接按下标随机存取原矩阵，必须经过映射计算；但只要映射是线性的，仍是 O(1)。"},{"t":"tx","h":"对称矩阵：只存下三角（含主对角线）","p":"n 阶对称矩阵满足 a<sub>ij</sub> = a<sub>ji</sub>，所以只需存 i≥j 的那一半，共 n(n+1)/2 个元素。按行序存入一维数组 sa，需要把二维下标 (i,j) 映射成一维下标 k。"},{"t":"dv","title":"推导：对称矩阵的下标映射 k = i(i−1)/2 + (j−1)（i≥j，k 从 0 起）","steps":["<b>第 1 步 数前面完整的行</b>：第 1 行存 1 个，第 2 行存 2 个，……，第 i−1 行存 i−1 个。","<b>第 2 步 累加</b>：前面 i−1 行共 1+2+…+(i−1) = (i−1)·i/2 个元素。","<b>第 3 步 加行内偏移</b>：第 i 行内，a<sub>ij</sub> 前面还有 j−1 个元素。","<b>第 4 步 得映射式</b>：k = i(i−1)/2 + (j−1)。","<b>第 5 步 验算</b>：i=1,j=1 → k=0 ✓（第一个元素）；i=2,j=1 → k=1 ✓；i=3,j=3 → k=3·2/2+2=5，而前两行共 1+2=3 个，第 3 行第 3 个正是第 6 个（k=5）✓。","<b>下三角以外的元素</b>：若 i&lt;j，则利用对称性换成 a<sub>ji</sub> 再套公式，即 k = j(j−1)/2 + (i−1)。","<b>总容量</b>：n(n+1)/2 个元素。"]},{"t":"tx","h":"三角矩阵：下三角 + 一个常数","p":"下三角矩阵中，主对角线以下（含）是数据，以上全是同一个常数 c。因此存 n(n+1)/2 个数据元素，另外用<b>一个单元</b>存常数 c，总容量 n(n+1)/2 + 1。下三角部分的下标映射与对称矩阵完全相同：k = i(i−1)/2 + (j−1)（i≥j）；i&lt;j 时直接取常数单元。"},{"t":"dv","title":"推导：上三角矩阵按行序压缩（k 从 0 起）","steps":["<b>第 1 步 数前面完整的行</b>：第 1 行存 n 个，第 2 行存 n−1 个，……，第 i−1 行存 n−i+2 个。","<b>第 2 步 累加</b>：共 n + (n−1) + … + (n−i+2) = (i−1)(2n−i+2)/2 个。","<b>第 3 步 加行内偏移</b>：第 i 行从第 i 列开始存，a<sub>ij</sub> 前有 j−i 个元素。","<b>第 4 步 得映射式</b>：k = (i−1)(2n−i+2)/2 + (j−i)，要求 i≤j。","<b>第 5 步 验算</b>：n=3，i=1,j=1 → k=0 ✓；i=1,j=3 → k=2 ✓；i=2,j=2 → (1)(6−2+2)/2=3，加 0 = 3 ✓（第 4 个元素）。","<b>要点</b>：上三角每行长度递减，所以累加项是等差求和，不要照抄下三角的 i(i−1)/2。"]},{"t":"tx","h":"对角矩阵（带状矩阵）",
"p":"只把主对角线及其两侧若干条对角线上的元素按行序存入一维数组，其余全为 0 不存。以最常见的<b>三对角矩阵</b>（半带宽为 1，即只有主对角线和上下各一条副对角线非零）为例，每行最多 3 个非零元，共 3n−2 个。"},{"t":"dv","title":"推导：三对角矩阵 Loc(a<sub>ij</sub>) = Loc(a<sub>11</sub>) + [2(i−1) + (j−1)]·L","steps":["<b>第 1 步 看每行存几个</b>：第 1 行只有 a<sub>11</sub>、a<sub>12</sub> 两个（无上一行），中间各行 3 个，最后一行 2 个。","<b>第 2 步 近似处理</b>：按“每行 3 个”统一计算，前 i−1 行占 3(i−1) 个位置，但这样每行都多算了行首那个不存在的位置。","<b>第 3 步 修正</b>：a<sub>ij</sub> 落在第 i 行内的第 (j−i+2) 个位置（j−i = −1,0,1）。合并前 i−1 行后得到一维下标 k = 3(i−1) + (j−i+1) = 2(i−1) + j。","<b>第 4 步 换成 1 起编号</b>：k′ = 2(i−1) + (j−1) + 1，故 Loc = Loc(a<sub>11</sub>) + [2(i−1) + (j−1)]·L。","<b>第 5 步 验算</b>：i=1,j=1 → 偏移 0 ✓；i=1,j=2 → 偏移 1 ✓；i=2,j=1 → 偏移 2 ✓（前两个是 a<sub>11</sub>,a<sub>12</sub>）；i=3,j=2 → 偏移 2·2+1=5 ✓。"]},{"t":"tb","head":["矩阵类型","只存哪些元素","元素个数","下标映射（按行序，k 从 0 起）"],"rows":[["对称矩阵","下三角（含对角线）","n(n+1)/2","i≥j：k = i(i−1)/2 + (j−1)；i&lt;j 换成 a<sub>ji</sub>"],["下三角矩阵","下三角 + 1 个常数","n(n+1)/2 + 1","i≥j：k = i(i−1)/2 + (j−1)；i&lt;j 取常数单元"],["上三角矩阵","上三角 + 1 个常数","n(n+1)/2 + 1","i≤j：k = (i−1)(2n−i+2)/2 + (j−i)"],["三对角矩阵","主对角线 + 上下各一条","3n − 2","|i−j|≤1：偏移 [2(i−1)+(j−1)]·L"]]},{"t":"ex","q":"已知 10 阶对称矩阵 A 按行序压缩存于一维数组 sa[0..54]，每个元素占 2 字节，sa 首地址为 200。求 A[6][4] 的地址。","steps":["先判断存哪一半：这里存下三角，A[6][4] 满足 i=6 ≥ j=4，可直接用公式。","套映射式：k = i(i−1)/2 + (j−1) = 6×5/2 + 3 = 15 + 3 = 18。","验算容量：n(n+1)/2 = 10×11/2 = 55 个元素，下标 0..54，k=18 在范围内 ✓。","地址 = 200 + 18×2 = 200 + 36 = <b>236</b>。","若题目问的是 A[4][6]（i&lt;j），则利用对称性转成 A[6][4]，答案相同——这正是对称矩阵压缩的意义。"]},{"t":"warn","text":"① 对称矩阵 i&lt;j 时必须先转成 a<sub>ji</sub> 再套公式，直接代 i、j 会算出负偏移。② 上三角与下三角的累加项完全不同，别混用 i(i−1)/2。③ 压缩后“元素个数”要单独记：对称/三角是 n(n+1)/2（三角再加 1 个常数单元），三对角是 3n−2。"},{"t":"sh","no":"5.5","title":"稀疏矩阵"},{"t":"tx","h":"定义与压缩原则","p":"<b>稀疏矩阵</b>：非零元个数远少于零元个数，且非零元分布没有规律。由于分布无规律，不能用下标公式映射，只能<b>把每个非零元的“行、列、值”一起存下来</b>。<br>压缩原则：存矩阵的行列维数 + 每个非零元的三元组 (行下标, 列下标, 值)。例如 M 由 {(1,2,12), (1,3,9), (3,1,−3), (3,6,14), (4,3,24), (5,2,18), (6,1,15), (6,4,−7)} 和维数 (6,7) 唯一确定。注意这里行、列下标习惯从 1 开始编号。"},{"t":"tb","head":["存储方式","结构要点","空间开销","适用场景"],"rows":[["三元组顺序表","data[0] 存 (行数,列数,非零元数)，其后存各三元组","3(tu+1) 个单元","非零元少、以整矩阵运算为主"],["行逻辑连接顺序表","三元组表 + rpos[] 记录每行第一个非零元位置","3(tu+1) + (行数+1)","需按行随机取（如稀疏矩阵相乘）"],["行指针单链表","每行一个单链表，行指针数组指向各行首结点","3t + m 个单元","非零元动态增删"],["十字链表","每结点含 row/col/val + down/right 两指针","每非零元 1 结点 + 行列头指针","非零元频繁变动、需按行列双向查找"]]},{"t":"tx","h":"行逻辑连接的顺序表（rpos 的作用）","p":"纯三元组表要取“第 i 行的所有非零元”，只能从头扫描，效率低。为此增加一个辅助数组 <b>rpos[i]</b>，记录第 i 行第一个非零元在三元组表中的位置。这样取某一行时直接从 rpos[i] 开始、到 rpos[i+1] 结束，不必从头扫。<br>典型应用是<b>两个稀疏矩阵相乘</b>：只有 A 的第 i 行与 B 的第 j 列中“列号 = 行号”的元素才相乘累加，rpos 让这个匹配过程变成顺序归并。"},
{"t":"tx","h":"链式存储与十字链表","p":"<b>行指针单链表</b>：为每一行建一个单链表，结点存 (列号, 值, next)，再用一个行指针数组指向各行第一个非零元；本行若无非零元则指针为空。所需存储单元个数为 <b>3t + m</b>（t 为非零元个数，m 为行数）。<br><b>十字链表</b>：每个非零元结点同时挂在“行链”和“列链”上，结点含 row、col、val 以及 down、right 两个指针；再设行头指针数组和列头指针数组。这样既能按行遍历也能按列遍历，适合非零元频繁插删的场合。"},{"t":"dv","title":"推导：一般转置算法为什么是 O(m×n)","steps":["<b>目标</b>：把 m 行 n 列的 A 转成 n 行 m 列的 B，规则 B[j][i] = A[i][j]。","<b>朴素写法</b>：双重循环，外层 row 从 0 到 n−1（B 的行），内层 col 从 0 到 m−1，逐个赋值 B[col][row] = A[row][col]。","<b>循环次数</b>：n × m 次，无论矩阵是否稀疏都要走满。","<b>复杂度</b>：T(n,m) = O(m×n)——对稀疏矩阵而言，明明只有 tu 个非零元，却要扫 m×n 个位置，绝大多数时间在搬 0。","<b>改进方向</b>：能否只处理 tu 个三元组？可以，这就是快速转置。"]},{"t":"dv","title":"推导：快速转置的 num[ ] 与 cpot[ ]（O(tu + n)）","steps":["<b>关键观察</b>：A 的第 col 列 → B 的第 col 行。所以 B 中元素是按“A 的列号”从小到大排列的。","<b>第 1 步 数每列非零元个数</b>：扫描 A 的三元组一次，num[A[p].j]++，得到 num[1..n]。","<b>第 2 步 定位每列在 B 中的起始位置</b>：第 1 列从 1 开始，cpot[1] = 1；之后 cpot[col] = cpot[col−1] + num[col−1]。","<b>第 3 步 一趟扫描直接落位</b>：再扫 A 的三元组，对每个 (i,j,v)，令 q = cpot[j]，把 (j,i,v) 放进 B 的第 q 个位置，然后 cpot[j]++。","<b>为什么对</b>：cpot[j] 始终指向“第 j 列下一个待放位置”，同一列的元素按 A 中的先后顺序依次排入，正好保持行序递增。","<b>复杂度</b>：数个数 O(tu)，求 cpot O(n)，落位 O(tu)，合计 O(tu + n)——只与非零元个数和列数有关，与 m×n 无关。"]},{"t":"ex","q":"设 A 为 6 行 7 列稀疏矩阵，三元组为 (1,2,12)、(1,3,9)、(3,1,−3)、(3,6,14)、(4,3,24)、(5,2,18)、(6,1,15)、(6,4,−7)。用快速转置求 B 中每列的起始位置及前 3 个落位结果。","steps":["第 1 步 数 num[ ]：第 1 列有 2 个（行 3、行 6），第 2 列有 2 个（行 1、行 5），第 3 列有 2 个（行 1、行 4），第 4 列有 1 个，第 5 列 0 个，第 6 列 1 个，第 7 列 0 个。","第 2 步 求 cpot[ ]：cpot[1]=1；cpot[2]=1+2=3；cpot[3]=3+2=5；cpot[4]=5+2=7；cpot[5]=7+1=8；cpot[6]=8+0=8；cpot[7]=8+1=9。","第 3 步 落位（按 A 的三元组顺序）：(1,2,12) → 列 2，q=cpot[2]=3，B 第 3 个放 (2,1,12)，cpot[2] 变 4。","(1,3,9) → 列 3，q=cpot[3]=5，B 第 5 个放 (3,1,9)，cpot[3] 变 6。","(3,1,−3) → 列 1，q=cpot[1]=1，B 第 1 个放 (1,3,−3)，cpot[1] 变 2。","依次处理完，B 的非零元按列号递增排列，行号在同列内递增，正好是转置矩阵的行序存储。","要点：cpot 是“写指针”，每放一个就自增；它初值靠 num 前缀和算出，所以整个算法只需两趟扫描。"]},{"t":"sh","no":"5.6","title":"广义表"},{"t":"tx","h":"定义：线性表的推广","p":"广义表（Lists）是线性表的一种推广：<b>允许元素本身又是一个广义表</b>，也允许出现空表。记作 L = (a<sub>1</sub>, a<sub>2</sub>, …, a<sub>n</sub>)，其中 a<sub>i</sub> 可以是单个元素（原子），也可以是一个子表。<br>例如 L = (1, 2, 3, (1, 2, (a, b)), 5, 4, ()) 就是一个合法广义表，最外层有 7 个元素，其中第 4 个是子表、第 7 个是空表。"},{"t":"tb","head":["概念","定义","上例中的值"],"rows":[["长度","最外层元素的个数","7"],["深度","括号嵌套的最大层数（原子深度为 0，空表深度为 1）","3（因为 (1,2,(a,b)) 里还套了 (a,b)）"],["表头 Head","取表的第一个元素（可以是原子，也可以是子表）","Head(L) = 1"],["表尾 Tail","去掉第一个元素后剩下的表（一定是个表，要加括号）","Tail(L) = (2, 3, (1,2,(a,b)), 5, 4, ())"]]},
{"t":"dv","title":"推导：怎样一步步求长度、深度与 Head / Tail","steps":["<b>求长度</b>：只数最外层被逗号分隔的项。L 中顶层是 1、2、3、(1,2,(a,b))、5、4、()，共 7 项，所以长度 = 7。注意括号内再多的内容都算一项。","<b>求深度</b>：从外向内数括号层数。最外层算 1 层；元素 (1,2,(a,b)) 又开 1 层，共 2 层；里面的 (a,b) 再开 1 层，共 3 层。原子本身深度记 0，空表 () 深度记 1。取最大值 → 深度 = 3。","<b>Head 操作</b>：只取第一个元素，不加括号：Head(L) = 1。若第一个元素是子表，则 Head 得到的是那个子表本身。","<b>Tail 操作</b>：删掉第一个元素，剩下的整体保留括号：Tail(L) = (2,3,(1,2,(a,b)),5,4,())。","<b>易错点</b>：Tail 的结果一定是表（要加括号），Head 的结果可能是原子也可能是表；长度看“顶层个数”，深度看“括号层数”，两者完全独立。"]},{"t":"ex","q":"已知 A = (a, (b, c))，B = ((), (a), ((a))) 。分别求 A、B 的长度与深度，并写出 head(A)、tail(A)、head(tail(A))。","steps":["A 的长度：顶层是 a 和 (b,c) 两项 → 长度 2。","A 的深度：最外 1 层，(b,c) 再 1 层 → 深度 2。","B 的长度：顶层是 ()、(a)、((a)) 三项 → 长度 3。","B 的深度：((a)) 有三层括号 → 深度 3。","head(A) = a（第一个元素，原子）；tail(A) = ((b,c))（只剩一个子表，外层还要括号）。","head(tail(A)) = head(((b,c))) = (b,c)。","要点：tail 之后外层括号不能省，否则 ((b,c)) 会错写成 (b,c)。"]},{"t":"sh","no":"5.7","title":"异构元素"},{"t":"tx","h":"同构与异构","p":"前面强调“数组元素同构”，是指同一数组内所有元素类型完全相同。而<b>异构</b>指一个结构里可以混放不同类型的元素——广义表正是最典型的异构结构：同一层里既有原子（整数、字符），又有子表。<br>在语言层面：C#/Java 的<b>值类型</b>（int、bool、struct）在内存中直接存值，长度固定、类型固定，天然同构；<b>引用类型</b>（class、数组、List）只存引用，指向的对象可以是不同类型，因而可以构造异构容器。<br>考试里常这样问：为什么数组能随机存取而广义表不能？因为数组同构 → 每元素等长 → 地址可算；广义表异构 → 元素长度不等、还可能是子表 → 只能靠指针逐层访问。"},{"t":"warn","text":"本章最容易混的三组概念：① <b>行序 vs 列序</b>——乘的是另一维长度；② <b>n(n+1)/2 与 3n−2</b>——前者是对称/三角矩阵的元素个数，后者是三对角矩阵；③ <b>长度 vs 深度</b>——长度数顶层项数，深度数括号层数，二者无固定关系。"},{"t":"pt","no":"1","name":"数组地址计算（行序 / 列序）","feature":"给出数组维度、首地址、元素长度，求某元素的存储地址。","method":"先判断行序还是列序，再数“整行/整列 + 行内/列内偏移”。","steps":["确认维数与各维长度，标清 m（行数）、n（列数）。","判断题目按行序还是列序（看存储顺序描述或语言）。","行序：偏移 = (i−1)·n + (j−1)；列序：偏移 = (j−1)·m + (i−1)。","地址 = 首地址 + 偏移 × 每元素字节数。","用首元素和末元素双向验算，防止差一位。"],"ex":{"q":"设 A[0..8][0..5] 按行序存储，首地址 100，每元素 1 字节，求 A[5][3] 的地址。","steps":["下标从 0 开始，行数 m=9，列数 n=6。","偏移 = 5×6 + 3 = 33。","地址 = 100 + 33 = 133。","验算：末元素 A[8][5] 偏移 = 8×6+5 = 53，总元素 54 个，地址 153，未越界 ✓。"]},"pit":"下标从 0 开始时公式里的 (i−1) 要换成 i，否则整体少算一行。"},{"t":"pt","no":"2","name":"压缩存储的下标映射","feature":"给出矩阵类型与压缩方式，求某元素在一维数组中的下标或地址。","method":"先判断属于哪一半，再用对应累加公式。","steps":["识别矩阵类型：对称、下三角、上三角、对角（带状）。","判断 (i,j) 落在存储区还是落在“另一半/常数区”。","对称矩阵 i&lt;j 先转成 a<sub>ji</sub>；三角矩阵 i 在常数区则返回常数的固定位置。","套公式：对称/下三角 k = i(i−1)/2+(j−1)；上三角 k = (i−1)(2n−i+2)/2+(j−i)；三对角偏移 2(i−1)+(j−1)。","按“地址 = 首地址 + k × 元素长度”换算，并检查 k &lt; 总容量。"],"ex":{"q":"20 阶上三角矩阵按行序压缩存储，求 A[3][15] 在一维数组中的下标（k 从 0 起）。","steps":["i=3 ≤ j=15，落在上三角存储区。","前 2 行共存 20+19 = 39 个元素。",
"行内偏移 = j−i = 15−3 = 12。","k = 39 + 12 = 51。","用公式核对：(i−1)(2n−i+2)/2 + (j−i) = 2×(40−3+2)/2 + 12 = 39 + 12 = 51 ✓。"]},"pit":"上三角每行长度递减，累加项是等差求和 (i−1)(2n−i+2)/2，不是 i(i−1)/2。"},{"t":"pt","no":"3","name":"稀疏矩阵转置（普通 / 快速）","feature":"给出三元组表，要求转置后的三元组表，或分析时间复杂度。","method":"普通算法按列扫，快速算法用 num/cpot 预定位。","steps":["普通转置：外层枚举列号 1..n，内层扫全部 tu 个三元组，把列为该号的取出 (j,i,v) 依次放入 B。","时间复杂度 O(n × tu)（或按朴素二维写法 O(m×n)）。","快速转置：先扫一遍统计 num[col]。","由 cpot[1]=1、cpot[col]=cpot[col−1]+num[col−1] 求出各列起始位置。","第二遍扫描按 cpot[j] 直接落位，并把 cpot[j] 自增。时间复杂度 O(tu + n)。"],"ex":{"q":"A 的 8 个非零元分布在第 1、2、3、4、6 列，各列个数为 2、2、2、1、1。求 B 中第 4 列的起始位置。","steps":["num：第 1 列 2、第 2 列 2、第 3 列 2、第 4 列 1，第 5 列 0，第 6 列 1。","cpot[1] = 1。","cpot[2] = 1+2 = 3；cpot[3] = 3+2 = 5；cpot[4] = 5+2 = 7。","所以第 4 列从 B 的第 7 个位置开始，该列只有 1 个元素，占第 7 位。","要点：cpot 是前缀和，不是累加个数，别把 num 直接当起始位置。"]},"pit":"cpot[1] 必须按存储起始下标写（三元组表 data[0] 存表头时，第 1 列从 1 开始），写成 2 会整体错位。"},{"t":"pt","no":"4","name":"广义表的长度、深度与 head/tail","feature":"给出广义表表达式，求长度、深度，或进行 head/tail 运算。","method":"长度数顶层逗号分隔项数，深度数括号层数。","steps":["长度：只数最外层元素个数，子表整体算 1 项。","深度：从最外层括号开始逐层向内数，取最大嵌套层数；原子深度 0，空表深度 1。","head：取第一个元素，不加外层括号。","tail：删掉第一个元素，剩余部分必须保留外层括号。","复合运算从内向外逐层做，每做一次 tail 都要核对括号是否还在。"],"ex":{"q":"L = ((a, b), (c, (d, e))) ，求 L 的长度、深度、head(L)、tail(L)。","steps":["长度：顶层是 (a,b) 和 (c,(d,e)) 两项 → 2。","深度：最外 1 层；两个子表各再 1 层，其中 (d,e) 再 1 层 → 最大 3 层。","head(L) = (a, b)。","tail(L) = ((c, (d, e)))——只剩一个子表，外层括号保留。","易错：head 作用在子表上时得到的是“去掉最外一层括号”的那个表，不是它的第一个原子。"]},"pit":"tail 的结果一定是表，必须带外层括号；把 ((c,(d,e))) 写成 (c,(d,e)) 就漏了一层。"},{"t":"tip","text":"第 5 章的计算题只有三类：数组地址（行/列序偏移）、压缩矩阵下标映射（对称/三角/三对角）、稀疏矩阵转置（num/cpot）。把三个公式背熟 + 各做两道题，本章计算题基本满分。"},{"t":"kw","items":["数组同构","行序为主序","列序为主序","对称矩阵压缩","三角矩阵","三对角矩阵","稀疏矩阵","三元组表","rpos","十字链表","快速转置","cpot","广义表","长度与深度","head/tail","异构元素"]}]},"d6":{"no":"6","title":"树和二叉树","tag":"第6章 · 当前","sub":"课本第6章(当前进度)。非线性结构的核心：树的定义、二叉树性质、四种遍历与递归操作。","blocks":[{"t":"sh","no":"6.1","title":"树的基本概念"},{"t":"tx","h":"树的定义与术语","p":"树是 n 个结点的有限集，有唯一的<b>根</b>，其余结点分成若干个互不相交的子树。术语：结点的度(子树数)、叶结点(度为0)、树的度(最大度)、层次、深度、森林(多棵树)。"},{"t":"sh","no":"6.2","title":"二叉树"},{"t":"tx","h":"定义与性质","p":"二叉树每个结点<b>至多两个子树</b>(左、右有序)。<b>满二叉树</b>每层都满；<b>完全二叉树</b>只有最下层右侧可缺，适合顺序存储。"},{"t":"fx","lines":["第 i 层最多 2^(i−1) 个结点","深度 k 的二叉树最多 2^k − 1 个结点","叶结点 n0 与双分支结点 n2：n0 = n2 + 1","n 个结点的完全二叉树深度 = ⌊log₂n⌋ + 1","完全二叉树(从1编号)：父 ⌊i/2⌋，左孩 2i，右孩 2i+1"]},{"t":"fig","kind":"fig-tree","cap":"二叉树结点计数：n0 叶 + n1 单分支 + n2 双分支；边数 n−1 = n1 + 2n2"},
{"t":"dv","title":"推导：n0 = n2 + 1","steps":["设结点总数 n = n0 + n1 + n2（叶、单分支、双分支数）","从“边数”看：每个结点(除根)都有一条入边，所以 边数 = n − 1","从“出度”看：边 = n1 + 2n2（单分支出1、双分支出2）","联立：n − 1 = n1 + 2n2","代入 n：n0+n1+n2 − 1 = n1+2n2 ⟹ <b>n0 = n2 + 1</b>"]},{"t":"sh","no":"6.3","title":"二叉树的遍历"},{"t":"tx","h":"四种遍历","p":"<b>先序</b>(根左右)、<b>中序</b>(左根右)、<b>后序</b>(左右根)、<b>层次</b>(逐层，用队列)。前三者深度优先(递归)，层次是广度优先。由中序 + 先序/后序可唯一确定二叉树(先序+后序不行)。"},{"t":"code","lang":"C · 二叉树遍历(递归)","code":"typedef struct TNode { int data; struct TNode *l, *r; } TNode;\n\nvoid preOrder(TNode *t){        /* 根左右 */\n    if (t == NULL) return;\n    visit(t); preOrder(t->l); preOrder(t->r);\n}\nvoid inOrder(TNode *t){         /* 左根右 */\n    if (t == NULL) return;\n    inOrder(t->l); visit(t); inOrder(t->r);\n}\nvoid postOrder(TNode *t){       /* 左右根 */\n    if (t == NULL) return;\n    postOrder(t->l); postOrder(t->r); visit(t);\n}"},{"t":"ex","q":"【典型例题】某二叉树先序为 ABDEC，中序为 DBEAC，求后序。","steps":["先序第一个 A 是根；在中序 DBEAC 中 A 把序列分成左 DBE 和右 C","左子树先序 BDE，中序 DBE → B 为根，D 左 E 右","右子树只有 C","后序 = 左右根，即 D→E→B→C→A","后序 = DEBCA。"]},{"t":"sh","no":"6.4","title":"线索二叉树与树、森林"},{"t":"tx","h":"线索化与树森转换","p":"<b>线索二叉树</b>利用空的指针域指向遍历前驱/后继，加快遍历。<b>树/森林与二叉树转换</b>口诀：“左孩子右兄弟”——结点的第一个孩子作左孩子，其余兄弟依次作右孩子。"},{"t":"sh","no":"6.5","title":"哈夫曼树"},{"t":"tx","h":"哈夫曼树与编码","p":"<b>哈夫曼树</b>是带权路径长度(WPL)最小的二叉树：每次选两个权最小的结点合并，重复至只剩一棵。用于<b>哈夫曼编码</b>(变长前缀码)，使出现频率高的字符编码短，压缩数据。"},{"t":"ex","q":"【典型例题】给定权值 {2,3,4,5}，构造哈夫曼树并求带权路径长度 WPL。","steps":["取最小的 2、3 合并为 5，集合变 {5,4,5}","取最小的 4、5 合并为 9，集合变 {5,9}","取 5、9 合并为 14(根)","WPL = 2×3 + 3×3 + 4×2 + 5×1? 按实际层数计算：2、3 在底层(长3)，4、5 次层","WPL = (2+3)×3 + (4+5)×2... 逐步按合并次序算得 WPL = 2×3+3×3+4×2+5×1；典型答案 WPL=32/33 视构造而定，方法即“每次合并最小的两个”。"]},{"t":"warn","text":"<b>易错点：</b>① 二叉树 ≠ 度为 2 的树(二叉树可空且有序)；② n0=n2+1 常考；③ 先序+后序不能唯一确定二叉树；④ 完全二叉树顺序存储下标从 1 起才好用 2i/2i+1。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第6章习题）"},{"t":"pt","no":"题型1","name":"二叉树性质计算（结点数/高度/叶子数）","feature":"求二叉树结点数、高度、叶子数、各类结点关系。","method":"n₀=n₂+1；满二叉树高度 h 有 2^h−1 个结点；完全二叉树按编号。","steps":["用 n₀ = n₂ + 1 联系叶子和双分支","总结点 n = n₀+n₁+n₂","第 i 层最多 2^(i−1) 个结点","完全二叉树用编号 i 判断左右孩子 2i、2i+1"],"ex":{"q":"一棵二叉树有 10 个度为 2 的结点，5 个度为 1 的结点，求叶子数。","steps":["n₀ = n₂ + 1","n₂ = 10","故 n₀ = 11","叶子结点 11 个。"]},"pit":"n₀=n₂+1 是二叉树通用性质；完全二叉树用编号定父子。"},{"t":"pt","no":"题型2","name":"二叉树的遍历（前/中/后/层序）","feature":"由遍历序列还原树，或写出某遍历序列。","method":"前序确定根、中序分左右；前序+中序 或 后序+中序 可唯一还原。","steps":["前序第一个（后序最后一个）是根",
"在中序中找根，划分左右子树","递归对左右子树重复","层序用队列逐层出队"],"ex":{"q":"前序 ABDECFG、中序 DBEAFCG，求后序。","steps":["前序首 A 为根","中序中 A 左边 DBE、右边 FCG","递归得左右子树后序","结果为 DEBFGCA。"]},"pit":"只知道前序+后序不能唯一确定二叉树；必须有中序。"},{"t":"pt","no":"题型3","name":"哈夫曼树与带权路径长度 WPL","feature":"构造哈夫曼树、求 WPL 或哈夫曼编码。","method":"每次取两个最小权值合并，直到只剩一棵；WPL = Σ权重×路径长。","steps":["所有权值作根结点","每次取最小的两个合并为新结点","重复直至合并为一棵树","WPL = 各叶权值 × 其深度之和"],"ex":{"q":"权值 {2,3,4,5} 构造哈夫曼树，求 WPL。","steps":["取 2,3 合成 5","权值变 {4,5,5}，取 4,5 合成 9","再取 5,9 合成 14","WPL = 2×2+3×2+4×… 计算得 (2+3)×2 + (4+5)×2 依结构定。"]},"pit":"哈夫曼树 WPL 最小；权值越大概率离根越近。"},{"t":"pt","no":"题型4","name":"树、森林与二叉树的转换","feature":"树/森林转二叉树，或还原。","method":"左孩子右兄弟表示法：长子作左孩子，其余兄弟依次作右孩子。","steps":["树转二叉树：结点左指针指第一个孩子","右指针指下一个兄弟","森林转二叉树：各树根互作兄弟连成右链","反向转换按规则还原"],"ex":{"q":"树的“左孩子右兄弟”表示中，某结点的右指针指向什么？","steps":["左指针指向第一个孩子","右指针指向下一个兄弟","这是孩子兄弟表示法","故右指针指向其兄弟。"]},"pit":"转换后二叉树的“右孩子”其实代表兄弟关系，别当真实右子树。"},{"t":"pt","no":"题型5","name":"二叉排序树（BST）的插入/删除/查找","feature":"构造 BST，或判断某序列是否构成 BST，或求查找长度。","method":"左<根<右；中序遍历得递增序列；删除分三种情况。","steps":["插入按大小逐层比较落位","查找路径即比较次数（ASL）","删除叶/单孩子/双孩子分别处理","双孩子用中序前驱或后继替换"],"ex":{"q":"判断序列 50,30,70,20,40 能否构成 BST？","steps":["50 为根","30<50 作左，70>50 作右","20<50 且 <30 作 30 左子","40>30 且 <50 作 30 右子，合法。"]},"pit":"删除双孩子结点要用中序前驱/后继填充，不能直接断链。"},{"t":"pt","no":"题型6","name":"平衡二叉树（AVL）与旋转","feature":"判断 AVL 是否平衡，或进行 LL/RR/LR/RL 旋转。","method":"平衡因子 = 左高 − 右高，绝对值 ≤ 1；失衡按类型旋转。","steps":["计算各结点平衡因子","找最小失衡子树根","判断是 LL/RR（单旋）还是 LR/RL（双旋）","旋转后更新高度与因子"],"ex":{"q":"插入后某结点左子树的右子树上插入导致失衡，应做哪种旋转？","steps":["失衡来自左子树的右侧","即 LR 型","先对左子树左旋","再对根右旋（先左后右）。"]},"pit":"LL/RR 单旋、LR/RL 双旋；旋转后要重新计算平衡因子。"},{"t":"pt","no":"题型7","name":"堆（大顶堆/小顶堆）的调整与建堆","feature":"判断是否堆，或建堆、插入、删除后的调整。","method":"大顶堆父≥子；建堆从最后一个非叶结点自下而上筛；插入/删除后再筛。","steps":["大顶堆：任一父结点 ≥ 孩子","建堆从 ⌊n/2⌋ 结点起向前调整","插入新元素到末尾再上浮","删除堆顶用末尾替换后下沉"],"ex":{"q":"序列 {3,1,6,5,2,9} 是否是大顶堆？","steps":["检查每个父与孩子","结点 3 的孩子有 6>3","违反大顶堆","故不是大顶堆。"]},"pit":"建堆从最后一个非叶结点开始向前；堆调整只在下沉路径上。"},{"t":"tip","text":"<b>第6章解题总流程：</b>①性质题用 n₀=n₂+1；②遍历还原必须有中序；③哈夫曼每次合并最小两个；④树/森林用孩子兄弟表示；⑤BST 中序递增、AVL 记旋转类型；⑥堆自下而上建、上浮下沉调。"},{"t":"kw","items":["二叉树性质","n0=n2+1","先中后序遍历","层次遍历","哈夫曼树","线索二叉树"]}]},"d7":{"no":"7","title":"图","tag":"第7章","sub":"课本第7章(拓展)。最灵活的结构，结点任意相连。存储、遍历、最短路/最小生成树是重点。","blocks":[{"t":"sh","no":"7.1","title":"图的定义和术语"},{"t":"tx","h":"基本术语","p":"图 G=(V,E)，分有向/无向、带权/无权。术语：顶点、边、度(无向)、入度/出度(有向)、路径、连通图、连通分量、生成树。"},{"t":"sh","no":"7.2","title":"图的存储结构"},{"t":"tb",
"head":["存储","空间","判边","遍历邻边"],"rows":[["邻接矩阵","O(n²)","O(1)","O(n)"],["邻接表","O(n+e)","O(度数)","O(度数)"]]},{"t":"sh","no":"7.3","title":"图的遍历"},{"t":"tx","h":"DFS 与 BFS","p":"<b>深度优先(DFS)</b>用栈/递归，深入到底再回溯；<b>广度优先(BFS)</b>用队列，逐层扩展。BFS 可求无权图最短路。两者时间复杂度：邻接矩阵 O(n²)、邻接表 O(n+e)。"},{"t":"code","lang":"C · DFS/BFS 骨架(邻接矩阵)","code":"#define N 100\nint g[N][N], vis[N], n;\n\nvoid dfs(int u){\n    vis[u] = 1; visit(u);\n    for (int v = 1; v <= n; v++)\n        if (g[u][v] && !vis[v]) dfs(v);\n}\nvoid bfs(int s){\n    int q[N], f = 0, r = 0;\n    vis[s] = 1; q[r++] = s;\n    while (f < r){\n        int u = q[f++]; visit(u);\n        for (int v = 1; v <= n; v++)\n            if (g[u][v] && !vis[v]) { vis[v] = 1; q[r++] = v; }\n    }\n}"},{"t":"sh","no":"7.4","title":"最小生成树与最短路径"},{"t":"tx","h":"四大算法","p":"<b>Prim</b>(从一个点出发逐步加最近点)与 <b>Kruskal</b>(按边权从小到大加不构成环的边)求最小生成树；<b>Dijkstra</b>(单源最短路，不能有负权)与 <b>Floyd</b>(多源最短路，三重循环)求最短路径。"},{"t":"ex","q":"【典型例题】Dijkstra 为什么不能处理负权边？","steps":["Dijkstra 每次贪心选“当前距离最小”的未确定点，断言其已最优","该断言依赖“边权非负”：否则先确定的点之后可能被负权边绕路变短","例：A→B=1，B→C=−5，则 C 经 B 反而更近","所以负权要用 Bellman-Ford；存在负环则无最短路解。"]},{"t":"warn","text":"<b>易错点：</b>① 无向图邻接矩阵对称、邻接表边存两次；② BFS 求无权最短路，DFS 不行；③ Dijkstra 不可有负权；④ 生成树恰有 n−1 条边且无环。"},{"t":"sh","no":"","title":"题型全解 · 本章能考到的所有题型（刷完 ≈ 刷完课本第7章习题）"},{"t":"dv","title":"推导：图的边数上界与度数公式","steps":["n 个顶点的<b>无向图</b>：每对顶点至多一条边 → e ≤ C(n,2) = <b>n(n−1)/2</b>（达到即无向完全图 K_n）。","n 个顶点的<b>有向图</b>：任意两顶点间可有方向相反的两条弧 → e ≤ <b>n(n−1)</b>。","度数之和：Σdeg(v) = <b>2e</b>——每条边给两个端点各贡献 1；有向图入度和 = 出度和 = e。","应用：判断存储结构——e ≪ n² 的稀疏图用邻接表（O(n+e)），稠密图用邻接矩阵（O(n²)）。","常考：无向图 n=6 时 e ≤ 15；若已知度数序列求边数，e = Σdeg/2。"]},{"t":"pt","no":"题型1","name":"图的基本概念与度数计算","feature":"求顶点的度、边数与度的关系，判断完全图边数。","method":"无向图 Σdeg = 2e；有向图 Σ入度 = Σ出度 = e；完全无向图 e = n(n−1)/2。","steps":["区分无向/有向图","无向：度数之和 = 2×边数","有向：入度和 = 出度和 = 边数","完全图按 n 套公式"],"ex":{"q":"无向图有 10 条边，则所有顶点度数之和为多少？","steps":["每条边贡献 2 个度","Σdeg = 2e","= 2×10 = 20","即度数之和为 20。"]},"pit":"无向图度和是边数 2 倍；有向图入度出度各等于边数。"},{"t":"pt","no":"题型2","name":"图的存储结构（邻接矩阵/邻接表）","feature":"画邻接矩阵/邻接表，或判断空间复杂度、适用场景。","method":"邻接矩阵 O(n²)、适合稠密图；邻接表 O(n+e)、适合稀疏图。","steps":["邻接矩阵：A[i][j]=1(或权) 表示边","无向图矩阵对称","邻接表：每个顶点挂一条边链","选择看图的稠密程度"],"ex":{"q":"含 n 个顶点的图用邻接矩阵存储，空间复杂度为？","steps":["邻接矩阵为 n×n","与边数无关","故空间 O(n²)","稀疏图浪费大。"]},"pit":"矩阵空间 O(n²) 与 e 无关；邻接表适合稀疏图。"},{"t":"pt","no":"题型3","name":"图的遍历（DFS/BFS）与生成树","feature":"写 DFS/BFS 序列，或求生成树、连通分量数。","method":"DFS 用栈/递归，BFS 用队列；遍历一次得一棵生成树。",
"steps":["DFS 沿一条路深入、回退","BFS 逐层访问","邻接表上 DFS/BFS 均为 O(n+e)","生成树边数 = n − 1（连通图）"],"ex":{"q":"对连通图做 DFS，按访问顺序可得到什么？","steps":["DFS 访问所有顶点","访问过程形成一棵树","即深度优先生成树","边数为 n−1。"]},"pit":"BFS 要用队列且访问标记、邻接矩阵上遍历为 O(n²)。"},{"t":"pt","no":"题型4","name":"最小生成树（Prim / Kruskal）","feature":"求最小生成树权值，或判断算法适用场景。","method":"Prim 从顶点扩展（O(n²)，适合稠密）；Kruskal 按边权排序加边（O(elog e)，适合稀疏）。","steps":["Prim：从任一顶点起，每次加连接已选集合的最小边","Kruskal：所有边排序，从小到大加不构成环的边","直到选中 n−1 条边","两者结果权值相同"],"ex":{"q":"稀疏图求最小生成树宜用哪种算法？","steps":["稀疏图边少 e 小","Kruskal 按边排序 O(elog e)","Prim 为 O(n²) 偏大","故宜用 Kruskal。"]},"pit":"最小生成树可能不唯一，但权值唯一；边数恒为 n−1。"},{"t":"pt","no":"题型5","name":"最短路径（Dijkstra / Floyd）","feature":"求单源或各顶点对最短路径。","method":"Dijkstra 求单源（不能负权）；Floyd 动态规划求任意两点。","steps":["Dijkstra：选最近未访问点，松弛邻边，重复","复杂度 O(n²)","Floyd：三重循环通过中间点松弛","D 矩阵与 P 路径矩阵同步更新"],"ex":{"q":"Dijkstra 算法能否处理含负权边的图？","steps":["Dijkstra 基于贪心","假设已确定的最短距离不再变短","负权边会破坏该假设","故不能用于负权图。"]},"pit":"Dijkstra 不适用负权；Floyd 可，但复杂度 O(n³)。"},{"t":"pt","no":"题型6","name":"拓扑排序与关键路径（AOV/AOE）","feature":"写拓扑序列，或求关键路径、最早/最迟时间。","method":"拓扑排序：每次输出入度为 0 的点；关键路径 = 最长路径，活动最早/最迟时间相等者为关键活动。","steps":["AOV 拓扑排序找入度 0 顶点","删除该点及其出边、更新入度","AOE 求各事件最早开始 ve 与最迟 vl","e(i)=l(i) 的活动在关键路径上"],"ex":{"q":"有向图存在环时，能否进行拓扑排序？","steps":["拓扑排序每步找入度 0 点","环中顶点入度始终不为 0","过程中断无法输出全部","故有环则不能拓扑排序。"]},"pit":"拓扑排序用于 AOV 判环；关键路径是 AOE 最长路径，非最短。"},{"t":"tip","text":"<b>第7章解题总流程：</b>①度数题无向 2e、有向各 e；②存储选择看稠密/稀疏；③DFS 栈、BFS 队列；④最小生成树稠密 Prim、稀疏 Kruskal；⑤最短路 Dijkstra 无负权、Floyd 全源；⑥拓扑排序判环，关键路径求最长。"},{"t":"kw","items":["邻接矩阵vs邻接表","DFS/BFS","Prim/Kruskal","Dijkstra/Floyd","负权限制"]}]},"d8":{"no":"9","title":"查找","tag":"核心 · 第9章","sub":"课本第9章。研究在查找表中定位关键字的方法：顺序、折半、分块、哈希。核心指标是平均查找长度 ASL，题目以「构造结构 + 算 ASL」为主。","blocks":[{"t":"sh","no":"9.1","title":"查找的基本概念与平均查找长度 ASL"},{"t":"ex","q":"【例题】对长度为 11 的有序表做二分查找，求等概率下查找成功的平均查找长度 ASL。","steps":[{"s":"画判定树：首查 mid = 6（第 1 层 1 个结点）","note":"每次 mid = ⌊(low+high)/2⌋"},{"s":"第 2 层：位置 3、9（2 个）；第 3 层：位置 1、4、7、10（4 个）","note":"左右子表递归折半"},{"s":"第 4 层：位置 2、5、8、11（4 个）","note":"1+2+4+4 = 11，正好放满"},{"s":"ASL = (1×1 + 2×2 + 3×4 + 4×4)/11 = (1+4+12+16)/11 = 33/11 = <b>3</b>","note":"层号就是各结点的比较次数"},{"s":"检验：二分查找 ASL ≈ log₂(n+1) − 1 = log₂12 − 1 ≈ 2.58，精确值 3 与之同阶 ✓"}]},{"t":"ex","q":"【例题】哈希表长 11，h(key) = key mod 11，线性探测法处理冲突。依次插入 13、24、35、46、57，求每个关键字的比较次数与成功 ASL。","steps":[{"s":"13：h = 2，直接命中 → 1 次","note":"13 mod 11 = 2"},{"s":"24：h = 2 冲突 → 探测 3，命中 → 2 次","note":"线性探测 +1"},
{"s":"35：h = 2 → 3（占）→ 4 命中 → 3 次","note":"连续跳过已占单元"},{"s":"46：h = 2 → 3 → 4 → 5 命中 → 4 次","note":"聚集现象开始"},{"s":"57：h = 2 → 3 → 4 → 5 → 6 命中 → 5 次","note":"57 mod 11 = 2"},{"s":"ASL_成功 = (1+2+3+4+5)/5 = <b>3</b>","note":"聚集使平均查找长度上升——这是线性探测的缺点"}]},{"t":"kw","items":[{"k":"查找表","d":"由同一类型数据元素构成的集合；分静态查找表（只查）与动态查找表（可插删）。"},{"k":"关键字","d":"数据元素中能唯一标识该元素的数据项（主关键字）；能标识若干元素的为次关键字。"},{"k":"平均查找长度 ASL","d":"ASL = Σ Pᵢ·Cᵢ，Pᵢ 为查第 i 个元素的概率，Cᵢ 为找到它所需的比较次数。是衡量查找算法效率的核心指标。"},{"k":"等概率假设","d":"默认每个元素被查概率相等，Pᵢ = 1/n，于是 ASL 就是“平均比较次数”。"}]},{"t":"fx","lines":["ASL 定义：ASL = Σ_{i=1}^{n} Pᵢ·Cᵢ","等概率时：ASL = (1/n)·Σ Cᵢ","查找成功 ASL 与查找失败 ASL 分别计算；有虚结点的判定树要算失败分支"]},{"t":"sh","no":"9.2","title":"顺序查找"},{"t":"dv","title":"推导：顺序查找的平均查找长度 ASL = (n+1)/2","goal":"目标：把“平均比几次”翻译成等差数列求和，得到顺序查找的 ASL。","steps":["顺序查找从表头逐个比较，第 i 个元素的比较次数 Cᵢ = i。","等概率下 Pᵢ = 1/n。","ASL = Σ (1/n)·i = (1/n)·(1+2+…+n)。","等差数列求和：1+2+…+n = n(n+1)/2。","故 ASL = (1/n)·n(n+1)/2 = (n+1)/2。"],"res":"结论：顺序查找成功 ASL=(n+1)/2，复杂度 O(n)；优点是无需有序、可用链式存储。"},{"t":"sh","no":"9.3","title":"折半查找（二分查找）"},{"t":"dv","title":"推导：折半查找 ASL ≈ log₂(n+1) − 1","goal":"目标：用“判定树”把折半查找的比较过程画成二叉树，再算平均深度。","steps":["折半查找每次取 mid=(low+high)/2 把区间一分为二，比较过程构成一棵判定树。","判定树是平衡的二叉排序树，近似满二叉树，n 个内部结点。","满二叉树第 k 层有 2^(k-1) 个结点，找到它们需比较 k 次。","高度 h ≈ ⌈log₂(n+1)⌉，故平均比较次数约为 h − 1。","结论：ASL ≈ log₂(n+1) − 1，时间复杂度 O(log₂n)。"],"res":"折半查找要求顺序存储且有序，插入删除不便。"},{"t":"tb","head":["方法","存储要求","平均 ASL","时间复杂度"],"rows":[["顺序查找","顺序或链式、无需有序","(n+1)/2","O(n)"],["折半查找","顺序存储且有序","log₂(n+1) − 1","O(log₂n)"],["分块查找","索引有序、块内可无序","√n + 1（理想）","O(√n)"]]},{"t":"fmt","title":"规范作答示范 · 折半查找过程与比较次数","q":"对有序表 {8,14,23,37,45,56,68,79} 折半查找关键字 56，写出比较过程与次数。","sol":["解：设 low=1，high=8。","第1次：mid=⌊(1+8)/2⌋=4，元素 37<56，故 low=mid+1=5。","第2次：mid=⌊(5+8)/2⌋=6，元素 56=56，查找成功。","共比较 2 次。","答：56 在第 6 位，折半查找需比较 2 次即可成功。"],"key":"规范点：① 每步写出 low、high、mid 的取值；② 说明比较后区间的收缩方向；③ 结尾给出“比较次数”与“位置”。"},{"t":"sh","no":"9.4","title":"分块查找（索引顺序查找）"},{"t":"tx","h":"分块查找思路","p":"把表分成若干块，块内可无序，但要求<b>“前一块的最大关键字 < 后一块的最小关键字”</b>（块间有序）。再建立索引表记录每块的起始位置与最大关键字。查找时先在索引表中确定块（可用折半），再在块内顺序查找。"},{"t":"dv","title":"推导：分块查找理想 ASL ≈ √n + 1","goal":"目标：块数 b 与块长 s 一起决定总比较次数，求使 ASL 最小的分块方案。","steps":["在索引表中确定块，平均比较 s/2 次（块内顺序）；在索引中平均比较 (b+1)/2 次。","总 ASL ≈ (b+1)/2 + (s+1)/2，其中 n = b·s。","固定 n，ASL 关于 b、s 在下述条件下取最小：b·s = n 且 b ≈ s。","解得 s = b = √n。","代回得 ASL ≈ (√n+1)/2 + (√n+1)/2 = √n + 1。"],"res":"结论：应使“块数 ≈ 块长 ≈ √n”，此时分块查找最省比较。"},{"t":"sh",
"no":"9.5","title":"哈希表（散列表）"},{"t":"kw","items":[{"k":"哈希函数","d":"把关键字映射为存储地址：H(key)。常用除留余数法 H(key)=key mod p（p 取不大于表长的质数）。"},{"k":"冲突（碰撞）","d":"不同关键字算出同一地址。需用冲突处理方法解决。"},{"k":"开放定址法","d":"线性探测 Hᵢ=(H(key)+dᵢ) mod m，dᵢ=1,2,…；也有二次探测、伪随机探测。"},{"k":"链地址法","d":"同地址的关键字挂成单链表（拉链法）；不发生“堆积”，删插方便。"},{"k":"装填因子","d":"α = 表中记录数 n / 表长 m；α 越大冲突越多，ASL 越大。"}]},{"t":"dv","title":"推导：哈希查找的平均查找长度随装填因子的关系","goal":"目标：说明为什么哈希查找的 ASL 只取决于装填因子 α，而与表长 n 无关。","steps":["设表长 m、记录数 n，装填因子 α = n/m（0<α<1）。","用线性探测法，所有地址等概率取到，可推得查找成功平均探测次数约为：ASL_成功 ≈ ½(1 + 1/(1−α))。","查找失败平均探测次数约为：ASL_失败 ≈ ½(1 + 1/(1−α)²)。","两式都只含 α，不含 n 或 m。","故 ASL 只由装填因子决定：α 越小越省查找，但空闲空间越多。"],"res":"这是哈希表的本质优点：把“与 n 相关”的查找降到“与 α 相关”。"},{"t":"fig","kind":"fig-hash-mini","inline":true,"cap":"装填因子越大，冲突越多，ASL 越大"},{"t":"fmt","title":"规范作答示范 · 构造哈希表并算 ASL","q":"关键字序列 {19,14,23,1,68,20,84}，表长 m=13，H(key)=key mod 13，用线性探测法处理冲突，构造哈希表并求查找成功的 ASL。","sol":["解：依次计算 H(key)=key mod 13，冲突则线性探测后移。","19→6；14→1；23→10；1→1 冲突→2；68→3；20→7；84→6 冲突→7 冲突→8。","各关键字比较次数：19(1)、14(1)、23(1)、1(2)、68(1)、20(1)、84(3)。","ASL = (1+1+1+2+1+1+3)/7 = 10/7 ≈ 1.43。","答：查找成功 ASL ≈ 1.43。"],"key":"规范点：① 逐个列 H(key)；② 遇冲突明确写“探测几次”；③ ASL 用 Σ比较次数 ÷ 元素个数；④ 结尾“答”。"},{"t":"sh","no":"9.6","title":"题型全解 · 本章能考到的所有题型"},{"t":"pt","no":"题型1","name":"折半查找的 ASL 或比较次数计算","feature":"给定有序表与查找目标，求比较次数，或求平均查找长度。","method":"画判定树/逐次取 mid，数比较次数；ASL 取各结点深度平均。","steps":["写出 low、high，逐步取 mid","按大小决定走左还是右子树","记录比较次数","ASL = Σ(所在层数)/n"],"ex":{"q":"有序表 11 个元素，折半查找成功时的最大比较次数是多少？","steps":["判定树高度 h=⌈log₂(11+1)⌉=4","最深结点在第 4 层","比较次数 = 深度 = 4","故最多比较 4 次。"]},"pit":"判定树层次数从 1 计；别把 O(log n) 当成具体次数。"},{"t":"pt","no":"题型2","name":"哈希表构造 + 冲突处理 + ASL","feature":"给定哈希函数与冲突方法，构造哈希表并求 ASL。","method":"逐个算 H(key)，冲突按指定方法探测，统计各关键字比较次数。","steps":["算每个关键字的 H(key)","冲突则按线性/二次探测/链地址处理","记录每个关键字的比较次数","ASL = Σ比较次数 / n"],"ex":{"q":"链地址法处理冲突，查找失败 ASL 如何近似？","steps":["失败时遍历到某地址的空指针","平均链长 = α = n/m","失败 ASL 与 α 同阶","故 ASL 只与装填因子有关。"]},"pit":"线性探测会产生“堆积”，链地址法不会；别混用公式。"},{"t":"pt","no":"题型3","name":"顺序查找的平均查找长度","feature":"求顺序查找成功/失败的 ASL。","method":"成功 ASL=(n+1)/2；失败需比较 n 次（到哨兵/表尾）。","steps":["成功：第 i 个比较 i 次，等概率取平均","得 (n+1)/2","失败：走完整表，C=n","对照有序/无序不同"],"ex":{"q":"n=10 的顺序表，查找成功 ASL 为多少？","steps":["ASL_成功=(n+1)/2","=(10+1)/2","=5.5","即平均比较 5.5 次。"]},"pit":"失败 ASL 与成功 ASL 不同，要看题干问哪个。"},{"t":"pt","no":"题型4","name":"分块查找的顺序/ASL","feature":"分块查找的比较次数与最优分块。","method":"先索引后块内，(b+1)/2+(s+1)/2，最优 b≈s≈√n。","steps":["确定块数 b 与块长 s",
"索引内平均 (b+1)/2","块内平均 (s+1)/2","总 ASL 求和并优化"],"ex":{"q":"n=100 的分块查找，最优每块长度约多少？","steps":["ASL=(b+1)/2+(s+1)/2 最小","当 b·s=100 且 b≈s","s≈√100=10","故每块约 10 个元素。"]},"pit":"分块要求“块间有序”，块内可无序，这是与折半的关键区别。"},{"t":"warn","text":"<b>典型易错：</b>① 折半查找要求“顺序存储且有序”，链式/无序表不能用；② ASL 要区分成功与失败（失败含虚结点）；③ 哈希 ASL 只与装填因子 α 有关，把 n 代进去就错；④ 线性探测会产生堆积、二次探测/链地址能减轻；⑤ 折半查找的比较次数是判定树深度，不是 log₂n 的近似值本身。"},{"t":"tip","text":"<b>第9章解题流程：</b>① 先看查找表是否有序、是否顺序存储 → 决定能否折半；② 顺序/折半/分块 ASL 用对应公式；③ 哈希题：列 H(key)→按冲突法探测→统计比较次数→算 ASL；④ 书写：先写公式名→逐项代入→“答”。"}]},"d9":{"no":"10","title":"排序","tag":"核心 · 第10章","sub":"课本第10章。掌握插入、交换、选择、归并、基数五类排序的思想、每趟结果、复杂度与稳定性，是期末与考研的高频考点。","blocks":[{"t":"sh","no":"10.1","title":"排序的基本概念与稳定性"},{"t":"ex","q":"【例题】对序列 (49, 38, 65, 97, 76, 13, 27) 以 49 为枢轴做一趟快速排序，写出结果。","steps":[{"s":"枢轴 pivot = 49 暂存；i 指左端、j 指右端","note":"挖坑填数法"},{"s":"从右向左找 < 49：27 → 填到 i 处：27 38 65 97 76 13 _","note":"j 处留下新坑"},{"s":"从左向右找 > 49：65 → 填到 j 处：27 38 _ 97 76 13 65"},{"s":"从右：13 < 49 → 填到 i：27 38 13 97 76 _ 65"},{"s":"从左：97 > 49 → 填到 j：27 38 13 _ 76 97 65"},{"s":"i、j 相遇，枢轴 49 入坑：<b>(27, 38, 13) 49 (76, 97, 65)</b>","note":"49 已落在最终位置"},{"s":"之后对左右两个子序列各递归一趟即可"}]},{"t":"ex","q":"【例题】把序列 (16, 23, 53, 31, 94, 72) 建成大顶堆，写出初始堆。","steps":[{"s":"完全二叉树共 6 个结点，从最后一个非叶子结点（第 3 个，值 53）开始向下调整","note":"⌊n/2⌋ = 3"},{"s":"53 与子结点 72 比较：72 大 → 交换：(16, 23, 72, 31, 94, 53)"},{"s":"第 2 个结点 23：子结点 31、94，94 最大 → 交换：(16, 94, 72, 31, 23, 53)"},{"s":"第 1 个结点 16：子结点 94、72，与 94 交换：(94, 16, 72, 31, 23, 53)"},{"s":"16 继续下滤：与子结点 31、23 比较，31 大 → 交换：<b>(94, 31, 72, 16, 23, 53)</b>","note":"堆顶 94 为最大值 ✓"},{"s":"建堆完成；若继续堆排序：交换堆顶 94 与末尾 53，再对前 5 个重新调整"}]},{"t":"kw","items":[{"k":"内排序 / 外排序","d":"全部记录可在内存中处理为内排序；数据量大需借助外存为外排序。本章主要讲内排序。"},{"k":"稳定性","d":"若两记录关键字相等，排序后它们的相对次序不变，则该算法稳定；否则不稳定。"},{"k":"时间复杂度","d":"衡量排序效率，看比较与移动次数；空间复杂度看辅助存储。"},{"k":"基本操作","d":"比较两个关键字；移动/交换记录。绝大多数比较类排序下界为 O(nlog₂n)。"}]},{"t":"sh","no":"10.2","title":"插入排序"},{"t":"tx","h":"三类插入排序","p":"<b>直接插入排序</b>：把待排序记录逐个插入已排好序的子序列；<b>折半插入排序</b>：用折半查找确定插入位置，减少比较；<b>希尔排序</b>：按增量分组做插入排序，逐步缩小增量。"},{"t":"dv","title":"推导：直接插入排序的时间复杂度 O(n²)","goal":"目标：把“插入一次要移动多少”累计起来，得到总的移动/比较次数。","steps":["插入第 i 个记录时，最坏要与其前面 i−1 个比较并后移。","最坏比较次数：Σ_{i=2}^{n}(i) = 1+2+…+(n−1) ≈ n²/2。","移动次数在最坏情况下同阶，约 n²/2。","故最坏时间复杂度 O(n²)。","最好情况（已有序）比较 n−1 次、移动 0 次，为 O(n)。"],"res":"直接插入排序稳定、空间 O(1)；对“基本有序”的表效率很高。"},{"t":"sh","no":"10.3","title":"交换排序（冒泡 / 快速排序）"},{"t":"dv","title":"推导：快速排序的平均时间复杂度 O(nlog₂n)",
"goal":"目标：说明快排为什么平均比冒泡快得多。","steps":["快排每趟选一个枢轴，把序列分成“小于枢轴”和“大于枢轴”两部分，做一次划分 O(n)。","若每次划分较均衡（左右规模接近），递归深度为 log₂n 层。","每层总工作量 O(n)，层数约 log₂n。","故平均时间复杂度 O(nlog₂n)。","最坏情形（每次只分出 1 个元素，序列已基本有序）退化为 O(n²)。"],"res":"快排平均性能最好、原地（空间 O(log₂n) 栈），但<b>不稳定</b>。"},{"t":"fmt","title":"规范作答示范 · 快速排序第一趟划分","q":"对序列 {49,38,65,97,76,13,27} 以首元素为枢轴，写出快速排序第一趟划分后的结果。","sol":["解：选枢轴 pivot=49，设 low 指向首、high 指向尾。","从右向左找小于 49 的：27，放到 low 处 → 序列 .27,...","从左向右找大于 49 的：65，放到 high 处 → 序列 27,38,.,97,76,13,65","继续交替，最终枢轴归位到位置 3（下标）。","第一趟划分结果：{27,38,13,49,76,97,65}（49 左侧全小于它，右侧全大于它）。","答：一次划分后为 {27,38,13,49,76,97,65}。"],"key":"规范点：① 标明枢轴；② 写出 low/high 交替填坑过程；③ 枢轴最终位置要“左边小、右边大”；④ 结尾“答”。"},{"t":"sh","no":"10.4","title":"选择排序（简单选择 / 堆排序）"},{"t":"dv","title":"推导：建堆时间复杂度 O(n)、每次调整 O(log₂n)","goal":"目标：说明堆排序为什么总复杂度是 O(nlog₂n)。","steps":["堆是完全二叉树：大顶堆父≥子，小顶堆父≤子。","把无序序列建成堆：从最后一个非叶结点到根逐个“下沉”，总代价 O(n)。","每次取堆顶（最大/最小）后，把末尾元素换到堆顶再“下沉”调整，一次调整沿树高走，需 O(log₂n)。","共 n−1 次取堆顶，总代价 O(nlog₂n)。","故堆排序时间复杂度 O(nlog₂n)，空间 O(1)。"],"res":"堆排序<b>不稳定</b>；适合求“前 k 大/小”这类 Top-K 问题。"},{"t":"fig","kind":"fig-heap-mini","inline":true,"cap":"下沉调整 O(log₂n)，自底向上建堆 O(n)"},{"t":"sh","no":"10.5","title":"归并排序与基数排序"},{"t":"dv","title":"推导：归并排序时间复杂度 O(nlog₂n)","goal":"目标：用“递归深度 × 每层代价”说明归并排序的复杂度。","steps":["归并排序把序列一分为二，递归排序两半，再“合并”两个有序段。","合并 n 个元素一趟需 O(n)。","每次二分，递归深度为 log₂n 层。","每层合并总代价 O(n)，共 log₂n 层。","故总时间复杂度 O(nlog₂n)，需要 O(n) 辅助空间。"],"res":"归并排序是<b>稳定</b>的；基数排序按位分配收集，不比较关键字，稳定。"},{"t":"tb","head":["排序方法","平均时间","最坏时间","辅助空间","稳定性"],"rows":[["直接插入","O(n²)","O(n²)","O(1)","稳定"],["希尔排序","O(n^1.3)","O(n²)","O(1)","不稳定"],["冒泡排序","O(n²)","O(n²)","O(1)","稳定"],["快速排序","O(nlog₂n)","O(n²)","O(log₂n)","不稳定"],["简单选择","O(n²)","O(n²)","O(1)","不稳定"],["堆排序","O(nlog₂n)","O(nlog₂n)","O(1)","不稳定"],["归并排序","O(nlog₂n)","O(nlog₂n)","O(n)","稳定"],["基数排序","O(d(n+r))","O(d(n+r))","O(n+r)","稳定"]]},{"t":"fmt","title":"规范作答示范 · 判断某趟排序结果","q":"对序列 {49,38,65,97,76,13,27,49'} 用直接插入排序，写出前两趟结束后的序列。","sol":["解：直接插入排序把每个元素插入前面已排好的有序区。","初始有序区为 {49}。","第1趟：插入 38，得 {38,49,65,97,76,13,27,49'} 之前的 38<49，前移 → {38,49,65,97,76,13,27,49'}。","第2趟：插入 65，65>49 保持末尾 → {38,49,65,97,76,13,27,49'}。","答：前两趟结果为 {38,49,65,97,76,13,27,49'}（每趟仅扩展有序区一位）。"],"key":"规范点：① 明确“第几趟处理到哪个元素”；② 直接插入是“局部有序、逐步扩大”；③ 稳定性体现在相等元素次序不变（49 与 49'）。"},{"t":"sh","no":"10.6","title":"题型全解 · 本章能考到的所有题型"},{"t":"pt","no":"题型1","name":"写出某趟排序后的序列","feature":"给定初始序列与排序方法，写出第 k 趟（或第一趟划分）结果。","method":"抓每种排序“每趟做什么”：插入看扩展有序区、冒泡看最大沉底、选择看最小归位、快排看划分。",
"steps":["确认排序方法","按方法规则模拟第一趟/第 k 趟","注意稳定性（相等元素次序）","写出结果序列"],"ex":{"q":"{5,3,8,1} 用冒泡排序第一趟后结果？","steps":["相邻比较，大的后移","5>3 交换→3,5,8,1","5<8 不换","8>1 交换→3,5,1,8","最大 8 沉底，得 {3,5,1,8}。"]},"pit":"冒泡每趟把当前最大元素送到末尾；快排第一趟要写“划分”结果。"},{"t":"pt","no":"题型2","name":"各排序算法的复杂度和稳定性判断","feature":"给算法列表，判断时间复杂度、空间或稳定性。","method":"背熟对比表：O(nlog n) 的有快排/堆排/归并；稳定的有插入/冒泡/归并/基数。","steps":["看是否比较类、是否原地","对号入座复杂度","稳定性按定义判断","区分平均与最坏"],"ex":{"q":"下列排序中，稳定且有 O(nlog₂n) 平均时间的是？","steps":["O(nlog₂n)：快排/堆排/归并","快排不稳定、堆排不稳定","归并稳定","答案：归并排序。"]},"pit":"“快排平均最快但不稳定”，别把速度与稳定性混为一谈。"},{"t":"pt","no":"题型3","name":"快速排序的划分过程与枢轴位置","feature":"写出某趟划分结果或枢轴最终位置。","method":"双指针 low/high 交替填坑，使枢轴左侧全小、右侧全大。","steps":["取枢轴并记其值","右指针左移找小于枢轴的填左坑","左指针右移找大于枢轴的填右坑","直到 low=high，枢轴归位"],"ex":{"q":"快排最坏情况出现在什么序列？","steps":["每次划分只分出 1 个元素","递归深度退化为 n","比较次数 O(n²)","即序列基本有序/逆序时最坏。"]},"pit":"枢轴选择影响性能，三数取中可缓解最坏情形。"},{"t":"pt","no":"题型4","name":"堆的建立与 Top-K 问题","feature":"建堆、调整堆，或用堆求前 k 大/小元素。","method":"自下而上建堆 O(n)；取堆顶后下沉调整 O(log n)；Top-K 用大小为 k 的堆。","steps":["按父与子下标关系调整","从最后一个非叶结点向前下沉","取堆顶后用末尾元素替换再下沉","Top-K 维护 k 个元素的小顶堆"],"ex":{"q":"求 n 个数中最大的 10 个，用什么结构最省？","steps":["维护大小为 10 的小顶堆","遍历其余元素与堆顶比较","大于堆顶则替换并调整","复杂度 O(nlog 10)，很省。"]},"pit":"大顶堆求前 k 小、小顶堆求前 k 大，方向别搞反。"},{"t":"warn","text":"<b>典型易错：</b>① 混淆“稳定性”：快排/堆排/希尔/简单选择不稳定，插入/冒泡/归并/基数稳定；② 快排最坏 O(n²)、平均 O(nlog n)，别只记平均；③ 写某趟结果时方向错（冒泡最大沉底 vs 选择最小归位）；④ 归并需要 O(n) 辅助空间，别写成 O(1)；⑤ 希尔排序按增量分组，不是“插入排序的简单变体”。"},{"t":"tip","text":"<b>第10章解题流程：</b>① 先看问法——写某趟结果、判复杂度、判稳定性、还是划分/建堆；② 写趟数题按方法规则逐步模拟并保稳定次序；③ 复杂度与稳定性直接查对比表；④ 快排题画 low/high 填坑，堆题按父子下标调整；⑤ 书写：过程分步写清→给结果序列/复杂度→“答”。"}]}}},
  "pr": {"key":"pr","name":"概率论与数理统计","icon":"∑","book":"《概率论与数理统计》· 丘小玲 王锦荣 主编 · 高教社","prog":"全书 10 章已收录 · 当前在第 4 章","progPct":20,"intro":"按课本《概率论与数理统计》（丘小玲、王锦荣）章节顺序编排，覆盖全书第 1–10 章（概率论 1–5 章 + 数理统计 6–10 章）。本门以【规范作答格式】为主线：每个小节给公式与推导，并配「标准答卷示范」——把“设事件 → 写公式名 → 代入 → 答”的完整规范写法示范出来，另附典型易错题。","map":{"root":{"title":"概率论与数理统计","x":50,"y":14},"hubs":[{"id":"qh1","title":"概率论 (1–5章)","x":8,"y":36},{"id":"qh2","title":"数理统计 (6–10章)","x":8,"y":62}],"units":[{"id":"pr1","no":"1","title":"随机事件和概率","sub":"古典概型·条件概率·贝叶斯","tag":"基础","x":24,"y":36,"parent":"qh1"},{"id":"pr2","no":"2","title":"随机变量及其分布","sub":"分布函数·离散连续·正态","tag":"基础","x":41,"y":36,"parent":"qh1"},{"id":"pr3","no":"3","title":"多维随机变量及其分布","sub":"联合·边缘·独立性·卷积","tag":"基础","x":58,"y":36,"parent":"qh1"},{"id":"pr4","no":"4","title":"随机变量的数字特征","sub":"期望·方差·协方差·相关系数","tag":"当前","x":75,"y":36,"parent":"qh1","cur":true},{"id":"pr5","no":"5","title":"大数定律及中心极限定理","sub":"切比雪夫·辛钦·正态近似","tag":"极限","x":92,"y":36,"parent":"qh1"},{"id":"pr6","no":"6","title":"数理统计的基本概念","sub":"样本·χ²/t/F·抽样分布","tag":"统计","x":24,"y":62,"parent":"qh2"},{"id":"pr7","no":"7","title":"参数估计","sub":"矩估计·极大似然·区间估计","tag":"统计","x":41,"y":62,"parent":"qh2"},{"id":"pr8","no":"8","title":"假设检验","sub":"两类错误·U/t/χ²/F 检验","tag":"统计","x":58,"y":62,"parent":"qh2"},{"id":"pr9","no":"9","title":"方差分析及回归分析","sub":"单因素·双因素·一元回归","tag":"统计","x":75,"y":62,"parent":"qh2"},{"id":"pr10","no":"10","title":"R 软件在数理统计中的应用","sub":"R 基础·检验·回归","tag":"工具","x":92,"y":62,"parent":"qh2"}]},"units":{"pr1":{"no":"1","title":"随机事件和概率","tag":"基础 · 第1章","sub":"课本第1章。从「样本空间」出发，用集合语言描述随机事件，再引入概率的公理化定义，最后处理条件概率与全概率/贝叶斯。本章题目几乎都要「设事件→写公式→代入」，是本门最讲究书写规范的起点。","blocks":[{"t":"sh","no":"1.0","title":"答题格式总则（本门通用）"},{"t":"tx","h":"概率论答题的规范格式","p":"概率题的得分点常在“过程”而不只是“结果”。养成固定书写格式：<b>①解</b>——以“解”字开头；<b>②设</b>——把每个随机事件用字母设出来并写清含义（如“设 A = {产品为次品}”）；<b>③依据</b>——明确写出所用公式或定理名称；<b>④代入</b>——先列式子再代数值，不跳步；<b>⑤结论</b>——末尾用“答：……”给出完整结论。概率值一般写成分数或保留 4 位小数。"},{"t":"sh","no":"1.1","title":"随机事件、样本空间与事件关系"},{"t":"ex","q":"【例题】袋中有 5 个白球、3 个黑球，任取 2 个，求恰有 1 个白球的概率。","steps":[{"s":"古典概型：样本点总数 = C(8,2) = 28","note":"无序取球用组合数"},{"s":"有利事件数 = C(5,1)×C(3,1) = 5×3 = 15","note":"1 白 1 黑分别选"},{"s":"P = 15/28 ≈ <b>0.536</b>","note":"对照：2 白概率 C(5,2)/28 = 10/28，2 黑 3/28，三者之和 = 1 ✓"}]},{"t":"ex","q":"【例题】某产品由甲、乙两车间生产，甲占 60%（次品率 2%）、乙占 40%（次品率 5%）。任取一件发现是次品，求它来自甲车间的概率。","steps":[{"s":"设 B = 取到次品，A₁ = 甲产、A₂ = 乙产。先用全概率公式求 P(B)",
"note":"贝叶斯必配全概率"},{"s":"P(B) = P(A₁)P(B|A₁) + P(A₂)P(B|A₂) = 0.6×0.02 + 0.4×0.05 = 0.012 + 0.020 = <b>0.032</b>"},{"s":"贝叶斯公式：P(A₁|B) = P(A₁)P(B|A₁)/P(B) = 0.012/0.032 = <b>0.375</b>","note":"由果溯因"},{"s":"合理性检验：甲的次品贡献占比 0.012/0.032 < 60%，因为甲的次品率更低 ✓"}]},{"t":"kw","items":[{"k":"样本空间 Ω","d":"随机试验所有可能结果的集合；每个结果叫样本点 ω。Ω 是必然事件，∅ 是不可能事件。"},{"k":"事件的关系","d":"包含 A⊂B；相等 A=B；互斥 AB=∅（不能同时发生）；对立 A 与 Ā（A∪Ā=Ω 且 AĀ=∅）。"},{"k":"事件的运算","d":"和 A∪B、积 AB、差 A−B、对立 Ā；满足交换、结合、分配律与德摩根律：(A∪B)‾=Ā∩B̄，(AB)‾=Ā∪B̄。"},{"k":"互斥 vs 对立","d":"互斥只要求不能同时发生(AB=∅)；对立还要求二者之和为必然(A∪B=Ω)。对立必互斥，互斥未必对立。"}]},{"t":"fx","lines":["概率的公理化定义：非负性 P(A)≥0；规范性 P(Ω)=1；可列可加性（互斥事件之和的概率等于概率之和）","性质1  P(∅) = 0","性质2  P(Ā) = 1 − P(A)","性质3  加法公式  P(A∪B) = P(A) + P(B) − P(AB)；若 A、B 互斥则 P(A∪B)=P(A)+P(B)","性质4  P(A−B) = P(A) − P(AB)；若 B⊂A 则 P(A−B)=P(A)−P(B)"]},{"t":"sh","no":"1.2","title":"古典概型与几何概型"},{"t":"dv","title":"推导：古典概型公式 P(A)=m/n","goal":"古典概型要求：样本点有限且等可能。先把“等可能”翻译成“每个样本点概率相同”，就能推出这个最常用的公式。","steps":["设样本空间 Ω 有 n 个等可能样本点，则每个样本点概率 p 都相等。","由规范性：n·p = P(Ω) = 1，所以每个样本点概率 p = 1/n。","设事件 A 由 m 个样本点组成（A 与这 m 个点一一对应）。","由可加性：P(A) = m × (1/n) = m/n。"],"res":"结论：P(A) = A 所含样本点数 m ÷ 样本空间总数 n。几何概型把“点数”换成“长度/面积/体积”——P(A) = A 的测度 ÷ Ω 的测度。"},{"t":"sh","no":"1.3","title":"条件概率、乘法公式与独立性"},{"t":"kw","items":[{"k":"条件概率","d":"P(B|A) = P(AB)/P(A)（P(A)>0），表示“A 已发生”条件下 B 发生的概率。"},{"k":"乘法公式","d":"P(AB) = P(A)P(B|A) = P(B)P(A|B)（P(A)>0）。三个及以上事件可逐步展开。"},{"k":"独立性","d":"A、B 独立 ⇔ P(AB) = P(A)P(B) ⇔ P(B|A)=P(B)。独立是“信息不影响”,不是“互斥”。"},{"k":"易错","d":"P(A|B) 与 P(B|A) 一般不同；互斥与独立是两回事（互斥事件一般反而不独立）。"}]},{"t":"sh","no":"1.4","title":"全概率公式与贝叶斯公式"},{"t":"dv","title":"推导：全概率公式 P(B)=Σ P(Aᵢ)P(B|Aᵢ)","goal":"目标：把“复杂事件 B 的概率”拆成按原因 Aᵢ 分类的若干部分，逐块算再相加。","steps":["设 A₁,A₂,…,Aₙ 是一组完备事件组（两两互斥且并集为 Ω）。","B 一定“落在”某个 Aᵢ 里：B = B A₁ ∪ B A₂ ∪ … ∪ B Aₙ（各块两两互斥）。","由可加性：P(B) = Σ P(B Aᵢ)。","对每一项用乘法公式：P(B Aᵢ) = P(Aᵢ)P(B|Aᵢ)。","代回即得 P(B) = Σ P(Aᵢ)P(B|Aᵢ)。"],"res":"这就是“先分类、后加权”的思想：把 B 按“来源/原因”拆开。"},{"t":"dv","title":"推导：贝叶斯公式 P(Aᵢ|B)=P(Aᵢ)P(B|Aᵢ) / Σ P(Aⱼ)P(B|Aⱼ)","goal":"目标：已知“结果 B”发生了，反推“是哪个原因 Aᵢ 导致”的概率——即由结果反查原因。","steps":["由条件概率定义：P(Aᵢ|B) = P(AᵢB) / P(B)。","分子用乘法公式：P(AᵢB) = P(Aᵢ)P(B|Aᵢ)。","分母用全概率公式：P(B) = Σ P(Aⱼ)P(B|Aⱼ)。","代回即得贝叶斯公式。"],"res":"贝叶斯 = 乘法公式(分子) ÷ 全概率公式(分母)，本质是“用新信息更新旧概率”。"},{"t":"fmt","title":"规范作答示范 · 全概率公式","q":"某工厂两条生产线：甲线产量占 60%，次品率 1%；乙线产量占 40%，次品率 2%。从总产品中任取一件，求取到次品的概率。","sol":["解：设 A₁ = {产品来自甲线}，A₂ = {产品来自乙线}，B = {产品为次品}。","显然 A₁、A₂ 构成完备事件组，且已知：","P(A₁)=0.6，P(A₂)=0.4，P(B|A₁)=0.01，P(B|A₂)=0.02。",
"由全概率公式：P(B) = P(A₁)P(B|A₁) + P(A₂)P(B|A₂)","= 0.6 × 0.01 + 0.4 × 0.02 = 0.006 + 0.008 = 0.014。","答：任取一件取到次品的概率为 0.014。"],"key":"① 先设事件，把每个条件写成事件的概率；② 点明“完备事件组”；③ 写公式名再代入，不跳步；④ 结尾必须“答：”。"},{"t":"fmt","title":"规范作答示范 · 贝叶斯公式","q":"接上题：已知取到的一件是次品，求它是甲线生产的概率。","sol":["解：设 A₁={产品来自甲线}，A₂={产品来自乙线}，B={产品为次品}（如上一题）。","所求为条件概率 P(A₁|B)。","由贝叶斯公式：","P(A₁|B) = P(A₁)P(B|A₁) / [P(A₁)P(B|A₁) + P(A₂)P(B|A₂)]","= (0.6 × 0.01) / (0.6 × 0.01 + 0.4 × 0.02)","= 0.006 / 0.014 = 3/7 ≈ 0.4286。","答：取到次品来自甲线的概率约为 0.4286。"],"key":"贝叶斯题的关键：分子写“所求原因那一支”，分母写“结果的总概率（全概率）”，两者都要写出对应公式名。"},{"t":"warn","text":"<b>典型易错：</b>① 把“互斥”写成“独立”——A、B 互斥时一般 P(AB)=0≠P(A)P(B)，二者不同；② 条件概率方向写反，P(A|B) 与 P(B|A) 混淆；③ 全概率公式使用前没验证 Aᵢ 是否“完备且两两互斥”；④ 只写数值结果、不设事件不写公式，格式分全失。"},{"t":"tip","text":"<b>第1章解题流程：</b>① 判断题型——数点数(古典/几何)、条件概率、全概率还是贝叶斯；② 一律先“设事件”；③ 全概率“先分类后加权”，贝叶斯“由果查因”；④ 涉及“至少/至多”优先用对立事件 P(Ā)=1−P(A)；⑤ 书写五步：解→设→依据公式→代入→答。"}]},"pr2":{"no":"2","title":"随机变量及其分布","tag":"基础 · 第2章","sub":"课本第2章。把随机试验的结果“数值化”为随机变量 X，用分布函数 F(x) 统一描述；重点掌握离散型（二项、泊松）与连续型（均匀、指数、正态）三大分布，以及正态标准化和随机变量函数的分布。","blocks":[{"t":"sh","no":"2.1","title":"随机变量与分布函数"},{"t":"tx","h":"分布函数 F(x)=P(X≤x)","p":"分布函数是描述随机变量最通用的工具，离散型和连续型都能用它统一刻画。"},{"t":"fx","lines":["分布函数定义：F(x) = P(X ≤ x)，−∞<x<+∞","性质① 单调不减：若 x₁<x₂ 则 F(x₁) ≤ F(x₂)","性质② 右连续：F(x+0) = F(x)","性质③ 取值界：F(−∞)=0，F(+∞)=1，且 0 ≤ F(x) ≤ 1","求概率：P(a<X≤b) = F(b) − F(a)"]},{"t":"sh","no":"2.2","title":"离散型随机变量及其分布律"},{"t":"ex","q":"【例题】随机变量 X 的分布律为 P(X=0)=0.2，P(X=1)=0.5，P(X=2)=0.3，求分布函数 F(x)。","steps":[{"s":"分布函数 F(x) = P(X ≤ x)，按分段点 0、1、2 累加","note":"右连续，左闭右开分段"},{"s":"x < 0：F(x) = <b>0</b>"},{"s":"0 ≤ x < 1：F(x) = 0.2"},{"s":"1 ≤ x < 2：F(x) = 0.2 + 0.5 = 0.7"},{"s":"x ≥ 2：F(x) = 0.2 + 0.5 + 0.3 = <b>1</b>","note":"检验：0.2+0.5+0.3 = 1 ✓ 分布律规范性"}]},{"t":"ex","q":"【例题】设连续型随机变量 X 的概率密度 f(x) = kx（0≤x≤2），其余为 0。求常数 k 与 P(1<X<2)。","steps":[{"s":"归一性：∫₀² kx dx = k·[x²/2]₀² = 2k = 1 → <b>k = 1/2</b>","note":"密度函数积分为 1"},{"s":"P(1<X<2) = ∫₁² (x/2) dx = [x²/4]₁² = 1 − 1/4 = <b>3/4</b>"},{"s":"易错：连续型单点概率为 0，P(1<X<2) 与 P(1≤X≤2) 相同","note":"别纠结端点开闭"}]},{"t":"kw","items":[{"k":"分布律","d":"P(X=xₖ)=pₖ，满足 pₖ≥0 且 Σpₖ=1；分布律用表格或通项式写出。"},{"k":"0-1 分布","d":"X 只取 0、1：P(X=1)=p，P(X=0)=1−p，记 X~B(1,p)。"},{"k":"二项分布 B(n,p)","d":"n 重伯努利试验中成功次数：P(X=k)=Cₙᵏ pᵏ(1−p)ⁿ⁻ᵏ，k=0,1,…,n。"},{"k":"泊松分布 P(λ)","d":"P(X=k)=λᵏ e^(−λ)/k!，k=0,1,2,…；常描述单位时间/面积内的稀有事件计数。"},{"k":"关系","d":"当 n 大、p 小时，二项分布 B(n,p) 近似泊松分布 P(λ)，λ=np（泊松定理）。"}]},{"t":"sh","no":"2.3",
"title":"连续型随机变量与概率密度"},{"t":"kw","items":[{"k":"概率密度 f(x)","d":"f(x)≥0，∫_{−∞}^{+∞} f(x)dx = 1；P(a<X≤b)=∫ₐᵇ f(x)dx；F(x)=∫_{−∞}^{x} f(t)dt。"},{"k":"关键性质","d":"连续型在任一点的概率为 0：P(X=a)=0，所以 P(a<X<b)=P(a≤X≤b)。"},{"k":"均匀分布 U(a,b)","d":"f(x)=1/(b−a)（a<x<b），其余为 0；区间内取值等可能。"},{"k":"指数分布 E(λ)","d":"f(x)=λe^(−λx)（x>0），其余为 0；常用于寿命、等待时间。"},{"k":"正态分布 N(μ,σ²)","d":"f(x)=[1/(√(2π)σ)]·e^(−(x−μ)²/(2σ²))；μ 定中心、σ 定胖瘦；曲线关于 x=μ 对称。"}]},{"t":"dv","title":"推导：正态分布的标准化 Z=(X−μ)/σ","goal":"目标：把任意正态 X~N(μ,σ²) 变成标准正态 Z~N(0,1)，好查表求概率。本质是对 X 做“先平移、再缩放”。","steps":["设 X~N(μ,σ²)，令 Z = (X−μ)/σ（即先减 μ 再把尺度除以 σ）。","平移不改变“正态性”：X−μ 仍服从正态，中心移到 0。","缩放也不改变“正态性”：再除以 σ，方差变为 σ²/σ² = 1。","于是 Z 服从均值 0、方差 1 的正态分布，即 Z~N(0,1)。","求概率：P(a<X≤b)=P((a−μ)/σ < Z ≤ (b−μ)/σ)=Φ((b−μ)/σ)−Φ((a−μ)/σ)。"],"res":"查表工具：Φ(x)=P(Z≤x) 为标准正态分布函数，且 Φ(−x)=1−Φ(x)。"},{"t":"fmt","title":"规范作答示范 · 正态分布标准化求概率","q":"设 X~N(3,4)，求 P(2<X≤5)。（已知 Φ(0.5)=0.6915，Φ(1)=0.8413）","sol":["解：由 X~N(μ,σ²) 得 μ=3，σ²=4，故 σ=2。","标准化：令 Z=(X−3)/2，则 Z~N(0,1)。","P(2<X≤5) = P((2−3)/2 < Z ≤ (5−3)/2)","= P(−0.5 < Z ≤ 1) = Φ(1) − Φ(−0.5)。","因 Φ(−0.5)=1−Φ(0.5)=1−0.6915=0.3085，","故原式 = 0.8413 − 0.3085 = 0.5328。","答：P(2<X≤5) = 0.5328。"],"key":"规范点：① 先写出 μ、σ（注意 σ²=4 时 σ=2）；② 明确“标准化”这一步；③ 负值用 Φ(−x)=1−Φ(x) 化正；④ 结尾“答”。"},{"t":"sh","no":"2.4","title":"随机变量函数的分布"},{"t":"tip","text":"<b>记住即可 · 分布函数法（Y=g(X)）</b>求 Y=g(X) 的分布：先写 F_Y(y)=P(g(X)≤y)，把这个不等式化为关于 X 的区间，再代入 X 的分布函数并求导得密度。本门只需掌握这个套路与结果，不必逐步推导。"},{"t":"warn","text":"<b>典型易错：</b>① 把 σ² 当 σ 用（如 N(3,4) 中 σ=2 而非 4）；② 连续型误算端点概率（P(X=a) 恒为 0）；③ 认为概率密度 f(x) 必须 ≤1——f(x) 可大于 1，只有积分才等于 1；④ 求 Y=g(X) 分布时没有逐段讨论 g 的单调性。"},{"t":"tip","text":"<b>第2章解题流程：</b>① 判断离散/连续——离散用分布律求和，连续用密度积分；② 正态题一律先标准化再查表；③ 求 Y=g(X) 分布走“分布函数法”；④ 书写：先写清 μ、σ 或分布律，再列式，最后“答”。"}]},"pr3":{"no":"3","title":"多维随机变量及其分布","tag":"基础 · 第3章","sub":"课本第3章。研究 (X,Y) 的联合分布、边缘分布与独立性，并会求二维随机变量函数的分布（重点：和的卷积、最大值/最小值分布）。","blocks":[{"t":"sh","no":"3.1","title":"二维随机变量与联合分布"},{"t":"fx","lines":["联合分布函数：F(x,y) = P(X≤x, Y≤y)","性质：对 x、y 分别单调不减；关于 x、y 均右连续；F(−∞,y)=F(x,−∞)=0，F(+∞,+∞)=1","二维连续型联合密度 f(x,y)：F(x,y)=∫_{−∞}^{x}∫_{−∞}^{y} f(u,v)dv du，且 ∫∫ f(x,y)dxdy = 1","区域概率：P((X,Y)∈D) = ∬_D f(x,y) dxdy","二维均匀分布：在区域 D 上 f(x,y)=1/S_D（S_D 为 D 的面积），其余为 0"]},{"t":"sh","no":"3.2","title":"边缘分布"},{"t":"dv","title":"推导：由联合密度求边缘密度 f_X(x)=∫ f(x,y)dy","goal":"目标：从“联合”里把某一个变量“积分掉”，得到它单独的分布。","steps":["边缘分布函数定义：F_X(x) = P(X≤x) = P(X≤x, Y<+∞)。","对连续的 (X,Y)：F_X(x) = ∫_{−∞}^{x} [∫_{−∞}^{+∞} f(u,y)dy] du。",
"方括号内的量正是 f_X(u)，因为 F_X(x)=∫_{−∞}^{x} f_X(u)du。","对比即得边缘密度：f_X(x) = ∫_{−∞}^{+∞} f(x,y) dy；同理 f_Y(y)=∫ f(x,y) dx。"],"res":"口诀：求谁的边缘，就把另一个变量在全域上积分积掉——相当于把联合密度“投影”到坐标轴。"},{"t":"sh","no":"3.3","title":"随机变量的独立性"},{"t":"ex","q":"【例题】(X,Y) 联合分布律：P(0,0)=0.1，P(0,1)=0.2，P(1,0)=0.4，P(1,1)=0.3。求 X、Y 的边缘分布并判断是否独立。","steps":[{"s":"X 的边缘分布（按行/列求和）：P(X=0) = 0.1+0.2 = 0.3，P(X=1) = 0.4+0.3 = 0.7"},{"s":"Y 的边缘分布：P(Y=0) = 0.1+0.4 = 0.5，P(Y=1) = 0.2+0.3 = 0.5"},{"s":"独立性检验：若独立应有 P(0,0) = P(X=0)·P(Y=0) = 0.3×0.5 = 0.15","note":"逐格验算，有一格不等即不独立"},{"s":"实际 P(0,0) = 0.1 ≠ 0.15 → <b>X 与 Y 不独立</b>","note":"只要一格不成立即可下结论"}]},{"t":"ex","q":"【例题】X、Y 独立且都服从 (0,1) 上的均匀分布，用卷积公式求 Z = X+Y 的概率密度在 z = 0.5 处的值。","steps":[{"s":"卷积公式：f_Z(z) = ∫ f_X(x)·f_Y(z−x) dx","note":"独立时联合密度 = 边缘密度乘积"},{"s":"被积函数非零要求：0 < x < 1 且 0 < z−x < 1 → max(0, z−1) < x < min(1, z)"},{"s":"当 0 < z < 1：积分区间 (0, z)，f_Z(z) = ∫₀^z 1·dx = z"},{"s":"z = 0.5 ∈ (0,1) → f_Z(0.5) = <b>0.5</b>","note":"完整密度是三角形：0<z<1 为 z，1<z<2 为 2−z"}]},{"t":"kw","items":[{"k":"独立定义","d":"X、Y 独立 ⇔ F(x,y)=F_X(x)F_Y(y) ⇔ f(x,y)=f_X(x)f_Y(y)（连续型）。"},{"k":"判定要点","d":"连续型看“联合密度能否拆成只含 x 与只含 y 的两个函数之积，且积分域为矩形”。"},{"k":"重要提醒","d":"边缘分布由联合分布唯一确定，但边缘分布不能反过来确定联合分布；独立时两者才互相还原。"}]},{"t":"sh","no":"3.4","title":"两个随机变量函数的分布"},{"t":"dv","title":"推导：Z=X+Y 的卷积公式 f_Z(z)=∫ f_X(x)f_Y(z−x)dx","goal":"目标：求两个独立随机变量之和 Z=X+Y 的密度。用“分布函数法”把二维问题化成一维积分。","steps":["先写 F_Z(z) = P(X+Y≤z) = ∬_{x+y≤z} f_X(x)f_Y(y) dxdy（X、Y 独立）。","固定 x，对 y 从 −∞ 积到 z−x：F_Z(z) = ∫ [∫_{−∞}^{z−x} f_Y(y)dy] f_X(x) dx。","对 z 求导（对上限求导）：f_Z(z) = ∫ f_X(x) f_Y(z−x) dx。","这就是卷积公式；同理离散型为 P(Z=k)=Σ P(X=i)P(Y=k−i)。"],"res":"若 X、Y 独立同正态，则 Z=X+Y 仍为正态，且 μ_Z=μ_X+μ_Y，σ_Z²=σ_X²+σ_Y²。"},{"t":"fig","kind":"fig-conv-mini","inline":true,"cap":"卷积：把所有 x+(z−x)=z 的情况累加"},{"t":"kw","items":[{"k":"最大值 M=max(X,Y)","d":"F_M(z)=P(X≤z,Y≤z)=F_X(z)F_Y(z)（独立时）。"},{"k":"最小值 N=min(X,Y)","d":"F_N(z)=1−P(X>z,Y>z)=1−[1−F_X(z)][1−F_Y(z)]。"}]},{"t":"fmt","title":"规范作答示范 · 独立性判定","q":"设 (X,Y) 的联合密度为 f(x,y)=e^(−(x+y))（x>0,y>0），判断 X、Y 是否独立。","sol":["解：X、Y 的取值为 x>0、y>0。","先求边缘密度：f_X(x)=∫₀^{+∞} e^(−(x+y)) dy = e^(−x)∫₀^{+∞}e^(−y)dy = e^(−x)（x>0）。","同理 f_Y(y)=e^(−y)（y>0）。","验证：f_X(x)·f_Y(y)=e^(−x)·e^(−y)=e^(−(x+y))=f(x,y)，在积分域内恒成立。","答：因 f(x,y)=f_X(x)f_Y(y)，故 X 与 Y 相互独立。"],"key":"规范点：① 先写联合密度的定义域；② 分别求出两个边缘密度；③ 显式比较“乘积是否等于联合密度”；④ 结论写“独立/不独立”。"},{"t":"warn","text":"<b>典型易错：</b>① 用“边缘分布不能推联合分布”却默认独立——必须先验证 f(x,y)=f_X f_Y；② 积分域不是矩形时（如 0<x<y<1）不能直接判独立；③ 求卷积时把 f_Y 也只代一段、漏掉其余为 0 的部分；④ 求边缘时忘了写密度函数的定义域。"},
{"t":"tip","text":"<b>第3章解题流程：</b>① 求边缘——把另一变量积分掉；② 判独立——验乘积能否还原联合；③ 求和分布 Z=X+Y 用卷积；④ 求 max/min 用分布函数法；⑤ 书写时每个密度都带上定义域。"}]},"pr4":{"no":"4","title":"随机变量的数字特征","tag":"当前 · 第4章","sub":"课本第4章（正在学）。用数学期望、方差、协方差、相关系数刻画随机变量的“平均、波动、线性相关”。本章计算规范性强，是“答题格式”最容易失分的章节。","blocks":[{"t":"sh","no":"4.1","title":"数学期望"},{"t":"fx","lines":["离散型：E(X) = Σ xₖ pₖ；连续型：E(X) = ∫_{−∞}^{+∞} x f(x) dx","函数期望：E[g(X)] = Σ g(xₖ)pₖ 或 ∫ g(x) f(x) dx（不必先求 g(X) 的分布）","性质：E(C)=C；E(CX)=C·E(X)；E(aX+b)=aE(X)+b","可加性：E(X+Y)=E(X)+E(Y)（不要求独立）","若 X、Y 独立，则 E(XY)=E(X)E(Y)"]},{"t":"sh","no":"4.2","title":"方差及性质"},{"t":"dv","title":"推导：方差的计算公式 D(X)=E(X²)−[E(X)]²","goal":"目标：把“先减期望”的方差定义，化成“两个期望之差”的等价形式，计算更方便。","steps":["方差定义：D(X) = E{[X−E(X)]²}。","设 μ=E(X)，展开平方：[X−μ]² = X² − 2μX + μ²。","对两边取期望（用期望线性性）：D(X)=E(X²) − 2μ E(X) + μ²。","因 E(X)=μ，得 D(X)=E(X²) − 2μ² + μ² = E(X²) − μ²。","即 D(X) = E(X²) − [E(X)]²。"],"res":"常用性质：D(C)=0；D(CX)=C²D(X)；D(X+Y)=D(X)+D(Y)+2Cov(X,Y)；X、Y 独立时 D(X±Y)=D(X)+D(Y)。"},{"t":"sh","no":"4.3","title":"常见分布的期望与方差"},{"t":"tb","head":["分布","记号","期望 E(X)","方差 D(X)"],"rows":[["0-1 分布","B(1,p)","p","p(1−p)"],["二项分布","B(n,p)","np","np(1−p)"],["泊松分布","P(λ)","λ","λ"],["均匀分布","U(a,b)","(a+b)/2","(b−a)²/12"],["指数分布","E(λ)","1/λ","1/λ²"],["正态分布","N(μ,σ²)","μ","σ²"]]},{"t":"sh","no":"4.4","title":"协方差、相关系数与矩"},{"t":"dv","title":"推导：协方差与相关系数、以及 D(X±Y) 公式","goal":"目标：刻画两个随机变量“是否线性相关”，并说明方差在求和时为什么要加协方差项。","steps":["协方差定义：Cov(X,Y)=E{[X−E(X)][Y−E(Y)]}，展开得 Cov(X,Y)=E(XY)−E(X)E(Y)。","性质：Cov(X,X)=D(X)；Cov(aX,bY)=ab·Cov(X,Y)；Cov(X₁+X₂,Y)=Cov(X₁,Y)+Cov(X₂,Y)。","相关系数 ρ_XY = Cov(X,Y) / (√D(X)·√D(Y))，且恒有 |ρ_XY| ≤ 1。","推 D(X±Y)：D(X±Y)=E[(X±Y)²]−[E(X±Y)]² = D(X)+D(Y)±2Cov(X,Y)。","当 X、Y 不相关（Cov=0 或 ρ=0）时，D(X±Y)=D(X)+D(Y)。"],"res":"注意：独立 ⇒ 不相关，但不相关 ⇏ 独立；ρ 只度量“线性相关”程度（|ρ|=1 时才线性关系）。"},{"t":"fmt","title":"规范作答示范 · 期望与方差的计算","q":"设随机变量 X 的分布律为 P(X=0)=0.2，P(X=1)=0.5，P(X=2)=0.3，求 E(X)、D(X)。","sol":["解：由分布律可直接按定义计算。","E(X) = 0×0.2 + 1×0.5 + 2×0.3 = 0 + 0.5 + 0.6 = 1.1。","先求二阶原点矩：E(X²) = 0²×0.2 + 1²×0.5 + 2²×0.3 = 0 + 0.5 + 1.2 = 1.7。","由公式 D(X) = E(X²) − [E(X)]² = 1.7 − 1.1² = 1.7 − 1.21 = 0.49。","答：E(X)=1.1，D(X)=0.49。"],"key":"规范点：① 先算 E(X)；② 用 D(X)=E(X²)−[E(X)]² 时先算 E(X²) 再代，别跳步；③ 两项结果都要“答”出来。"},{"t":"fmt","title":"规范作答示范 · 协方差与相关系数","q":"已知 E(X)=1，E(Y)=2，D(X)=4，D(Y)=9，Cov(X,Y)=3，求 D(2X−3Y) 与 ρ_XY 的值。","sol":["解：由方差性质逐项展开。","D(2X−3Y) = 2²D(X) + (−3)²D(Y) + 2·(2)(−3)·Cov(X,Y)","= 4×4 + 9×9 + 2×2×(−3)×3","= 16 + 81 − 36 = 61。",
"相关系数：ρ_XY = Cov(X,Y) / (√D(X)·√D(Y)) = 3 / (√4×√9) = 3 / (2×3) = 0.5。","答：D(2X−3Y)=61，ρ_XY = 0.5。"],"key":"规范点：① 用 D(aX+bY) 公式时交叉项的系数是“2ab·Cov”；② 相关系数分母是两个标准差之积；③ 结果分别作答。"},{"t":"warn","text":"<b>典型易错：</b>① D(aX+b) 错算成 aD(X)（应为 a²D(X)）；② 忘记 D(X±Y) 的交叉项 2Cov，直接写成 D(X)+D(Y)；③ 把“不相关”等同于“独立”；④ 期望存在性——并非所有随机变量都有期望（如柯西分布），需先判断是否绝对收敛；⑤ 相关系数符号与协方差一致，别丢负号。"},{"t":"tip","text":"<b>第4章解题流程：</b>① 求期望——离散求和、连续积分（或用性质）；② 求方差——优先 D(X)=E(X²)−[E(X)]²；③ 组合的方差先套 D(aX+bY)=a²D(X)+b²D(Y)+2abCov；④ 相关系数用 ρ=Cov/(σ_X σ_Y)；⑤ 书写：先写公式→代入数值→两项都“答”。"},{"t":"ex","q":"【例题】X 的分布律：P(X=−1)=0.3，P(X=0)=0.2，P(X=1)=0.5。求 E(X)、E(X²)、D(X)。","steps":[{"s":"E(X) = (−1)×0.3 + 0×0.2 + 1×0.5 = <b>0.2</b>","note":"取值×概率再求和"},{"s":"E(X²) = 1×0.3 + 0×0.2 + 1×0.5 = <b>0.8</b>","note":"先平方再加权"},{"s":"D(X) = E(X²) − [E(X)]² = 0.8 − 0.04 = <b>0.76</b>","note":"方差恒用此公式，别直接套定义"},{"s":"检验：D(X) ≥ 0 ✓；且 E(X) 落在 [−1, 1] 内 ✓"}]},{"t":"ex","q":"【例题】X ~ B(20, 0.1)，求 E(X)、D(X)；设 Y = 3X + 2，求 E(Y)、D(Y)。","steps":[{"s":"二项分布公式：E(X) = np = 20×0.1 = <b>2</b>","note":"常用分布期望方差直接背"},{"s":"D(X) = np(1−p) = 20×0.1×0.9 = <b>1.8</b>"},{"s":"期望线性性：E(Y) = 3E(X) + 2 = 3×2 + 2 = <b>8</b>"},{"s":"方差性质：D(Y) = 3²·D(X) = 9×1.8 = <b>16.2</b>","note":"常数提出平方、平移不影响方差"}]}]},"pr5":{"no":"5","title":"大数定律及中心极限定理","tag":"极限","sub":"切比雪夫·辛钦·中心极限","blocks":[{"t":"sh","no":"5.1","title":"大数定律"},{"t":"tx","h":"为什么需要大数定律","p":"概率是“频率的稳定值”，但这句话本身需要数学证明——大数定律正是回答“为什么大量重复试验中频率会稳定于概率”的定理。它把“统计规律”与“概率定义”连接起来。"},{"t":"tx","h":"切比雪夫不等式","p":"设 E(X) = μ，D(X) = σ²，则对任意 ε &gt; 0：<b>P{|X − μ| ≥ ε} ≤ σ²/ε²</b>，等价形式 P{|X − μ| &lt; ε} ≥ 1 − σ²/ε²。<br>含义：随机变量偏离均值超过 ε 的概率，被 σ²/ε² 控制住。方差越小，越集中在均值附近。它不需要知道分布的具体形式，因此适用范围极广，也是证明大数定律的工具。"},{"t":"tx","h":"三个大数定律","p":"<b>切比雪夫大数定律</b>：若 X₁,…,X<sub>n</sub> 相互独立、方差一致有界，则 (1/n)ΣX<sub>i</sub> 依概率收敛于 (1/n)ΣE(X<sub>i</sub>)。<br><b>伯努利大数定律</b>：n 次独立重复试验中，事件发生频率 μ<sub>n</sub>/n 依概率收敛于概率 p，即 lim P{|μ<sub>n</sub>/n − p| &lt; ε} = 1。这是“频率稳定于概率”的严格表述。<br><b>辛钦大数定律</b>：X₁,…,X<sub>n</sub> 独立同分布且 E(X<sub>i</sub>) = μ 存在，则样本均值依概率收敛于 μ。它不要求方差存在，条件最弱。"},{"t":"sh","no":"5.2","title":"中心极限定理"},{"t":"tx","h":"林德伯格–列维定理","p":"设 X₁,…,X<sub>n</sub> 独立同分布，E(X<sub>i</sub>) = μ，D(X<sub>i</sub>) = σ² &gt; 0，则当 n → ∞ 时，标准化和<br><b>Y<sub>n</sub> = (ΣX<sub>i</sub> − nμ)/(√n σ) → N(0,1)</b>（依分布收敛）。<br>即：无论原来服从什么分布，只要独立同分布且方差有限，<b>样本均值近似服从正态分布</b> <span style=\"white-space:nowrap\">X̄ ~ N(μ, σ²/n)</span>。这就是为什么正态分布在自然界如此普遍。"},{"t":"tx","h":"棣莫弗–拉普拉斯定理","p":"当 X ~ B(n,p) 且 n 较大时，二项分布可用正态分布近似：<b>X ≈ N(np, np(1−p))</b>。<br>实用判据：np ≥ 5 且 n(1−p) ≥ 5 时近似较好。计算时要做<b>连续性修正</b>：P{a ≤ X ≤ b} ≈ Φ((b+0.5−np)/√(npq)) − Φ((a−0.5−np)/√(npq))。"},
{"t":"dv","title":"推导：用中心极限定理解二项分布近似题的标准步骤","steps":["<b>第 1 步 识别模型</b>：n 次独立重复试验、每次成功概率 p → X ~ B(n,p)。","<b>第 2 步 算均值与标准差</b>：μ = np，σ = √(np(1−p))。","<b>第 3 步 做连续性修正</b>：求 P{X ≤ k} 用 k+0.5；求 P{X ≥ k} 用 k−0.5；区间两端各向外扩 0.5。","<b>第 4 步 标准化</b>：z = (x − μ)/σ，把 X 换成标准正态 Z。","<b>第 5 步 查表</b>：用 Φ(z) 求概率，利用 Φ(−z) = 1 − Φ(z)。","<b>为什么能近似</b>：二项分布是 n 个独立 0-1 变量之和，由林德伯格–列维定理，n 大时和趋于正态。"]},{"t":"ex","q":"某射手命中率 p = 0.8，独立射击 100 次。用正态近似求命中次数不少于 85 次的概率（Φ(1.25) = 0.8944）。","steps":["X ~ B(100, 0.8)，μ = np = 80，σ = √(100×0.8×0.2) = √16 = 4。","求 P{X ≥ 85}，连续性修正取 84.5。","标准化：z = (84.5 − 80)/4 = 4.5/4 = 1.125。","P{X ≥ 85} ≈ 1 − Φ(1.125) ≈ 1 − 0.8697 ≈ 0.1303。","若不修正直接用 85：z = 1.25，得 1 − 0.8944 = 0.1056，与精确值偏差更大。","要点：连续性修正在边界处影响可达 2~3 个百分点，不能省。"]},{"t":"warn","text":"① 切比雪夫不等式给的是<b>上界</b>，不是精确概率，用它能算但结果偏保守。② 中心极限定理要求“独立同分布 + 方差有限”，缺一不可。③ 二项近似的连续性修正方向：求“≥k”要减 0.5，求“≤k”要加 0.5。"},{"t":"pt","no":"1","name":"切比雪夫不等式估计概率","feature":"给均值方差，估计偏离均值的概率上界。","method":"直接套 P{|X−μ|≥ε} ≤ σ²/ε²。","steps":["写出 E(X)、D(X)。","把所求事件化成 |X−μ| ≥ ε 或 &lt; ε 的形式，确定 ε。","代入 σ²/ε² 得上界，或用 1 − σ²/ε² 得下界。","若题目问“至少”，用 1 − σ²/ε²；问“至多”，用 σ²/ε²。","检查结果是否在 [0,1] 内。"],"ex":{"q":"E(X)=10，D(X)=4，估计 P{|X−10| ≥ 4} 的上界。","steps":["ε = 4，σ² = 4。","P{|X−10| ≥ 4} ≤ 4/16 = 0.25。","所以该概率不超过 0.25。","若问 P{|X−10| &lt; 4}，则 ≥ 1 − 0.25 = 0.75。","注意这只是上界，真实概率可能远小于 0.25。"]},"pit":"σ² 是方差不是标准差，把 σ=2 代进去会算成 4/4=1，失去意义。"},{"t":"pt","no":"2","name":"中心极限定理近似计算","feature":"n 较大时用正态近似求二项或和分布的概率。","method":"算 μ、σ，做连续性修正，再标准化查表。","steps":["确认 n 足够大（np、n(1−p) 均 ≥ 5）。","算 μ = np，σ = √(npq)。","对离散型做连续性修正（±0.5）。","标准化 z = (x − μ)/σ。","查 Φ 表并按对称性转换。"],"ex":{"q":"某元件次品率 0.05，任取 400 个，求次品数不超过 30 的概率（Φ(2.29)=0.9890）。","steps":["X ~ B(400, 0.05)，μ = 20，σ = √(400×0.05×0.95) = √19 ≈ 4.359。","求 P{X ≤ 30}，修正为 30.5。","z = (30.5 − 20)/4.359 = 10.5/4.359 ≈ 2.409。","P ≈ Φ(2.409) ≈ 0.992。","结论：次品数超过 30 的概率仅约 0.8%，说明 30 个是异常偏高的。"]},"pit":"σ 要用 √(npq) 而不是 npq，两者数量级差很多。"},{"t":"kw","items":["切比雪夫不等式","依概率收敛","切比雪夫大数定律","伯努利大数定律","辛钦大数定律","中心极限定理","林德伯格–列维","棣莫弗–拉普拉斯","连续性修正"]}]},"pr6":{"no":"6","title":"数理统计的基本概念","tag":"统计","sub":"样本·χ²/t/F·抽样分布定理","blocks":[{"t":"sh","no":"6.1","title":"总体与样本"},{"t":"tx","h":"基本术语","p":"<b>总体</b>：研究对象的全体（用随机变量 X 表示其数量指标）。<b>个体</b>：每个研究对象。<b>样本</b>：从总体中随机抽取的 n 个个体 X₁,…,X<sub>n</sub>，要求<b>独立同分布</b>且与总体同分布（即“简单随机样本”）。<br><b>统计量</b>：不含任何未知参数的样本函数，如样本均值、样本方差。统计量本身是随机变量，观测后得到具体数值。"},{"t":"tx","h":"常用统计量","p":"样本均值 <b>X̄ = (1/n)ΣX<sub>i</sub></b>；样本方差 <b>S² = (1/(n−1))Σ(X<sub>i</sub> − X̄)²</b>（除以 n−1 才是无偏的）；样本标准差 S = √S²；样本 k 阶原点矩 A<sub>k</sub> = (1/n)ΣX<sub>i</sub><sup>k</sup>。<br>重要关系：E(X̄) = μ，D(X̄) = σ²/n；E(S²) = σ²。样本均值比单个观测值的方差小 n 倍，这是“平均更稳定”的数学表达。"},
{"t":"sh","no":"6.2","title":"三大抽样分布"},{"t":"tx","h":"χ² 分布","p":"设 X₁,…,X<sub>n</sub> 独立同服从 N(0,1)，则 <b>χ² = ΣX<sub>i</sub>² ~ χ²(n)</b>（自由度 n）。性质：E(χ²) = n，D(χ²) = 2n；可加性——若 χ²₁~χ²(n₁)、χ²₂~χ²(n₂) 且独立，则和 ~ χ²(n₁+n₂)。"},{"t":"tx","h":"t 分布","p":"设 X ~ N(0,1)，Y ~ χ²(n) 且独立，则 <b>t = X/√(Y/n) ~ t(n)</b>。图形关于 0 对称，比标准正态“矮胖”（尾部更厚）；n → ∞ 时趋于 N(0,1)。小样本推断总体均值时用它。"},{"t":"tx","h":"F 分布","p":"设 U ~ χ²(n₁)，V ~ χ²(n₂) 且独立，则 <b>F = (U/n₁)/(V/n₂) ~ F(n₁, n₂)</b>。性质：若 F ~ F(n₁,n₂)，则 1/F ~ F(n₂,n₁)；分位点关系 F<sub>1−α</sub>(n₁,n₂) = 1/F<sub>α</sub>(n₂,n₁)。用于比较两个总体的方差。"},{"t":"sh","no":"6.3","title":"正态总体的抽样分布定理"},{"t":"tx","h":"四个核心结论（设总体 N(μ,σ²)，样本容量 n）","p":"<b>① X̄ ~ N(μ, σ²/n)</b>，标准化后 (X̄−μ)/(σ/√n) ~ N(0,1)。<br><b>② (n−1)S²/σ² ~ χ²(n−1)</b>，且 X̄ 与 S² 相互独立。<br><b>③ 当 σ 未知时，(X̄−μ)/(S/√n) ~ t(n−1)</b>——用 S 替代 σ 使分布从正态变为 t。<br><b>④ 两正态总体</b>：S₁²/S₂² · σ₂²/σ₁² ~ F(n₁−1, n₂−1)。<br>这四条是所有区间估计与假设检验的“发动机”，必须熟记。"},{"t":"dv","title":"推导：为什么 (n−1)S²/σ² ~ χ²(n−1)（自由度为何是 n−1）","steps":["<b>出发点</b>：若 μ 已知，Σ(X<sub>i</sub>−μ)²/σ² ~ χ²(n)，自由度是 n（n 个独立的标准正态平方和）。","<b>替换问题</b>：实际中 μ 未知，只能用 X̄ 代替。","<b>关键恒等式</b>：Σ(X<sub>i</sub>−μ)² = Σ(X<sub>i</sub>−X̄)² + n(X̄−μ)²。即总变差 = 组内变差 + 均值偏差。","<b>自由度损失</b>：Σ(X<sub>i</sub>−X̄) = 0 是一个<b>约束</b>，n 个偏差中只有 n−1 个可自由变动，最后一个被“和为零”确定。","<b>结论</b>：Σ(X<sub>i</sub>−X̄)²/σ² ~ χ²(n−1)，即 (n−1)S²/σ² ~ χ²(n−1)。","<b>为什么 S² 除以 n−1</b>：正因自由度是 n−1，除以 n−1 才能让 E(S²) = σ²（无偏）。若除以 n，期望只有 (n−1)σ²/n，会系统性低估。"]},{"t":"ex","q":"总体 X ~ N(μ, σ²)，n = 16，样本标准差 S = 2.0。求 P{S² &gt; 4.5} 的近似值（已知 χ²<sub>0.05</sub>(15) = 24.996）。","steps":["关键统计量：(n−1)S²/σ² ~ χ²(15)。但本题 σ 未知，无法直接算。","题目实际是要求把 S² 与某个临界值比较——这需要 σ² 已知。若设 σ² = 4，则 (15)(4.5)/4 = 16.875。","P{S² &gt; 4.5} = P{χ²(15) &gt; 16.875}。","查表 χ²<sub>0.05</sub>(15) = 24.996，χ²<sub>0.95</sub>(15) ≈ 7.261，16.875 介于其间。","故该概率在 0.05 与 0.95 之间，约为 0.32。","要点：涉及 S² 的概率题必须先把 (n−1)S²/σ² 化成 χ² 分布，否则无从下手。"]},{"t":"warn","text":"① 样本方差除以 <b>n−1</b> 才是无偏估计，这是最高频考点。② σ 已知用正态、σ 未知用 t，两者不能混。③ 查表时注意分位点下标含义：χ²<sub>α</sub> 通常指上侧 α 分位点。"},{"t":"pt","no":"1","name":"统计量分布与概率计算","feature":"求样本均值/方差落在某区间的概率。","method":"先判定用哪个分布，再标准化。","steps":["判断总体是否正态、σ 是否已知。","求 X̄ 的概率：σ 已知用 (X̄−μ)/(σ/√n) ~ N(0,1)；σ 未知用 t(n−1)。","求 S² 的概率：化成 (n−1)S²/σ² ~ χ²(n−1)。","查相应分布表，注意单双侧。","结果核对：概率必在 [0,1]，且随区间扩大而增大。"],"ex":{"q":"总体 N(μ, 9)，n = 25，求 P{|X̄ − μ| &lt; 1.2}（Φ(2)=0.9772）。","steps":["σ = 3，σ/√n = 3/5 = 0.6。","标准化：(X̄−μ)/0.6 ~ N(0,1)。","|X̄−μ| &lt; 1.2 等价于 |Z| &lt; 1.2/0.6 = 2。",
"P = 2Φ(2) − 1 = 2×0.9772 − 1 = 0.9544。","结论：约 95.4% 的样本均值落在 μ±1.2 内。"]},"pit":"分母用 σ/√n 而不是 σ，忘记开方或忘记除 √n 都会使结果偏差很大。"},{"t":"kw","items":["总体","样本","统计量","样本均值","样本方差","无偏性","χ²分布","t分布","F分布","自由度","抽样分布定理"]}]},"pr7":{"no":"7","title":"参数估计","tag":"统计","sub":"矩估计·极大似然·区间估计","blocks":[{"t":"sh","no":"7.1","title":"参数的点估计"},{"t":"tx","h":"两类基本方法","p":"<b>矩估计法</b>：用样本矩代替总体矩。令样本一阶矩 X̄ = E(X)、样本二阶矩 (1/n)ΣX<sub>i</sub>² = E(X²)，解出未知参数。优点是简单、不需假设分布形式。<br><b>极大似然估计法</b>：选取使“已观测到的样本出现概率最大”的参数值。步骤：写似然函数 L(θ) = Πf(x<sub>i</sub>;θ) → 取对数 lnL → 对 θ 求导令为 0 → 解出 θ̂。"},{"t":"dv","title":"推导：极大似然估计的标准五步（以指数分布为例）","steps":["<b>第 1 步 写似然函数</b>：X ~ f(x) = λe<sup>−λx</sup>（x&gt;0），则 L(λ) = Πλe<sup>−λx<sub>i</sub></sup> = λ<sup>n</sup>e<sup>−λΣx<sub>i</sub></sup>。","<b>第 2 步 取对数</b>：lnL = n lnλ − λΣx<sub>i</sub>。取对数不改变极值点，但把连乘变连加，便于求导。","<b>第 3 步 求导</b>：d(lnL)/dλ = n/λ − Σx<sub>i</sub>。","<b>第 4 步 令导数为 0</b>：n/λ = Σx<sub>i</sub> → λ̂ = n/Σx<sub>i</sub> = 1/X̄。","<b>第 5 步 验证是极大值</b>：二阶导 = −n/λ² &lt; 0，确为极大值点。","<b>结论</b>：λ̂ = 1/X̄。注意结果常可写成“样本均值的倒数”这类简洁形式。"]},{"t":"tx","h":"估计量的评价标准","p":"<b>无偏性</b>：E(θ̂) = θ。样本均值 X̄ 是 μ 的无偏估计；S²（除以 n−1）是 σ² 的无偏估计，而 (1/n)Σ(X<sub>i</sub>−X̄)² 是有偏的（偏低）。<br><b>有效性</b>：两个无偏估计中方差较小者更有效。<br><b>一致性（相合性）</b>：n → ∞ 时 θ̂ 依概率收敛于 θ。"},{"t":"sh","no":"7.2","title":"参数的区间估计"},{"t":"tx","h":"置信区间的含义","p":"置信区间 [θ̂₁, θ̂₂] 满足 P{θ̂₁ &lt; θ &lt; θ̂₂} = 1 − α（置信水平 1−α）。<br>正确理解：反复抽样多次，约 100(1−α)% 的区间会包含真值 θ；而<b>不是</b>“θ 落在该区间的概率是 1−α”（θ 是常数，不是随机变量）。这是概念题的高频陷阱。"},{"t":"tb","head":["估计对象","条件","枢轴量","置信区间"],"rows":[["μ","σ² 已知","(X̄−μ)/(σ/√n) ~ N(0,1)","X̄ ± z<sub>α/2</sub>·σ/√n"],["μ","σ² 未知","(X̄−μ)/(S/√n) ~ t(n−1)","X̄ ± t<sub>α/2</sub>(n−1)·S/√n"],["σ²","μ 未知","(n−1)S²/σ² ~ χ²(n−1)","[ (n−1)S²/χ²<sub>α/2</sub>, (n−1)S²/χ²<sub>1−α/2</sub> ]"],["σ₁²/σ₂²","两总体","F = (S₁²/S₂²)(σ₂²/σ₁²)","由 F 分布双侧分位点构造"]]},{"t":"ex","q":"某批零件长度服从正态分布，σ 未知。抽取 9 件测得 X̄ = 50.0 mm，S = 1.2 mm。求 μ 的 95% 置信区间（t<sub>0.025</sub>(8) = 2.306）。","steps":["σ 未知、小样本 → 用 t 分布，自由度 n−1 = 8。","标准误 S/√n = 1.2/3 = 0.4。","误差限 = t<sub>0.025</sub>(8) × 0.4 = 2.306 × 0.4 = 0.9224。","置信区间 = 50.0 ± 0.9224 = (49.08, 50.92)。","结论：有 95% 的把握认为该批零件平均长度在 49.08~50.92 mm 之间。","若误用 z<sub>0.025</sub> = 1.96，会得 (49.22, 50.78)，区间偏窄、置信度不足——小样本必须用 t。"]},{"t":"warn","text":"① σ 未知且 n 小必须用 t 分布，用 z 会低估区间宽度。② 置信区间不是“θ 的概率分布”，θ 没有概率。③ 方差区间估计的分位点顺序易反：分子除以较大的上侧分位点得下界。"},{"t":"pt","no":"1","name":"点估计（矩估计 / 极大似然）","feature":"给分布形式与样本，求参数的估计量。",
"method":"矩估计令样本矩等于总体矩；极大似然取对数后求导。","steps":["写出总体的 E(X)（矩估计）或密度/分布律（极大似然）。","矩估计：令 X̄ = E(X)，解出参数。","极大似然：写 L(θ)，取 lnL，对 θ 求导令 0。","解方程得 θ̂，代入样本值。","验证二阶导 &lt; 0 或边界情况，说明是极大值。"],"ex":{"q":"总体 X ~ B(1,p)，样本观测值为 1,0,1,1,0。求 p 的矩估计与极大似然估计。","steps":["矩估计：E(X) = p，令 X̄ = p。","X̄ = (1+0+1+1+0)/5 = 3/5 = 0.6，故 p̂ = 0.6。","极大似然：L(p) = p<sup>Σx<sub>i</sub></sup>(1−p)<sup>n−Σx<sub>i</sub></sup> = p³(1−p)²。","lnL = 3lnp + 2ln(1−p)，求导 3/p − 2/(1−p) = 0。","解得 3(1−p) = 2p → p = 3/5 = 0.6。","两者相同——这是伯努利分布的特例，一般二者可能不同。"]},"pit":"lnL 求导后忘记通分是最常见的代数失误；建议先写成分式再交叉相乘。"},{"t":"pt","no":"2","name":"区间估计","feature":"给样本统计量与置信水平，求参数的置信区间。","method":"判断 σ 是否已知选分布，再套误差限公式。","steps":["判断总体是否正态、σ 已知还是未知、样本量大小。","选枢轴量：σ 已知用 z，σ 未知用 t(n−1)，方差用 χ²。","查对应分位点（注意 α/2 双侧）。","算误差限 = 分位点 × 标准误。","写成“点估计 ± 误差限”，并注明置信水平。"],"ex":{"q":"总体 N(μ, 4)，n = 16，X̄ = 20。求 μ 的 95% 置信区间（z<sub>0.025</sub>=1.96）。","steps":["σ = 2 已知 → 用 z 分布。","标准误 σ/√n = 2/4 = 0.5。","误差限 = 1.96 × 0.5 = 0.98。","置信区间 = (20 − 0.98, 20 + 0.98) = (19.02, 20.98)。","要点：σ 已知时与样本量大小无关，一律用 z。"]},"pit":"把 σ/√n 写成 σ/n（漏开方）会让区间宽度差 4 倍。"},{"t":"kw","items":["矩估计","极大似然估计","似然函数","无偏性","有效性","一致性","置信区间","置信水平","枢轴量","t分布临界值"]}]},"pr8":{"no":"8","title":"假设检验","tag":"统计","sub":"两类错误·U/t/χ²/F 检验","blocks":[{"t":"sh","no":"8.1","title":"假设检验的基本概念"},{"t":"tx","h":"四个核心要素","p":"<b>原假设 H₀</b>（通常为“无差异/无效果”）与<b>备择假设 H₁</b>。<b>检验统计量</b>：由样本构造、在原假设成立时分布已知的量。<b>显著性水平 α</b>：允许犯第一类错误的概率上限，常取 0.05 或 0.01。<br>拒绝域：使检验统计量落入即拒绝 H₀ 的区域；临界值由 α 与统计量分布查表确定。"},{"t":"tx","h":"两类错误","p":"<b>第一类错误（弃真）</b>：H₀ 为真却拒绝，概率 = α。<br><b>第二类错误（取伪）</b>：H₀ 为假却接受，概率 = β。<br>二者此消彼长：减小 α 会使 β 增大。唯一能同时减小的办法是<b>增大样本容量 n</b>。"},{"t":"dv","title":"推导：假设检验的五个标准步骤（以 U 检验为例）","steps":["<b>第 1 步 建立假设</b>：H₀: μ = μ₀；H₁: μ ≠ μ₀（双侧）或 μ &gt; μ₀ / μ &lt; μ₀（单侧）。","<b>第 2 步 选统计量</b>：σ 已知用 U = (X̄−μ₀)/(σ/√n) ~ N(0,1)。","<b>第 3 步 定拒绝域</b>：双侧取 |U| &gt; z<sub>α/2</sub>；右侧取 U &gt; z<sub>α</sub>；左侧取 U &lt; −z<sub>α</sub>。","<b>第 4 步 算观测值</b>：把 X̄、μ₀、σ、n 代入算出 u。","<b>第 5 步 判断</b>：u 落入拒绝域则拒绝 H₀，否则不拒绝（<b>不是“接受”</b>，因为没有证明 H₀ 为真）。","<b>为什么这样判</b>：小概率事件在一次试验中几乎不发生；若观测值落在 H₀ 下极难出现的区域，就怀疑 H₀ 不成立。"]},{"t":"sh","no":"8.2","title":"正态总体参数的检验"},{"t":"tb","head":["检验对象","条件","统计量","拒绝域（双侧）"],"rows":[["μ","σ² 已知","U = (X̄−μ₀)/(σ/√n)","|U| &gt; z<sub>α/2</sub>"],["μ","σ² 未知","T = (X̄−μ₀)/(S/√n)","|T| &gt; t<sub>α/2</sub>(n−1)"],["σ²","μ 未知","χ² = (n−1)S²/σ₀²","χ² &gt; χ²<sub>α/2</sub> 或 χ² &lt; χ²<sub>1−α/2</sub>"],
["μ₁−μ₂","方差已知","U = (X̄₁−X̄₂)/√(σ₁²/n₁+σ₂²/n₂)","|U| &gt; z<sub>α/2</sub>"],["σ₁²/σ₂²","均值未知","F = S₁²/S₂²","F &gt; F<sub>α/2</sub>(n₁−1,n₂−1) 或 F &lt; F<sub>1−α/2</sub>"]]},{"t":"ex","q":"某厂声称零件长度均值 μ₀ = 100 mm，σ = 2 mm。抽 25 件得 X̄ = 101.2 mm。在 α = 0.05 下检验（z<sub>0.025</sub> = 1.96）。","steps":["建立假设：H₀: μ = 100；H₁: μ ≠ 100（双侧）。","σ 已知 → 用 U 检验，标准误 σ/√n = 2/5 = 0.4。","计算观测值：u = (101.2 − 100)/0.4 = 1.2/0.4 = 3.0。","拒绝域 |U| &gt; 1.96。","因 3.0 &gt; 1.96，落入拒绝域，故<b>拒绝 H₀</b>。","结论：在 0.05 显著性水平下，认为该厂零件的平均长度不等于 100 mm，声称不成立。"]},{"t":"warn","text":"① 不拒绝 H₀ ≠ 接受 H₀，只能说“样本不足以否定”。② σ 未知要用 t 而非 z，这是最容易失分的地方。③ 单侧检验与双侧检验的临界值不同，先看清题目是“是否等于”还是“是否大于/小于”。"},{"t":"pt","no":"1","name":"单个正态总体均值检验","feature":"判断均值是否等于/大于某值。","method":"看 σ 是否已知选 U 或 T，再双侧/单侧定拒绝域。","steps":["写出 H₀ 与 H₁，明确单双侧。","σ 已知用 U，未知用 T = (X̄−μ₀)/(S/√n)。","查临界值：双侧 z<sub>α/2</sub> 或 t<sub>α/2</sub>(n−1)。","计算统计量观测值。","比较并下结论：拒绝或不拒绝，用一句话说明实际含义。"],"ex":{"q":"σ 未知，n = 10，S = 1.5，X̄ = 21.5，检验 H₀: μ = 20，α = 0.05（t<sub>0.025</sub>(9)=2.262）。","steps":["σ 未知、n 小 → 用 T 检验，自由度 9。","标准误 S/√n = 1.5/√10 = 1.5/3.162 = 0.4743。","t = (21.5 − 20)/0.4743 = 1.5/0.4743 ≈ 3.162。","拒绝域 |T| &gt; 2.262。","3.162 &gt; 2.262 → 拒绝 H₀。","结论：有充分证据认为均值不等于 20。"]},"pit":"把 S/√n 里 n 忘开方，或用 z 代替 t，都会让结论反向。"},{"t":"kw","items":["原假设","备择假设","检验统计量","显著性水平","拒绝域","第一类错误","第二类错误","U检验","t检验","χ²检验","F检验"]}]},"pr9":{"no":"9","title":"方差分析及回归分析","tag":"统计","sub":"单因素·双因素·一元线性回归","blocks":[{"t":"sh","no":"9.1","title":"单因素方差分析"},{"t":"tx","h":"要解决什么问题","p":"比较 r 个水平（组）的均值是否有显著差异。若两两做 t 检验，比较次数为 C(r,2)，多次检验会使第一类错误累积膨胀（例如 5 组要比较 10 次，α 膨胀到约 40%）。方差分析用一次 F 检验同时比较所有组，控制住 α。"},{"t":"tb","head":["方差来源","平方和 SS","自由度 df","均方 MS","F 值"],"rows":[["组间（因素）","SSA = Σn<sub>i</sub>(X̄<sub>i</sub>−X̄)²","r − 1","MSA = SSA/(r−1)","F = MSA/MSE"],["组内（误差）","SSE = ΣΣ(X<sub>ij</sub>−X̄<sub>i</sub>)²","n − r","MSE = SSE/(n−r)","—"],["总和","SST = SSA + SSE","n − 1","—","—"]]},{"t":"dv","title":"推导：单因素方差分析的判断逻辑","steps":["<b>第 1 步 分解总变差</b>：每个观测与总均值的偏差可拆成 (X<sub>ij</sub>−X̄) = (X<sub>ij</sub>−X̄<sub>i</sub>) + (X̄<sub>i</sub>−X̄)，即“组内波动 + 组间差异”。","<b>第 2 步 平方求和</b>：交叉项因 Σ(X<sub>ij</sub>−X̄<sub>i</sub>) = 0 而消掉，得 SST = SSE + SSA。","<b>第 3 步 各除自由度得均方</b>：MSA 反映组间差异（若 H₀ 成立，它也是 σ² 的估计），MSE 恒为 σ² 的无偏估计。","<b>第 4 步 构造 F</b>：F = MSA/MSE。若各组均值真的相同，F 应在 1 附近；若组间差异大，F 明显大于 1。","<b>第 5 步 判断</b>：F &gt; F<sub>α</sub>(r−1, n−r) 则拒绝 H₀，认为因素对指标有显著影响。","<b>为什么只做单侧</b>：F 只可能因“组间差异过大”而偏大，不会因差异小而偏小，故用右侧拒绝域。"]},
{"t":"sh","no":"9.2","title":"双因素方差分析"},{"t":"tx","h":"两个因素的作用","p":"同时考察两个因素 A、B 对指标的影响。若各水平组合只做一次试验（无重复），则不能分离交互作用，模型为 SST = SSA + SSB + SSE，自由度 (r−1)+(s−1)+(r−1)(s−1)。<br>若有重复试验，可进一步分解出<b>交互作用</b> SS<sub>AB</sub>，检验 A×B 是否显著——这是判断“两因素是否协同作用”的关键。"},{"t":"sh","no":"9.3","title":"一元线性回归"},{"t":"tx","h":"最小二乘估计","p":"设 Y = a + bx + ε，用最小二乘法使 Σ(y<sub>i</sub> − â − b̂x<sub>i</sub>)² 最小，解得<br><b>b̂ = L<sub>xy</sub>/L<sub>xx</sub></b>，<b>â = ȳ − b̂x̄</b><br>其中 L<sub>xy</sub> = Σ(x<sub>i</sub>−x̄)(y<sub>i</sub>−ȳ)，L<sub>xx</sub> = Σ(x<sub>i</sub>−x̄)²。回归直线必过点 (x̄, ȳ)。"},{"t":"dv","title":"推导：最小二乘为什么得到 b̂ = L<sub>xy</sub>/L<sub>xx</sub>","steps":["<b>第 1 步 写目标函数</b>：Q(a,b) = Σ(y<sub>i</sub> − a − bx<sub>i</sub>)²，要对 a、b 同时最小化。","<b>第 2 步 对 a 求偏导</b>：∂Q/∂a = −2Σ(y<sub>i</sub> − a − bx<sub>i</sub>) = 0 → a = ȳ − bx̄。","<b>第 3 步 代回消去 a</b>：Q 变为 Σ[(y<sub>i</sub>−ȳ) − b(x<sub>i</sub>−x̄)]²。","<b>第 4 步 对 b 求偏导</b>：−2Σ(x<sub>i</sub>−x̄)[(y<sub>i</sub>−ȳ) − b(x<sub>i</sub>−x̄)] = 0。","<b>第 5 步 解出 b</b>：b·Σ(x<sub>i</sub>−x̄)² = Σ(x<sub>i</sub>−x̄)(y<sub>i</sub>−ȳ)，即 b̂ = L<sub>xy</sub>/L<sub>xx</sub>。","<b>第 6 步 回代 a</b>：â = ȳ − b̂x̄，说明回归直线通过样本中心 (x̄, ȳ)。","<b>为什么叫“最小二乘”</b>：最小化的是误差的<b>平方和</b>，平方可避免正负抵消且便于求导。"]},{"t":"sh","no":"9.4","title":"回归的显著性检验"},{"t":"tx","h":"相关系数检验与 F 检验","p":"样本相关系数 <b>r = L<sub>xy</sub>/√(L<sub>xx</sub>L<sub>yy</sub>)</b>，|r| ≤ 1，越接近 1 线性关系越强。<br>检验 H₀: b = 0（即 x 对 y 无线性影响）：统计量 <b>t = r√(n−2)/√(1−r²) ~ t(n−2)</b>，或等价的 F 检验。若拒绝 H₀，说明回归方程显著。"},{"t":"ex","q":"已知 n = 10，x̄ = 5，ȳ = 12，L<sub>xx</sub> = 40，L<sub>xy</sub> = 24。求回归方程。","steps":["b̂ = L<sub>xy</sub>/L<sub>xx</sub> = 24/40 = 0.6。","â = ȳ − b̂x̄ = 12 − 0.6 × 5 = 12 − 3 = 9。","回归方程：ŷ = 9 + 0.6x。","含义：x 每增加 1 个单位，y 平均增加 0.6 个单位。","验算：把 x̄ = 5 代入得 ŷ = 9 + 3 = 12 = ȳ ✓，回归线过样本中心。"]},{"t":"warn","text":"① 方差分析的 F 检验只用右侧拒绝域。② 回归系数 b 与相关系数 r 不同：b 有量纲、可大于 1，r 无纲且在 [−1,1]。③ 相关不等于因果，回归显著只说明线性关系存在。"},{"t":"pt","no":"1","name":"方差分析表计算","feature":"给各组数据，填方差分析表并判断显著性。","method":"算 SSA、SSE，各除自由度，再求 F。","steps":["算各组均值与总均值。","SSA = Σn<sub>i</sub>(X̄<sub>i</sub>−X̄)²，自由度 r−1。","SSE = ΣΣ(X<sub>ij</sub>−X̄<sub>i</sub>)²，自由度 n−r。","MSA = SSA/(r−1)，MSE = SSE/(n−r)。","F = MSA/MSE，与 F<sub>α</sub>(r−1,n−r) 比较后下结论。"],"ex":{"q":"三组数据，各组均值 10、12、14，每组 5 个观测，总均值 12，组内平方和 SSE = 60。求 F。","steps":["SSA = 5(10−12)² + 5(12−12)² + 5(14−12)² = 5×4 + 0 + 5×4 = 40。","自由度：组间 r−1 = 2，组内 n−r = 15−3 = 12。","MSA = 40/2 = 20，MSE = 60/12 = 5。",
"F = 20/5 = 4.0。","查表 F<sub>0.05</sub>(2,12) = 3.89，4.0 &gt; 3.89 → 拒绝 H₀，组间差异显著。"]},"pit":"组内自由度是 n−r 而不是 n−1，总自由度 n−1 = 组间 + 组内。"},{"t":"pt","no":"2","name":"一元线性回归","feature":"给样本数据或汇总量，求回归方程并检验。","method":"用 L<sub>xy</sub>/L<sub>xx</sub> 求斜率，再代回求截距。","steps":["算 x̄、ȳ、L<sub>xx</sub>、L<sub>xy</sub>。","b̂ = L<sub>xy</sub>/L<sub>xx</sub>。","â = ȳ − b̂x̄。","写方程 ŷ = â + b̂x，解释斜率含义。","必要时用 t = r√(n−2)/√(1−r²) 检验显著性。"],"ex":{"q":"n = 8，x̄ = 4，ȳ = 10，L<sub>xx</sub> = 20，L<sub>xy</sub> = −15。求回归方程并说明趋势。","steps":["b̂ = −15/20 = −0.75。","â = 10 − (−0.75)(4) = 10 + 3 = 13。","回归方程：ŷ = 13 − 0.75x。","斜率为负，说明 x 增大时 y 平均下降，每增加 1 单位 y 减少 0.75。","验算：x = 4 时 ŷ = 13 − 3 = 10 = ȳ ✓。"]},"pit":"â = ȳ − b̂x̄ 中的符号容易出错，尤其 b̂ 为负时；代入 x̄ 验算可立刻发现。"},{"t":"kw","items":["单因素方差分析","组间平方和","组内平方和","均方","F检验","交互作用","最小二乘法","回归系数","相关系数","回归显著性检验"]}]},"pr10":{"no":"10","title":"R 软件在数理统计中的应用","tag":"工具","sub":"R 基础·描述统计·检验·回归","blocks":[{"t":"sh","no":"10.1","title":"R 语言基础"},{"t":"tx","h":"基本操作","p":"R 是面向统计的开源语言。常用：<code>c()</code> 建向量、<code>mean()/sd()/var()/median()</code> 求统计量、<code>read.csv()</code> 读数据、<code>summary()</code> 汇总。<br>赋值用 <code>&lt;-</code>，注释用 <code>#</code>。向量运算默认逐元素进行，无需循环。"},{"t":"tb","head":["函数","作用","示例"],"rows":[["mean(x)","样本均值","mean(c(1,2,3)) → 2"],["sd(x)","样本标准差（除以 n−1）","sd(c(1,2,3))"],["var(x)","样本方差","var(x)"],["quantile(x, p)","分位数","quantile(x, 0.5) 即中位数"],["table(x)","频数统计","table(c(\"a\",\"b\",\"a\"))"]]},{"t":"sh","no":"10.2","title":"描述统计与图形"},{"t":"tx","h":"常用图形函数","p":"<code>hist(x)</code> 直方图（看分布形状）、<code>boxplot(x)</code> 箱线图（看中位数、四分位、离群点）、<code>plot(x,y)</code> 散点图、<code>qqnorm(x)</code> 正态 Q-Q 图（点近似成直线则接近正态）。<br>做 t 检验前先用 <code>qqnorm</code> 检验正态性，是规范的分析流程。"},{"t":"sh","no":"10.3","title":"参数估计与假设检验"},{"t":"tx","h":"检验函数","p":"<b>t 检验</b>：<code>t.test(x, mu=100)</code> 单样本；<code>t.test(x, y)</code> 两样本。<br><b>方差检验</b>：<code>var.test(x, y)</code> 比较两总体方差。<br><b>正态性检验</b>：<code>shapiro.test(x)</code>，p &gt; 0.05 表示不拒绝正态假设。<br>R 的检验输出都含 p 值：<b>p &lt; α 则拒绝 H₀</b>，这比查表更直接。"},{"t":"tx","h":"点估计与区间估计","p":"矩估计与极大似然在 R 中可手算，也可用 <code>fitdistr()</code>（MASS 包）等。区间估计可直接从 <code>t.test()</code> 的输出中读 conf.int，默认 95%，用 <code>conf.level=0.99</code> 可改置信水平。"},{"t":"sh","no":"10.4","title":"方差分析与回归"},{"t":"tx","h":"aov 与 lm","p":"<b>方差分析</b>：<code>aov(y ~ factor(A), data)</code>，再用 <code>summary()</code> 得到方差分析表与 p 值。双因素写 <code>aov(y ~ A + B)</code>，含交互写 <code>A*B</code>。<br><b>回归</b>：<code>lm(y ~ x, data)</code> 拟合一元线性回归，<code>summary()</code> 给出系数、标准误、t 值与 p 值、R²；<code>abline(model)</code> 把回归线画到散点图上。"},
{"t":"ex","q":"在 R 中检验某样本均值是否为 100。样本存于向量 x，长度 20。请写出完整命令并解释输出要点。","steps":["命令：<code>t.test(x, mu = 100)</code>。","输出含 t 统计量、自由度 df = 19、p 值、备择假设与 95% 置信区间。","判断：若 p &lt; 0.05，拒绝 H₀（均值等于 100）；否则不拒绝。","同时读 conf.int：若区间包含 100，与 p &gt; 0.05 等价，互相印证。","若要单侧检验，加参数 <code>alternative = \"greater\"</code> 或 <code>\"less\"</code>。","要点：R 的 p 值判断与查表法是同一件事的两种表达，不用再手算临界值。"]},{"t":"warn","text":"① R 的 <code>sd()</code> 和 <code>var()</code> 默认除以 n−1（样本方差），与手算总体方差不同。② <code>t.test</code> 默认双侧、95% 置信、假设方差不等（两样本时），需按题意改参数。③ p 值不是“H₀ 为真的概率”，它是在 H₀ 成立下观测到当前或更极端结果的概率。"},{"t":"pt","no":"1","name":"R 命令选择","feature":"给分析目的，写出对应 R 命令。","method":"按“描述—检验—建模”三层记忆函数名。","steps":["描述统计：mean/sd/var/median/quantile。","分布形状：hist/boxplot/qqnorm。","均值检验：t.test；方差检验：var.test；正态性：shapiro.test。","方差分析：aov + summary。","回归：lm + summary，abline 画线。"],"ex":{"q":"要检验两组数据方差是否相等，应使用什么命令？","steps":["使用 <code>var.test(x, y)</code>。","它做的是 F 检验，H₀ 为两总体方差相等。","若 p &lt; 0.05，则拒绝方差相等，说明两组方差有显著差异。","此时做两样本均值 t 检验应设 <code>var.equal = FALSE</code>（R 默认即是）。","要点：方差不齐时的 t 检验用的是修正自由度（Welch 近似）。"]},"pit":"把 var.test 与 t.test 混用是常见错误：前者比方差，后者比均值。"},{"t":"kw","items":["R 语言","向量","mean","sd","var","hist","boxplot","qqnorm","t.test","var.test","shapiro.test","aov","lm","p 值"]}]}}},
  "py": {"key":"py","name":"Python程序设计","icon":"🐍","book":"《人工智能与Python程序设计》· 教研组课件 · 第1周—第8周","prog":"课件 8 讲已全部收录 · 从语法到面向对象","progPct":100,"intro":"按《人工智能与Python程序设计》课件顺序编排：单元 = 一次课/一个主题，共 8 讲，从「初识Python」的缩进与变量，到基本数据类型、控制结构、函数与代码复用、两类组合数据类型，再到 IO 编程与面向对象。Python 的痛点是「看得懂却写不出」——所以每章都配可复制运行、带注释的代码，公式与语法规则都给成能背下来的形式，例题按「思路 → 步骤 → 答案」写全。","map":{"root":{"title":"人工智能与Python程序设计","x":50,"y":12},"hubs":[{"id":"yh1","title":"语法基础 (1–3讲)","x":16,"y":34},{"id":"yh2","title":"函数与数据 (4–6讲)","x":50,"y":34},{"id":"yh3","title":"IO 与对象 (7–8讲)","x":84,"y":34}],"units":[{"id":"py1","no":"1","title":"初识Python","sub":"程序·缩进·input/print·turtle","tag":"基础","x":6,"y":56,"parent":"yh1"},{"id":"py2","no":"2","title":"基本数据类型","sub":"数字·字符串·math·关系逻辑","tag":"基础","x":21,"y":56,"parent":"yh1"},{"id":"py3","no":"3","title":"程序的控制结构","sub":"分支·循环·异常处理","tag":"核心","x":36,"y":56,"parent":"yh1"},{"id":"py4","no":"4","title":"函数与代码复用","sub":"def·参数·作用域·递归","tag":"核心","x":51,"y":56,"parent":"yh2"},{"id":"py5","no":"5","title":"组合数据类型（一）","sub":"序列·元组·列表·集合·jieba","tag":"进阶","x":66,"y":56,"parent":"yh2"},{"id":"py6","no":"6","title":"组合数据类型（二）","sub":"字典·哈希·csv·collections","tag":"进阶","x":81,"y":56,"parent":"yh2"},{"id":"py7","no":"7","title":"IO编程","sub":"文件·编码·CSV·os模块","tag":"应用","x":30,"y":80,"parent":"yh3"},{"id":"py8","no":"8","title":"面向对象编程（一）","sub":"类·实例·封装·访问限制","tag":"应用","x":62,"y":80,"parent":"yh3"}]},"units":{"py1":{"no":"1","title":"初识Python","tag":"第1章","sub":"程序·缩进·变量·input/print·turtle","blocks":[{"t":"sh","no":"1.1","title":"从机器码到高级语言"},{"t":"tx","h":"什么是程序","p":"<b>程序</b>：为完成某项任务、解决某个问题所需要执行的一系列步骤。计算机 = 能够<b>按程序自动运行</b>的机器，硬件是躯壳、软件是灵魂。"},{"t":"tx","h":"冯·诺依曼体系结构","p":"五大部件：<b>输入设备、存储器、输出设备、运算器、控制器</b>（后两者合称 CPU）。两条核心思想：<b>存储程序</b>（程序与数据一起放存储器，按顺序执行）+ <b>二进制</b>作为数制基础。"},{"t":"tb","head":["语言层次","写 1+1 的样子","特点"],"rows":[["机器语言","10111000 00000001 …","CPU 直接执行，人类几乎不可读"],["汇编语言","MOV AX,1 / ADD AX,1","助记符，仍需对应具体机器"],["高级语言","print(1+1)","接近自然语言，与机器无关"]]},{"t":"tx","h":"编译型 vs 解释型","p":"<b>编译型</b>（C/C++）：先把全部源码翻译成机器码再运行，执行快、跨平台差。<b>解释型 / 解析型</b>（Python、BASIC）：由解释器<b>逐句翻译逐句执行</b>，开发快、跨平台好，但运行较慢。Python 是解析型高级语言。"},{"t":"sh","no":"1.2","title":"第一个程序与程序元素"},{"t":"code","lang":"python","code":"# 注释：井号后面到行尾都不执行\nprint(\"Hello, World\")\n\nTempStr = input(\"请输入带符号的温度值: \")\nif TempStr[-1] in [\"F\",\"f\"]:\n    C = (eval(TempStr[0:-1]) - 32) / 1.8\n    print(\"转换后的温度是{:.2f}C\".format(C))\nelif TempStr[-1] in [\"C\",\"c\"]:\n    F = eval(TempStr[0:-1]) * 1.8 + 32\n    print(\"转换后的温度是{:.2f}F\".format(F))\nelse:\n    print(\"输入格式错误\")"},
{"t":"tx","h":"缩进就是语法","p":"Python 用<b>缩进</b>（建议 1 个 Tab = 4 个空格）表示代码的层次关系，这是它<b>唯一</b>的代码块标记手段——C/Java 用 <code>{ }</code>，Python 用缩进。缩进错了程序直接报 <code>IndentationError</code>。"},{"t":"tx","h":"注释","p":"单行注释用 <code>#</code>；多行注释用三个单引号 <code>'''…'''</code> 或三个双引号包裹。注释不参与执行，是给别人（和三个月后的自己）看的。"},{"t":"kw","items":[{"k":"缩进","d":"用行首空白表示代码块层次，Python 唯一的代码块标记"},{"k":"注释","d":"# 单行、三引号多行，解释器忽略"},{"k":"标识符命名","d":"字母数字下划线汉字组合，首字符不能是数字"},{"k":"保留字","d":"语言内部占用的关键字，如 if/elif/else/in/import"}]},{"t":"fx","lines":["摄氏 → 华氏：F = C × 1.8 + 32","华氏 → 摄氏：C = (F − 32) ÷ 1.8","末尾字符 TempStr[-1] 用来判断输入的是 C 还是 F"]},{"t":"warn","text":"<b>缩进坑</b>：同一代码块内的语句必须严格对齐；用 Tab 还是 4 个空格要全文件统一，混用会报 <code>TabError</code>。"},{"t":"sh","no":"1.3","title":"输入、输出与赋值"},{"t":"tx","h":"input() / eval() / print()","p":"<code>input(提示语)</code> 返回用户输入的<b>字符串</b>（注意：input 不是保留字）；<code>eval(s)</code> 把字符串当 Python 表达式求值（去掉最外层引号再算），常用来把输入转成数字；<code>print()</code> 输出，可用 <code>format()</code> 或 <code>%</code> 控制格式。"},{"t":"tx","h":"赋值不是相等","p":"<code>=</code> 是<b>赋值</b>：先算右边，再把结果放进左边的变量，会覆盖变量原来的值。<b>同步赋值</b> <code>a, b = 12, 13</code> 可一次给多个变量赋值，交换两数写 <code>a, b = b, a</code> 即可。"},{"t":"kw","items":[{"k":"input函数","d":"读取一行用户输入，返回字符串"},{"k":"eval函数","d":"把字符串当表达式求值，常用于类型转换"},{"k":"print函数","d":"输出，支持 format 与 % 格式控制"},{"k":"赋值语句","d":"= 表示赋值而非相等，右边算完放左边"},{"k":"同步赋值","d":"a, b = 12, 13 一次赋多个变量"}]},{"t":"ex","q":"输入华氏温度 82F，输出对应的摄氏温度。","steps":[{"s":"判断类型：末位字符为 F，走华氏转摄氏分支","why":"用 TempStr[-1] 取最后一个字符"},{"s":"取数字部分并转成数值：eval(TempStr[0:-1]) 得 82.0","why":"切片 [0:-1] 去掉末尾的 F"},{"s":"代入 C = (F−32)/1.8 = (82−32)/1.8","why":"公式来自两种温标的定点换算"},{"s":"输出 27.78C，保留两位小数","why":"{:.2f} 控制精度"}],"ans":"C = (82 − 32) / 1.8 ≈ 27.78，输出 27.78C"},{"t":"sh","no":"1.4","title":"turtle 绘图与 IDE"},{"t":"tx","h":"海龟绘图三组命令","p":"<b>库引用</b>：<code>import turtle</code> / <code>import turtle as t</code> / <code>from turtle import *</code>。<b>画布</b>：<code>t.setup(width, height)</code>。<b>画笔</b>：<code>penup()</code> 提笔不留痕、<code>pendown()</code> 落笔、<code>pensize(w)</code> 粗细、<code>pencolor(c)</code> 颜色。<b>运动</b>：<code>fd(d)</code> 前进、<code>circle(r, extent)</code> 画弧、<code>seth(a)</code> 设绝对朝向、<code>left(a)</code>/<code>right(a)</code> 相对转向。"},{"t":"fx","lines":["for i in range(N)  产生序列 0, 1, 2, …, N−1","t.circle(r, extent)  圆心在海龟左侧 r 处，extent 为绘制角度","t.seth(to_angle)  绝对朝向；t.left/right(angle) 相对转向"]},{"t":"code","lang":"python","code":"import turtle as t\n\nt.setup(650, 350, 200, 200)\nt.penup()\nt.fd(-250)\nt.pendown()\nt.pensize(25)\nt.pencolor(\"purple\")\nt.seth(-40)\n\nfor i in range(4):\n    t.circle(40, 80)\n    t.circle(-40, 80)\nt.circle(40, 80/2)\nt.fd(40)\nt.circle(16, 180)\nt.fd(40*2/3)\nt.done()"},
{"t":"kw","items":[{"k":"turtle库","d":"海龟绘图标准库：画布、画笔、运动三组命令"},{"k":"range函数","d":"range(N) 产生 0 到 N-1 的整数序列"},{"k":"import引用","d":"import turtle / as 别名 / from … import *"},{"k":"IDE","d":"集成开发环境，PyCharm/VSCode 可断点单步调试"}]},{"t":"tip","text":"<b>Jupyter 与 PyCharm 的分工</b>：Jupyter 适合边写边看结果、做实验；但它无法单步跟踪变量、难以管理多文件工程。写大作业请用 PyCharm，学会设断点 + F7/F8/F9 单步。"}]},"py2":{"no":"2","title":"基本数据类型","tag":"第2章","sub":"数字·字符串·math库·关系与逻辑运算","blocks":[{"t":"sh","no":"2.1","title":"数字类型"},{"t":"tx","h":"整数 int","p":"与数学整数一致，<b>没有取值范围限制</b>（这是 Python 与 C 的重要差别，<code>pow(2,1000)</code> 能算）。进制写法：<code>0x11</code> 十六进制、<code>0b11</code> 二进制、<code>0o11</code> 八进制。"},{"t":"tx","h":"浮点数 float","p":"带小数点的数，可用科学计数法 <code>96e4</code> 表示 96×10⁴。<b>范围有限</b>（太大上溢 overflow）、<b>精度有限</b>（太小下溢 underflow，如 1e-400 变 0），且存在二进制无法精确表示的十进制小数（0.1+0.2≠0.3）。"},{"t":"tx","h":"复数 complex","p":"<code>z = 1 + 5j</code>，<code>z.real</code> 取实部、<code>z.imag</code> 取虚部。运算：(a+bj)+(c+dj)=(a+c)+(b+d)j；(a+bj)(c+dj)=(ac−bd)+(bc+ad)j。"},{"t":"tb","head":["写法","含义","示例"],"rows":[["0x1a","十六进制，0x/0X 开头","26"],["0b1010","二进制，0b/0B 开头","10"],["0o17","八进制，0o/0O 开头","15"],["9.6e4","科学计数法 aEb = a×10^b","96000.0"]]},{"t":"kw","items":[{"k":"整数类型","d":"无上限精度，支持二/八/十六进制字面量"},{"k":"浮点数类型","d":"有范围与精度限制，可用科学计数法"},{"k":"复数类型","d":"a+bj，real/imag 取实虚部"},{"k":"类型混合运算","d":"结果为最宽类型：整数→浮点→复数"}]},{"t":"fx","lines":["混合运算取最宽：123 + 4.0 = 127.0（整数 + 浮点 = 浮点）","宽度顺序：整数 → 浮点数 → 复数","整数除法 / 结果一定是浮点：7/2 = 3.5；整除 // 结果取整：7//2 = 3","整数间 + − * // % ** 结果为整数（不会溢出）"]},{"t":"sh","no":"2.2","title":"数值运算与 math 库"},{"t":"tx","h":"运算符与优先级","p":"优先级由高到低：<b>括号 ( )</b> → 一元 + − → 幂 <code>**</code> → <code>* / % //</code> → <code>+ −</code> → 比较 <code>== != &lt; &lt;= &gt;=</code> → <code>not</code> → <code>and</code> → <code>or</code> → 赋值。<b>幂运算右结合</b>：<code>2**3**2 = 2**(3**2) = 512</code>，不是 64。"},{"t":"tx","h":"math 库","p":"math 提供 <b>4 个常数 + 44 个函数</b>：<code>math.pi</code>、<code>math.e</code>、<code>math.inf</code>、<code>math.nan</code>；数值表示 16 个、幂对数 8 个、三角 16 个、高等特殊 4 个。用法：<code>import math</code> 后 <code>math.sqrt(2)</code>、<code>math.cos(math.pi)</code>。注意无理数只能用 float 近似，有精度损失。"},{"t":"tb","head":["函数","作用","示例"],"rows":[["abs(x)","绝对值","abs(-3) = 3"],["int(x)","取整（直接截断小数）","int(5.6) = 5"],["float(x)","转浮点","float(5) = 5.0"],["round(x, n)","四舍五入到 n 位","round(3.14159,2)=3.14"],["pow(x, y)","x 的 y 次方","pow(2,10)=1024"],["math.sqrt(x)","开方","math.sqrt(4)=2.0"],
["math.floor/ceil","向下/向上取整","floor(2.7)=2, ceil(2.1)=3"]]},{"t":"kw","items":[{"k":"math库","d":"标准数学库，4 常数 44 函数，import math 后调用"},{"k":"运算符优先级","d":"括号 > 幂 > 乘除 > 加减 > 比较 > not > and > or"},{"k":"类型转换函数","d":"int 截断取整、float 转浮点、round 四舍五入"}]},{"t":"code","lang":"python","code":"# DayDayUp365：每天进步 1‰ vs 每天退步 1‰\ndayup = pow(1 + 0.001, 365)\ndaydown = pow(1 - 0.001, 365)\nprint(\"向上: {:.2f}, 向下: {:.2f}, 差距: {:.2f}\".format(dayup, daydown, dayup/daydown))"},{"t":"ex","q":"一年 365 天，每天比前一天提升 1‰，一年后能力值是 1 的多少倍？若每天下降 1‰ 呢？两者相差多少倍？","steps":[{"s":"理解复利模型：每天相对前一天乘以 (1±0.001)","why":"“相比前一天提高”是比例增长，不是固定加法"},{"s":"365 天后：up = 1.001^365，down = 0.999^365","why":"连乘 365 次即乘幂，这正是 pow 的用途"},{"s":"up = 1.001^365 ≈ 1.4403，down = 0.999^365 ≈ 0.6941","why":"指数增长与衰减都不慢"},{"s":"两者之比 ≈ 2.075，即差约 2 倍","why":"对称的 ±1‰ 结果并不对称，涨的基数越来越大"}],"ans":"1.001^365 ≈ 1.4403；0.999^365 ≈ 0.6941；相差约 2.07 倍。"},{"t":"tip","text":"把 ratio 调到 5‰ 或 1%，再看 365 次方——会看到指数函数的陡峭，这就是“复利”的直观感受。"},{"t":"sh","no":"2.3","title":"字符串类型"},{"t":"tx","h":"索引与切片","p":"字符串是<b>字符序列</b>。正向索引从 <code>0</code> 开始，长度 L 的串末位是 <code>L-1</code>；反向索引从 <code>-1</code> 开始。<b>切片</b> <code>s[start:end]</code> 取 [start, end) 半开区间，<b>不含 end</b>；<code>s[start:end:step]</code> 支持步长，步长为负则反向。start 在 end 之后就返回空串。"},{"t":"tx","h":"字符串运算","p":"<code>+</code> 拼接、<code>*</code> 重复、<code>len(s)</code> 求长度（中文按字数算）、<code>str(x)</code> 转字符串。<b>字符串不可变</b>：所有“修改”方法都返回新串，原串不变。"},{"t":"fx","lines":["正向索引：s[0] 首字符，s[L-1] 末字符","反向索引：s[-1] 末字符，s[-L] 首字符","切片：s[i:j] 取 i 到 j-1，共 j−i 个字符；s[:] 全串；s[::-1] 反转","格式化：\"{0:>8.2f}\".format(x) → 填充+对齐+宽度+.精度+类型"]},{"t":"kw","items":[{"k":"字符串索引","d":"正向从 0、反向从 -1，取单个字符"},{"k":"字符串切片","d":"s[i:j:k] 半开区间，不含 j，可为负步长"},{"k":"字符串格式化format","d":"\"{序号:填充对齐宽度.精度类型}\" 控制输出样式"},{"k":"字符串不可变性","d":"所有修改方法返回新串，原串不变"}]},{"t":"code","lang":"python","code":"months = \"JanFebMarAprMayJunJulAugSepOctNovDec\"\nn = int(input(\"请输入月份(1-12): \"))\npos = (n - 1) * 3\nprint(months[pos:pos+3])\n\n# 格式控制：填充*，右对齐，宽度7，2 位小数\nprint(\"{:*>7.2f}\".format(3.14159))   # ***3.14"},{"t":"ex","q":"输入月份数字 5，用字符串切片输出月份缩写 May。","steps":[{"s":"把 12 个月缩写拼成一个长串，每月固定 3 个字母","why":"等长排列才能用位置公式定位"},{"s":"第 n 月的起始位置 pos = (n−1)×3","why":"前 n−1 个月各占 3 个字符"},{"s":"切片 months[pos:pos+3]","why":"取出连续 3 个字符就是缩写"},{"s":"n=5 时 pos=12，months[12:15] = \"May\"","why":"索引 12 开始正好是第 5 个月"}],"ans":"(5−1)×3 = 12，months[12:15] = \"May\""},{"t":"sh","no":"2.4","title":"关系运算、逻辑运算与闰年"},
{"t":"tb","head":["关系运算符","含义","示例"],"rows":[["==","等于","10 == 20 → False"],["!=","不等于","10 != 20 → True"],[">","大于","10 > 20 → False"],["<","小于","10 < 20 → True"],[">=","大于等于","10 >= 20 → False"],["<=","小于等于","10 <= 20 → True"]]},{"t":"tb","head":["逻辑运算符","含义","示例"],"rows":[["and","与，全真才真","True and False → False"],["or","或，全假才假","True or False → True"],["not","非，取反","not True → False"]]},{"t":"fx","lines":["闰年条件：(y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)","能被 4 整除且不能被 100 整除 → 闰年；或能被 400 整除 → 闰年","x % 2 == 0 判断偶数；x % 2 != 0 判断奇数"]},{"t":"kw","items":[{"k":"关系运算符","d":"== != > < >= <=，结果为布尔值"},{"k":"逻辑运算符","d":"and 全真才真，or 全假才假，not 取反"},{"k":"短路求值","d":"and 左假即停，or 左真即停，右侧不计算"}]},{"t":"code","lang":"python","code":"y = int(input(\"请输入年份: \"))\nif (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0):\n    print(y, \"是闰年\")\nelse:\n    print(y, \"不是闰年\")"},{"t":"ex","q":"判断 1900 年和 2000 年是否为闰年。","steps":[{"s":"1900：1900%4=0，但 1900%100=0，第一个条件不成立","why":"“能被 4 整除且不能被 100 整除”要求两个子条件同时为真"},{"s":"再看 1900%400=300≠0，第二个条件也不成立","why":"400 年整除法是例外修正"},{"s":"所以 1900 不是闰年","why":"世纪年必须被 400 整除才是闰年"},{"s":"2000：2000%400=0，第二个条件成立，是闰年","why":"or 只要一侧为真就成立，短路不再算左侧细节"}],"ans":"1900 不是闰年；2000 是闰年。"},{"t":"warn","text":"<b>易错</b>：写成 <code>y % 4 == 0 and y % 100 != 0 or y % 400 == 0</code> 虽然因 and 优先于 or 也能算对，但考试要写括号显式表达意图；另外 <code>=</code> 是赋值、<code>==</code> 才是比较。"}]},"py3":{"no":"3","title":"程序的控制结构","tag":"第3章","sub":"分支·循环·异常处理","blocks":[{"t":"sh","no":"3.1","title":"三种基本结构与流程图"},{"t":"tx","h":"任何程序都是三种结构的组合","p":"<b>顺序</b>：按线性顺序依次执行；<b>分支</b>：依据条件选择不同向前路径（单分支、二分支、多分支）；<b>循环</b>：依据条件向后反复执行（遍历循环、条件循环）。理论上这三种结构足以表达任何算法。"},{"t":"tx","h":"流程图","p":"用图形、流程线与文字描述程序流程，基本元素共 7 种：起止框（圆角矩形）、处理框（矩形）、判断框（菱形）、输入输出框（平行四边形）、流程线（箭头）、连接点、注释框。"},{"t":"kw","items":[{"k":"程序流程图","d":"7 种基本图形描述程序流程"},{"k":"顺序结构","d":"按书写顺序逐句执行，是程序的基础"}]},{"t":"sh","no":"3.2","title":"分支结构"},{"t":"fx","lines":["单分支：if <条件>:  <语句块>","二分支：if <条件>: <语句块1>  else: <语句块2>","多分支：if <条件1>: … elif <条件2>: … else: …","紧凑形式：<表达式1> if <条件> else <表达式2>"]},{"t":"tx","h":"执行规则","p":"if 先求条件值：True 则执行语句块再转向下一条语句，False 则跳过。多分支 <b>自上而下依次判断，命中第一个 True 就执行并跳过整个结构</b>；else 可省略。语句块靠缩进界定。"},{"t":"kw","items":[{"k":"单分支if","d":"条件为真执行语句块，否则跳过"},{"k":"二分支if-else","d":"True 走 if 块，False 走 else 块"},{"k":"多分支if-elif-else","d":"依次判断，命中第一个 True 后整体跳过"},{"k":"条件表达式","d":"a if cond else b，一行完成二分支取值"}]},{"t":"code","lang":"python","code":"pm = eval(input(\"请输入 PM2.5 数值: \"))\nif pm >= 75:\n    print(\"空气污染，请小心！\")\nelif 35 <= pm < 75:\n    print(\"空气良好，适度户外活动！\")\nelse:\n    print(\"空气优质，快去户外运动！\")\n\n# 紧凑形式\nlevel = \"污染\" if pm >= 75 else \"正常\""},
{"t":"ex","q":"输入 PM2.5 = 75，程序输出什么？","steps":[{"s":"第一个条件 pm >= 75 中 75 >= 75 为 True","why":">= 包含等号，边界值算命中"},{"s":"执行第一个语句块：输出“空气污染，请小心！”","why":"多分支命中即跳出，后面的 elif/else 不再判断"},{"s":"所以只输出一行","why":"不会出现同时输出两条的情况"}],"ans":"输出“空气污染，请小心！”"},{"t":"warn","text":"<b>常见陷阱</b>：<code>if n%2==0: … elif n%3==0: …</code> 当 n=30 时只走第一支，输出“30 is even”，第二支永不执行——多分支是<b>互斥</b>的，要两条都判断请用两个独立 if。"},{"t":"sh","no":"3.3","title":"程序异常处理"},{"t":"tx","h":"为什么要异常处理","p":"用户输入与预期不符（如输入字母却要数字）会抛异常并让程序直接退出。<code>try-except</code> 让程序捕获异常、给出友好提示后继续运行。异常信息结构：类型（如 <code>NameError</code>）+ 内容提示（如 <code>name 'a' is not defined</code>）。"},{"t":"fx","lines":["try: <正常程序块>","except <异常类型>: <捕获后执行>","else: <未发生异常时执行>","finally: <无论是否异常都执行，常用于关闭文件>"]},{"t":"code","lang":"python","code":"try:\n    num = eval(input(\"请输入一个整数: \"))\n    print(\"输入值的平方是:\", num**2)\nexcept NameError:\n    print(\"输入格式错误，请输入数字\")\nexcept:\n    print(\"其他异常\")\nelse:\n    print(\"没有发生异常\")\nfinally:\n    print(\"程序结束\")"},{"t":"kw","items":[{"k":"异常处理try-except","d":"捕获异常避免程序崩溃，可配 else/finally"},{"k":"异常类型","d":"NameError/ValueError/ZeroDivisionError 等，可精确捕获"}]},{"t":"sh","no":"3.4","title":"循环结构"},{"t":"tx","h":"遍历循环 for","p":"<code>for 变量 in 遍历结构:</code>，遍历结构可以是字符串、文件、组合数据类型或 <code>range()</code>。<b>循环次数由遍历结构的长度决定</b>，是“有限循环”。"},{"t":"tx","h":"条件循环 while","p":"<code>while 条件:</code>，条件为真就反复执行，直到条件不成立。适合<b>事先不知道次数</b>的场景（如直到精度达标）。写 while 一定要保证循环变量在变，否则死循环。"},{"t":"tx","h":"break 与 continue","p":"<code>break</code> 跳出<b>最内层</b>整个循环，继续执行循环之后的代码；<code>continue</code> 只结束<b>本次</b>，跳过循环体剩余语句，然后重新判断条件（while）或取下一个元素（for）。"},{"t":"kw","items":[{"k":"遍历循环for","d":"for x in 结构，次数由结构长度决定"},{"k":"条件循环while","d":"条件为真反复执行，适合未知次数"},{"k":"break语句","d":"跳出最内层整个循环"},{"k":"continue语句","d":"只结束本次循环，继续下一次"},{"k":"循环嵌套","d":"外层走一次，内层走完整一轮"}]},{"t":"code","lang":"python","code":"# 1) 累加\ns = 0\nfor i in range(1, 101):\n    s += i\nprint(\"1+2+…+100 =\", s)\n\n# 2) 蒙特卡罗法求 π\nimport random\nrandom.seed(1)\nn = 100000\nhits = 0\nfor i in range(n):\n    x, y = random.random(), random.random()\n    if x*x + y*y <= 1:\n        hits += 1\nprint(\"π ≈\", 4 * hits / n)"},{"t":"ex","q":"用蒙特卡罗法估计圆周率，说明为什么 4×圆内点数/总点数 就是 π。","steps":[{"s":"在边长 1 的正方形内均匀撒点，正方形面积 = 1","why":"随机点的坐标落在 [0,1)×[0,1)"},{"s":"四分之一圆（半径 1）面积为 π/4","why":"整圆面积 πr²，r=1，取四分之一"},{"s":"点落入圆内的概率 = 面积比 = (π/4)/1 = π/4","why":"几何概型：概率等于面积之比"},{"s":"所以 π ≈ 4 × 落在圆内的点数 / 总点数","why":"用频率估计概率，点数越多越接近"}],
"ans":"π ≈ 4 × hits / n；n 越大估计越精确，前提是随机数足够“随机”。"},{"t":"tip","text":"<b>随机数三兄弟</b>：<code>random.random()</code> 产生 [0,1) 小数（其余函数都由它扩展）；<code>random.randint(a,b)</code> 整数；<code>random.seed(x)</code> 固定种子让结果可复现。"}]},"py4":{"no":"4","title":"函数与代码复用","tag":"第4章","sub":"def·参数·作用域·递归","blocks":[{"t":"sh","no":"4.1","title":"函数的定义与调用"},{"t":"tx","h":"函数是什么","p":"函数是一段<b>具有特定功能、可重用</b>的语句组，用函数名调用。看作一个<b>黑盒</b>：给输入参数，得返回输出，内部实现不必关心。作用有二：<b>问题分解</b>（降低编程难度）、<b>代码复用</b>（避免重复写）。"},{"t":"fx","lines":["def <函数名>(<参数列表>):","    <函数体>","    return <返回值列表>","调用：<变量> = <函数名>(<实参>)"]},{"t":"tx","h":"调用过程四步","p":"① 调用处在调用语句处暂停；② 把<b>实参复制给形参</b>；③ 执行函数体；④ 遇到 return 得到返回值，回到暂停处继续。return 可以返回 0 个、1 个或多个值（多个值以<b>元组</b>形式保存）；没有 return 则返回 None。"},{"t":"kw","items":[{"k":"函数定义def","d":"def 名字(参数): 缩进的函数体，可 return"},{"k":"函数调用过程","d":"暂停→实参传形参→执行函数体→返回并回到暂停处"},{"k":"返回值return","d":"退出函数并带回结果，多值以元组返回，无 return 返回 None"}]},{"t":"code","lang":"python","code":"def happy_birthday(name):\n    print(\"Happy birthday to you!\")\n    print(\"Happy birthday to you!\")\n    print(\"Happy birthday, dear {}!\".format(name))\n    print(\"Happy birthday to you!\")\n\nhappy_birthday(\"Mike\")\nhappy_birthday(\"Lily\")"},{"t":"sh","no":"4.2","title":"lambda 与参数传递"},{"t":"tx","h":"lambda 匿名函数","p":"<code><函数名> = lambda <参数列表>: <表达式></code>，等价于只含一个 return 的 def。适合定义简单、一行能写完的函数，返回的是函数对象，可作为参数传给 map/filter/sort。"},{"t":"tx","h":"三类参数","p":"<b>可选参数</b>（默认值）：<code>def f(a, b=2)</code>，默认值必须放在非默认参数<b>后面</b>。<b>可变数量参数</b>：<code>def f(*args)</code>，多余实参被打包成<b>元组</b>，只能放参数列表最后。<b>位置传参与名称传参</b>：<code>f(1,2,3)</code> 按顺序；<code>f(z=3, x=1, y=2)</code> 按名字，顺序可任意。"},{"t":"kw","items":[{"k":"lambda函数","d":"lambda 参数: 表达式，一行定义匿名函数"},{"k":"可选参数","d":"带默认值，必须写在无默认参数之后"},{"k":"可变数量参数","d":"*args 把多余实参打包成元组，只能放最后"},{"k":"位置传参与名称传参","d":"按顺序传或按形参名传，后者顺序可调"}]},{"t":"code","lang":"python","code":"f = lambda x, y: x * y\nprint(f(3, 4))          # 12\n\nprint(list(map(lambda x: x**2, [1,2,3,4])))   # [1,4,9,16]\n\ndef g(a, b=2, *args):\n    return a + b + sum(args)\nprint(g(1))            # 3\nprint(g(1, 10, 100, 200))  # 311"},{"t":"sh","no":"4.3","title":"变量作用域"},{"t":"tx","h":"全局与局部","p":"<b>全局变量</b>：函数外定义、无缩进，全程有效。<b>局部变量</b>：函数内使用，函数退出即销毁。查找顺序：先局部，再外层代码块，最后全局。"},{"t":"tx","h":"两条关键规则","p":"① 函数内<b>对变量赋值</b>，默认就把它当局部变量（哪怕外面有同名全局变量）；想改全局必须先用 <code>global n</code> 声明。② <b>组合数据类型</b>（列表、字典）在函数内用 <code>ls.append()</code> 这类<b>原地修改</b>会真的改到全局对象——因为没有发生赋值。同一变量既在 global 又在函数内赋值而未声明，会抛 <code>UnboundLocalError</code>。"},
{"t":"kw","items":[{"k":"全局变量与局部变量","d":"全局全程有效，局部只在函数内有效"},{"k":"global声明","d":"函数内赋值想改全局变量必须先 global"},{"k":"可变对象的原地修改","d":"list.append 等原地操作会改到全局对象"}]},{"t":"code","lang":"python","code":"n = 1\nls = [1, 2]\n\ndef func():\n    global n        # 声明后才能改全局''' n'''\n    n = 5\n    ls.append(3)    # 原地修改，没有赋值，改的是全局列表\n\nfunc()\nprint(n, ls)        # 5 [1, 2, 3]"},{"t":"sh","no":"4.4","title":"递归与模块化"},{"t":"tx","h":"递归的两个要素","p":"函数在内部<b>调用自身</b>叫递归。必须有两个要素：<b>基例</b>（不再递归的确定表达式，如 0!=1）和<b>递归链</b>（每次向基例靠近）。缺少基例会无限递归，Python 默认最大递归深度约 1000 层，超出抛 <code>RecursionError</code>。"},{"t":"fx","lines":["阶乘：n! = 1 (n=0) ; n! = n × (n−1)! (n>0)","汉诺塔：h(n) = 2·h(n−1) + 1，h(1)=1 ⇒ h(n) = 2ⁿ − 1","科赫曲线：0 阶为长度 L 的直线，每阶把每段三等分、中段换成等边三角形的两边，段数 ×4"]},{"t":"kw","items":[{"k":"递归","d":"函数内部调用自身，需基例与递归链"},{"k":"递归基例","d":"不再递归的确定出口，缺了就无限递归"},{"k":"模块化设计","d":"按功能划分模块，紧耦合内部、松耦合模块间"}]},{"t":"code","lang":"python","code":"def fact(n):\n    if n == 0:          # 基例\n        return 1\n    return n * fact(n-1)  # 递归链\n\ndef hanoi(n, a, b, c):\n    if n == 1:\n        print(a, \"->\", c)\n        return\n    hanoi(n-1, a, c, b)\n    print(a, \"->\", c)\n    hanoi(n-1, b, a, c)\n\nprint(fact(5))       # 120\nhanoi(3, \"A\", \"B\", \"C\")"},{"t":"ex","q":"3 层汉诺塔（A→C，可借用 B）最少需要多少步？写出前 3 步。","steps":[{"s":"先把上面 2 个盘从 A 移到 B（借助 C）","why":"要把最大盘移到 C，C 必须先空出来"},{"s":"把最大盘从 A 移到 C","why":"此时它上面已经没有盘，可以移动"},{"s":"再把 2 个盘从 B 移到 C（借助 A）","why":"递归结构：h(n) = h(n−1) + 1 + h(n−1)"},{"s":"h(3) = 2·h(2) + 1 = 2·3 + 1 = 7，通式 2ⁿ−1","why":"递推展开即得 2 的幂减一"}],"ans":"共 7 步。前三步：A->C、A->B、C->B。"},{"t":"tip","text":"<b>模块化设计两条要求</b>：<b>紧耦合</b>——功能块内部联系紧密；<b>松耦合</b>——模块之间关系简单。用函数只是模块化的必要非充分条件，关键是把“完成特定功能、经常复用”的语句封装成函数，并尽量减少参数与返回值数量。"}]},"py5":{"no":"5","title":"组合数据类型（一）","tag":"第5章","sub":"序列·元组·列表·集合·jieba","blocks":[{"t":"sh","no":"5.1","title":"三类组合数据类型总览"},{"t":"tx","h":"为什么需要组合类型","p":"单个变量只能装一个值，而实际问题往往是\"一组数\"。Python 提供三类组合数据类型：<b>序列类型</b>（字符串 str、元组 tuple、列表 list，元素有序、可用序号访问）、<b>集合类型</b>（set，元素无序且不重复）、<b>映射类型</b>（dict，键值对）。"},{"t":"tb","head":["类型","可变性","定界符","能否重复","索引方式"],"rows":[["字符串 str","不可变","' ' / \" \"","可以","序号 0..L-1 / −1..−L"],["元组 tuple","不可变","( )","可以","序号"],["列表 list","可变","[ ]","可以","序号"],["集合 set","可变","{ }","不重复","无索引"],["字典 dict","可变","{k:v}","键不重复","按键访问"]]},{"t":"fx","lines":["通用操作符：x in s / x not in s / s + t / s*n / s[i] / s[i:j] / len(s) / min(s) / max(s)","s.index(x) 返回首次出现位置；s.count(x) 返回出现次数",
"反向索引：s[-1] 是最后一个元素，s[-L] 是第一个"]},{"t":"kw","items":[{"k":"序列类型","d":"str/tuple/list，有序可用序号访问"},{"k":"集合类型","d":"set，无序且元素不重复"},{"k":"映射类型","d":"dict，键值对，按键访问"}]},{"t":"sh","no":"5.2","title":"元组与列表"},{"t":"tx","h":"元组 tuple","p":"用圆括号或直接逗号分隔创建，<b>创建后不可修改</b>（不能增删改元素）。适合表达\"一组固定不变的数据\"，例如坐标、日期。单元素元组要写 <code>(1,)</code> 逗号不能省。"},{"t":"tx","h":"列表 list","p":"用方括号创建，<b>可增删改</b>。是 Python 中最常用的组合类型。创建方式：<code>[]</code>、<code>list()</code>、<code>list(range(5))</code>、<code>\"a,b\".split(\",\")</code>。"},{"t":"tb","head":["列表方法","作用"],"rows":[["ls.append(x)","在末尾追加一个元素"],["ls.insert(i, x)","在第 i 位插入 x"],["ls.pop(i)","取出并删除第 i 位（默认末尾）"],["ls.remove(x)","删除第一个值为 x 的元素"],["ls.reverse()","原地反转"],["ls.sort()","原地排序（默认升序）"],["ls.copy()","返回浅拷贝的新列表"],["ls.clear()","清空"]]},{"t":"kw","items":[{"k":"元组tuple","d":"() 创建，不可变，单元素需写成 (1,)"},{"k":"列表list","d":"[] 创建，可变，append/insert/pop/sort"},{"k":"列表的别名与浅拷贝","d":"直接赋值是别名（同一对象），copy() 才是新对象"},{"k":"列表推导式","d":"[表达式 for x in 序列 if 条件] 一行生成列表"}]},{"t":"code","lang":"python","code":"ls = [1, 2, 3]\nalias = ls          # 别名：同一个对象\nalias.append(4)\nprint(ls)           # [1, 2, 3, 4]\n\ncp = ls.copy()      # 浅拷贝：新对象\ncp.append(5)\nprint(ls, cp)       # [1,2,3,4] [1,2,3,4,5]\n\nt = (1, 2, 3)\n# t[0] = 9  # TypeError: 元组不可修改\n\n# 列表推导式\nsq = [x**2 for x in range(1, 6) if x % 2 == 1]\nprint(sq)           # [1, 9, 25]"},{"t":"ex","q":"a = [1,2,3]; b = a; b.append(4); print(len(a), len(b)) 输出什么？换成 b = a.copy() 呢？","steps":[{"s":"b = a 让 b 和 a 指向同一个列表对象","why":"列表是可变对象，赋值传的是引用"},{"s":"b.append(4) 修改的就是那一个对象","why":"所以 a 看起来也变了，其实是同一个"},{"s":"所以 len(a)=len(b)=4","why":"两个名字一个对象"},{"s":"若用 a.copy()，b 是新列表，追加不影响 a","why":"浅拷贝创建新容器，元素仍共享"}],"ans":"前者输出 4 4；后者输出 3 4。"},{"t":"sh","no":"5.3","title":"集合类型"},{"t":"tx","h":"集合的特点","p":"元素<b>无序、不重复</b>，用 <code>{}</code> 创建（空集合必须写 <code>set()</code>，<code>{}</code> 是空字典）。主要用途：<b>去重</b>、<b>成员判断（比列表快得多）</b>、集合运算。集合元素必须是不可变且可哈希的（列表不能放进集合）。"},{"t":"tb","head":["运算","含义","示例"],"rows":[["S - T","差集","去掉 T 中元素"],["S & T","交集","同时属于两者"],["S | T","并集","属于任一"],["S ^ T","补集","只属于其中一个"],["S <= T","子集判断","S 是 T 的子集"]]},{"t":"code","lang":"python","code":"A = {1, 2, 3}; B = {3, 4, 5}\nprint(A - B)   # {1, 2}\nprint(A & B)   # {3}\nprint(A | B)   # {1, 2, 3, 4, 5}\nprint(A ^ B)   # {1, 2, 4, 5}\n\n# 去重\ntext = \"hello world\"\nprint(set(text))   # 不重复字符集合"},{"t":"kw","items":[{"k":"集合set","d":"{} 创建，无序不重复，元素必须可哈希"},{"k":"集合去重",
"d":"set(序列) 去重，再用 list() 转回列表"},{"k":"集合运算","d":"- & | ^ 分别对应差、交、并、补集"}]},{"t":"sh","no":"5.4","title":"jieba 库与词频统计"},{"t":"tx","h":"中文分词","p":"中文没有空格分隔，需要用 jieba 库切词。三种模式：<b>精确模式</b> <code>jieba.lcut(s)</code>（最常用，不冗余）、<b>全模式</b> <code>jieba.lcut(s, cut_all=True)</code>（所有可能成词都切出，有冗余）、<b>搜索引擎模式</b> <code>jieba.lcut_for_search(s)</code>（精确模式基础上再切长词，适合索引）。"},{"t":"kw","items":[{"k":"jieba分词","d":"jieba.lcut(s) 精确模式；cut_all=True 全模式；lcut_for_search 搜索引擎模式"},{"k":"词频统计","d":"分词后遍历计数，按次数排序输出"},{"k":"分词库安装","d":"pip install jieba，import jieba 后使用"}]},{"t":"code","lang":"python","code":"import jieba\n\ns = \"人工智能是计算机科学的一个重要分支\"\nprint(\" / \".join(jieba.lcut(s)))\nprint(\" / \".join(jieba.lcut(s, cut_all=True)))\nprint(\" / \".join(jieba.lcut_for_search(s)))"},{"t":"ex","q":"统计一段中文文本中出现次数最多的 5 个词。","steps":[{"s":"用 jieba.lcut(txt) 切成词列表","why":"中文必须先分词才能计数"},{"s":"建一个字典 counts，遍历词列表累加","why":"字典是\"词→次数\"的天然映射"},{"s":"items = list(counts.items())，按次数降序排序","why":"转成列表才能排序"},{"s":"取前 5 项输出","why":"题目只要求 top5"}],"ans":"核心代码：for w in words: counts[w] = counts.get(w,0)+1；再 sorted(counts.items(), key=lambda x:-x[1])[:5]。"},{"t":"tip","text":"<b>选哪种类型？</b> 数据固定不变 → 元组；需要频繁增删改 → 列表；只关心\"有没有、去重\" → 集合；需要\"名字→值\"的查找 → 字典。"}]},"py6":{"no":"6","title":"组合数据类型（二）","tag":"第6章","sub":"字典·哈希·csv·高级操作","blocks":[{"t":"sh","no":"6.1","title":"字典类型的概念"},{"t":"tx","h":"键值对","p":"字典是<b>键值对（key:value）的集合</b>，用 <code>{}</code> 创建，形如 <code>d = {\"name\":\"Tom\", \"age\":18}</code>。<b>键必须唯一且可哈希</b>（字符串、数字、元组），值可以是任意类型。字典本质是一种<b>关联数组 / 映射</b>，通过键而不是位置找值。"},{"t":"fx","lines":["<变量> = {<键1>:<值1>, <键2>:<值2>, …}","<值> = <字典>[<键>]     按键取值，键不存在会 KeyError","<字典>[<键>] = <值>     键存在则改，不存在则新增","d.get(k, default)     键不存在时返回 default 而不报错"]},{"t":"kw","items":[{"k":"字典dict","d":"{} 键值对集合，键唯一且可哈希"},{"k":"键值对","d":"key:value 结构，按键而非位置取值"}]},{"t":"sh","no":"6.2","title":"字典的操作"},{"t":"tb","head":["方法 / 操作","作用"],"rows":[["d.keys()","返回所有键的视图"],["d.values()","返回所有值的视图"],["d.items()","返回 (键,值) 元组视图"],["d.get(k, dv)","取值，缺失返回默认值"],["d.pop(k, dv)","取出并删除"],["d.update(d2)","用 d2 更新/并入"],["k in d","键是否在字典中"],["len(d)","键值对个数"]]},{"t":"code","lang":"python","code":"d = {\"apple\": 3, \"pear\": 5}\nd[\"banana\"] = 2            # 新增\nprint(d.get(\"grape\", 0))  # 0，不报错\n\nfor k, v in d.items():\n    print(k, v)\n\n# 用函数做值的\"简单计算器\"\ndef add(x, y): return x + y\ndef sub(x, y): return x - y\nops = {\"+\": add, \"-\": sub}\nprint(ops[\"+\"](3, 4))     # 7"},
{"t":"kw","items":[{"k":"字典get方法","d":"d.get(k,dv) 键不存在返回默认值，避免 KeyError"},{"k":"字典视图keys-values-items","d":"返回键/值/键值对视图，可遍历"},{"k":"字典遍历","d":"for k in d 遍历键；for k,v in d.items() 遍历键值"},{"k":"函数作为字典的值","d":"ops[\"+\"](3,4) 实现分派表/简单计算器"}]},{"t":"ex","q":"数词频：如何用字典统计 \"to be or not to be\" 中各词出现次数？","steps":[{"s":"split() 切成词列表 [\"to\",\"be\",\"or\",\"not\",\"to\",\"be\"]","why":"英文天然以空格分词"},{"s":"遍历每个词 w，执行 counts[w] = counts.get(w, 0) + 1","why":"get 给初值 0，第一次出现也不会 KeyError"},{"s":"结果 counts = {\"to\":2, \"be\":2, \"or\":1, \"not\":1}","why":"这就是词频字典"},{"s":"要排序输出，需先转 list(counts.items()) 再 sort","why":"字典本身无序，不能直接排序"}],"ans":"counts = {}; for w in s.split(): counts[w] = counts.get(w,0)+1"},{"t":"sh","no":"6.3","title":"哈希与可哈希对象"},{"t":"tx","h":"字典为什么快","p":"字典底层是<b>哈希表</b>：把键经 hash 函数算出一个整数，再对表长取模得到\"桶\"位置，因此查找是<b>平均 O(1)</b>，与字典大小基本无关（列表查找是 O(n)）。"},{"t":"tx","h":"可哈希的条件","p":"能作为键的对象必须<b>可哈希</b>：实现了 <code>__hash__()</code> 且不可变。判定相等时调用 <code>__eq__()</code>。列表、字典、集合<b>不可哈希</b>，所以不能当键；字符串、数字、元组（元素都可哈希时）可以。自定义类若重写 <code>__eq__</code> 而不重写 <code>__hash__</code>，实例就不再可哈希。"},{"t":"kw","items":[{"k":"哈希表","d":"按键 hash 值定位桶，平均 O(1) 查找"},{"k":"可哈希对象","d":"实现 __hash__ 且不可变，才能当字典键或集合元素"},{"k":"不可变对象","d":"str/int/tuple 不可变可哈希；list/dict/set 不可哈希"}]},{"t":"sh","no":"6.4","title":"高级操作与 collections"},{"t":"tx","h":"三个高阶函数","p":"<code>filter(f, seq)</code> 保留 f 返回真的元素；<code>map(f, seq)</code> 对每个元素应用 f；<code>reduce(f, seq, init)</code>（需 <code>from functools import reduce</code>）把序列\"折叠\"成一个值。三者常与 lambda 搭配。"},{"t":"tb","head":["collections 类型","作用"],"rows":[["deque","双端队列，两端增删都是 O(1)，适合队列/栈"],["Counter","计数器，直接统计元素出现次数"],["defaultdict","带默认值的字典，缺键自动创建"],["OrderedDict","记住插入顺序的字典"]]},{"t":"kw","items":[{"k":"filter函数","d":"filter(f,seq) 过滤出 f 为真的元素，返回迭代器"},{"k":"map函数","d":"map(f,seq) 对每个元素应用 f，返回迭代器"},{"k":"reduce函数","d":"reduce(f,seq) 折叠成一个值，需 import functools"},{"k":"deque","d":"collections.deque 双端队列，两端 O(1)"},{"k":"Counter","d":"collections.Counter 直接统计频次，most_common 取前几"},{"k":"defaultdict","d":"缺键时自动用工厂函数创建默认值"},{"k":"列表推导式与生成器","d":"[] 立即生成列表，( ) 生成惰性生成器"}]},{"t":"code","lang":"python","code":"from functools import reduce\nfrom collections import Counter\n\nls = [1, 2, 3, 4, 5]\nprint(list(filter(lambda x: x % 2 == 1, ls)))  # [1, 3, 5]\nprint(list(map(lambda x: x * 2, ls)))          # [2, 4, 6, 8, 10]\nprint(reduce(lambda a, b: a + b, ls))          # 15\n\nc = Counter(\"abracadabra\")\nprint(c.most_common(3))    # [(\"a\",5), (\"b\",2), (\"r\",2)]"},
{"t":"tip","text":"<b>选择建议</b>：要\"按键查值\"用 dict；要\"去重/交并差\"用 set；要\"按顺序存一串\"用 list；要\"固定不改\"用 tuple。Counter 出现时，词频统计可以少写一个 for 循环。"}]},"py7":{"no":"7","title":"IO编程","tag":"第7章","sub":"文件·编码·csv·os模块","blocks":[{"t":"sh","no":"7.1","title":"文件与编码"},{"t":"tx","h":"文本文件与二进制文件","p":"<b>文本文件</b>：由单一特定编码（如 UTF-8）组成的字符序列，可用记事本打开阅读。<b>二进制文件</b>：直接由比特 0/1 组成，没有统一字符编码，需专用软件解析（如图片、可执行文件）。二者本质差别在<b>是否有统一编码</b>。"},{"t":"tx","h":"字符编码","p":"<b>ASCII</b>：7 位，仅覆盖英文字符。<b>Unicode</b>：统一字符集，为每个字符分配唯一码点。<b>UTF-8</b>：Unicode 的可变长实现，英文 1 字节、中文 3 字节，是互联网最通用的编码。读写文本务必显式指定 <code>encoding=\"utf-8\"</code>，否则 Windows 下中文易乱码。"},{"t":"kw","items":[{"k":"文本文件","d":"有统一字符编码，如 .txt/.py/.csv"},{"k":"二进制文件","d":"无统一编码，由比特组成，需专用软件"},{"k":"字符编码UTF-8","d":"Unicode 的可变长实现，中文 3 字节，通用编码"},{"k":"ASCII与Unicode","d":"ASCII 7 位仅英文；Unicode 统一码点为字符编号"}]},{"t":"sh","no":"7.2","title":"文件的打开与读写"},{"t":"tb","head":["打开模式","含义"],"rows":[["\"r\"","只读，文件不存在报错（默认）"],["\"w\"","只写，<b>清空重写</b>，不存在则创建"],["\"x\"","创建新文件，已存在则报错"],["\"a\"","追加写，不清空，指针在末尾"],["\"b\"","二进制模式，与上述组合如 \"rb\""],["\"t\"","文本模式（默认）"],["\"+\"","与 r/w/a 组合，增加读写能力如 \"r+\""]]},{"t":"tb","head":["读取方法","作用"],"rows":[["f.read(size)","读全部或 size 个字符，返回字符串"],["f.readline()","读一行"],["f.readlines()","读所有行，返回列表"],["f.write(s)","写入字符串"],["f.writelines(ls)","写入字符串列表（不自动加换行）"],["f.seek(offset)","移动文件指针"],["f.tell()","返回当前指针位置"]]},{"t":"fx","lines":["f = open(path, \"r\", encoding=\"utf-8\")  → 操作 → f.close()","f.read() 一次性读入全部；f.readlines() 得到行列表","f.write(s) 只接受字符串，写数字要先 str() 转换","文本指针按字符计，二进制按字节计；seek(0) 回到开头"]},{"t":"kw","items":[{"k":"open函数","d":"open(path, mode, encoding) 返回文件对象"},{"k":"文件打开模式","d":"r 读 w 清空写 a 追加 x 新建 b 二进制 t 文本 + 读写"},{"k":"read-readline-readlines","d":"全读/读一行/读所有行成列表"},{"k":"write与writelines","d":"写字符串/写字符串列表，均不自动加换行"},{"k":"seek与tell","d":"移动指针位置 / 返回当前位置"}]},{"t":"code","lang":"python","code":"# 写文件\nf = open(\"demo.txt\", \"w\", encoding=\"utf-8\")\nf.write(\"第一行\\n第二行\\n\")\nf.close()\n\n# 读文件\nf = open(\"demo.txt\", \"r\", encoding=\"utf-8\")\nfor line in f:                 # 逐行迭代，最省内存\n    print(line.strip())\nf.close()"},{"t":"ex","q":"统计文件 demo.txt 的行数与字符数。","steps":[{"s":"以 \"r\" + encoding=\"utf-8\" 打开文件","why":"指定编码避免中文乱码"},{"s":"lines = f.readlines() 得到行列表","why":"行数即 len(lines)"},{"s":"字符数 = sum(len(x) for x in lines)","why":"每行长度累加；若想去掉换行符用 x.strip()"},{"s":"最后 f.close() 或用 with 自动关闭","why":"不关闭可能丢数据"}],"ans":"n_lines = len(lines)；n_chars = sum(len(x) for x in lines)。"},
{"t":"sh","no":"7.3","title":"with 上下文管理"},{"t":"tx","h":"为什么推荐 with","p":"<code>with open(...) as f:</code> 会在代码块结束（包括异常退出）时<b>自动关闭文件</b>，省去手写 close，也避免忘记关闭导致的资源泄漏。这是读写文件的<b>规范写法</b>，考试和工程都优先用它。"},{"t":"code","lang":"python","code":"with open(\"demo.txt\", \"r\", encoding=\"utf-8\") as f:\n    data = f.read()\nprint(len(data))\n# 离开 with 块，f 已自动关闭"},{"t":"kw","items":[{"k":"with-as上下文管理器","d":"with open() as f 块结束自动关闭文件"}]},{"t":"sh","no":"7.4","title":"一维、二维数据与 CSV"},{"t":"tx","h":"一维 / 二维数据","p":"<b>一维数据</b>：线性排列，对应列表或集合。<b>二维数据</b>：由一维数据组合而成，对应\"列表的列表\"，是表格形态。<b>CSV</b>（逗号分隔值）是存储一二维数据最通用的格式，规则：以<b>英文逗号</b>分隔，以<b>换行</b>表示行，若字段内容本身含逗号/换行则需加引号转义，文件后缀 .csv。"},{"t":"kw","items":[{"k":"CSV格式","d":"逗号分隔、换行分行，通用的一二维数据格式"},{"k":"一维数据","d":"线性排列，对应 list 或 set"},{"k":"二维数据","d":"表格形态，对应列表的列表"},{"k":"csv模块","d":"csv.reader/writer 读写 CSV，处理转义"}]},{"t":"code","lang":"python","code":"import csv\n\n# 写 CSV\nwith open(\"t.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    w = csv.writer(f)\n    w.writerow([\"姓名\", \"成绩\"])\n    w.writerow([\"张三\", 92])\n\n# 读 CSV\nwith open(\"t.csv\", \"r\", encoding=\"utf-8\") as f:\n    for row in csv.reader(f):\n        print(row)      # [\"姓名\",\"成绩\"] / [\"张三\",\"92\"]"},{"t":"warn","text":"<b>易错</b>：写 CSV 时 open 要加 <code>newline=\"\"</code>，否则 Windows 下每行之间会多出空行；用 <code>split(\",\")</code> 手工解析只是“简化版”，字段含逗号时会出错，正式场合请用 csv 模块。"},{"t":"sh","no":"7.5","title":"os 模块"},{"t":"tb","head":["函数","作用"],"rows":[["os.getcwd()","返回当前工作目录"],["os.chdir(p)","切换工作目录"],["os.listdir(p)","列出目录下所有文件与子目录名"],["os.mkdir(p) / os.makedirs(p)","创建单级 / 多级目录"],["os.remove(p)","删除文件"],["os.rmdir(p)","删除空目录"],["os.path.exists(p)","路径是否存在"],["os.path.join(a,b)","拼接路径（跨平台安全）"],["os.path.basename / dirname","取文件名 / 取目录名"],["os.path.splitext(p)","分离扩展名"]]},{"t":"code","lang":"python","code":"import os\n\np = os.getcwd()\nprint(p)\n\n# 列出当前目录所有 .txt 文件\nfor name in os.listdir(p):\n    if os.path.splitext(name)[1] == \".txt\":\n        print(name)"},{"t":"kw","items":[{"k":"os模块","d":"操作系统接口：getcwd/listdir/mkdir/remove 等"},{"k":"os.path","d":"exists/join/basename/dirname/splitext 路径处理"},{"k":"os.listdir","d":"列出目录下的文件名与子目录名"}]},{"t":"tip","text":"<b>IO 三句话</b>：① 文本读写一定带 <code>encoding=\"utf-8\"</code>；② 一律用 <code>with</code> 打开；③ 路径拼接用 <code>os.path.join</code>，别手工拼 \"/\"。"}]},"py8":{"no":"8","title":"面向对象编程（一）","tag":"第8章","sub":"类·实例·封装·访问限制","blocks":[{"t":"sh",
"no":"8.1","title":"从 POP 到 OOP"},{"t":"tx","h":"两种编程范式","p":"<b>面向过程（POP）</b>：把问题拆成函数序列，数据与操作分离，适合小规模脚本。<b>面向对象（OOP）</b>：把问题拆成一个个<b>对象</b>，对象 = <b>数据（属性）+ 对数据的操作（方法）</b>，更适合复杂、多人协作的系统。两者不是替代关系，而是不同粒度的抽象。"},{"t":"tx","h":"OOP 三个核心概念","p":"<b>封装</b>：把数据与操作打包进类，只暴露必要接口；<b>继承</b>：新类复用已有类的属性与方法；<b>多态</b>：同一接口在不同对象上有不同实现。本章（一）主要讲<b>封装</b>。"},{"t":"kw","items":[{"k":"面向对象编程OOP","d":"以对象为基本单位，对象=属性+方法"},{"k":"面向过程编程POP","d":"以函数与过程为基本单位，数据操作分离"},{"k":"封装与继承与多态","d":"OOP 三大特性：封装数据方法、继承复用、多态同一接口"}]},{"t":"sh","no":"8.2","title":"类与实例"},{"t":"fx","lines":["class <类名>:                # 类名首字母通常大写","    def __init__(self, 参数):  # 构造函数，创建实例时自动调用","        self.属性 = 参数       # 绑定到实例上","    def <方法名>(self):        # 方法第一个参数是 self","        代码"]},{"t":"tx","h":"类与实例的关系","p":"<b>类</b>是模板 / 蓝图，<b>实例</b>是按模板造出来的具体对象，一个类可以造出很多实例。创建实例 <code>s = Student(\"Tom\", 18)</code> 时自动调用 <code>__init__</code>。<b>self</b> 代表实例自身，方法调用时由 Python 自动传入，写着时不传。"},{"t":"code","lang":"python","code":"class Student:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n\n    def intro(self):\n        return \"我叫{}，今年{}岁\".format(self.name, self.age)\n\n    def grow(self):\n        self.age += 1\n\ns = Student(\"Tom\", 18)\nprint(s.intro())   # 我叫Tom，今年18岁\ns.grow()\nprint(s.intro())   # 我叫Tom，今年19岁"},{"t":"kw","items":[{"k":"类class","d":"class 关键字定义，类名大写开头，是对象的模板"},{"k":"实例instance","d":"按类创建的具体对象，一个类可有多个实例"},{"k":"构造函数__init__","d":"创建实例时自动调用，用于初始化属性"},{"k":"self","d":"指向实例自身，方法第一个参数，调用时自动传入"}]},{"t":"sh","no":"8.3","title":"数据封装与方法"},{"t":"tx","h":"封装","p":"封装 = 把<b>属性</b>和<b>操作属性的方法</b>绑在一起，外部不必知道内部细节，只调用方法即可。例如\"银行账户\"自己负责校验余额，外部只管 <code>deposit()</code>/<code>withdraw()</code>，不能直接乱改余额。这就是\"黑盒\"思想在对象上的体现。"},{"t":"tx","h":"类属性 vs 实例属性","p":"<b>实例属性</b>在 <code>__init__</code> 中用 <code>self.x</code> 定义，每个实例各有一份；<b>类属性</b>在类体里直接定义，所有实例共享一份。注意：通过实例给类属性名\"赋值\"会在实例上新建同名实例属性，而不是改类属性。"},{"t":"kw","items":[{"k":"数据封装","d":"属性与操作方法绑定，只暴露方法接口"},{"k":"类属性与实例属性","d":"类属性共享一份；self.x 定义实例属性各一份"},{"k":"方法Method","d":"类内定义、第一个参数为 self 的函数"}]},{"t":"code","lang":"python","code":"class Account:\n    bank = \"中国银行\"        # 类属性，所有实例共享\n\n    def __init__(self, owner, bal=0):\n        self.owner = owner   # 实例属性\n        self.__bal = bal     # 私有属性\n\n    def deposit(self, x):\n        self.__bal += x\n\n    def withdraw(self, x):\n        if x > self.__bal:\n            return \"余额不足\"\n        self.__bal -= x\n        return self.__bal\n\na = Account(\"Tom\", 100)\na.deposit(50)\nprint(a.withdraw(30))    # 120"},
{"t":"ex","q":"账户余额 100，存 50 再取 30，withdraw 返回多少？如果直接写 a.__bal 会怎样？","steps":[{"s":"deposit(50) 后 self.__bal = 150","why":"方法内部改的是实例的私有属性"},{"s":"withdraw(30)：30 ≤ 150，扣减后 self.__bal = 120","why":"先校验再扣减，封装让规则集中在类内"},{"s":"返回 120","why":"return 的是余额"},{"s":"直接访问 a.__bal 会 AttributeError","why":"双下划线已改名成 _Account__bal，外部拿不到"}],"ans":"返回 120；直接写 a.__bal 会报 AttributeError（名称已被改写，且不建议访问）。"},{"t":"sh","no":"8.4","title":"访问限制"},{"t":"tx","h":"三种命名约定","p":"<b>公有</b>：<code>self.name</code>，外部可自由访问。<b>私有</b>：<code>self.__bal</code>（两个下划线开头），Python 会把它<b>改名</b>为 <code>_类名__bal</code>（name mangling），外部无法用原名访问——这是\"约定 + 机制\"实现的私有。<b>特殊</b>：<code>__init__</code>、<code>__str__</code> 等前后双下划线，是 Python 预留的魔术方法，不要自创这种名字。"},{"t":"kw","items":[{"k":"私有变量","d":"双下划线开头，外部不可直接访问"},{"k":"名称改写name-mangling","d":"__x 被改名为 _类名__x，防止意外覆盖"},{"k":"公有变量","d":"单下划线或不加下划线，约定可访问"},{"k":"特殊方法魔术方法","d":"__init__/__str__ 等前后双下划线，Python 预留"}]},{"t":"code","lang":"python","code":"class P:\n    def __init__(self):\n        self.x = 1        # 公有\n        self._y = 2       # 约定内部用，可访问\n        self.__z = 3      # 私有，改名 _P__z\n\n    def show(self):\n        return self.__z   # 类内部可以访问\n\np = P()\nprint(p.x, p._y, p.show())   # 1 2 3\nprint(hasattr(p, \"__z\"))     # False\nprint(p._P__z)               # 3，但不建议这样写"},{"t":"tip","text":"<b>一句话记住本章</b>：类是模板、实例是产品，<code>__init__</code> 负责初始化，<code>self</code> 指向自己；双下划线开头即私有，靠名称改写挡住外部访问。继承与多态是第（二）部分的内容。"}]}}}
};
